INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95aacfc7-e732-4bed-8217-6e32c1c9d227','70-volt and 100-volt systems','Constant-voltage loudspeaker distribution schemes in which a power amplifier drives a line at a fixed nominal voltage (70.7 V RMS in North America, 100 V RMS elsewhere) at full rated power, and each loudspeaker connects through a step-down transformer with selectable power taps. The high line voltage lowers current, so many speakers share long, thin cable runs.','These systems send audio at a high, fixed voltage down one cable. Each speaker has a small transformer that steps the voltage back down. Because the voltage is high, the current is low. That lets you run many speakers on thin, long wires. You pick each speaker''s loudness with a power tap.','It lets one amplifier feed dozens of speakers over long distances in paging, background music, and public-address systems, with per-speaker level set by transformer taps.','A technician sums the wattage taps of all speakers and keeps the total below the amplifier''s rated power; for example, twenty speakers tapped at 4 W need at least 80 W of amplifier capacity plus headroom.','Power Distribution',ARRAY['Bridged amplifier operation','Amplifier gain','Cable resistance','Alternating current','Impedance matching']::text[],ARRAY['Thinking the ''70 volt'' figure is a peak value; it is 70.7 V RMS, chosen because its peak is about 100 V.','Overloading the amplifier by tapping more total wattage than its rated output.','UNSAFE: Treating 70/100 V speaker lines as harmless low voltage; at rated power these lines can exceed safe-touch limits and, per NEC Article 640 and UL rules, may require appropriate wiring and insulation.','Connecting a low-impedance (8 ohm) speaker directly to a 70 V line without a matching transformer.']::text[],ARRAY['Wiring ceiling speakers for background music across a large retail store.','Designing a life-safety paging system in an airport or factory.','Selecting speaker power taps to balance loudness between zones.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='70-volt and 100-volt systems');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95aacfc7-e732-4bed-8217-6e32c1c9d227','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95aacfc7-e732-4bed-8217-6e32c1c9d227') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95aacfc7-e732-4bed-8217-6e32c1c9d227');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a56223a-c6e2-4dc1-b157-6e77b207e11f','A weighting','A standardized frequency-weighting curve applied to sound-level measurements that de-emphasizes low and very high frequencies to approximate the ear''s relative sensitivity near the 40-phon equal-loudness contour. Its magnitude response is defined by fixed pole frequencies of 20.6 Hz, 107.7 Hz, 737.9 Hz and 12194 Hz, normalized to 0 dB at 1 kHz.','A-weighting is a filter used when measuring loudness. It lowers the weight of very low and very high tones. This matches how our ears hear quiet sounds. Meters set to this show results in dB(A). It is common for noise and hearing rules.','It makes a single sound-level number track perceived loudness of moderate sounds, so noise and hearing-exposure limits can be stated consistently as dB(A).','A technician switches a sound level meter to the A weighting to log workplace noise; a reading of 85 dB(A) over 8 hours is a common exposure action level.','Measurement Weighting',ARRAY['C weighting','Sound level meter','Equal-loudness contour','Decibel','Calibration offsets']::text[],ARRAY['Assuming dB(A) equals unweighted SPL; A-weighting removes several dB of low-frequency energy.','Using A-weighting for loud, bass-heavy sources where C-weighting is more appropriate.','Forgetting that A-weighting is normalized to 0 dB at 1 kHz, not at low frequencies.']::text[],ARRAY['Measuring occupational noise exposure on a factory floor.','Reporting a venue''s ambient noise level to meet a local ordinance.','Comparing microphone self-noise specs given in dB(A).']::text[],'Intermediate','R_A(f) = (12194^2 * f^4) / [ (f^2 + 20.6^2)(f^2 + 12194^2) * sqrt((f^2 + 107.7^2)(f^2 + 737.9^2)) ] ;  A(f) = 20*log10(R_A(f)) + 2.00 dB','The A-weighting gain in decibels equals twenty times the base-ten log of the rational magnitude response built from the four standard corner frequencies, plus a 2.00 dB offset that makes the response exactly 0 dB at 1 kHz.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='A weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a56223a-c6e2-4dc1-b157-6e77b207e11f','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a56223a-c6e2-4dc1-b157-6e77b207e11f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a56223a-c6e2-4dc1-b157-6e77b207e11f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '716c3e2b-94d9-4458-867c-a1fc0483507e','Accuracy versus precision','Two distinct measurement qualities: accuracy (trueness) is how close a measured value or its mean lies to the true or reference value, while precision is how closely repeated measurements agree with each other regardless of the true value. A result can be precise but biased, or accurate on average yet scattered.','Accuracy means your reading is close to the true value. Precision means your readings agree with each other. You can be precise but wrong if a bias shifts every reading. You can be accurate on average but scattered. Good measurements aim for both.','The distinction guides technicians to separate a fixed bias, which calibration can correct, from random scatter, which better technique or averaging reduces.','If a level meter reads 1.02, 1.03, 1.02 V for a true 1.00 V source, it is precise but biased high by about 0.02 V, so a calibration offset fixes the accuracy problem.','Measurement Concept',ARRAY['Calibration offsets','Measurement uncertainty','Repeatability','Systematic error','A weighting']::text[],ARRAY['Using ''accurate'' and ''precise'' as if they mean the same thing.','Believing many tightly agreeing readings prove correctness; they only prove precision.','Ignoring a repeatable offset because the numbers look consistent.']::text[],ARRAY['Comparing two SPL meters that agree with each other but disagree with a calibrator.','Judging whether a distortion analyzer needs recalibration.','Explaining why averaging reduces scatter but not bias.']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Accuracy versus precision');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '716c3e2b-94d9-4458-867c-a1fc0483507e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='716c3e2b-94d9-4458-867c-a1fc0483507e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='716c3e2b-94d9-4458-867c-a1fc0483507e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bc0a2cbd-a1d4-4ece-9a71-830689445888','Acoustic crossover zones','Regions in a coverage area where the sound levels from two adjacent loudspeakers or array elements become equal, so their outputs combine and the summation depends strongly on relative phase. These spatial crossover zones are where comb filtering and level ripple are most likely.','This is the spot in a room where two speakers are equally loud. There, their sounds add together. If they are in phase, the sound gets louder. If out of phase, it cancels. These zones need careful aiming and timing.','Identifying these zones lets a designer control how neighboring sources combine, aiming for smooth coverage instead of loud and dead spots.','A technician overlaps two speakers so their spatial crossover falls at a seating boundary and time-aligns them there, reducing comb filtering where levels are equal.','System Design',ARRAY['Acoustic overlap','Boundary interaction','Array steering','Comb filtering','Coverage pattern']::text[],ARRAY['Confusing the acoustic (spatial) crossover between two speakers with an electronic frequency crossover.','Assuming overlap always adds level; at the crossover zone phase can cause deep cancellation.','Ignoring path-length differences that shift the crossover zone off the intended line.']::text[],ARRAY['Splaying two point-source speakers to cover a wide audience.','Blending fill speakers with a main system.','Diagnosing ripple in the seats between two loudspeakers.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic crossover zones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bc0a2cbd-a1d4-4ece-9a71-830689445888','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bc0a2cbd-a1d4-4ece-9a71-830689445888') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bc0a2cbd-a1d4-4ece-9a71-830689445888');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6afcb1c9-2093-42a4-b771-cba126f040af','Acoustic overlap','The condition where the coverage areas of two or more loudspeakers cover the same listening region, so their outputs sum acoustically. The amount of overlap sets how much level addition and phase-dependent interference occur in the shared area.','Overlap is when two speakers cover the same seats. Their sounds meet and mix there. Depending on timing, they can add up or cancel. Some overlap can raise level. Too much overlap causes uneven, comb-filtered sound.','Managing overlap lets designers trade added level and coverage against the interference ripple that heavy overlap creates.','A technician limits overlap between neighboring array cabinets, or time-aligns them, so combined response stays smooth rather than developing comb-filter notches.','System Design',ARRAY['Acoustic crossover zones','Comb filtering','Array steering','Boundary interaction','Coverage pattern']::text[],ARRAY['Assuming more overlap always means better coverage; it often increases interference.','Overlooking arrival-time differences that turn overlap into cancellation.','Confusing overlap of coverage with overlap of frequency bands.']::text[],ARRAY['Setting splay angles between line-array boxes.','Adding delay speakers that overlap the main coverage.','Explaining uneven audience coverage caused by overlapping fills.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic overlap');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6afcb1c9-2093-42a4-b771-cba126f040af','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6afcb1c9-2093-42a4-b771-cba126f040af') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6afcb1c9-2093-42a4-b771-cba126f040af');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b0d9706-9123-4077-bc3f-d6ca601755fd','Alternating current','An electric current whose direction and magnitude vary periodically with time, typically as a sinusoid, in contrast to steady direct current. Mains AC is distributed at standard frequencies of 50 Hz or 60 Hz, and its effective (RMS) value equals the peak divided by the square root of two.','Alternating current flows back and forth many times each second. Wall power is alternating current. In many countries it cycles 50 or 60 times per second. Its useful, or RMS, value is the peak divided by about 1.41. Audio signals are also alternating current.','AC lets voltage be transformed up and down efficiently for power distribution, and it is the natural form of audio signals, which swing positive and negative around zero.','For a 120 V RMS outlet the peak voltage is about 170 V; a technician uses the RMS value to compute real power and to size fuses and cabling.','Electrical Fundamentals',ARRAY['Capacitance','Cable inductance','70-volt and 100-volt systems','Amplifier gain','Balanced signaling']::text[],ARRAY['Confusing RMS voltage with peak voltage when calculating power.','Assuming mains frequency is the same worldwide; it is 50 Hz in many regions and 60 Hz in others.','UNSAFE: Treating mains AC as safe to probe by hand; contact with live conductors can be lethal, so follow lockout and insulation practice.']::text[],ARRAY['Checking that gear is set for the local mains voltage and frequency.','Calculating power draw of an amplifier rack from a wall circuit.','Explaining why an audio waveform swings above and below zero.']::text[],'Beginner','v(t) = Vpeak * sin(2*pi*f*t) ;  Vrms = Vpeak / sqrt(2)','The instantaneous voltage equals the peak voltage times the sine of two pi times frequency times time; the RMS voltage equals the peak voltage divided by the square root of two.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Alternating current');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b0d9706-9123-4077-bc3f-d6ca601755fd','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b0d9706-9123-4077-bc3f-d6ca601755fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b0d9706-9123-4077-bc3f-d6ca601755fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df560349-ad70-4136-a314-61c05a60d498','Amplifier clipping','A form of overload distortion that occurs when an amplifier is driven beyond its supply-rail limits, so signal peaks are flattened at the maximum output level. Clipping adds strong harmonic content and increases average power, and sustained clipping can damage loudspeaker drivers.','Clipping happens when an amplifier is pushed too hard. The tops of the waveform get cut off flat. This adds harsh harmonics to the sound. It also raises average power sent to the speakers. Long clipping can burn out tweeters.','Recognizing clipping tells a technician the system has run out of headroom, so gain or level must be reduced to protect sound quality and drivers.','A technician watches an amplifier''s clip LED and lowers input gain until peaks stop lighting it, keeping the signal below the rails with headroom to spare.','Amplifier Behavior',ARRAY['Amplifier gain','Class AB amplification','Class D amplification','Bridged amplifier operation','Headroom']::text[],ARRAY['Believing a bigger amplifier is more dangerous to speakers than clipping a small one.','UNSAFE: Running an amplifier into steady clipping to get more loudness; the added high-frequency energy can overheat and destroy tweeters.','Assuming clipping only affects level, not tone; it adds audible harmonic distortion.','Ignoring a lit clip indicator as long as nothing sounds obviously wrong.']::text[],ARRAY['Setting amplifier gain during a live-sound soundcheck.','Diagnosing a blown high-frequency driver after a loud event.','Explaining why a distorted PA sounds harsh at high levels.']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Amplifier clipping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df560349-ad70-4136-a314-61c05a60d498','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df560349-ad70-4136-a314-61c05a60d498') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df560349-ad70-4136-a314-61c05a60d498');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '42243ada-5dcb-42a8-8904-b1d3603802ee','Amplifier gain','The ratio of an amplifier''s output signal to its input signal, expressed as voltage gain in decibels as 20 times the base-ten logarithm of the output/input voltage ratio, or as power gain using a factor of 10. Pro audio amplifiers are commonly specified with a fixed voltage gain such as 26 or 32 dB.','Gain is how much an amplifier boosts a signal. It compares output to input. Engineers often state it in decibels. A common power amp gain is around 26 to 32 decibels. Higher gain means a small input drives a large output.','Knowing the gain lets a technician predict output voltage from a given input and set levels so the system reaches full power without clipping the amplifier first.','With 26 dB of voltage gain (a ratio of 20), a 1 V RMS input produces 20 V RMS out, which is 50 W into an 8 ohm load.','Amplifier Behavior',ARRAY['Amplifier clipping','Decibel','Bridged amplifier operation','Alternating current','Headroom']::text[],ARRAY['Mixing up voltage gain (factor of 20 in dB) with power gain (factor of 10 in dB).','Assuming the gain knob sets absolute output level rather than input sensitivity.','Thinking two amplifiers with the same wattage must have the same gain.']::text[],ARRAY['Gain-staging a signal chain from console to amplifier.','Matching amplifier sensitivity to a system processor''s output.','Calculating output voltage for a distributed-line design.']::text[],'Intermediate','Gv(dB) = 20*log10(Vout/Vin) ;  Gp(dB) = 10*log10(Pout/Pin)','Voltage gain in decibels equals twenty times the base-ten log of the output-to-input voltage ratio; power gain in decibels equals ten times the base-ten log of the output-to-input power ratio.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Amplifier gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '42243ada-5dcb-42a8-8904-b1d3603802ee','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='42243ada-5dcb-42a8-8904-b1d3603802ee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='42243ada-5dcb-42a8-8904-b1d3603802ee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7936cd61-e2ce-41b6-908d-94ded06a8518','Array steering','The control of a loudspeaker array''s radiated coverage direction and shape by adjusting the relative delay, level, and sometimes phase of its individual elements, rather than by physically re-aiming the cabinets. Digital signal processing applies element-by-element delays so the combined wavefront tilts or focuses toward the target area.','Array steering aims a speaker array using electronics, not by tilting it. Each driver gets its own tiny delay and level. Those settings tilt the combined sound beam. This points coverage at the audience. It is common in tall column speakers.','It lets designers direct sound onto listeners and away from reflective surfaces, improving clarity in reverberant rooms without moving hardware.','A technician enters the array height and target angle into the manufacturer''s software, which computes per-element delays that steer the beam downward onto the seating.','System Design',ARRAY['Acoustic overlap','Acoustic crossover zones','Buffering and end-to-end latency','Coverage pattern','Line array']::text[],ARRAY['Believing steering can point sound anywhere; the achievable range depends on array length and frequency.','Steering low frequencies as tightly as highs; long wavelengths steer far less.','Ignoring that added delays raise overall system latency.']::text[],ARRAY['Aiming a steerable column array in a reverberant church.','Directing coverage away from a hard rear wall.','Focusing an array on a balcony without physical tilt.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array steering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7936cd61-e2ce-41b6-908d-94ded06a8518','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7936cd61-e2ce-41b6-908d-94ded06a8518') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7936cd61-e2ce-41b6-908d-94ded06a8518');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eaed5ec9-398e-42f2-a5b6-7a7d98fbb979','Asynchronous endpoints','In USB audio, isochronous data endpoints that operate in asynchronous mode, where the audio device generates its own sample clock and uses an explicit feedback endpoint to tell the host how fast to send data. This decouples audio timing from the USB host clock, reducing clock jitter.','USB audio moves sound in timed packets. In asynchronous mode, the audio device keeps its own clock. It then tells the computer how fast to send data. This frees the audio from the computer''s timing. It usually lowers jitter and improves quality.','Asynchronous mode lets a high-quality converter run on its own low-jitter clock instead of following the less stable host clock, improving audio timing.','A technician chooses a USB interface that lists asynchronous USB audio when clock stability matters, knowing the device, not the computer, masters the sample rate.','Digital Audio Transport',ARRAY['Bit clock','Buffering and end-to-end latency','Clock mismatch during measurement','Boundary clocks','Jitter']::text[],ARRAY['Confusing ''asynchronous'' here with a lack of synchronization; the device is actually the clock master.','Assuming all USB audio is asynchronous; adaptive and synchronous modes also exist.','Thinking asynchronous mode removes the need for any buffering.']::text[],ARRAY['Selecting a USB audio interface for a mastering room.','Explaining why an external converter sounds cleaner than onboard USB audio.','Troubleshooting clock-related artifacts on a computer recording rig.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Asynchronous endpoints');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eaed5ec9-398e-42f2-a5b6-7a7d98fbb979','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eaed5ec9-398e-42f2-a5b6-7a7d98fbb979') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eaed5ec9-398e-42f2-a5b6-7a7d98fbb979');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'de6fa16b-3679-4739-8750-b4df7876cfb6','Balanced signaling','A method of transmitting an audio signal over two conductors carrying equal-impedance, opposite-polarity versions of the signal, with a receiver that responds to the difference between them. Interference coupled equally onto both conductors appears as common-mode noise and is rejected at the input.','Balanced signaling sends audio on two wires. The two carry the same signal with opposite polarity. Noise hits both wires almost equally. The input keeps the difference and cancels that shared noise. This is why balanced cables run long distances quietly.','It suppresses hum and interference picked up on long cable runs, so signals stay clean over distances that would be noisy on unbalanced lines.','A technician wires a stage microphone through a balanced XLR line so induced hum from nearby power cables is rejected as common-mode at the console input.','Signal Transmission',ARRAY['Cable resistance','Cable inductance','Alternating current','Capacitance','Common-mode rejection']::text[],ARRAY['Believing balance depends on the two signals being present; matched impedance, not opposite polarity alone, gives the rejection.','Assuming a balanced connector guarantees a balanced circuit inside the gear.','Confusing balanced with stereo because both use three-pin connectors.']::text[],ARRAY['Running microphone lines across a large stage.','Interconnecting racks in a noisy electrical environment.','Diagnosing hum caused by an unbalanced patch in a balanced chain.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Balanced signaling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'de6fa16b-3679-4739-8750-b4df7876cfb6','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='de6fa16b-3679-4739-8750-b4df7876cfb6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='de6fa16b-3679-4739-8750-b4df7876cfb6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '863889c0-5c3f-4681-b8c9-1180eca2db1d','Balloon interpolation','In loudspeaker directivity modeling, the estimation of a source''s output at angles between the discrete points of a measured spherical (balloon) directivity dataset by interpolating the measured magnitude and phase. Prediction software uses it to compute coverage at angles that were not directly measured.','A speaker''s output is measured at many angles. These points form a sphere of data called a balloon. Software must fill the gaps between angles. Balloon interpolation estimates the values in between. This lets design tools map coverage at any angle.','It allows acoustic prediction software to produce smooth, complete coverage maps from a finite set of measured directivity points.','A technician loads a manufacturer''s directivity data into modeling software, which interpolates the balloon to predict sound level at a seat lying between measured angles.','System Design',ARRAY['Array steering','Acoustic overlap','Coverage pattern','Directivity','Boundary interaction']::text[],ARRAY['Assuming interpolated values are as trustworthy as directly measured points.','Ignoring phase when interpolating, which distorts predicted summation between sources.','Using too coarse a measured grid, so interpolation smooths over real directivity detail.']::text[],ARRAY['Modeling a venue''s coverage in loudspeaker prediction software.','Comparing predicted and measured SPL at off-axis seats.','Evaluating the resolution of a manufacturer''s directivity data.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Balloon interpolation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '863889c0-5c3f-4681-b8c9-1180eca2db1d','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='863889c0-5c3f-4681-b8c9-1180eca2db1d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='863889c0-5c3f-4681-b8c9-1180eca2db1d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '54875eef-7bda-4722-9c87-8c6ce50cd150','Bit clock','The clock signal in a digital audio interface that times the transfer of each individual data bit on the serial link. Its frequency equals the sample rate multiplied by the bit depth and the number of channels carried in the stream.','Digital audio moves one bit at a time. The bit clock ticks once for each bit. Its speed depends on sample rate, bit depth, and channel count. It is much faster than the word clock. Devices must share it to read the data.','The bit clock keeps transmitter and receiver aligned at the individual-bit level so the serial audio data is sampled at the correct instants.','For stereo 24-bit audio at 48 kHz on an I2S link, the bit clock runs at 48000 x 24 x 2 = 2.304 MHz.','Digital Audio Transport',ARRAY['Asynchronous endpoints','Clock mismatch during measurement','Boundary clocks','Bit-depth effects on network load','Word clock']::text[],ARRAY['Confusing the bit clock with the slower word (sample) clock.','Assuming the bit-clock rate is fixed; it scales with sample rate, bit depth, and channels.','Overlooking that a wrong bit-clock edge choice can shift or corrupt the data.']::text[],ARRAY['Wiring an I2S link between a converter and a DSP chip.','Debugging a garbled digital audio connection.','Calculating the clock speed needed for a multichannel serial stream.']::text[],'Advanced','f_bitclock = fs * bit_depth * N_channels','The bit-clock frequency equals the sample rate times the bit depth times the number of channels carried on the serial link.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bit clock');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '54875eef-7bda-4722-9c87-8c6ce50cd150','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='54875eef-7bda-4722-9c87-8c6ce50cd150') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='54875eef-7bda-4722-9c87-8c6ce50cd150');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0fbf69f5-824c-4df6-ac73-e32536a99c99','Bit-depth effects on network load','The effect of chosen audio bit depth on the data rate an audio-over-network stream consumes, since each channel''s payload rate equals the sample rate times the bit depth. Moving from 16-bit to 24-bit samples raises the per-channel data rate by fifty percent, increasing required network bandwidth.','Networked audio sends samples as digital data. More bits per sample means more data to send. Going from 16-bit to 24-bit adds half again as much data. That uses more network bandwidth. It also limits how many channels fit on a link.','Understanding this helps a technician budget network bandwidth and channel counts when choosing sample rate and bit depth for audio-over-IP systems.','One channel of 48 kHz audio needs 48000 x 16 = 768 kbit/s at 16-bit, but 48000 x 24 = 1.152 Mbit/s at 24-bit, before packet overhead.','Digital Audio Transport',ARRAY['Channel count calculations','Buffering and end-to-end latency','Bit clock','Boundary clocks','Sample rate']::text[],ARRAY['Ignoring that bit depth, not just sample rate and channel count, sets the data rate.','Forgetting packet and protocol overhead when estimating real network load.','Assuming 24-bit costs the same bandwidth as 16-bit.']::text[],ARRAY['Planning channel counts on a Dante or AES67 network.','Deciding between 16-bit and 24-bit for a large distributed system.','Estimating switch and link capacity for a live-sound network.']::text[],'Intermediate','rate_per_channel = fs * bit_depth ;  total_rate = N_channels * fs * bit_depth','Each channel''s data rate equals the sample rate times the bit depth; the total stream rate multiplies that by the number of channels, before adding protocol overhead.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bit-depth effects on network load');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0fbf69f5-824c-4df6-ac73-e32536a99c99','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0fbf69f5-824c-4df6-ac73-e32536a99c99') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0fbf69f5-824c-4df6-ac73-e32536a99c99');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8eb1b3b7-b7c4-4305-a375-c3f8c3a0f58c','Boundary clocks','In IEEE 1588 Precision Time Protocol, a network device with multiple ports that terminates the timing on one port as a slave, recovers the time, and re-serves it as a master on its other ports. Boundary clocks segment a network so timing errors and message load do not accumulate across many hops.','Precision Time Protocol keeps networked audio devices in sync. A boundary clock is a switch that helps this. It listens to the master on one port. It then acts as a clock for devices on its other ports. This keeps timing steady across a big network.','Boundary clocks reduce accumulated jitter and reduce timing-message traffic in large audio networks by regenerating the clock at each hop.','A technician enables the boundary-clock function on a PTP-aware network switch so many Dante or AES67 endpoints stay tightly synchronized across several switch hops.','Network Synchronization',ARRAY['Asynchronous endpoints','Clock mismatch during measurement','Bit clock','Buffering and end-to-end latency','Precision Time Protocol']::text[],ARRAY['Confusing a boundary clock with a transparent clock; the boundary clock terminates and regenerates the timing.','Assuming any network switch handles PTP; boundary-clock support must be present and enabled.','Mixing incompatible PTP profiles across boundary-clock switches.']::text[],ARRAY['Designing a large audio-over-IP network with many switches.','Improving sync stability across multiple network hops.','Configuring PTP settings on managed switches for AES67.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary clocks');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8eb1b3b7-b7c4-4305-a375-c3f8c3a0f58c','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8eb1b3b7-b7c4-4305-a375-c3f8c3a0f58c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8eb1b3b7-b7c4-4305-a375-c3f8c3a0f58c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '709a6856-2417-47f8-829a-353e41007595','Boundary conditions','In acoustics, the constraints a physical surface places on a sound field at that surface, which determine how waves reflect. A rigid boundary forces the normal particle velocity to zero and produces a pressure maximum, while a pressure-release (soft) boundary forces the sound pressure to zero.','Boundary conditions describe what happens where sound meets a surface. A hard wall stops air motion into it. That makes pressure pile up there. A very soft surface forces the pressure to zero instead. These rules decide how sound reflects.','Boundary conditions let acousticians predict reflections, room modes, and standing-wave patterns by defining wave behavior at each surface.','A technician treats a hard concrete wall as a rigid boundary, expecting a pressure buildup and strong reflection, so bass traps and absorption are placed accordingly.','Acoustics Concept',ARRAY['Boundary interaction','Standing wave','Room modes','Reflection','Acoustic overlap']::text[],ARRAY['Assuming every surface reflects sound the same way regardless of its properties.','Confusing a rigid (velocity-zero) boundary with a pressure-release (pressure-zero) boundary.','Ignoring that real surfaces are partly absorbing, between the two ideal cases.']::text[],ARRAY['Predicting room modes in a small studio.','Explaining bass buildup at a hard wall.','Modeling reflections in an acoustics simulation.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary conditions');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '709a6856-2417-47f8-829a-353e41007595','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='709a6856-2417-47f8-829a-353e41007595') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='709a6856-2417-47f8-829a-353e41007595');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '905eed57-453f-420e-886b-3ec7c3093c62','Boundary interaction','The change in a loudspeaker''s radiated response caused by nearby reflective surfaces such as floors, walls, or corners. Reflections from these boundaries combine with the direct sound, producing low-frequency reinforcement and frequency-dependent peaks and dips (comb filtering) that depend on distance to the surface.','A speaker near a wall or floor behaves differently. The surface reflects sound back. That reflection mixes with the direct sound. It can boost bass and cause peaks and dips. How far the speaker sits from the surface sets which notes change.','Understanding boundary interaction lets technicians place and equalize loudspeakers to control unwanted bass buildup and comb-filter dips near surfaces.','A technician moving a subwoofer into a corner expects extra low-frequency output from added boundaries and trims subwoofer gain to compensate.','Acoustics Concept',ARRAY['Boundary conditions','Acoustic overlap','Comb filtering','Standing wave','Loudspeaker placement']::text[],ARRAY['Assuming a loudspeaker''s anechoic response holds once it is placed near surfaces.','Overlooking floor-bounce cancellation when a speaker sits above a reflective floor.','Treating corner placement as always beneficial rather than as a strong response change.']::text[],ARRAY['Placing subwoofers relative to walls and corners.','Diagnosing a midrange dip from a floor reflection.','Setting studio monitor distance from the rear wall.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary interaction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '905eed57-453f-420e-886b-3ec7c3093c62','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='905eed57-453f-420e-886b-3ec7c3093c62') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='905eed57-453f-420e-886b-3ec7c3093c62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '06bbf0f8-dc04-4ee9-beb8-4458e715e4a8','Bridged amplifier operation','A mode in which two amplifier channels are driven with equal but opposite-polarity signals and the loudspeaker is connected across the two live outputs, so it sees the sum of the two channels'' voltage swings. This roughly doubles output voltage and, into a given load, quadruples available power, but each channel effectively sees half the load impedance.','Bridging joins two amplifier channels into one bigger channel. The two work in opposite directions. The speaker connects across both hot outputs. This doubles the voltage and greatly raises power. But each channel now sees half the speaker''s impedance.','Bridging lets one two-channel amplifier deliver much higher power to a single load, useful for driving large subwoofers or long distribution lines.','Bridging into an 8 ohm load makes each channel behave as if driving 4 ohms, so a technician must confirm the amplifier is rated for that per-channel load before bridging.','Amplifier Behavior',ARRAY['Amplifier gain','Amplifier clipping','Class D amplification','70-volt and 100-volt systems','Impedance']::text[],ARRAY['Forgetting that a bridged load is effectively halved per channel.','UNSAFE: Bridging into an impedance below the amplifier''s rated minimum, which can overheat the amplifier and cause failure or fire.','UNSAFE: Grounding one bridged output terminal; in bridged mode neither output is at ground, so both must stay isolated.','Assuming any two channels can be bridged without a dedicated bridge mode or switch.']::text[],ARRAY['Driving a large subwoofer from a two-channel amplifier.','Feeding a high-power 70 V line from a bridged output.','Checking load ratings before enabling bridge mode.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bridged amplifier operation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '06bbf0f8-dc04-4ee9-beb8-4458e715e4a8','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='06bbf0f8-dc04-4ee9-beb8-4458e715e4a8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='06bbf0f8-dc04-4ee9-beb8-4458e715e4a8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '42d8f04b-44af-4883-bd39-6727c595b60f','Buffering and end-to-end latency','The relationship between the buffers that hold audio data at each stage of a digital or networked audio path and the total delay from input to output. Larger buffers guard against dropouts and network timing variation but add latency, so total end-to-end delay is the sum of conversion, processing, packet, and playout-buffer times.','Digital audio is held briefly in buffers along the way. Buffers protect against gaps and timing jitter. But every buffer adds delay. End-to-end latency is the total time from input to output. Bigger buffers are safer but slower.','Balancing buffer size against latency lets a technician keep audio glitch-free while holding delay low enough for live monitoring and lip-sync.','A technician sets a Dante receiver''s latency to 1 ms on a small, well-managed network but raises it to 5 ms across many switch hops to prevent dropouts.','Digital Audio Transport',ARRAY['Boundary clocks','Asynchronous endpoints','Bit-depth effects on network load','Channel count calculations','Jitter']::text[],ARRAY['Setting the smallest buffer for lowest latency and then suffering dropouts.','Ignoring that each device in the chain adds its own buffer delay.','Assuming network audio latency is fixed rather than a configurable trade-off.']::text[],ARRAY['Tuning in-ear monitor latency for performers.','Setting receiver latency on a large audio-over-IP network.','Diagnosing pops caused by too-small buffers.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Buffering and end-to-end latency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '42d8f04b-44af-4883-bd39-6727c595b60f','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='42d8f04b-44af-4883-bd39-6727c595b60f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='42d8f04b-44af-4883-bd39-6727c595b60f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '07b464fe-42b6-49f3-aa8b-6c1762acce19','C weighting','A standardized frequency-weighting curve for sound-level measurement that is nearly flat across the mid-band and rolls off only gently at the frequency extremes, approximating the ear''s response to loud sounds near the 100-phon contour. It is defined by pole frequencies of 20.6 Hz and 12194 Hz and normalized to 0 dB at 1 kHz.','C-weighting is a filter for measuring loud sounds. It stays flat through most of the range. It rolls off only slightly at the very low and very high ends. It keeps more bass than A-weighting. Meters show it as dB(C).','C-weighting gives a fair single-number level for loud, full-range sources and is used to measure peak levels and bass content that A-weighting under-represents.','A technician measures a concert''s low-frequency level in dB(C) to check it against a venue''s bass limit, since dB(A) would understate the bass.','Measurement Weighting',ARRAY['A weighting','Sound level meter','Calibration offsets','Decibel','Equal-loudness contour']::text[],ARRAY['Assuming C-weighting is completely flat; it still rolls off at the extremes.','Using dB(A) where a loud, bass-heavy source calls for dB(C).','Reporting a level without stating whether it is A- or C-weighted.']::text[],ARRAY['Measuring peak concert sound levels.','Assessing low-frequency output against a noise limit.','Comparing A- and C-weighted readings to gauge bass content.']::text[],'Intermediate','R_C(f) = (12194^2 * f^2) / [ (f^2 + 20.6^2)(f^2 + 12194^2) ] ;  C(f) = 20*log10(R_C(f)) + 0.06 dB','The C-weighting gain in decibels equals twenty times the base-ten log of a magnitude response set by the 20.6 Hz and 12194 Hz corner frequencies, plus a small 0.06 dB offset for 0 dB at 1 kHz.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='C weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '07b464fe-42b6-49f3-aa8b-6c1762acce19','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='07b464fe-42b6-49f3-aa8b-6c1762acce19') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='07b464fe-42b6-49f3-aa8b-6c1762acce19');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f66c21dc-45ea-4d7c-8fa9-14d3ef92f061','Cable inductance','The series inductance per unit length of a cable, which opposes changes in current and whose reactance rises with frequency as two pi times frequency times inductance. In long loudspeaker cables it contributes a small high-frequency loss and interacts with the load impedance.','Every cable has a little inductance. Inductance resists fast changes in current. Its effect grows at higher frequencies. On long speaker runs it can slightly dull the highs. It adds to the cable''s total impedance.','Accounting for cable inductance helps a technician understand high-frequency loss and phase effects on long cable runs.','For a long speaker run, a technician uses adequately sized, low-inductance cable because inductive reactance X_L = 2*pi*f*L grows with frequency and can trim the top end.','Cable Electrical Properties',ARRAY['Cable resistance','Capacitance','Balanced signaling','Alternating current','Impedance']::text[],ARRAY['Assuming cable inductance matters equally at all frequencies; its effect grows with frequency.','Overstating cable inductance effects on short runs where resistance dominates.','Confusing series inductance with the cable''s shunt capacitance.']::text[],ARRAY['Specifying long loudspeaker cable runs in a large venue.','Explaining slight high-frequency loss on a long speaker line.','Comparing cable constructions for high-frequency performance.']::text[],'Advanced','X_L = 2*pi*f*L','The inductive reactance equals two pi times the frequency times the inductance, so the opposition to current from inductance rises with frequency.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cable inductance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f66c21dc-45ea-4d7c-8fa9-14d3ef92f061','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f66c21dc-45ea-4d7c-8fa9-14d3ef92f061') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f66c21dc-45ea-4d7c-8fa9-14d3ef92f061');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e35d7951-0d52-48bc-b280-10024107c649','Cable resistance','The direct-current resistance of a cable conductor, equal to the material resistivity times length divided by cross-sectional area. In loudspeaker cabling it causes power loss and lowers the effective damping factor by adding series resistance between amplifier and driver.','A cable''s wire has resistance. Longer or thinner wire has more resistance. This wastes some power as heat. It also weakens the amplifier''s grip on the speaker. Thicker, shorter cable keeps resistance low.','Knowing cable resistance lets a technician size conductors so power loss and damping-factor degradation stay acceptable over the run length.','A 30 m run of thin cable, counting both the send and return conductors, can add an ohm or more of series resistance; using a larger gauge keeps resistance a small fraction of an 8 ohm load.','Cable Electrical Properties',ARRAY['Cable inductance','Capacitance','Amplifier gain','70-volt and 100-volt systems','Damping factor']::text[],ARRAY['Ignoring that cable resistance counts twice, on both the send and return conductors.','Using undersized cable on long low-impedance speaker runs.','Confusing DC resistance with the cable''s frequency-dependent impedance.']::text[],ARRAY['Choosing wire gauge for a long low-impedance speaker run.','Explaining power loss between amplifier and loudspeaker.','Deciding when a distributed 70 V line is preferable to low impedance.']::text[],'Intermediate','R = rho * L / A','Conductor resistance equals the material resistivity times the conductor length divided by its cross-sectional area, so longer or thinner wire has more resistance.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cable resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e35d7951-0d52-48bc-b280-10024107c649','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e35d7951-0d52-48bc-b280-10024107c649') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e35d7951-0d52-48bc-b280-10024107c649');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f59b0fc4-c40b-4fe0-b652-10e77c7ea715','Calibration offsets','Correction values applied to an instrument''s readings so its indicated output matches a known reference standard. A calibration offset removes a repeatable systematic error, such as the difference between a sound level meter''s reading and a calibrator''s certified level.','Instruments drift from true readings over time. Calibration compares them to a known reference. Any fixed difference becomes an offset. Adding that offset corrects the readings. This fixes steady bias but not random scatter.','Calibration offsets keep measurements traceable and accurate by cancelling known, repeatable errors in an instrument.','A technician applies a 94 dB acoustic calibrator to a sound level meter; if it reads 93.7 dB, a +0.3 dB offset is set so measurements match the reference.','Measurement Concept',ARRAY['Accuracy versus precision','A weighting','C weighting','Systematic error','Traceability']::text[],ARRAY['Believing an offset can fix random scatter; it only corrects a fixed bias.','Applying an old offset after conditions or the instrument have changed.','Skipping calibration because readings look internally consistent.']::text[],ARRAY['Calibrating a sound level meter before field measurements.','Aligning a distortion analyzer to a reference level.','Correcting a microphone''s sensitivity in measurement software.']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Calibration offsets');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f59b0fc4-c40b-4fe0-b652-10e77c7ea715','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f59b0fc4-c40b-4fe0-b652-10e77c7ea715') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f59b0fc4-c40b-4fe0-b652-10e77c7ea715');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bc50ae63-07c6-4e5b-9daa-e9e344dc6aea','Capacitance','The property of a conductor arrangement to store electric charge per unit voltage, measured in farads, where capacitance equals stored charge divided by voltage. In audio cabling, distributed capacitance between conductors shunts high frequencies and can roll off the top end on long runs driven by high-impedance sources.','Capacitance is the ability to store electric charge. A capacitor holds charge when a voltage is applied. Cables have capacitance between their wires. On long cables this can dull high frequencies. It matters most with high-impedance sources.','Understanding capacitance explains high-frequency loss on cables and underlies filters, coupling, and energy storage throughout audio electronics.','A long unbalanced instrument cable with high capacitance loaded by a guitar pickup can noticeably cut treble; a technician keeps such runs short or uses a buffer.','Electrical Fundamentals',ARRAY['Cable inductance','Cable resistance','Alternating current','Balanced signaling','Impedance']::text[],ARRAY['Assuming cable capacitance is negligible with any source impedance.','Confusing capacitance (charge storage) with inductance (opposition to current change).','Overlooking that capacitance stores energy and can hold charge after power is removed.']::text[],ARRAY['Explaining treble loss on a long passive instrument cable.','Choosing low-capacitance cable for high-impedance sources.','Understanding coupling capacitors in an audio circuit.']::text[],'Intermediate','C = Q / V ;  E = 0.5 * C * V^2','Capacitance equals the stored charge divided by the voltage across it; the energy stored equals one half the capacitance times the voltage squared.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Capacitance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bc50ae63-07c6-4e5b-9daa-e9e344dc6aea','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bc50ae63-07c6-4e5b-9daa-e9e344dc6aea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bc50ae63-07c6-4e5b-9daa-e9e344dc6aea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55950734-6a7d-43a3-ad35-9f9f8a983f73','Channel count calculations','The arithmetic that determines how many audio channels a digital link or network can carry, given the available data rate, the sample rate, and the bit depth. The maximum channel count is the usable bandwidth divided by the product of sample rate and bit depth, before allowing for packet and protocol overhead.','Each audio channel uses a set amount of data. That depends on sample rate and bit depth. A link has a limited data rate. Dividing the link rate by the per-channel rate gives the channel count. Overhead lowers this a little.','These calculations let a technician plan how many channels a cable, converter, or network link can support before it runs out of capacity.','One channel at 48 kHz, 24-bit needs about 1.152 Mbit/s; ignoring overhead, a 100 Mbit/s link could carry roughly 86 such channels, so a gigabit link carries far more.','Digital Audio Transport',ARRAY['Bit-depth effects on network load','Bit clock','Buffering and end-to-end latency','Boundary clocks','Sample rate']::text[],ARRAY['Forgetting to subtract packet and protocol overhead from raw link capacity.','Assuming channel count is fixed regardless of sample rate and bit depth.','Overlooking device and switch limits that cap channels below the theoretical maximum.']::text[],ARRAY['Planning a Dante or AES67 network''s channel capacity.','Checking how many channels a MADI or serial link can carry.','Sizing a switch and its uplinks for a large audio system.']::text[],'Intermediate','N_channels_max = floor( usable_bitrate / (fs * bit_depth) )','The maximum channel count is the usable data rate divided by the product of the sample rate and bit depth, rounded down, before deducting protocol overhead.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Channel count calculations');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55950734-6a7d-43a3-ad35-9f9f8a983f73','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55950734-6a7d-43a3-ad35-9f9f8a983f73') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55950734-6a7d-43a3-ad35-9f9f8a983f73');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b44f6ab-58c2-463f-97fd-d1a66bcc33d7','Class A amplification','An amplifier output stage whose active devices conduct for the entire input cycle, biased so current flows continuously even with no signal. It offers low distortion and simple linearity but is inefficient, dissipating substantial heat because the devices conduct at all times.','In Class A, the output devices are always on. They pass current for the whole waveform. This gives smooth, low-distortion sound. But it wastes a lot of power as heat. So Class A runs hot and is inefficient.','Class A is used where low distortion matters more than efficiency, such as in some preamps and high-end audio stages.','A technician expects a Class A power stage to run hot and draw significant idle current, so it needs generous heatsinking and ventilation.','Amplifier Class',ARRAY['Class AB amplification','Class B amplification','Class D amplification','Amplifier clipping','Amplifier gain']::text[],ARRAY['Assuming Class A is always audibly superior regardless of the application.','Overlooking its low efficiency, typically well under a third at full output.','UNSAFE: Enclosing a Class A stage without airflow; its constant heat can cause thermal failure or burns.']::text[],ARRAY['Explaining why a preamp stays warm at idle.','Comparing amplifier topologies for a monitoring chain.','Justifying heatsink size in a Class A design.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Class A amplification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b44f6ab-58c2-463f-97fd-d1a66bcc33d7','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b44f6ab-58c2-463f-97fd-d1a66bcc33d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b44f6ab-58c2-463f-97fd-d1a66bcc33d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75ac3227-8046-4f5b-883d-6d44ae0ad5a1','Class AB amplification','A push-pull output stage biased so that each device conducts for slightly more than half of the input cycle, with a small overlap around the zero crossing. This bias overlap greatly reduces the crossover distortion of Class B while keeping efficiency far higher than Class A.','Class AB uses two devices in a push-pull pair. Each handles about half the waveform. A small overlap keeps them both on near the middle. This removes the harsh crossover glitch of Class B. It is efficient and clean enough for most power amps.','Class AB is the common compromise for audio power amplifiers, balancing good linearity against reasonable efficiency and heat.','A technician recognizes most conventional rack power amplifiers as Class AB and provides cooling for their moderate heat under load.','Amplifier Class',ARRAY['Class A amplification','Class B amplification','Class D amplification','Amplifier clipping','Amplifier gain']::text[],ARRAY['Thinking Class AB is a separate device type rather than biased between Class A and Class B.','Assuming it has no crossover distortion; a small residual can remain if bias is set wrong.','Expecting Class D efficiency from a Class AB amplifier.']::text[],ARRAY['Identifying the topology of a conventional touring power amp.','Explaining why an amp runs cooler than Class A but warmer than Class D.','Setting or checking output-stage bias during service.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Class AB amplification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75ac3227-8046-4f5b-883d-6d44ae0ad5a1','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75ac3227-8046-4f5b-883d-6d44ae0ad5a1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75ac3227-8046-4f5b-883d-6d44ae0ad5a1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f660bb9e-1bf5-40bc-ab9f-43f5e9f898b1','Class B amplification','A push-pull output stage in which each device conducts for essentially half of the input cycle and is off for the other half, with no bias overlap. It is more efficient than Class A but produces crossover distortion at the zero crossing where the devices hand off.','In Class B, two devices split the waveform. One handles the top half, the other the bottom. Each is off for its idle half. This is efficient. But the handoff at the middle causes crossover distortion.','Class B illustrates the efficiency gain of push-pull operation and the crossover-distortion problem that Class AB was developed to solve.','A technician troubleshooting audible zero-crossing distortion suspects a stage running too close to pure Class B and checks the bias setting.','Amplifier Class',ARRAY['Class A amplification','Class AB amplification','Class D amplification','Amplifier clipping','Amplifier gain']::text[],ARRAY['Assuming Class B is distortion-free because it is push-pull.','Confusing Class B with Class AB, which adds bias to reduce crossover distortion.','Ignoring crossover distortion because it is worst at low signal levels.']::text[],ARRAY['Explaining the origin of crossover distortion.','Contrasting amplifier classes in a training session.','Diagnosing zero-crossing distortion in an output stage.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Class B amplification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f660bb9e-1bf5-40bc-ab9f-43f5e9f898b1','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f660bb9e-1bf5-40bc-ab9f-43f5e9f898b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f660bb9e-1bf5-40bc-ab9f-43f5e9f898b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b280f10-4ec4-4a27-8aa9-f6cbc8311513','Class D amplification','A switching amplifier whose output devices operate as high-speed on/off switches, driven by a pulse-width or similar modulation of the audio signal, followed by a low-pass filter that reconstructs the analog waveform. Because the devices are either fully on or fully off, dissipation is low and efficiency is high, often above ninety percent.','Class D amplifiers switch their output devices fully on or off very fast. The switching pattern encodes the audio. A filter then smooths it back to sound. Because the devices are never half-on, little power is wasted. So Class D runs cool and efficient.','High efficiency makes Class D ideal for lightweight, high-power, and battery or installed amplifiers where heat and size must stay low.','A technician chooses a compact Class D amplifier for a powered loudspeaker because it delivers high power with little heat and low weight.','Amplifier Class',ARRAY['Class AB amplification','Class A amplification','Class B amplification','Amplifier clipping','Bridged amplifier operation']::text[],ARRAY['Assuming the ''D'' stands for ''digital''; Class D is an analog switching amplifier.','Believing Class D always sounds worse; modern designs measure very well.','Omitting or mis-designing the output filter, which is essential to reconstruct the signal.']::text[],ARRAY['Selecting an amplifier for a powered speaker or subwoofer.','Explaining why modern amps are light yet powerful.','Comparing efficiency across amplifier classes.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Class D amplification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b280f10-4ec4-4a27-8aa9-f6cbc8311513','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b280f10-4ec4-4a27-8aa9-f6cbc8311513') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b280f10-4ec4-4a27-8aa9-f6cbc8311513');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '89524a39-e5df-42ce-98d0-47d8846af00c','Clock mismatch during measurement','An error condition in which two digital devices in a measurement path run on slightly different sample clocks that are not synchronized. The resulting rate offset causes sample slips, dropouts, or a slow drift in relative phase that corrupts dual-channel or transfer-function measurements.','Digital devices each keep their own clock. If two clocks in a measurement are not locked together, they drift apart. This causes clicks, dropouts, or a slow phase slide. It ruins transfer-function and phase readings. Locking to one clock fixes it.','Recognizing clock mismatch tells a technician to synchronize devices to a common clock before trusting phase- or timing-sensitive measurements.','A technician sees measured phase drifting steadily during a dual-channel FFT measurement and locks the interface and device to a shared word clock to stop the drift.','Measurement Concept',ARRAY['Bit clock','Boundary clocks','Asynchronous endpoints','Accuracy versus precision','Word clock']::text[],ARRAY['Assuming two unlinked digital devices share the same sample rate exactly.','Blaming acoustics for a slow phase drift that is really a clock offset.','Ignoring occasional clicks that signal a sample-rate mismatch.']::text[],ARRAY['Running a dual-channel transfer-function measurement of a sound system.','Diagnosing steady phase drift in analysis software.','Synchronizing a measurement interface to an external clock.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clock mismatch during measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '89524a39-e5df-42ce-98d0-47d8846af00c','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='89524a39-e5df-42ce-98d0-47d8846af00c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='89524a39-e5df-42ce-98d0-47d8846af00c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '436d3769-e241-44c4-b6ae-41d1b1f7cbb7','Clock-master election','Clock-master election is the automatic process by which devices on a shared audio network agree on one device to act as the master timing reference (grandmaster) that all others synchronize to. Protocols such as IEEE 1588 Precision Time Protocol use a Best Master Clock Algorithm to compare each clock''s advertised quality and priority and select the winner.','Networked audio gear must share one common clock. The devices talk to each other and pick one unit as the timing leader. They compare each clock''s quality and a set priority. The best clock wins, and the rest follow it.','It ensures every device samples and plays audio on the same time base, preventing drift, clicks, and dropouts across a digital audio network.','A technician sets a high clock priority on a preferred device, such as a stable interface or dedicated clock, so the network reliably elects it, then confirms lock in the control software.','Networking / Clocking',ARRAY['Embedded clocking','Deterministic latency','Discovery and subscription','Word clock','Precision Time Protocol']::text[],ARRAY['Assuming the loudest or newest device becomes master; election is decided by advertised clock quality and priority, not by device role.','Leaving two devices at equal top priority, which invites avoidable master changes; set a clear priority order.','Confusing the timing master with audio routing; the clock master and the signal patch are separate.']::text[],ARRAY['Powering up a Dante or AES67 network and confirming which unit became grandmaster.','A clock master dropping offline and the network re-electing a new one.','Setting priority so a dedicated master clock is always chosen over converters.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clock-master election');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '436d3769-e241-44c4-b6ae-41d1b1f7cbb7','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='436d3769-e241-44c4-b6ae-41d1b1f7cbb7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='436d3769-e241-44c4-b6ae-41d1b1f7cbb7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '63e26f29-3473-4013-9b42-9c579ce81b65','Comb filtering from multiple loudspeakers','Comb filtering is a series of regularly spaced peaks and notches in the frequency response caused when the same signal reaches a listener from two or more loudspeakers with a small arrival-time difference, so the copies alternately add and cancel. The deepest notches fall at odd multiples of one over twice the time difference, and successive notches repeat every 1/Delta-t hertz.','Two speakers can send the same sound to one spot. If one arrives a little later, the copies clash. At some pitches they add and get louder. At others they cancel and drop out. The response then looks like the teeth of a comb.','Recognizing comb filtering explains the hollow, uneven tone in speaker overlap zones and guides how systems are placed, aimed, and delayed to reduce it.','With a 1 ms arrival difference, notches appear near 500 Hz, 1500 Hz, and so on; a technician measures this and repositions or delays a speaker to move the overlap out of the audience.','Acoustics / Measurement',ARRAY['Delay speakers','Delay shading','Coverage versus throw','Phase','Path-length difference']::text[],ARRAY['Blaming an equalizer for the dips; comb filtering is a time-and-space effect that moving the microphone changes.','Thinking one setting fixes it everywhere; the notch frequencies shift with each listener position.','Ignoring reflections; a wall or floor bounce combs with the direct sound just like a second speaker.']::text[],ARRAY['Two front speakers overlapping at center stage.','Measuring a hollow sound where main and fill coverage cross.','A microphone near a hard tabletop picking up its own reflection.']::text[],'Intermediate','f_notch = (2k-1) / (2*Delta_t),  k = 1,2,3...;   spacing Delta_f = 1 / Delta_t','The deepest cancellations sit at odd multiples of one over twice the arrival-time difference, and the spacing between notches equals one over that time difference.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Comb filtering from multiple loudspeakers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '63e26f29-3473-4013-9b42-9c579ce81b65','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='63e26f29-3473-4013-9b42-9c579ce81b65') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='63e26f29-3473-4013-9b42-9c579ce81b65');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ab2b3ca-edc2-4a2a-988a-e159ca4f87fb','Complex numbers','A complex number combines a real part and an imaginary part in the form a + jb, where the imaginary unit j satisfies j-squared = -1. In audio they represent magnitude and phase together, and Euler''s relation e^(j-theta) = cos(theta) + j*sin(theta) links them to the sinusoids used throughout signal analysis.','A complex number has two parts joined together. One part is ordinary; the other uses a special unit whose square is minus one. Engineers use them to hold size and timing at once. This makes it easy to describe waves and filters.','They give a compact way to carry amplitude and phase together, which underlies transfer functions, the Fourier transform, and filter design.','A technician reading a transfer-function plot is viewing complex values shown as magnitude in decibels and phase in degrees at each frequency.','Mathematics',ARRAY['Differential equations','Eigenvalues','Dot products','Phase','Fourier transform']::text[],ARRAY['Reading j as a mistake rather than a defined unit that represents a 90-degree phase shift.','Thinking the imaginary part is unreal or unmeasurable; it maps directly to phase.','Forgetting that magnitude uses both parts, not just the real one.']::text[],ARRAY['Interpreting magnitude and phase from a measurement system.','Understanding why filters shift phase as well as level.','Following a DSP manual that writes signals in exponential form.']::text[],'Advanced','z = a + j*b,  j^2 = -1,  |z| = sqrt(a^2 + b^2),  e^(j*theta) = cos(theta) + j*sin(theta)','A complex number is a real part plus an imaginary part; its magnitude is the square root of the sum of the squared parts, and the exponential of an imaginary angle equals cosine plus j times sine.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex numbers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ab2b3ca-edc2-4a2a-988a-e159ca4f87fb','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ab2b3ca-edc2-4a2a-988a-e159ca4f87fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ab2b3ca-edc2-4a2a-988a-e159ca4f87fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f4d0f53a-b062-4734-b28d-d5049f780338','Confidence intervals','A confidence interval is a range computed from sample data that is expected to contain the true population value at a stated confidence level, such as 95%. For a mean it is the sample mean plus and minus a multiplier times the standard error, and the interval narrows as the sample size grows.','You often measure a few samples, not everything. A confidence interval gives a range likely to hold the true value. A 95 percent level means the method captures the truth most of the time. More samples make the range tighter.','It expresses how much uncertainty surrounds a measured average, so results carry honest error bounds instead of a single exact number.','After averaging ten level readings, a technician reports the mean plus or minus its 95% interval to show how repeatable the measurement is.','Statistics',ARRAY['Standard deviation','Mean','Sample size','Measurement uncertainty','Distortion measurement']::text[],ARRAY['Saying there is a 95% chance the true value lies in this one interval; the confidence describes the long-run method.','Ignoring sample size; a tiny sample gives a wide, weak interval.','Confusing the interval with the spread of the raw data itself.']::text[],ARRAY['Reporting the repeatability of a set of sound-level readings.','Comparing two measured results to see if they truly differ.','Stating error bars on a measured frequency response.']::text[],'Advanced','CI = x-bar +/- z*(sigma / sqrt(n))   (z ~= 1.96 for 95%)','The interval equals the sample mean plus and minus a confidence multiplier times the standard deviation divided by the square root of the sample size.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Confidence intervals');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f4d0f53a-b062-4734-b28d-d5049f780338','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f4d0f53a-b062-4734-b28d-d5049f780338') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f4d0f53a-b062-4734-b28d-d5049f780338');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '735fd65e-61ff-4319-8868-742ab5b4a514','Constant-Hz bandwidth','Constant-Hz bandwidth describes analysis in which every frequency band has the same width in hertz, as produced by an FFT/DFT analyzer with linearly spaced bins. Because the band width is fixed, resolution is uniform on a linear frequency axis but looks very fine at high frequencies and coarse at low frequencies on a logarithmic (octave) scale.','Some analyzers split sound into equal-width slices in hertz. Each slice covers the same number of hertz. This gives even detail across a straight frequency scale. On a musical, doubling scale the low end looks coarse. The high end then looks very detailed.','It gives uniform absolute resolution, which suits finding fixed-frequency tones, hum, and harmonics.','Using a 1 Hz-per-bin FFT, a technician can clearly separate 60 Hz mains hum from a nearby 50 Hz tone that an octave analyzer would blur together.','Measurement / Analysis',ARRAY['Constant-percentage bandwidth','Distortion measurement','Fast Fourier transform','Spectrum analyzer','Resolution']::text[],ARRAY['Assuming FFT bins match how we hear; hearing is closer to constant-percentage, not constant-Hz.','Thinking more bins always help; longer FFTs trade time resolution for frequency resolution.','Comparing a constant-Hz plot directly to a one-third-octave plot without noting the different band widths.']::text[],ARRAY['Hunting a narrow hum component down in a noise floor.','Separating closely spaced tones during a distortion test.','Reading an FFT display while troubleshooting electrical noise.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant-Hz bandwidth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '735fd65e-61ff-4319-8868-742ab5b4a514','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='735fd65e-61ff-4319-8868-742ab5b4a514') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='735fd65e-61ff-4319-8868-742ab5b4a514');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2c1e8c20-f434-4086-b2e3-346412dc390b','Constant-percentage bandwidth','Constant-percentage bandwidth describes analysis in which each band''s width is a fixed fraction of its center frequency, so the bands widen in hertz as frequency rises. Octave and one-third-octave filters are the common examples; a band''s width in hertz equals its center frequency divided by the filter''s quality factor Q.','Other analyzers use slices that grow with pitch. Each slice covers a set percentage of its center frequency. Low bands are narrow in hertz; high bands are wide. This matches how people hear pitch. Octave and third-octave bands work this way.','It mirrors the ear''s roughly logarithmic response to pitch, making it the standard basis for room and system equalization work.','On a one-third-octave analyzer the 1 kHz band is about 230 Hz wide while the 100 Hz band is about 23 Hz wide, giving even musical resolution for tuning a room.','Measurement / Analysis',ARRAY['Constant-Hz bandwidth','Octave band','Quality factor (Q)','Real-time analyzer','Room equalization']::text[],ARRAY['Calling every graphic-EQ band an octave; many are one-third-octave, a different width.','Expecting equal hertz spacing; these bands widen with frequency.','Confusing filter Q with bandwidth; they are inversely related, not the same thing.']::text[],ARRAY['Tuning a room with a one-third-octave real-time analyzer.','Setting a graphic equalizer whose bands follow octave fractions.','Comparing octave-band noise data against a fine FFT.']::text[],'Intermediate','BW = f_c / Q;  fractional-octave width BW ~= f_c*(2^(1/2N) - 2^(-1/2N))','The band width in hertz equals the center frequency divided by the filter''s quality factor, so a fixed Q keeps the percentage bandwidth constant across frequency.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant-percentage bandwidth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2c1e8c20-f434-4086-b2e3-346412dc390b','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2c1e8c20-f434-4086-b2e3-346412dc390b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2c1e8c20-f434-4086-b2e3-346412dc390b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '321ebeea-6c42-4019-b748-a0b89d0532c8','Constant-voltage distributed systems','A constant-voltage (also called 70-volt or 100-volt) distributed system uses a step-up transformer at the amplifier and step-down transformers at each loudspeaker so that many speakers share one line at a fixed reference voltage (70.7 V or 100 V at full amplifier output). Each loudspeaker''s power tap is rated in watts, and the sum of all tap wattages must stay within the amplifier''s rating.','Long speaker runs lose power over thin wire. These systems raise the line voltage to send power efficiently. A transformer at each speaker steps it back down. You pick each speaker''s power with a labeled tap. The total taps must stay below the amplifier''s rating.','It lets one amplifier drive dozens of loudspeakers over long, thin cable with low loss, which suits paging, background music, and public address in large buildings.','A technician sets each ceiling speaker to a 5 W tap; forty speakers then total 200 W, so a 250 W-rated 70 V amplifier keeps a safe power margin.','Electrical / Distribution',ARRAY['Distributed systems','Impedance matching','Step-up transformer','Public address','Speaker tap']::text[],ARRAY['UNSAFE: Treating an energized 70/100 V speaker line as harmless low voltage; a 100 V line can deliver a hazardous shock, so de-energize and lock out the amplifier before working on connections.','UNSAFE: Overloading the amplifier by summing taps beyond its rating, which can overheat the wiring and the amplifier.','Wiring the speaker''s low-impedance voice-coil terminals instead of the transformer''s line taps.','Forgetting transformer insertion loss and long-cable loss when the last speakers sound weak.']::text[],ARRAY['Designing background music for a large retail store.','Adding speakers to an existing 70 V paging line without overloading it.','Troubleshooting a weak zone caused by a wrong tap setting.']::text[],'Advanced','Z_tap = V_line^2 / P_tap;   sum(P_taps) <= P_amp (with headroom)','A tap''s reflected impedance equals the line voltage squared divided by the tap power, and the sum of all tap powers must stay below the amplifier''s rated power.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant-voltage distributed systems');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '321ebeea-6c42-4019-b748-a0b89d0532c8','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='321ebeea-6c42-4019-b748-a0b89d0532c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='321ebeea-6c42-4019-b748-a0b89d0532c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9b328865-6e59-422d-91a9-5afc39a77422','Coordinate systems','A coordinate system is a scheme for locating points in space using ordered numbers relative to defined axes or references, such as Cartesian (x, y, z), cylindrical (r, theta, z), or spherical (r, theta, phi). In audio they specify source and listener positions, microphone placement, and the angles used to describe loudspeaker directivity.','A coordinate system gives every point an address in space. Straight-line systems use left-right, front-back, and up-down. Angle-based systems use a distance and directions. Sound work uses both kinds. They fix where sources, microphones, and listeners sit.','It provides a shared, unambiguous way to state positions and directions for measurement, modeling, and spatial audio.','A technician logs a measurement microphone at spherical coordinates of 2 m distance, 30 degrees horizontal, and 0 degrees vertical, so the setup can be repeated exactly.','Mathematics',ARRAY['Directivity balloon','Dot products','Cross products','Vector','Spatial audio']::text[],ARRAY['Mixing degrees and radians for angles, which gives wrong positions.','Assuming everyone shares the same axis convention; front and up must be defined first.','Confusing azimuth and elevation when reading spherical positions.']::text[],ARRAY['Documenting microphone positions for a repeatable measurement.','Reading a loudspeaker directivity balloon defined over a sphere.','Placing objects in an immersive audio scene.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coordinate systems');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9b328865-6e59-422d-91a9-5afc39a77422','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9b328865-6e59-422d-91a9-5afc39a77422') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9b328865-6e59-422d-91a9-5afc39a77422');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b9c3bced-eb22-4f88-b784-d1af449167dc','Coverage versus throw','Coverage is the angular width over which a loudspeaker delivers acceptably uniform sound (its coverage angle), while throw is how far the loudspeaker projects useful level along its axis before the sound falls off. The two trade against each other, since narrowing the coverage angle concentrates energy and increases throw.','Coverage is how wide a speaker spreads sound. Throw is how far it reaches. A wide speaker fills a broad area up close. A narrow speaker sends sound farther but covers less width. Designers balance the two.','It guides loudspeaker choice and aiming so the whole audience hears even level, without gaps or energy wasted on walls.','For a deep, narrow room a technician picks a long-throw box with a tight 40-degree pattern; for a wide, shallow room a 90-degree speaker gives broad coverage.','Loudspeaker / Coverage',ARRAY['Directivity control','Coverage angle','Comb filtering from multiple loudspeakers','Delay speakers','Directivity index']::text[],ARRAY['Thinking a louder speaker automatically throws farther; pattern control, not just power, sets reach.','Using a wide-pattern speaker in a long room and losing level and clarity at the back.','Ignoring that the coverage angle changes with frequency.']::text[],ARRAY['Choosing between a wide and a narrow horn for a venue''s shape.','Aiming a speaker so its coverage edge meets the last row.','Deciding whether one long-throw box or added delay speakers serve a deep room.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coverage versus throw');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b9c3bced-eb22-4f88-b784-d1af449167dc','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b9c3bced-eb22-4f88-b784-d1af449167dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b9c3bced-eb22-4f88-b784-d1af449167dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ca87772b-a587-4336-ab01-f25b01d4409d','Cross products','The cross product of two three-dimensional vectors produces a third vector perpendicular to both, with magnitude equal to |a||b|sin(theta) (the area of the parallelogram they span) and direction set by the right-hand rule. It is defined only in three dimensions and is central to describing rotation, torque, and surface orientation.','The cross product combines two arrows in space. It makes a new arrow at right angles to both. Its length grows with the angle between them. The right-hand rule sets which way it points. It appears in twisting and rotation.','It yields a direction perpendicular to a plane and a measure of how much two vectors differ in direction, used in rotation, torque, and geometry.','A technician finding the facing (normal) direction of a loudspeaker-mounting surface can take the cross product of two edge vectors to see which way it points.','Mathematics',ARRAY['Dot products','Coordinate systems','Vector','Eigenvectors','Directivity control']::text[],ARRAY['Swapping the order; reversing the vectors flips the result''s direction.','Trying to use it in two dimensions, where it is not defined as a vector.','Confusing it with the dot product, which gives a single number rather than a vector.']::text[],ARRAY['Finding the perpendicular direction of a mounting surface.','Computing torque on a rigging point in physics work.','Setting up 3D geometry for acoustic modeling.']::text[],'Advanced','|a x b| = |a|*|b|*sin(theta);   (a x b) is perpendicular to a and b, direction by right-hand rule','The cross product''s length equals the two vector lengths times the sine of the angle between them, and it points at right angles to both vectors.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cross products');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ca87772b-a587-4336-ab01-f25b01d4409d','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ca87772b-a587-4336-ab01-f25b01d4409d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ca87772b-a587-4336-ab01-f25b01d4409d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2f4f81fc-eeb4-44b1-be93-d408658ec82e','Delay shading','Delay shading is the technique of applying progressively different signal delays across the individual elements of a loudspeaker array to steer or curve its coverage without physically moving the boxes. Combined with level tapering (amplitude shading), it electronically shapes the array''s radiated pattern.','A speaker array has many elements. Delay shading feeds each one a slightly different delay. This bends the combined coverage where you want it. It aims the array without tilting boxes. It often pairs with changing each element''s level.','It lets designers steer or spread an array''s coverage electronically, improving even audience coverage from fixed physical positions.','A technician adds progressively more delay down a column array so its coverage tilts downward onto the seating, with no re-rigging needed.','Loudspeaker / Array',ARRAY['Delay speakers','Coverage versus throw','Directivity control','Beam steering','Amplitude shading']::text[],ARRAY['Confusing delay shading with a single delay used for time alignment; shading applies a graded set across elements.','Expecting it to replace physical aiming entirely; the practical steering range is limited.','Ignoring that the steering effect changes with frequency.']::text[],ARRAY['Steering a digitally controlled column array in a reverberant hall.','Curving array coverage to reach a balcony.','Designing a steerable loudspeaker for a church nave.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Delay shading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2f4f81fc-eeb4-44b1-be93-d408658ec82e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2f4f81fc-eeb4-44b1-be93-d408658ec82e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2f4f81fc-eeb4-44b1-be93-d408658ec82e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '999b227f-c8f6-4ce5-bbf4-761d79281a2e','Delay speakers','Delay speakers are additional loudspeakers placed farther from the stage whose signal is electronically delayed so their sound arrives just after the sound from the main system. Setting the delay from the distance divided by the speed of sound preserves the sense that all sound comes from the stage while restoring level and clarity for distant listeners.','In a long room, far seats hear the mains late and quiet. Delay speakers sit closer to those seats. Their signal is held back a little. The main sound still reaches listeners first. So the sound seems to come from the stage.','They add level and intelligibility for distant audiences while keeping the perceived source at the stage, by using the precedence (Haas) effect.','A delay speaker 34 m behind the mains is delayed about 100 ms (34 m divided by 343 m/s), often with a small extra offset, so the stage image stays intact.','Loudspeaker / System',ARRAY['Delay shading','Coverage versus throw','Comb filtering from multiple loudspeakers','Precedence effect','Distributed systems']::text[],ARRAY['Forgetting the small extra delay (Haas offset) that keeps the image at the stage.','Using distance in feet with a metric speed of sound, which gives a wrong time.','Setting the delay so sound arrives before the mains, pulling the image toward the rear speaker.']::text[],ARRAY['Adding delay towers down a long festival field.','Timing under-balcony speakers to the main array.','Restoring clarity at the back of a deep auditorium.']::text[],'Intermediate','t = d / c,   c ~= 343 m/s at 20 degrees C','The delay time equals the distance between the main and delay speakers divided by the speed of sound in air.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Delay speakers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '999b227f-c8f6-4ce5-bbf4-761d79281a2e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='999b227f-c8f6-4ce5-bbf4-761d79281a2e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='999b227f-c8f6-4ce5-bbf4-761d79281a2e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97789b18-0c4a-47cc-81db-5a93828f2385','Deterministic latency','Deterministic latency is a fixed, predictable end-to-end delay through a system or network, where the time from input to output is known and bounded rather than varying with traffic. Networked audio protocols achieve it through synchronized clocks and reserved bandwidth so every packet arrives within a guaranteed window.','Latency is the delay from input to output. Deterministic means that delay is fixed and known. It does not drift as network traffic changes. Audio networks reserve bandwidth and share a clock to guarantee it. This keeps devices in tight sync.','It guarantees that audio from many devices stays time-aligned and glitch-free, which is essential for live sound and lip-sync.','On a Dante network a technician selects a fixed latency such as 1 ms, knowing every stream will arrive within that bound so devices stay phase-aligned.','Networking',ARRAY['Clock-master election','Embedded clocking','Discovery and subscription','Jitter','Buffer']::text[],ARRAY['Confusing low latency with deterministic latency; a low but variable delay still causes problems.','Setting the network latency below what the cable length and switch count allow, which causes dropouts.','Assuming ordinary office Ethernet gives guarantees; determinism needs proper quality-of-service or Time-Sensitive Networking.']::text[],ARRAY['Choosing a Dante latency setting for a large stage network.','Ensuring multi-device playback stays sample-aligned.','Explaining why a shared office network is unsuitable for live audio.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Deterministic latency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97789b18-0c4a-47cc-81db-5a93828f2385','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97789b18-0c4a-47cc-81db-5a93828f2385') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97789b18-0c4a-47cc-81db-5a93828f2385');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39b03564-4e98-4abf-80bd-6fab6b90111d','Differential equations','A differential equation relates a function to its own rates of change (its derivatives), describing how a quantity evolves over time or space. Audio systems such as resonators, circuits, and filters are modeled by them; for example, a series RLC circuit obeys L*(d2q/dt2) + R*(dq/dt) + q/C = 0.','A differential equation links a quantity to how fast it is changing. It describes systems that move or settle over time. A plucked string or a filter follows one. Solving it predicts the behavior. Much of audio physics rests on them.','They model the dynamic behavior of circuits, transducers, and rooms, forming the basis of filter, resonance, and vibration analysis.','A technician who understands that a speaker''s low-frequency resonance follows a second-order differential equation can read its damping and Q from the response curve.','Mathematics',ARRAY['Differentiation','Complex numbers','Eigenvalues','Resonance','Transfer function']::text[],ARRAY['Thinking they only appear in theory; every real filter and resonator obeys one.','Confusing an equation''s order with how hard it is to solve.','Ignoring initial conditions, which shape the actual response.']::text[],ARRAY['Explaining why a resonant system rings and then decays.','Understanding filter behavior from its underlying circuit.','Relating loudspeaker damping to a second-order model.']::text[],'Advanced','L*(d^2 q/dt^2) + R*(dq/dt) + q/C = 0   (series RLC circuit)','A second-order differential equation sets a weighted sum of a quantity and its first and second rates of change equal to a driving term, here zero for a freely ringing circuit.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Differential equations');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39b03564-4e98-4abf-80bd-6fab6b90111d','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39b03564-4e98-4abf-80bd-6fab6b90111d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39b03564-4e98-4abf-80bd-6fab6b90111d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3b77c182-6c69-4a82-a5ba-8e92db75fb68','Differential signaling','Differential signaling carries information as the voltage difference between two conductors driven with equal and opposite polarity, rather than referenced to ground. Because interference couples nearly equally into both wires (common mode), a receiver that subtracts them cancels the shared noise while keeping the wanted difference signal, giving high common-mode rejection.','A balanced line uses two signal wires plus a shield. One wire carries the signal, the other its mirror. Noise hits both wires the same way. The receiver subtracts the two wires. The shared noise cancels, but the wanted signal remains.','It rejects hum and interference over long cable runs, which is why professional audio uses balanced, differential connections.','A technician runs a microphone 50 m on balanced XLR cable; noise picked up equally on both conductors cancels at the differential input, keeping the signal clean.','Electrical / Signal',ARRAY['Balanced line','Common-mode rejection ratio','Ground loop','Cable shielding','Impedance']::text[],ARRAY['Thinking two wires alone reject noise; rejection needs a differential receiver that subtracts them and balanced source impedances.','Assuming balanced means louder; it is about noise rejection, not level.','Unbalancing a line at one end, which defeats common-mode cancellation.']::text[],ARRAY['Running long microphone lines in an electrically noisy venue.','Diagnosing hum from a broken shield or a cold solder joint.','Interfacing balanced gear to unbalanced consumer equipment.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Differential signaling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3b77c182-6c69-4a82-a5ba-8e92db75fb68','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3b77c182-6c69-4a82-a5ba-8e92db75fb68') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3b77c182-6c69-4a82-a5ba-8e92db75fb68');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '36ae0fd0-8c6f-482d-971b-15845293a5e7','Differentiation','Differentiation is the mathematical operation that finds the instantaneous rate of change of a function, its derivative, defined as the limit of the average rate of change as the interval shrinks to zero. Applied to a signal, differentiating emphasizes rapid changes and corresponds to a +6 dB-per-octave high-frequency emphasis.','Differentiation measures how fast something changes at an instant. It is the slope of a curve at a point. For a signal, it stresses quick changes. Slow parts shrink and fast parts grow. It acts like a rising treble tilt.','It quantifies rates of change and underlies velocity, slope, and the behavior of differentiating circuits and filters.','A technician recognizes that a differentiator circuit boosts highs by 6 dB per octave, which helps in understanding certain equalizers and transducer responses.','Mathematics',ARRAY['Differential equations','Integration','Slew rate','High-pass filter','Rate of change']::text[],ARRAY['Confusing the derivative (a rate of change) with the function''s value.','Thinking differentiation is only abstract; it maps to real high-frequency emphasis.','Forgetting that differentiating noise makes it worse, since it lifts high frequencies.']::text[],ARRAY['Explaining why a differentiator circuit boosts treble.','Relating slew rate to how fast a signal can change.','Deriving velocity from a displacement signal.']::text[],'Advanced','f''(x) = dy/dx = lim_{h->0} [f(x+h) - f(x)] / h','The derivative is the limit of the change in the function divided by the change in the input, as that input change approaches zero.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Differentiation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '36ae0fd0-8c6f-482d-971b-15845293a5e7','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='36ae0fd0-8c6f-482d-971b-15845293a5e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='36ae0fd0-8c6f-482d-971b-15845293a5e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e72b6462-8f39-4b3f-a3b5-7f6417b29adf','Direct current','Direct current (DC) is electric current that flows in one direction only, with constant polarity, as supplied by batteries and DC power supplies. It contrasts with alternating current, and audio equipment converts AC mains to regulated DC to power its internal circuits.','Direct current flows one way only. Its polarity does not switch. Batteries and power supplies provide it. Audio gear runs its circuits on direct current. A power supply makes it from the wall''s alternating current.','It provides the steady, single-polarity power that electronic circuits need to operate, and is the reference level about which AC signals swing.','A technician measures a pedal''s 9 V DC supply with a multimeter set to DC volts, and checks correct polarity before connecting it.','Electrical',ARRAY['Electrical power','Alternating current','Voltage','Battery','Ohm''s law']::text[],ARRAY['UNSAFE: Assuming low-voltage DC is always harmless; shorting a battery or a high-current DC supply can cause burns, arcs, or fire.','Reversing DC polarity on a device, which can damage it instantly.','Confusing a DC offset on an audio signal with the audio itself; a large offset can harm a speaker.']::text[],ARRAY['Checking a phantom-power or pedal DC supply voltage.','Diagnosing a DC offset that pushes a speaker cone off-center.','Verifying battery polarity before powering portable gear.']::text[],'Beginner','Ohm''s law: V = I*R;   power: P = V*I','For a resistive load, the direct voltage equals the current times the resistance, and the power equals voltage times current.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Direct current');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e72b6462-8f39-4b3f-a3b5-7f6417b29adf','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e72b6462-8f39-4b3f-a3b5-7f6417b29adf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e72b6462-8f39-4b3f-a3b5-7f6417b29adf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f7914e18-0b05-4efe-957f-58789cd216ec','Directivity balloon','A directivity balloon is a three-dimensional plot of a loudspeaker''s (or microphone''s) output level as a function of direction, measured across a sphere of angles at many frequencies. Stored in data formats such as CLF or GLL, it lets prediction software model how the device covers a space.','A directivity balloon shows how a speaker radiates in every direction. It maps level over a full sphere of angles. It is measured at many frequencies. The shape can look like a lumpy balloon. Design software uses it to predict coverage.','It fully describes directional behavior in three dimensions, enabling accurate acoustic modeling and system design.','A technician imports a speaker''s GLL balloon into prediction software to see how its pattern covers seating before the rig is built.','Loudspeaker / Measurement',ARRAY['Directivity control','Coverage versus throw','Directivity index','Coordinate systems','Polar pattern']::text[],ARRAY['Reading a single polar plot as the whole picture; the balloon is fully three-dimensional.','Assuming the pattern is the same at all frequencies; it usually narrows at high frequencies.','Ignoring that balloon data quality depends on the measurement''s angular resolution.']::text[],ARRAY['Loading manufacturer balloon data into modeling software.','Comparing two speakers'' coverage in three dimensions.','Predicting even coverage across a fan-shaped audience.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity balloon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f7914e18-0b05-4efe-957f-58789cd216ec','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f7914e18-0b05-4efe-957f-58789cd216ec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f7914e18-0b05-4efe-957f-58789cd216ec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '315b858c-09e4-4c5c-be0c-878d5c40d54a','Directivity control','Directivity control is the design of a loudspeaker to radiate sound into a defined angular pattern rather than uniformly, achieved with horns, waveguides, and arrays. Its effectiveness is summarized by the directivity factor Q and the directivity index DI = 10*log10(Q), which rise as the pattern narrows.','A speaker naturally spreads highs narrowly and lows widely. Directivity control shapes where the sound goes. Horns and waveguides steer the pattern. This aims energy at the audience. Less sound then hits walls and ceilings.','It focuses sound onto listeners and away from reflective surfaces, improving clarity and reducing unwanted room excitation.','A technician chooses a constant-directivity horn so coverage stays even across frequency, then aims it to keep energy off a reflective rear wall.','Loudspeaker / Radiation',ARRAY['Directivity balloon','Coverage versus throw','Directivity index','Comb filtering from multiple loudspeakers','Horn']::text[],ARRAY['Assuming a bigger box always controls the pattern to lower frequencies; low-frequency control needs large radiators or arrays.','Confusing high sensitivity with high directivity; they are different properties.','Expecting even coverage across frequency without a constant-directivity design.']::text[],ARRAY['Selecting a horn for even coverage in a reverberant room.','Using directional control to raise gain before feedback.','Keeping sound off a hard rear wall to improve intelligibility.']::text[],'Advanced','DI = 10*log10(Q);   Q = on-axis intensity / intensity averaged over all directions','The directivity index in decibels is ten times the base-ten logarithm of the directivity factor, which compares on-axis intensity to the average over all directions.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '315b858c-09e4-4c5c-be0c-878d5c40d54a','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='315b858c-09e4-4c5c-be0c-878d5c40d54a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='315b858c-09e4-4c5c-be0c-878d5c40d54a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ba6d2ff-abac-4cf8-a79e-696deed26d89','Discovery and subscription','In networked audio, discovery is the automatic process by which devices announce and find each other''s available audio streams on a network, and subscription is the routing step in which a receiver is assigned to a particular transmitter''s stream. Systems such as Dante use these to build audio paths without manual IP configuration.','Networked audio devices must find each other first. Discovery lets them announce and see the available signals. Subscription then connects an output to a chosen input. It is like patching, but over the network. Control software handles it automatically.','It lets technicians route audio between many networked devices by name instead of by fixed addresses, simplifying large systems.','In Dante Controller a technician clicks the crosspoint to subscribe a stagebox output to a console input; discovery has already listed both devices.','Networking',ARRAY['Clock-master election','Deterministic latency','Embedded clocking','Audio-over-IP','Dante']::text[],ARRAY['Confusing discovery (finding devices) with subscription (making the audio connection).','Blocking the multicast or mDNS traffic that discovery needs, so devices never appear.','Assuming a subscription passes audio without the devices sharing a clock lock.']::text[],ARRAY['Patching a stagebox to a console over Dante.','Troubleshooting a device that does not appear in the control app.','Setting up an AES67 stream between different manufacturers'' gear.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Discovery and subscription');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ba6d2ff-abac-4cf8-a79e-696deed26d89','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ba6d2ff-abac-4cf8-a79e-696deed26d89') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ba6d2ff-abac-4cf8-a79e-696deed26d89');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd5a73478-16c7-4d3f-b75a-72f58169019e','Distortion measurement','Distortion measurement quantifies unwanted changes a device adds to a signal, most commonly total harmonic distortion (THD) - the ratio of the summed harmonic content to the fundamental - and THD+N, which also includes noise. It is measured by feeding a pure tone and analyzing the output spectrum, expressed as a percentage or in decibels.','Real gear adds content that was not in the input. Distortion measurement puts a clean tone in and studies the output. It measures the extra harmonics that appear. The result is a percentage or a decibel figure. Lower means cleaner.','It reveals how faithfully equipment reproduces a signal, helping compare gear and find faults such as clipping or a failing component.','Feeding a 1 kHz tone, a technician reads 0.01% THD+N on an analyzer to confirm an amplifier is clean, then drives it harder to find where distortion rises.','Measurement',ARRAY['Constant-Hz bandwidth','Constant-percentage bandwidth','Total harmonic distortion','Signal-to-noise ratio','Clipping']::text[],ARRAY['Comparing THD figures taken at different levels or bandwidths as if they were equal.','Assuming lower THD always sounds better; the harmonic makeup also matters.','Confusing THD (harmonics only) with THD+N (harmonics plus noise).']::text[],ARRAY['Bench-testing an amplifier''s THD+N before deployment.','Finding the onset of clipping by sweeping the level.','Diagnosing a distorted channel against a clean reference.']::text[],'Intermediate','THD = sqrt(V2^2 + V3^2 + V4^2 + ...) / V1   (harmonics relative to the fundamental)','Total harmonic distortion is the square root of the summed squares of the harmonic amplitudes divided by the fundamental amplitude.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distortion measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd5a73478-16c7-4d3f-b75a-72f58169019e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d5a73478-16c7-4d3f-b75a-72f58169019e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d5a73478-16c7-4d3f-b75a-72f58169019e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '48fda38e-b5f4-4902-8f7a-6e2292ceaf60','Distributed systems','A distributed loudspeaker system uses many low-power speakers spread evenly across an area - typically flush-mounted in a ceiling - so that every listener is close to a source and hears uniform level. Such systems commonly run on constant-voltage (70 V or 100 V) lines, and are designed by loudspeaker spacing and coverage overlap.','Instead of a few big speakers, this uses many small ones. They are spread evenly, often in the ceiling. Everyone stays close to a speaker. So the level is even everywhere. These are common for paging and background music.','It delivers consistent, intelligible sound over large flat areas such as offices, stores, and transit halls, where a few point sources would be uneven.','A technician lays out ceiling speakers on a grid so their coverage circles overlap at ear height, giving even level with no loud or dead spots.','Loudspeaker / Distribution',ARRAY['Constant-voltage distributed systems','Delay speakers','Coverage versus throw','Public address','Speaker tap']::text[],ARRAY['Spacing the speakers too far apart, which leaves quiet gaps between them.','Ignoring ceiling height, which sets how much coverage overlaps at ear level.','Confusing a distributed ceiling system with a few point-source loudspeakers.']::text[],ARRAY['Designing office or retail background music.','Covering a large transit concourse for paging.','Retrofitting even coverage into a low-ceiling room.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distributed systems');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '48fda38e-b5f4-4902-8f7a-6e2292ceaf60','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='48fda38e-b5f4-4902-8f7a-6e2292ceaf60') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='48fda38e-b5f4-4902-8f7a-6e2292ceaf60');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'efc1b494-e56e-45ee-bcf4-3f53ee69c6eb','Dose','Noise dose is the amount of sound energy a person accumulates over a period relative to a permissible daily limit, expressed as a percentage. Under OSHA 29 CFR 1910.95, 100% dose equals an 8-hour exposure at a 90 dBA time-weighted average using a 5 dB exchange rate; NIOSH recommends a stricter 85 dBA limit with a 3 dB exchange rate.','Dose adds up how much loud sound you take in during a shift. It is shown as a percent of a daily limit. Full dose is a full shift at the legal limit. Louder sound uses up the dose faster. Going over risks hearing loss.','It measures cumulative hearing-hazard exposure so employers can protect workers and stay within legal noise limits.','A live-sound engineer wearing a dosimeter reads 100% dose at the end of a shift, meaning exposure reached the OSHA daily limit and hearing protection is needed to stay safe.','Hearing Safety',ARRAY['Sound pressure level','Time-weighted average','Permissible exposure limit','Hearing protection','Exchange rate']::text[],ARRAY['UNSAFE: Treating brief very loud exposure as safe because a shift average looks acceptable; levels above roughly 115 dBA and any impulse over about 140 dB can injure hearing quickly.','UNSAFE: Removing hearing protection near 100% dose, which pushes exposure past the legal daily limit.','Confusing OSHA''s 5 dB exchange rate with NIOSH''s stricter 3 dB rate; they give different dose figures.','Assuming dose matters only at work; loud monitoring anywhere adds to daily exposure.']::text[],ARRAY['Wearing a dosimeter during a concert load-in and show.','Deciding when crew must put on earplugs.','Comparing a venue''s exposure against both OSHA and NIOSH limits.']::text[],'Intermediate','D = 100 * sum(C_i / T_i);   TWA = 16.61*log10(D/100) + 90  (dBA, OSHA)','Dose is one hundred times the sum of each actual exposure time divided by the time permitted at that level, and the time-weighted average follows from that dose.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dose');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'efc1b494-e56e-45ee-bcf4-3f53ee69c6eb','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='efc1b494-e56e-45ee-bcf4-3f53ee69c6eb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='efc1b494-e56e-45ee-bcf4-3f53ee69c6eb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ee058c8-012e-4889-8490-ac1329efa697','Dot products','The dot (scalar) product of two vectors multiplies their corresponding components and sums the results, yielding a single number equal to |a||b|cos(theta). It measures how much two vectors point in the same direction and is zero when they are perpendicular.','The dot product combines two arrows into one number. It multiplies matching parts and adds them up. The result shows how aligned they are. Same direction gives a large value. At right angles it is zero.','It quantifies alignment and projection between vectors, used in geometry, signal correlation, and computing angles.','A technician computing the correlation between two signals, or the angle between two directions, uses a dot product; a zero result means the vectors are at 90 degrees.','Mathematics',ARRAY['Cross products','Coordinate systems','Complex numbers','Vector','Correlation']::text[],ARRAY['Expecting a vector result; the dot product gives a single number.','Forgetting that a zero dot product means the vectors are perpendicular.','Mixing it up with the cross product, which measures perpendicularity instead.']::text[],ARRAY['Finding the angle between two directions.','Computing the correlation between two signals.','Projecting one vector onto another in acoustic geometry.']::text[],'Advanced','a . b = sum(a_i * b_i) = |a|*|b|*cos(theta)','The dot product is the sum of the products of matching components, which also equals the two vector lengths times the cosine of the angle between them.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dot products');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ee058c8-012e-4889-8490-ac1329efa697','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ee058c8-012e-4889-8490-ac1329efa697') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ee058c8-012e-4889-8490-ac1329efa697');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c09c644d-8e3a-46f8-8681-0e25bdbb5d39','Eigenvalues','An eigenvalue is a scalar for which a linear transformation merely scales a special nonzero vector without changing its direction, satisfying A*v = lambda*v. In audio, eigenvalues arise in room-mode analysis and in the modal behavior of vibrating systems, where they correspond to natural (resonant) frequencies.','Some directions are special for a transformation. Along them, it only stretches or shrinks, without turning. The stretch factor is the eigenvalue. In rooms and vibrating parts, these relate to natural resonances. They reveal a system''s built-in frequencies.','They identify the natural frequencies and stability of vibrating and dynamic systems, key to modal and room-acoustic analysis.','A technician modeling room modes finds resonant frequencies as eigenvalues of the room''s acoustic model, predicting where bass builds up.','Mathematics',ARRAY['Eigenvectors','Differential equations','Complex numbers','Room modes','Resonance']::text[],ARRAY['Thinking every vector is scaled cleanly; only eigenvectors keep their direction.','Assuming eigenvalues are always real; they can be complex.','Confusing the eigenvalue (the factor) with the eigenvector (the direction).']::text[],ARRAY['Finding a room''s resonant frequencies in a modal model.','Analyzing the stability of a feedback or control system.','Studying the vibration modes of a speaker cone.']::text[],'Advanced','A*v = lambda*v,  v != 0;   det(A - lambda*I) = 0','An eigenvalue is a scaling factor for which the matrix acting on its eigenvector equals that eigenvector times the factor, found where the characteristic determinant is zero.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Eigenvalues');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c09c644d-8e3a-46f8-8681-0e25bdbb5d39','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c09c644d-8e3a-46f8-8681-0e25bdbb5d39') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c09c644d-8e3a-46f8-8681-0e25bdbb5d39');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '49a8a5db-b8cf-42be-a050-37b31d20ae4c','Eigenvectors','An eigenvector is a nonzero vector whose direction is unchanged by a linear transformation, being only scaled by its corresponding eigenvalue, so that A*v = lambda*v. In physical systems, eigenvectors describe the mode shapes - the characteristic patterns of motion - associated with each natural frequency.','An eigenvector is a special direction for a transformation. Acting on it only stretches or shrinks it. Its direction stays the same. In a vibrating system it shows a mode''s shape. Each natural frequency has its own pattern.','They reveal the characteristic patterns (mode shapes) of a system, complementing eigenvalues in vibration and acoustic analysis.','A technician studying a panel''s resonances uses eigenvectors to see the vibration pattern at each resonant frequency, guiding where to add damping.','Mathematics',ARRAY['Eigenvalues','Differential equations','Cross products','Mode shape','Room modes']::text[],ARRAY['Confusing the eigenvector (a direction) with the eigenvalue (a scale factor).','Forgetting that eigenvectors can be scaled to any length; direction is what matters.','Assuming a matrix always has a full set of independent eigenvectors.']::text[],ARRAY['Visualizing the mode shapes of a vibrating panel.','Interpreting a room mode''s pressure pattern.','Understanding principal directions in signal decorrelation.']::text[],'Advanced','A*v = lambda*v,  v != 0','An eigenvector is a nonzero vector that the matrix maps to a scalar multiple of itself, that scalar being its eigenvalue.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Eigenvectors');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '49a8a5db-b8cf-42be-a050-37b31d20ae4c','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='49a8a5db-b8cf-42be-a050-37b31d20ae4c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='49a8a5db-b8cf-42be-a050-37b31d20ae4c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e8ccff71-996f-4fbb-a7ed-f4f7333e6789','Electrical power','Electrical power is the rate at which electrical energy is delivered or dissipated, measured in watts. For a resistive load it equals voltage times current, P = V*I = I^2*R = V^2/R; in AC circuits, real power also depends on the phase between voltage and current, P = V_rms*I_rms*cos(phi).','Electrical power is how fast energy is used or delivered. It is measured in watts. For a simple load, it is voltage times current. In alternating-current circuits, the timing between voltage and current matters. A power factor accounts for that.','It sets how much energy an amplifier delivers to a speaker and how much a device draws from the mains, governing equipment sizing and heat.','Driving an 8-ohm speaker at 20 V RMS, a technician computes P = V^2/R = 400/8 = 50 W delivered to the load.','Electrical',ARRAY['Direct current','Ohm''s law','RMS','Impedance','Power factor']::text[],ARRAY['UNSAFE: Underrating cable or connectors for the power involved, which can overheat and cause a fire; size conductors for the current they carry.','Using peak instead of RMS voltage, which overstates the real power.','Ignoring the power factor in AC, which overestimates the true power.']::text[],ARRAY['Sizing an amplifier for a speaker''s power rating.','Estimating a rig''s mains current draw.','Checking heat dissipation in a resistive load.']::text[],'Beginner','P = V*I = I^2*R = V^2/R;   AC real power P = V_rms*I_rms*cos(phi)','Power equals voltage times current, or current squared times resistance, or voltage squared divided by resistance; in alternating current, multiply by the power factor.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrical power');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e8ccff71-996f-4fbb-a7ed-f4f7333e6789','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e8ccff71-996f-4fbb-a7ed-f4f7333e6789') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e8ccff71-996f-4fbb-a7ed-f4f7333e6789');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e6fb47d9-90d5-4486-b22b-7fc50ce45b5f','Embedded clocking','Embedded clocking carries the timing (sample-clock) reference within the audio data stream itself, rather than on a separate wire, so the receiver recovers the clock from the incoming signal. Self-clocking line codes such as the biphase-mark coding used in AES3 and S/PDIF, and packet timing in audio-over-IP, let one connection convey both data and clock.','Digital audio needs a shared clock to stay in step. Embedded clocking hides that clock inside the audio stream. No extra clock cable is needed. The receiver pulls the timing out of the signal. AES3 and S/PDIF work this way.','It simplifies wiring by combining data and timing on one link, while keeping devices sample-synchronous.','A technician feeding S/PDIF into a converter sets it to slave to the incoming stream, since the clock is embedded in that signal.','Networking / Clocking',ARRAY['Clock-master election','Deterministic latency','Word clock','AES3','Jitter']::text[],ARRAY['Also feeding a separate word clock while slaving to the embedded clock, which causes conflicts.','Assuming embedded clocks are jitter-free; clock recovery quality varies.','Leaving two devices in a chain both set as clock master.']::text[],ARRAY['Slaving a converter to an incoming S/PDIF or AES3 signal.','Deciding between an embedded clock and separate word-clock distribution.','Diagnosing clicks caused by a clock-source mismatch.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Embedded clocking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e6fb47d9-90d5-4486-b22b-7fc50ce45b5f','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e6fb47d9-90d5-4486-b22b-7fc50ce45b5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e6fb47d9-90d5-4486-b22b-7fc50ce45b5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e7adb71-0b15-4f29-8c65-49c8c3de8b22','Empty-room versus occupied-room response','This refers to how a room''s acoustic response changes between when it is empty and when it is filled with people, because audience bodies and seating add sound absorption. Occupancy typically shortens the reverberation time and lowers mid- and high-frequency level, so tuning done in an empty room may not match show conditions.','A room sounds different empty versus full of people. Bodies and seats soak up sound. A full room has less echo and shorter reverberation. Highs and mids drop the most. Tuning done empty may not hold during the show.','It reminds technicians that measurements and tuning must account for audience absorption to sound correct once the room is occupied.','A technician tunes a system in an empty hall, then trims high-frequency level and expects shorter reverberation once the audience arrives and adds absorption.','Room Acoustics',ARRAY['Reverberation time','Absorption coefficient','Room tuning','Sabine equation','Coverage versus throw']::text[],ARRAY['Assuming an empty-room tuning holds once the audience arrives.','Overcompensating so the sound is too dark and dull when the room is full.','Ignoring that upholstered seats mimic much of an audience''s absorption.']::text[],ARRAY['Tuning a theater system before doors open.','Predicting how a full house changes the reverberation.','Choosing seating that keeps the empty and full responses similar.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Empty-room versus occupied-room response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e7adb71-0b15-4f29-8c65-49c8c3de8b22','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e7adb71-0b15-4f29-8c65-49c8c3de8b22') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e7adb71-0b15-4f29-8c65-49c8c3de8b22');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ca2a0af-78d4-4f30-8287-44bfea142f3f','Error correction','Error correction is a set of techniques that detect and repair bit errors in digital audio using added redundant data, so the original signal is recovered without audible dropouts. Methods include Reed-Solomon codes with interleaving - as in the Cross-Interleaved Reed-Solomon Code (CIRC) used on the Compact Disc - and checks such as cyclic redundancy check (CRC) and parity in transmission.','Digital audio can pick up bit errors from scratches or noise. Error correction adds extra data to catch and fix them. Some schemes rebuild lost bits exactly. Others spread the data out so damage is scattered. The CD uses this to survive scratches.','It keeps digital audio accurate over imperfect media and links, preventing clicks, dropouts, and corrupted data.','A technician relies on CIRC to let a lightly scratched CD play cleanly, and on packet retransmission or forward error correction to protect networked audio.','Digital Audio / Networking',ARRAY['Deterministic latency','Embedded clocking','Interleaving','Parity','Cyclic redundancy check']::text[],ARRAY['Confusing error detection (finding errors) with error correction (actually fixing them).','Thinking interpolation or muting is true correction; those only conceal unrecoverable errors.','Assuming correction is unlimited; heavy damage exceeds a code''s capacity.']::text[],ARRAY['Explaining why a lightly scratched CD still plays perfectly.','Choosing forward error correction for a wireless audio link.','Understanding a CRC check flagging a corrupted data packet.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Error correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ca2a0af-78d4-4f30-8287-44bfea142f3f','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ca2a0af-78d4-4f30-8287-44bfea142f3f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ca2a0af-78d4-4f30-8287-44bfea142f3f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a7d5947d-243e-4529-8729-adc09cd9ae19','Excess-phase plot','A graph of the phase that remains after the minimum-phase component of a system''s response is removed, revealing pure time delay and any non-minimum-phase behavior versus frequency.','This plot shows extra phase shift a device adds beyond the minimum it must have. It is found by subtracting the minimum-phase part from the measured phase. What is left is mostly pure time delay and any non-minimum-phase behavior that an equalizer cannot fix. Engineers use it to study loudspeakers and rooms.','It separates unavoidable minimum-phase behavior from pure delay and non-minimum-phase effects, so a technician can see what an equalizer can and cannot correct.','In room and loudspeaker measurement software, a technician derives excess phase from an impulse response to check for all-pass delay before deciding whether phase problems are fixable with EQ.','Measurement / Analysis',ARRAY['Group-delay plot','Minimum phase','Phase response','All-pass filter','Impulse response']::text[],ARRAY['Assuming any phase shift shown can be flattened with EQ; excess (non-minimum) phase cannot be corrected by a minimum-phase equalizer.','Confusing the constant slope from pure time delay with a real problem in the device.','Reading excess phase without first removing the bulk propagation delay, which hides the useful detail.']::text[],ARRAY['Deciding whether a dip in a loudspeaker response is minimum-phase and EQ-correctable.','Analyzing crossover regions for non-minimum-phase behavior between drivers.','Studying a room measurement to distinguish delay from resonant phase shifts.']::text[],'Advanced','φ_exc(f) = φ_tot(f) − φ_min(f)','Excess phase at a frequency equals the total measured phase minus the minimum-phase value computed from the magnitude response.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Excess-phase plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a7d5947d-243e-4529-8729-adc09cd9ae19','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a7d5947d-243e-4529-8729-adc09cd9ae19') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a7d5947d-243e-4529-8729-adc09cd9ae19');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '25ec2591-e893-43ea-ae41-7ed62ec67bb6','Exponents','In mathematics, an exponent indicates how many times a base value is multiplied by itself; it is the inverse operation to the logarithm and underlies exponential and power relationships used throughout audio.','An exponent tells you how many times to multiply a number by itself. For example, ten to the third power means ten times ten times ten. Exponents are the opposite of logarithms. Audio uses them for decibels, capacitor decay, and horn shapes.','Exponents give a compact way to express repeated multiplication and rapid growth or decay, which is essential to decibels, powers of ten, and time-constant behavior.','A technician uses exponents when reading powers of ten in decibel math, for example recognizing that 10 raised to the power 2 equals 100, a factor of 100 that is a 40 dB voltage ratio or a 20 dB power ratio.','Mathematics',ARRAY['Logarithms','Decibel','Scientific notation','Exponential function','Powers of ten']::text[],ARRAY['Adding exponents when the bases differ, which is not valid.','Confusing a negative exponent with a negative number; a negative exponent means a reciprocal.','Treating raising to a power and multiplying by that number as the same operation.']::text[],ARRAY['Working through decibel conversions that rely on powers of ten.','Reading component values written in scientific notation on a schematic.','Understanding the exponential flare rate of a horn or an RC decay curve.']::text[],'Beginner','b^n = b × b × … × b (n factors)','A base raised to an exponent equals the base multiplied by itself as many times as the exponent indicates.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exponents');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '25ec2591-e893-43ea-ae41-7ed62ec67bb6','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='25ec2591-e893-43ea-ae41-7ed62ec67bb6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='25ec2591-e893-43ea-ae41-7ed62ec67bb6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e9547649-a284-40a3-bdf2-6a9675f93847','Fast weighting','A standardized exponential time weighting for sound level meters, denoted F, using a 125 ms time constant so the displayed level responds quickly to changing sound.','Fast weighting sets how quickly a sound level meter reacts to changes. It uses a short averaging time of 125 milliseconds. The reading follows brief, changing sounds closely. Technicians pick it when they need to see fast level swings.','It defines a consistent, quick meter response so measured sound levels can be compared across instruments and against noise limits that specify Fast weighting.','A technician selects F on a sound level meter to capture the rapid peaks of speech or music, reading a level that decays at about 34.7 dB per second after the sound stops.','Metering / Weighting',ARRAY['Slow weighting','Impulse weighting','Frequency weighting','Sound level meter','Time weighting']::text[],ARRAY['Confusing Fast time weighting with A frequency weighting; one controls speed, the other controls frequency response.','Comparing Fast readings to limits that are specified for Slow weighting.','UNSAFE: Trusting a Fast meter reading as a full hearing-risk assessment; occupational exposure limits require time-averaged levels and dose, not a single quick reading.']::text[],ARRAY['Measuring fluctuating environmental or venue noise where quick response is wanted.','Checking short-term level swings during a live sound check.','Comparing a reading against a regulation that names Fast time weighting.']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fast weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e9547649-a284-40a3-bdf2-6a9675f93847','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e9547649-a284-40a3-bdf2-6a9675f93847') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e9547649-a284-40a3-bdf2-6a9675f93847');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac1ee791-b0e5-42e1-8ea5-0bba0211e4f1','Feedback loop gain','In a feedback system, the loop gain is the product of the forward-path gain and the feedback factor, describing the total gain a signal experiences going once around the loop.','Loop gain is the total gain a signal picks up on one trip around a feedback circuit. It multiplies the amplifier''s forward gain by the fraction fed back. Its size and phase decide how the circuit behaves. Large loop gain lowers distortion but can risk instability.','It quantifies how strongly feedback acts on a system, which sets closed-loop accuracy, distortion reduction, and the margin before oscillation.','An engineer evaluates loop gain when designing or troubleshooting an amplifier, checking that its magnitude falls below unity before the phase reaches minus 180 degrees.','Control / Amplifiers',ARRAY['Feedback stability','Feedback stability margin','Closed-loop gain','Open-loop gain','Negative feedback']::text[],ARRAY['Confusing loop gain with closed-loop gain; loop gain is measured around the loop, not input to output.','Ignoring the phase of loop gain and looking only at its magnitude.','Assuming more loop gain is always better, when excessive loop gain can cause instability.']::text[],ARRAY['Designing a negative-feedback power amplifier for low distortion.','Diagnosing oscillation in an op-amp circuit.','Analyzing a servo or level-control loop for stability.']::text[],'Advanced','T = Aβ','Loop gain equals the forward-path gain multiplied by the feedback factor.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Feedback loop gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac1ee791-b0e5-42e1-8ea5-0bba0211e4f1','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac1ee791-b0e5-42e1-8ea5-0bba0211e4f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac1ee791-b0e5-42e1-8ea5-0bba0211e4f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0aff1f6-1bcc-4ab4-ab5a-7bf7235789d5','Feedback stability','The property of a feedback system that its output settles to a bounded value rather than growing without limit or breaking into sustained oscillation.','A stable feedback system returns to a steady output after a disturbance. An unstable one rings or oscillates and will not settle. Stability depends on the loop gain''s size and phase together. Engineers design circuits to stay well inside stable limits.','It ensures an amplifier, filter, or control loop behaves predictably and does not oscillate, which is required for safe, usable audio equipment.','A technician confirms stability by checking that loop gain drops below unity before its phase shift reaches minus 180 degrees, the condition described by the Nyquist criterion.','Control / Amplifiers',ARRAY['Feedback loop gain','Feedback stability margin','Nyquist criterion','Phase margin','Oscillation']::text[],ARRAY['Believing negative feedback is always stable; too much delay or phase shift can turn it positive at some frequency.','Judging stability from gain alone while ignoring phase.','Confusing acoustic feedback howl at a microphone with electronic loop instability inside a circuit.']::text[],ARRAY['Verifying an amplifier does not oscillate under a capacitive loudspeaker load.','Tuning a control loop so it settles without ringing.','Investigating a supersonic oscillation that overheats an output stage.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Feedback stability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0aff1f6-1bcc-4ab4-ab5a-7bf7235789d5','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0aff1f6-1bcc-4ab4-ab5a-7bf7235789d5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0aff1f6-1bcc-4ab4-ab5a-7bf7235789d5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5ddcbd3-d4d8-4078-a287-e502f3498f0d','Feedback stability margin','A measure of how far a feedback system is from instability, expressed as gain margin (how much loop gain may rise, in dB, at the frequency where phase is minus 180 degrees) and phase margin (extra phase, in degrees, at the frequency where loop gain is unity).','Stability margin says how much safety room a feedback system has before it oscillates. Gain margin is the extra loop gain it can take at the danger phase. Phase margin is the extra phase it can take at unity gain. Bigger margins mean a more robust design.','It gives designers a numerical safety buffer so a circuit stays stable despite component tolerances, temperature, and load changes.','An engineer reads gain and phase margins from a loop-gain Bode plot, typically aiming for at least about 45 degrees of phase margin for a well-damped, stable response.','Control / Amplifiers',ARRAY['Feedback stability','Feedback loop gain','Phase margin','Gain margin','Bode plot']::text[],ARRAY['Treating any positive margin as safe; small margins leave the circuit prone to ringing and drift.','Reporting only gain margin or only phase margin when both are needed.','Measuring margins from closed-loop response instead of the loop gain.']::text[],ARRAY['Reviewing a Bode plot during amplifier design.','Adding compensation to increase phase margin.','Explaining why a marginally stable device rings on transients.']::text[],'Advanced','GM = −20·log10|T(f_180)| dB ; PM = 180° + ∠T(f_0dB)','Gain margin is how far the loop-gain magnitude is below unity at the frequency where phase is minus 180 degrees; phase margin is 180 degrees plus the loop-gain phase at the frequency where loop-gain magnitude equals one.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Feedback stability margin');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5ddcbd3-d4d8-4078-a287-e502f3498f0d','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5ddcbd3-d4d8-4078-a287-e502f3498f0d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5ddcbd3-d4d8-4078-a287-e502f3498f0d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3399e930-b682-4835-8efb-b5cf073c212e','Fourier transforms','A mathematical operation that expresses a time-domain signal as a sum or integral of sinusoids, giving its amplitude and phase at each frequency; the discrete version is computed efficiently by the FFT.','A Fourier transform turns a signal over time into its mix of frequencies. It reveals which tones are present and how strong each is. Computers use a fast version called the FFT. It is the basis of most audio spectrum analysis.','It lets engineers move between the time view and the frequency view of a signal, which underlies spectrum analysis, filtering, and transfer-function measurement.','A technician relies on the FFT inside an analyzer to display a signal''s spectrum, choosing a block size that trades frequency resolution against time resolution.','Signal Analysis',ARRAY['Laplace transforms','Fractional-octave analysis','Spectrum','Frequency-response measurement','Window function']::text[],ARRAY['Confusing the continuous Fourier transform with the discrete FFT used on sampled data.','Ignoring windowing, which causes spectral leakage on non-periodic blocks.','Assuming finer frequency resolution is free; it requires a longer time record.']::text[],ARRAY['Viewing the harmonic content of a distorted signal.','Running a dual-channel FFT to measure a system transfer function.','Explaining why a short analysis window smears low-frequency detail.']::text[],'Intermediate','X(f) = ∫ x(t) e^{−j2πft} dt','The spectrum at a frequency equals the integral over time of the signal multiplied by a complex sinusoid at that frequency.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fourier transforms');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3399e930-b682-4835-8efb-b5cf073c212e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3399e930-b682-4835-8efb-b5cf073c212e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3399e930-b682-4835-8efb-b5cf073c212e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3f08274a-4ed9-4ef7-9950-d3b2c58ba05a','Fractional-octave analysis','Spectral analysis using a bank of filters whose bandwidths are a constant fraction of an octave, such as one-third octave, giving constant relative bandwidth across frequency.','This method splits sound into bands that are a set fraction of an octave wide. One-third-octave bands are the most common. The bands get wider at high frequencies to match how we hear. It is standard for noise and room measurements.','It presents spectra with resolution that matches human hearing and standard acoustic practice, making results comparable across instruments and against limits.','A technician runs a one-third-octave analysis of pink noise in a room to check tonal balance against a target, reading roughly 31 bands from 20 Hz to 20 kHz.','Signal Analysis',ARRAY['Fractional-octave smoothing','Fourier transforms','Frequency-response measurement','Pink noise','Octave band']::text[],ARRAY['Confusing constant-relative-bandwidth octave bands with the constant-absolute-bandwidth bins of an FFT.','Comparing one-third-octave results to full-octave limits without noting the band width.','Assuming octave-band centers are arbitrary; they follow the standard base-ten or base-two series.']::text[],ARRAY['Measuring room tonal balance with pink noise.','Documenting environmental noise in standardized bands.','Setting a graphic equalizer whose bands align with one-third-octave centers.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fractional-octave analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3f08274a-4ed9-4ef7-9950-d3b2c58ba05a','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3f08274a-4ed9-4ef7-9950-d3b2c58ba05a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3f08274a-4ed9-4ef7-9950-d3b2c58ba05a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cd518aff-7348-464d-80ef-cfbbed6e2bd6','Fractional-octave smoothing','A display technique that averages a high-resolution frequency response over a moving window a fixed fraction of an octave wide, reducing fine ripple while preserving broad trends.','This smooths a jagged measured response by averaging over a set fraction of an octave. One-sixth or one-third octave are common settings. It hides tiny wiggles so the overall shape is clear. Heavier smoothing hides more detail.','It makes measured responses easier to read and compare by suppressing narrow measurement ripple that would not be equalized or heard as tonal color.','A technician sets one-sixth-octave smoothing in a measurement program so a loudspeaker curve shows meaningful trends rather than every narrow reflection notch.','Signal Analysis',ARRAY['Fractional-octave analysis','Frequency-response measurement','Gating reflections','Frequency response','Octave band']::text[],ARRAY['Using heavy smoothing that hides real narrow resonances that should be treated.','Comparing two curves smoothed by different amounts as if they matched.','Believing smoothing changes the signal itself rather than only the displayed data.']::text[],ARRAY['Presenting a loudspeaker response cleanly for a report.','Comparing before-and-after equalization curves at matched smoothing.','Deciding whether a dip is a broad tonal issue or a narrow reflection artifact.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fractional-octave smoothing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cd518aff-7348-464d-80ef-cfbbed6e2bd6','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cd518aff-7348-464d-80ef-cfbbed6e2bd6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cd518aff-7348-464d-80ef-cfbbed6e2bd6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '43d38f13-7dc4-4e9e-b971-85e03f876408','Frame clock','In serial digital audio interfaces, the frame (or word) clock is the signal that marks the boundary of each audio sample frame; its rate equals the sample rate and it distinguishes left and right channels in formats such as I2S.','A frame clock marks where each audio sample begins in a digital stream. Its rate matches the sample rate, for example 48 kHz. In the I2S format it also flags left versus right channel. It works alongside a faster bit clock.','It keeps a receiver aligned to sample boundaries so audio words are read in the right order and the correct channel, preventing sample slips and channel swaps.','A technician verifying an I2S or TDM link checks that the frame-clock rate equals the intended sample rate and stays phase-locked to the bit clock and master word clock.','Digital Audio / Clocking',ARRAY['Word clock','Bit clock','Sample rate','Jitter accumulation','Sample rate conversion']::text[],ARRAY['Confusing the frame clock with the much faster bit clock that carries individual data bits.','Assuming the frame clock alone conveys audio data; it only marks timing.','Overlooking that a wrong frame-clock edge or polarity can swap left and right channels.']::text[],ARRAY['Bringing up an I2S link between a DAC and a processor.','Diagnosing channel swaps or clicks on a digital audio board.','Confirming a device follows an external word-clock reference.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frame clock');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '43d38f13-7dc4-4e9e-b971-85e03f876408','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='43d38f13-7dc4-4e9e-b971-85e03f876408') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='43d38f13-7dc4-4e9e-b971-85e03f876408');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9fb1e149-e56b-4d05-a9b9-7face9bdc8f0','Frequency shading','In array loudspeaker systems, the practice of applying different level and equalization to individual elements as a function of position, tapering the drive so array directivity and coverage are controlled with frequency.','Frequency shading feeds different elements of a speaker array by different amounts. Levels and tone are tapered across the array. This shapes where sound goes at each frequency. It smooths coverage over the audience and reduces spill.','It controls an array''s directivity and evenness of coverage across frequency, compensating for how directivity naturally narrows as frequency rises.','A system engineer applies progressive high-frequency shading to a line array so the top boxes carry more high-frequency energy to distant listeners while lower boxes are eased back.','System Design',ARRAY['Line array','Beam steering','Array processing','Directivity','Frequency-response measurement']::text[],ARRAY['Confusing amplitude shading with delay-based beam steering; they control coverage in different ways.','Applying uniform level to all boxes and expecting even coverage front to back.','Shading so aggressively that overall level or headroom is needlessly lost.']::text[],ARRAY['Tuning a line array for even front-to-back coverage.','Reducing high-frequency spill onto a stage or ceiling.','Setting per-element gains in array prediction software.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency shading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9fb1e149-e56b-4d05-a9b9-7face9bdc8f0','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9fb1e149-e56b-4d05-a9b9-7face9bdc8f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9fb1e149-e56b-4d05-a9b9-7face9bdc8f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '139f8773-e24a-4387-b66c-d5c53bfae371','Frequency weighting','A standardized filter applied in sound level measurement to shape a signal''s frequency response before a level is read; A, C, and Z weightings are defined so results reflect chosen aspects of human hearing or a flat reference.','Frequency weighting is a filter used before a sound meter reads a level. A-weighting mimics how our ears respond at quiet levels. C-weighting is flatter and used for loud, low-frequency sound. Z-weighting is essentially flat, with no shaping.','It makes measured levels reflect a defined hearing model or reference so readings are consistent between instruments and comparable to noise limits.','A technician selects A-weighting to measure an environmental noise level in dB(A), or C-weighting to assess strong low-frequency content near a subwoofer.','Metering / Weighting',ARRAY['Fast weighting','Slow weighting','Sound level meter','Equal-loudness contours','A-weighting']::text[],ARRAY['Confusing frequency weighting (A/C/Z) with time weighting (Fast/Slow/Impulse).','Reporting a level in dB without stating the weighting used.','UNSAFE: Assuming a single A-weighted reading alone certifies a safe noise exposure; occupational limits depend on time-averaged level and total dose.']::text[],ARRAY['Measuring community or venue noise in dB(A).','Assessing subwoofer output with C-weighting.','Choosing Z-weighting for an unweighted engineering measurement.']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '139f8773-e24a-4387-b66c-d5c53bfae371','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='139f8773-e24a-4387-b66c-d5c53bfae371') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='139f8773-e24a-4387-b66c-d5c53bfae371');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9fd3c62-bedf-4d17-8372-41bf1a8f00c1','Frequency-response measurement','The measurement of a device or system''s output level, and often phase, as a function of frequency, typically obtained from a transfer-function comparison of output to input or from a swept-sine excitation.','This measures how a device treats each frequency. It compares the output to the input across the audio range. The result shows which frequencies are boosted, cut, or delayed. It is the core test for speakers, rooms, and processors.','It reveals tonal balance and phase behavior so a technician can verify performance, align systems, and set equalization.','Using dual-channel transfer-function software, a technician plays music or noise through a PA and compares a measurement microphone to the source to view magnitude and phase.','Measurement',ARRAY['Frequency response','Fourier transforms','Fractional-octave smoothing','Gating reflections','Coherence']::text[],ARRAY['Ignoring coherence, so noisy or reflection-corrupted data is trusted as valid.','Failing to time-align the reference to the measurement, corrupting the phase result.','Assuming one microphone position represents an entire room.']::text[],ARRAY['Aligning a live sound system before a show.','Verifying an equalizer or processor''s response.','Documenting a loudspeaker''s response for a specification sheet.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-response measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9fd3c62-bedf-4d17-8372-41bf1a8f00c1','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9fd3c62-bedf-4d17-8372-41bf1a8f00c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9fd3c62-bedf-4d17-8372-41bf1a8f00c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd59cf13c-3af5-41d8-b234-847c5a89967b','Gating reflections','A measurement technique that applies a time window to an impulse response to keep only the direct sound and exclude later room reflections, yielding a quasi-anechoic frequency response above a frequency set by the window length.','Gating cuts off the room reflections in a measurement. It keeps only the first, direct sound from the speaker. This lets you measure a speaker in a normal room. The trade-off is losing accuracy at low frequencies.','It isolates a loudspeaker''s own response from room reflections so meaningful data can be gathered without an anechoic chamber.','A technician sets a window that ends just before the first floor or wall reflection; a 5 ms window gives valid data down to roughly 200 Hz.','Measurement',ARRAY['Impulse response','Frequency-response measurement','Quasi-anechoic measurement','Window function','Fractional-octave smoothing']::text[],ARRAY['Trusting gated data below the frequency the window can resolve.','Setting the gate after the first reflection, so a reflection is still included.','Forgetting that a shorter window improves reflection rejection but worsens low-frequency resolution.']::text[],ARRAY['Measuring a loudspeaker''s response in a normal room.','Separating a driver''s direct response from a nearby boundary reflection.','Explaining why gated measurements are unreliable at low frequencies.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gating reflections');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd59cf13c-3af5-41d8-b234-847c5a89967b','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d59cf13c-3af5-41d8-b234-847c5a89967b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d59cf13c-3af5-41d8-b234-847c5a89967b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3e0c3e9e-73ae-4528-8d8d-4dd33a4fdb4a','Ground loops','An unwanted condition in which two or more grounded points are joined by more than one conductive path, forming a loop in which small voltage differences drive currents that couple into audio signals as hum and buzz.','A ground loop happens when equipment shares more than one path to ground. Tiny voltage differences push current around the loop. This current leaks into audio cables as hum and buzz. It is a common cause of noise in connected systems.','Understanding ground loops lets a technician find and cure hum caused by multiple ground paths without defeating the protective safety ground.','A technician cures a 50 or 60 Hz hum between two racks by using balanced interconnects or an audio isolation transformer to break the signal-ground loop, never by removing the safety ground.','Electrical / Grounding',ARRAY['Grounding','Isolation transformers','Balanced audio','Hum','Shield']::text[],ARRAY['UNSAFE: Lifting the third pin or using a ground-lift adapter on a power cord to stop hum; this defeats protective earth and can leave chassis at a lethal voltage.','Assuming all hum is a ground loop; it can also be induced from nearby power wiring or a bad shield.','Breaking a cable shield at both ends when it should be lifted at only one end.','Believing more ground connections always reduce noise, when extra paths create the loop.']::text[],ARRAY['Tracing hum after connecting a computer to a mixer.','Interconnecting two racks fed from different mains circuits.','Adding an isolation transformer on a hum-prone consumer input.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ground loops');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3e0c3e9e-73ae-4528-8d8d-4dd33a4fdb4a','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3e0c3e9e-73ae-4528-8d8d-4dd33a4fdb4a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3e0c3e9e-73ae-4528-8d8d-4dd33a4fdb4a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0451d00f-02b0-447d-bbca-97b0c5aa7496','Grounding','The intentional connection of equipment and circuits to earth or a common reference conductor, serving both electrical safety (a low-impedance fault path) and signal integrity (a stable reference and shielding return).','Grounding connects equipment to earth and a shared reference. For safety, it gives fault current a safe path that trips the breaker. For audio, it sets a stable zero-volt reference and helps shielding. Safety grounding must never be removed.','It protects people from electric shock by carrying fault current safely and gives audio circuits a common reference and shield return to reduce noise.','A technician bonds equipment chassis to the mains protective-earth conductor for safety, then manages signal grounds with balanced connections to control hum without defeating that earth.','Electrical / Grounding',ARRAY['Ground loops','Isolation transformers','Balanced audio','Shield','Earth']::text[],ARRAY['UNSAFE: Disconnecting or lifting the protective-earth (safety ground) connection to reduce noise; this removes shock protection and can be lethal.','Confusing the safety ground with the audio signal ground; they serve different purposes.','UNSAFE: Using a 3-to-2-prong adapter or bootleg ground to power gear without a proper earth.','Assuming a chassis is safe to touch just because it is metal; without proper earth it may be energized on a fault.']::text[],ARRAY['Wiring a rack so all chassis are safely earthed.','Deciding how to reference cable shields in a balanced system.','Explaining why defeating the ground pin is never an acceptable hum fix.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Grounding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0451d00f-02b0-447d-bbca-97b0c5aa7496','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0451d00f-02b0-447d-bbca-97b0c5aa7496') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0451d00f-02b0-447d-bbca-97b0c5aa7496');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'edd97361-cb37-49d2-932c-297a3717f1df','Group-delay plot','A graph of group delay, the negative derivative of phase with respect to angular frequency, showing how long each frequency component is delayed as it passes through a system.','A group-delay plot shows how long each frequency is held back by a device. It is found from the slope of the phase response. Large changes with frequency can smear transients. Engineers use it to judge time behavior of filters and speakers.','It reveals frequency-dependent time delay so a technician can assess transient smearing from filters, crossovers, and room behavior.','A technician inspects the group-delay plot near a crossover; excess low-frequency group delay of many milliseconds warns of audible time smear or a design issue.','Measurement / Analysis',ARRAY['Excess-phase plot','Phase response','Latency in monitoring systems','All-pass filter','Frequency-response measurement']::text[],ARRAY['Confusing group delay with a single fixed latency; group delay varies with frequency.','Reading noisy group-delay data where phase is poorly measured, giving meaningless spikes.','Assuming any group delay is audible; small, smooth delay is usually inaudible.']::text[],ARRAY['Evaluating a crossover''s time behavior.','Checking a filter for excessive low-frequency delay.','Comparing linear-phase and minimum-phase processing.']::text[],'Advanced','τ_g(ω) = − dφ/dω','Group delay equals the negative rate of change of phase with respect to angular frequency.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Group-delay plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'edd97361-cb37-49d2-932c-297a3717f1df','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='edd97361-cb37-49d2-932c-297a3717f1df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='edd97361-cb37-49d2-932c-297a3717f1df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55c28e27-bbc7-4904-8c67-6a1b246022fc','House curves','A target frequency-response shape a sound system is tuned toward for a given room or application, usually flat in the midrange with a controlled high-frequency roll-off and often a low-frequency lift, reflecting listener preference and standard practice.','A house curve is the target tone shape a system is tuned to. It is usually flat in the middle, with softer highs and often stronger lows. It reflects what listeners prefer in real rooms. Cinemas use a standardized version called the X-curve.','It gives a consistent, preferred tonal target so a system sounds balanced in its room rather than measuring flat but sounding harsh.','A technician equalizes a room''s measured response toward the house curve, for cinema following the standardized high-frequency roll-off of the SMPTE/ISO X-curve.','System Tuning',ARRAY['Frequency-response measurement','Fractional-octave smoothing','Room EQ','Target curve','Equalization']::text[],ARRAY['Aiming for a ruler-flat measured response, which often sounds too bright in a real room.','Applying a cinema X-curve target to a small music-monitoring room where it does not belong.','Chasing narrow measurement wiggles instead of matching the broad target shape.']::text[],ARRAY['Tuning a cinema B-chain to the standardized X-curve.','Setting a preferred house target for a club or theater.','Explaining why a flat measurement can still sound harsh.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='House curves');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55c28e27-bbc7-4904-8c67-6a1b246022fc','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55c28e27-bbc7-4904-8c67-6a1b246022fc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55c28e27-bbc7-4904-8c67-6a1b246022fc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd31b9654-3a49-4a97-bd96-6cd72796e46c','Impulse weighting','A legacy exponential time weighting for sound level meters, denoted I, with a very fast 35 ms rise time constant and a slow decay of about 2.9 dB per second, intended to capture short impulsive sounds; it was defined in older IEC 651 and is not part of the current IEC 61672.','Impulse weighting makes a meter react very fast to sudden sounds but fall slowly afterward. Its rise time is 35 milliseconds and it decays about 2.9 dB per second. It was made for brief, impulsive noise. Newer standards no longer include it.','It was designed to give a meter a fast-attack, slow-release response so brief impulsive sounds registered a readable level.','A technician may meet Impulse weighting only on older meters or in legacy regulations; on current IEC 61672 instruments, peak measurement is used instead for impulsive sound.','Metering / Weighting',ARRAY['Fast weighting','Slow weighting','Frequency weighting','Sound level meter','Peak level']::text[],ARRAY['Assuming Impulse weighting is still standard; it was dropped from the current IEC 61672.','Confusing Impulse time weighting with true peak measurement, which captures the instantaneous maximum.','Mixing up Impulse''s fast rise with a fast decay; its decay is deliberately slow.']::text[],ARRAY['Reading measurements taken on legacy meters.','Interpreting an older regulation that specifies Impulse weighting.','Explaining why modern practice uses peak instead of Impulse for impulsive noise.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impulse weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd31b9654-3a49-4a97-bd96-6cd72796e46c','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d31b9654-3a49-4a97-bd96-6cd72796e46c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d31b9654-3a49-4a97-bd96-6cd72796e46c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee069ccf-2b75-4bad-b6ca-211becc62da4','In-ear monitor isolation','The passive attenuation of outside sound provided by an in-ear monitor''s ear tip seal, reducing the ambient level reaching the eardrum so the performer can hear the monitor mix at a lower, safer volume.','In-ear isolation is how well an earpiece blocks outside noise by sealing the ear canal. A good seal lets a performer hear their mix clearly. Because outside noise is reduced, they can turn the level down. This helps protect hearing.','It blocks stage and crowd noise so a performer can monitor at a lower level, improving clarity and reducing hearing-damage risk compared with loud wedge monitors.','A technician fits well-sealing tips so a singer gets strong isolation, letting them set a comfortable in-ear level well below the loud stage volume they would otherwise need.','Monitoring',ARRAY['Latency in monitoring systems','Hearing protection','Ambient mic','Noise reduction rating','Frequency-response measurement']::text[],ARRAY['Assuming a poor tip seal still isolates well; a leak drops isolation, especially at low frequencies.','UNSAFE: Raising in-ear level to overcome a bad seal, which pushes the mix to hearing-damaging levels.','Confusing passive isolation with active noise cancellation; most in-ears rely on the seal alone.']::text[],ARRAY['Fitting in-ear monitors for a loud stage.','Choosing tip type to improve a performer''s isolation.','Explaining why a leaking earpiece sounds thin and unsafe.']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='In-ear monitor isolation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee069ccf-2b75-4bad-b6ca-211becc62da4','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee069ccf-2b75-4bad-b6ca-211becc62da4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee069ccf-2b75-4bad-b6ca-211becc62da4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1b1bb2c7-a5f5-4943-8eef-59bad043a7ca','Inductance','The property of a conductor or coil, measured in henries, by which a changing current induces an opposing voltage; it stores energy in a magnetic field and its reactance rises with frequency.','Inductance is a coil''s tendency to oppose changes in current. A changing current makes a magnetic field that pushes back. It is measured in henries. Inductors block high frequencies more than low ones.','It underlies coils, transformers, and crossovers, where controlled inductance shapes frequency response and stores magnetic energy.','A technician selects a crossover inductor knowing its reactance is X = 2πfL; a 1 mH coil presents about 6.3 ohms at 1 kHz.','Electrical Fundamentals',ARRAY['Input impedance','Isolation transformers','Reactance','Capacitance','Impedance']::text[],ARRAY['Confusing inductance (in henries) with the frequency-dependent reactance it produces (in ohms).','Forgetting that inductor reactance rises with frequency, opposite to a capacitor.','Ignoring an inductor''s series resistance, which affects real crossover behavior.']::text[],ARRAY['Choosing a coil for a passive loudspeaker crossover.','Analyzing a transformer or choke in a power supply.','Explaining why a long coil of cable can affect high frequencies.']::text[],'Intermediate','v = L (di/dt) ; X_L = 2πfL','The voltage across an inductor equals its inductance times the rate of change of current; its reactance equals two pi times frequency times inductance.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inductance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1b1bb2c7-a5f5-4943-8eef-59bad043a7ca','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1b1bb2c7-a5f5-4943-8eef-59bad043a7ca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1b1bb2c7-a5f5-4943-8eef-59bad043a7ca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3136d8d-4ec1-4d1d-b9c7-18ea7dbfc1df','Input impedance','The impedance a device presents at its input terminals to the source driving it; in modern audio it is usually made high relative to the source so the input bridges the source and draws little current.','Input impedance is the load a device puts on whatever feeds it. In audio it is usually kept high. A high input impedance draws little current and does not weaken the source. This is called a bridging connection.','It sets how much a device loads its source, which affects signal level, frequency response, and noise; high bridging inputs transfer voltage with minimal loading.','A technician confirms a mixer line input of around 10 kohms comfortably bridges a source of a few hundred ohms, so the source is not loaded down.','Electrical Fundamentals',ARRAY['Inductance','Impedance','Bridging','Load impedance','Balanced audio']::text[],ARRAY['Assuming inputs should be impedance-matched to the source; modern audio uses voltage bridging, not matching.','Confusing input impedance with the source''s output impedance.','Ignoring that very low input impedance can load a source and lose level or bass.']::text[],ARRAY['Connecting a microphone preamp to a microphone.','Bridging a line output into a mixer channel.','Diagnosing level loss from an input that loads the source too heavily.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Input impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3136d8d-4ec1-4d1d-b9c7-18ea7dbfc1df','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3136d8d-4ec1-4d1d-b9c7-18ea7dbfc1df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3136d8d-4ec1-4d1d-b9c7-18ea7dbfc1df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1654680-8038-4788-990a-4909abc7e839','Inverse-square relationships','A physical relationship in which a quantity falls in proportion to one over the square of distance from a point source; for sound radiating freely, intensity follows the inverse-square law and sound pressure level drops 6 dB per doubling of distance.','The inverse-square law says a point source gets weaker fast with distance. Sound intensity falls as one over distance squared. In free space, the level drops 6 dB each time you double the distance. Rooms and directional sources change this in practice.','It predicts how sound level falls with distance from a source, which is basic to estimating coverage, gain before feedback, and safe listening distances.','A technician estimates that moving from 2 m to 4 m from a point source in the open drops the level by about 6 dB, useful for planning coverage.','Acoustics',ARRAY['Sound pressure level','Free field','Directivity','Point source','Line array']::text[],ARRAY['Applying the 6 dB per doubling rule indoors, where reflections make the loss smaller.','Assuming it holds for line sources; an ideal line source falls about 3 dB per doubling in its near region.','Assuming sound pressure falls as one over distance squared like intensity; pressure falls as one over distance while intensity falls as one over distance squared, and both give a 6 dB drop per doubling.']::text[],ARRAY['Estimating coverage from a point-source loudspeaker outdoors.','Judging how far to place a measurement microphone.','Explaining why doubling the distance from a source cuts the level by 6 dB in the open.']::text[],'Intermediate','I ∝ 1/r² ; ΔL = 20·log10(r₂/r₁) dB','Intensity is proportional to one over distance squared; the level change equals twenty times the base-ten logarithm of the ratio of the two distances.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inverse-square relationships');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1654680-8038-4788-990a-4909abc7e839','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1654680-8038-4788-990a-4909abc7e839') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1654680-8038-4788-990a-4909abc7e839');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6374572a-956c-4807-b012-42b793286f31','Isolation transformers','A transformer whose primary and secondary windings are electrically separate, so a signal or power passes magnetically without a direct conductive path; in audio it breaks ground loops and blocks direct current while passing the signal.','An isolation transformer passes signal through a magnetic field, not a wire link. Its two windings are not directly connected. This breaks the ground path that causes hum. It is a safe way to stop ground-loop noise.','It provides galvanic isolation to break ground loops and block DC and common-mode voltage while passing the audio signal, curing hum without defeating safety earth.','A technician inserts a 1:1 audio isolation transformer in a hum-prone line between two devices, breaking the ground loop while leaving each unit''s protective earth intact.','Electrical / Grounding',ARRAY['Ground loops','Grounding','Balanced audio','Inductance','Common-mode rejection']::text[],ARRAY['UNSAFE: Treating an audio isolation transformer as a replacement for the mains safety ground; it is not, and earth must stay connected.','Confusing a small signal isolation transformer with a mains power isolation transformer; they serve different jobs.','Overloading a transformer''s level or low-frequency limit, causing distortion.','Assuming any transformer isolates; only separate, non-connected windings provide galvanic isolation.']::text[],ARRAY['Breaking a ground loop between a laptop and a mixer.','Isolating an unbalanced consumer device from a balanced system.','Passing audio across equipment at different ground potentials.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Isolation transformers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6374572a-956c-4807-b012-42b793286f31','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6374572a-956c-4807-b012-42b793286f31') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6374572a-956c-4807-b012-42b793286f31');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '27fe986b-32a3-45ec-a588-7fdc65c52ba5','Jitter accumulation','The buildup of timing error in a digital audio clock as jitter is added and passed along a chain of cascaded devices, links, and phase-locked loops, potentially degrading conversion quality if not attenuated.','Jitter is small timing wobble in a digital clock. As a signal passes through device after device, jitter can add up. Too much can hurt sound when it reaches a converter. Clean master clocks and reclocking limit the buildup.','Understanding jitter accumulation helps a technician design clock distribution so timing error stays low at the point where it matters, the digital-to-analog conversion.','A technician distributes a low-jitter master word clock and avoids long chains of daisy-chained devices, since each stage can add jitter that accumulates toward the converters.','Digital Audio / Clocking',ARRAY['Frame clock','Word clock','Jitter buffers','Sample rate','Phase-locked loop']::text[],ARRAY['Assuming jitter only matters at the converter and ignoring how it accumulates upstream.','Daisy-chaining many devices for clock instead of distributing from one clean master.','Confusing clock jitter with network packet delay variation, which is a different phenomenon handled by buffers.']::text[],ARRAY['Planning word-clock distribution in a large studio.','Diagnosing subtle high-frequency artifacts traced to a noisy clock.','Choosing between daisy-chained and star clock topologies.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Jitter accumulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '27fe986b-32a3-45ec-a588-7fdc65c52ba5','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='27fe986b-32a3-45ec-a588-7fdc65c52ba5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='27fe986b-32a3-45ec-a588-7fdc65c52ba5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4bf5abb-f24e-4926-9edc-030da13c204c','Jitter buffers','A buffer in a networked or streaming audio receiver that briefly stores incoming packets to absorb variation in their arrival time (packet delay variation), so audio can be played out at a steady rate without dropouts.','On a network, packets do not arrive evenly spaced. A jitter buffer holds them for a short time to smooth this out. Then audio plays at a steady pace without gaps. A bigger buffer is safer but adds delay.','It converts uneven network packet arrival into a smooth, continuous audio stream, trading a small amount of added latency for freedom from dropouts.','A technician on an audio-over-IP or VoIP link sets the jitter buffer just large enough to cover the network''s delay variation, minimizing added latency while avoiding glitches.','Networking',ARRAY['Layer 2 versus Layer 3 transport','Latency in monitoring systems','Packet delay variation','Jitter accumulation','Audio over IP']::text[],ARRAY['Confusing network packet jitter with digital clock jitter; buffers address the network kind.','Setting the buffer too small, causing dropouts under network delay variation.','Setting it needlessly large, adding audible latency to monitoring.']::text[],ARRAY['Tuning an audio-over-IP link over a busy network.','Reducing glitches on a remote broadcast contribution feed.','Balancing latency against stability for networked monitoring.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Jitter buffers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4bf5abb-f24e-4926-9edc-030da13c204c','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4bf5abb-f24e-4926-9edc-030da13c204c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4bf5abb-f24e-4926-9edc-030da13c204c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30b10349-b06b-4f7e-a3f8-91221cdb2ee6','Laplace transforms','A mathematical transform that maps a time-domain function into a complex frequency variable s, converting differential equations of a linear system into algebra and yielding transfer functions with poles and zeros.','The Laplace transform turns a time signal into a function of a complex variable called s. It changes hard calculus problems into simpler algebra. Engineers use it to analyze filters and feedback systems. Its poles and zeros describe how a system behaves.','It provides a systematic way to analyze and design linear systems, giving transfer functions whose poles and zeros reveal stability and frequency behavior.','An engineer writes a filter''s transfer function in the s-domain, then reads its poles and zeros to predict frequency response and confirm stability.','Signal Analysis',ARRAY['Fourier transforms','Feedback stability','Transfer function','Poles and zeros','Frequency response']::text[],ARRAY['Confusing the Laplace variable s with ordinary frequency; the Fourier transform is the special case on the imaginary axis.','Forgetting initial conditions when using the transform to solve a circuit.','Assuming a right-half-plane pole is acceptable; it signals an unstable system.']::text[],ARRAY['Deriving an analog filter''s transfer function.','Analyzing the stability of a feedback amplifier.','Relating pole locations to frequency response and damping.']::text[],'Advanced','X(s) = ∫₀^∞ x(t) e^{−st} dt','The Laplace transform equals the integral from zero to infinity of the time function multiplied by e to the negative s times t.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laplace transforms');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30b10349-b06b-4f7e-a3f8-91221cdb2ee6','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30b10349-b06b-4f7e-a3f8-91221cdb2ee6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30b10349-b06b-4f7e-a3f8-91221cdb2ee6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3e8b6a56-23a0-49a3-8adc-4a56cfa0d710','Latency in monitoring systems','The total time delay between a sound entering a monitoring signal path and the performer hearing it back, arising from conversion, digital processing, buffering, and network transport; excessive latency disturbs timing and can cause comb filtering with acoustic sound.','Monitoring latency is the delay a performer hears between playing and hearing themselves. It comes from converters, processing, and buffers. Even a few milliseconds can feel wrong to a singer. Combined with direct sound it can also cause hollow comb-filter tone.','Managing latency keeps monitor feedback tight enough for performers to play in time and avoids audible comb filtering when the delayed signal mixes with direct acoustic sound.','A technician keeps round-trip monitoring latency low, generally aiming under about 10 ms, by minimizing buffer sizes and processing in the monitor path.','Monitoring',ARRAY['Latency','Jitter buffers','Group-delay plot','In-ear monitor isolation','Direct monitoring']::text[],ARRAY['Confusing latency (a delay) with jitter (a timing variation).','Adding heavy plug-in processing to a monitor path, which raises latency.','Ignoring that delayed monitoring plus direct sound can comb-filter the performer''s tone.']::text[],ARRAY['Setting up low-latency monitoring for a vocalist tracking.','Choosing buffer size on a digital console or interface.','Diagnosing a performer''s complaint that their voice sounds delayed or hollow.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Latency in monitoring systems');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3e8b6a56-23a0-49a3-8adc-4a56cfa0d710','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3e8b6a56-23a0-49a3-8adc-4a56cfa0d710') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3e8b6a56-23a0-49a3-8adc-4a56cfa0d710');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a83d23c1-e339-4aab-9201-e4bb5a8ebcd9','Layer 2 versus Layer 3 transport','A distinction from the OSI networking model between carrying audio at Layer 2, the data-link layer using Ethernet MAC addresses within a single switched network, and Layer 3, the network layer using IP addresses that can be routed between subnets.','Networks are described in layers. Layer 2 moves data by hardware Ethernet addresses inside one local network. Layer 3 uses IP addresses and can route between networks. Audio systems may run at either layer, which affects how far they can travel.','It determines how networked audio is addressed and how far it can travel; Layer 2 stays within a switched LAN, while Layer 3 (IP) can be routed across subnets and larger networks.','A technician deploying AES67, which runs over Layer 3 IP, plans subnets and routing, whereas a purely Layer 2 mode is confined to one switched local network.','Networking',ARRAY['Jitter buffers','Audio over IP','AES67','Latency in monitoring systems','Ethernet']::text[],ARRAY['Assuming a Layer 2 audio flow can be routed across subnets; it cannot without Layer 3.','Confusing the OSI layer with the physical cable type.','Overlooking that multicast handling differs between Layer 2 switching and Layer 3 routing.']::text[],ARRAY['Designing an audio-over-IP network that spans multiple subnets.','Deciding whether a networked audio format needs routing.','Troubleshooting why devices on different subnets cannot exchange audio.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Layer 2 versus Layer 3 transport');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a83d23c1-e339-4aab-9201-e4bb5a8ebcd9','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a83d23c1-e339-4aab-9201-e4bb5a8ebcd9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a83d23c1-e339-4aab-9201-e4bb5a8ebcd9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '05604e78-191c-47b3-a08f-f75240dfd326','Linear timecode','A form of SMPTE timecode, abbreviated LTC, encoded as a biphase-mark audio-frequency signal so it can be recorded on and played back from an audio track, carrying hours, minutes, seconds, and frames for synchronization.','Linear timecode is a clock signal recorded like audio on a track. It carries hours, minutes, seconds, and frames. Machines read it to stay in sync. It works well while tape or media is moving at play speed.','It lets audio and video machines share a common time reference for synchronization by recording an addressable timecode onto an ordinary audio track.','A technician stripes LTC onto a track and feeds it to a synchronizer so a recorder locks frame-accurately to picture, choosing the frame rate to match the video standard.','Synchronization',ARRAY['Frame clock','Word clock','Frame rate','Synchronization','Vertical interval timecode']::text[],ARRAY['Confusing linear timecode with vertical interval timecode, which is embedded in the video signal instead.','Mismatching the timecode frame rate to the project''s video frame rate.','Assuming LTC reads reliably at very slow shuttle or still, where it becomes unreadable.']::text[],ARRAY['Synchronizing a multitrack recorder to a video deck.','Striping timecode across devices on a shoot.','Choosing 24, 25, or 29.97 frame rates to match a production standard.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linear timecode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '05604e78-191c-47b3-a08f-f75240dfd326','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='05604e78-191c-47b3-a08f-f75240dfd326') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='05604e78-191c-47b3-a08f-f75240dfd326');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '559c4d11-965c-4887-ba2c-d2c13f3b154c','Link aggregation','Link aggregation combines two or more physical Ethernet links into one logical link that shares traffic across the members and continues operating if a member link fails. The IEEE standard defines the Link Aggregation Control Protocol (LACP) that negotiates the bundle between two devices.','Link aggregation ties several network cables together so they act as one bigger link. It shares the traffic across all the cables. If one cable fails, the others keep the connection alive. Audio networks use it for more bandwidth and backup paths.','It increases available bandwidth beyond a single link and adds fault tolerance so a single cable or port failure does not drop the connection.','A technician may bond two 1 Gbps switch ports with LACP so a Dante network gains headroom and a redundant path; if one link dies, audio keeps flowing on the other.','Networking',ARRAY['Network topology','Multicast','Network clock domains','Networked-audio troubleshooting']::text[],ARRAY['Assuming a single stream gets the summed speed; one flow usually rides one member link, so aggregation adds capacity across many flows, not one.','Bonding ports without configuring LACP on both switch ends, which can cause loops or a failed bundle.','Confusing link aggregation with Dante''s separate primary/secondary redundancy, which uses two independent networks.']::text[],ARRAY['Trunking two uplinks between stage and front-of-house switches for a large Dante system.','Adding a redundant, higher-bandwidth path to a networked-audio core switch.','Diagnosing why aggregated links do not double a single file-transfer speed.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Link aggregation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '559c4d11-965c-4887-ba2c-d2c13f3b154c','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='559c4d11-965c-4887-ba2c-d2c13f3b154c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='559c4d11-965c-4887-ba2c-d2c13f3b154c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff2fa137-16e7-496d-a3dd-8d62ed7e6c5f','Logarithms','A logarithm is the exponent to which a fixed base must be raised to produce a given number, so log_b(x)=y means b^y=x. Base-10 logarithms underlie the decibel, which expresses ratios of power or amplitude on a compressed scale.','A logarithm answers the question: what power gives this number? For base 10, the log of 1000 is 3, because 10 to the 3rd is 1000. Audio uses base-10 logs to build the decibel. This turns huge ratios into small, easy numbers.','Logarithms compress very large ranges into manageable numbers and turn multiplication into addition, which is why decibels and octave scales rely on them.','To find gain in decibels for a voltage ratio, a technician computes 20*log10(Vout/Vin); a 10x voltage gain gives 20*log10(10)=20 dB.','Mathematics',ARRAY['Matrix operations','Loudspeaker load calculations','Maximum power transfer']::text[],ARRAY['Using 10*log10 for voltage or pressure ratios instead of 20*log10, which are power-based versus amplitude-based.','Forgetting that log of a ratio is subtraction of logs, so dividing values means subtracting their dB.','Trying to take the logarithm of zero or a negative number, which is undefined.']::text[],ARRAY['Converting a measured voltage ratio to a gain figure in decibels.','Reading an octave-spaced frequency axis on an analyzer.','Explaining why each 10 dB step is a tenfold change in power.']::text[],'Beginner','log_b(x) = y  <=>  b^y = x ;  log_b(x*z) = log_b(x) + log_b(z)','The logarithm base b of x is the exponent y that makes b raised to y equal x; the log of a product equals the sum of the logs.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Logarithms');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff2fa137-16e7-496d-a3dd-8d62ed7e6c5f','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff2fa137-16e7-496d-a3dd-8d62ed7e6c5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff2fa137-16e7-496d-a3dd-8d62ed7e6c5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cdf7b557-abaf-4257-81da-15a302ede4ee','Loudspeaker aiming','Loudspeaker aiming is the deliberate setting of a loudspeaker''s horizontal and vertical orientation so its coverage pattern points at the intended audience area and away from reflective or unoccupied surfaces. It is guided by the device''s rated coverage angles and the geometry of the listening area.','Loudspeaker aiming means pointing each speaker so its sound lands on the audience. You tilt and turn it to cover the seats, not the walls or ceiling. Good aiming spreads level evenly. It also keeps sound off surfaces that cause echoes.','Correct aiming maximizes direct sound onto listeners and even coverage while minimizing energy hitting reflective surfaces that reduce clarity.','Using a speaker''s rated -6 dB coverage angle, a technician tilts a box down so its pattern edge reaches the last row and the on-axis line clears the front rows.','System Design',ARRAY['Out fills','Loudspeaker load calculations','Main-to-sub timing','Microphone-loudspeaker geometry']::text[],ARRAY['Aiming the on-axis line at the front rows, leaving the back too quiet.','Ignoring vertical coverage and letting energy splash off the ceiling or rear wall.','Assuming louder equals better instead of aiming for even coverage across seats.']::text[],ARRAY['Setting tilt angles on flown mains before a concert.','Orienting delay speakers to cover a balcony without hitting the ceiling.','Adjusting a horn to reduce reflections off a hard side wall.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudspeaker aiming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cdf7b557-abaf-4257-81da-15a302ede4ee','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cdf7b557-abaf-4257-81da-15a302ede4ee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cdf7b557-abaf-4257-81da-15a302ede4ee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '628fe6e4-75cc-41cd-82cc-200f560c4b6e','Loudspeaker load calculations','Loudspeaker load calculations determine the total electrical load an amplifier drives, either as the combined impedance of parallel low-impedance drivers or as the summed tap wattage on a constant-voltage (25/70.7/100 V) distribution line. The result must stay within the amplifier''s rated minimum impedance or power capability.','Load calculations check that the speakers do not overwork the amplifier. For low-impedance speakers, wiring them in parallel lowers the total impedance. For 70-volt lines, you add up the wattage each speaker taps. The total must stay inside the amplifier''s rating, with headroom to spare.','These calculations prevent overloading an amplifier below its safe minimum impedance or above its power rating, protecting the amplifier and connected loudspeakers.','On a 70.7 V line, a technician sums the tap settings (for example ten 10 W plus five 20 W taps = 200 W) and picks an amplifier rated well above that, commonly sizing to about 1.5 times the tap total for losses.','Electrical',ARRAY['Maximum power transfer','Output-current limiting','Logarithms','Loudspeaker aiming']::text[],ARRAY['UNSAFE: Paralleling low-impedance speakers below the amplifier''s rated minimum impedance, which can overheat the amplifier and cause a fire or failure.','UNSAFE: Loading a 70.7/100 V line with taps that total more than the amplifier''s rated power, causing overload, overheating, and shutdown or damage.','Confusing a speaker''s tap wattage with its continuous power handling.','Forgetting to leave headroom above the calculated load for line and transformer losses.']::text[],ARRAY['Designing a 70.7 V paging system across many ceiling speakers.','Checking that four paralleled 8-ohm cabinets do not drop an amplifier below 2 ohms.','Sizing an amplifier for a distributed background-music zone.']::text[],'Intermediate','1/Z_total = sum(1/Z_i)  (low-Z parallel) ;  P_amp >= 1.5 * sum(P_tap)  (constant-voltage line)','For parallel low-impedance speakers the reciprocal of total impedance equals the sum of the reciprocals; for a constant-voltage line the amplifier power should be at least about 1.5 times the sum of all tap wattages.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudspeaker load calculations');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '628fe6e4-75cc-41cd-82cc-200f560c4b6e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='628fe6e4-75cc-41cd-82cc-200f560c4b6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='628fe6e4-75cc-41cd-82cc-200f560c4b6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35026e19-d13f-4ca8-8b4b-e466cb46f614','MIDI timecode','MIDI Time Code (MTC) carries SMPTE-style timecode (hours:minutes:seconds:frames) over MIDI so devices can synchronize to a common time reference. Running time is sent as quarter-frame messages, with eight quarter-frame messages conveying one full timecode value over two frames, plus a full-frame message for locating.','MIDI Time Code sends clock position over MIDI cables. It carries the same hours, minutes, seconds, and frames used by film and video. Small quarter-frame messages update the time as it runs. This lets synths, recorders, and sequencers all follow one clock.','MTC lets separate MIDI-connected devices lock to the same running timecode so playback, recording, and cues stay aligned with picture or other machines.','A technician sets a DAW to send MTC at 29.97 fps so a hardware sampler chases the same timecode and both start and stay locked to the video.','Synchronization',ARRAY['Network clock domains','Measurement latency','Main-to-sub timing']::text[],ARRAY['Setting different frame rates on the two devices, so they drift or refuse to lock.','Confusing MTC (running position) with MIDI Clock, which sends musical tempo pulses instead.','Expecting sample-accurate audio sync, when MTC resolution is one quarter-frame.']::text[],ARRAY['Locking a DAW to a video deck for post-production.','Chasing a hardware sequencer to a master timeline.','Synchronizing lighting or show-control cues to audio playback.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='MIDI timecode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35026e19-d13f-4ca8-8b4b-e466cb46f614','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35026e19-d13f-4ca8-8b4b-e466cb46f614') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35026e19-d13f-4ca8-8b4b-e466cb46f614');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a435125d-76b2-4831-8009-8d10f790718e','Magnitude summation','Magnitude summation combines the frequency responses of two or more sources by adding their magnitudes while ignoring phase, giving the maximum possible combined level rather than the true acoustic sum. It bounds the result that full phase-aware (complex) summation would produce.','Magnitude summation adds the levels of two signals but ignores their phase. It shows the loudest possible combined result. The real acoustic sum is usually less, because phase differences cause partial cancellation. It is a quick upper-limit estimate, not the true total.','It provides a fast worst-case or best-case level estimate for combined sources without the phase data needed for a full complex sum.','Two equal sources summed by magnitude give +6 dB; a technician uses this as the ceiling, knowing real overlap with phase offset yields less, often nearer 0 to +6 dB.','Measurement',ARRAY['Main-to-sub timing','Merging near-field and far-field responses','Loudspeaker aiming','Modal decomposition']::text[],ARRAY['Treating magnitude summation as the real acoustic result, when phase can cause deep cancellations.','Assuming two sources always add to +6 dB regardless of phase and correlation.','Ignoring that only correlated signals sum coherently; uncorrelated signals add on a power basis (+3 dB).']::text[],ARRAY['Estimating maximum combined level from overlapping loudspeakers.','Sanity-checking a prediction against analyzer traces.','Explaining why measured combined level is below the simple magnitude sum.']::text[],'Advanced','|H_total(f)| = sum |H_i(f)|   (phase ignored)','The summed magnitude at each frequency is the sum of the individual magnitudes, with phase disregarded.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnitude summation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a435125d-76b2-4831-8009-8d10f790718e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a435125d-76b2-4831-8009-8d10f790718e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a435125d-76b2-4831-8009-8d10f790718e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a0bd72ff-572a-4b01-a634-ff2eac68a882','Main-to-sub timing','Main-to-sub timing is the delay adjustment that aligns the arrival time of a subwoofer''s output with the main loudspeakers at the crossover region so the two combine additively rather than cancel. It is set from the path-length difference and verified by measurement of the summed response.','Main-to-sub timing lines up the subwoofers with the main speakers. If they arrive at different times, the bass can cancel where they overlap. A technician adds delay to the earlier source. The goal is strong, even output through the crossover.','It ensures the sub and mains add constructively through the crossover band instead of partially cancelling, giving smooth, powerful low-frequency coverage.','If mains sit 3.4 m in front of the subs, a technician delays the subs by about 10 ms (3.4 m divided by 343 m/s) and confirms addition on an analyzer at the crossover.','System Alignment',ARRAY['Magnitude summation','Loudspeaker aiming','Measurement latency','Merging near-field and far-field responses']::text[],ARRAY['Setting delay by physical distance alone and skipping measurement to confirm addition.','Aligning at one frequency only and ignoring polarity, which can flip addition to cancellation.','Forgetting that moving the measurement position changes the relative arrival times.']::text[],ARRAY['Time-aligning ground-stacked subs to flown mains before a show.','Fixing a dip at the sub-to-main crossover heard in the audience.','Setting delay after subs are relocated during load-in.']::text[],'Advanced','t_delay = d / c   (c ~= 343 m/s at 20 C)','The delay time equals the extra path length divided by the speed of sound.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Main-to-sub timing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a0bd72ff-572a-4b01-a634-ff2eac68a882','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a0bd72ff-572a-4b01-a634-ff2eac68a882') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a0bd72ff-572a-4b01-a634-ff2eac68a882');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '692af275-bdb8-4af2-8e79-51897faddf7a','Matrix operations','Matrix operations are the arithmetic rules for combining rectangular arrays of numbers, including addition, scalar multiplication, and matrix multiplication, where the product entry is the dot product of a row and a column. In audio they model routing and mixing where many inputs map to many outputs.','A matrix is a grid of numbers. Matrix math combines these grids by set rules. Multiplying a routing matrix by inputs gives the outputs. Audio consoles use this idea to send many inputs to many outputs with set gains.','They provide a compact way to describe and compute many-input to many-output mappings, such as mixer routing, channel gains, and signal transforms.','A matrix mixer applies a gain matrix to input channels; multiplying the 4x4 gain matrix by the 4 input levels yields the 4 output bus levels in one operation.','Mathematics',ARRAY['Logarithms','Modal decomposition','Minimum-phase derivation']::text[],ARRAY['Multiplying matrices in the wrong order, since matrix multiplication is not commutative.','Trying to multiply matrices whose inner dimensions do not match.','Confusing element-by-element multiplication with true matrix multiplication.']::text[],ARRAY['Configuring a matrix mixer to feed multiple zones from shared inputs.','Describing a signal transform such as a mid-side encode with a 2x2 matrix.','Understanding channel-routing math in a DSP processor.']::text[],'Advanced','(AB)_{ij} = sum_k A_{ik} * B_{kj}','Each entry of a matrix product is the sum over k of the row element times the corresponding column element.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Matrix operations');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '692af275-bdb8-4af2-8e79-51897faddf7a','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='692af275-bdb8-4af2-8e79-51897faddf7a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='692af275-bdb8-4af2-8e79-51897faddf7a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e76d4a11-bbb5-4521-88c1-50271595f402','Maximum power transfer','The maximum power transfer theorem states that a source delivers the greatest power to a load when the load resistance equals the source''s internal (Thevenin) resistance, or, for AC, when the load impedance equals the complex conjugate of the source impedance. At that match, only half the total power reaches the load; the rest is dissipated in the source.','This rule says a source gives the most power to a load when their resistances match. But at that match, only half the power reaches the load. The other half is lost inside the source. Audio gear usually avoids this and uses voltage bridging instead.','The theorem sets the condition for peak power delivery and explains why matched loads are only 50 percent efficient, guiding when to match versus when to bridge.','Modern audio uses a low source impedance into a much higher input impedance (voltage bridging) for efficiency and low loss, rather than matching impedances to chase maximum power.','Electrical',ARRAY['Loudspeaker load calculations','Output-current limiting','Logarithms']::text[],ARRAY['UNSAFE: Deliberately matching a loudspeaker load to an amplifier''s output impedance to draw maximum power, which halves efficiency and can overheat the amplifier.','Assuming impedance matching gives maximum voltage transfer; it maximizes power, not voltage.','Applying the resistive form to reactive loads instead of using the complex-conjugate condition.']::text[],ARRAY['Explaining why line outputs bridge into high-impedance inputs instead of matching.','Analyzing power delivery in an RF or antenna-matched stage.','Understanding efficiency trade-offs in a source-load pairing.']::text[],'Advanced','P_load is max when R_load = R_source ; for AC, Z_load = Z_source*','Power in the load is greatest when the load resistance equals the source resistance, or for alternating current when the load impedance equals the complex conjugate of the source impedance.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum power transfer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e76d4a11-bbb5-4521-88c1-50271595f402','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e76d4a11-bbb5-4521-88c1-50271595f402') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e76d4a11-bbb5-4521-88c1-50271595f402');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2bc6dab-0220-458a-8296-ece6be556411','Maximum-length sequence measurement','Maximum-length sequence (MLS) measurement excites a system with a deterministic pseudo-random binary sequence and recovers the impulse response by cross-correlating the output with the known sequence. Because an MLS has a flat spectrum and its periodic autocorrelation approximates an impulse, it yields the transfer function with good noise immunity.','MLS measurement plays a special noise-like signal into a system. Software then compares the output with the known signal. This recovers the system''s impulse response. The method resists background noise and was widely used in acoustic analyzers.','It measures a system''s impulse response and transfer function efficiently and with strong noise rejection using a repeatable, spectrally flat stimulus.','A technician plays an MLS through a loudspeaker into a room; the analyzer cross-correlates the captured signal to extract the impulse response and derive frequency response and reverberation data.','Measurement',ARRAY['Measurement latency','Minimum-phase derivation','Multitone testing','Measurement noise floor']::text[],ARRAY['Applying MLS to strongly time-variant or nonlinear systems, where distortion smears into the recovered response.','Using too short a sequence for the room, so the response wraps and truncates the decay.','Assuming any random noise works; the sequence must be the exact known MLS for correlation.']::text[],ARRAY['Measuring a room impulse response and reverberation time.','Capturing a loudspeaker frequency response in a noisy venue.','Comparing MLS with swept-sine methods for distortion handling.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum-length sequence measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2bc6dab-0220-458a-8296-ece6be556411','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2bc6dab-0220-458a-8296-ece6be556411') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2bc6dab-0220-458a-8296-ece6be556411');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'adcd1ebe-b2a7-4efa-9565-c7bb29bb7766','Measurement latency','Measurement latency is the time offset a dual-channel analyzer must compensate between its reference input and the microphone (measurement) input so the two align in time before a transfer-function computation. It accounts for propagation delay plus processing delay in the signal chain.','Measurement latency is the delay between the reference signal and the microphone signal. The analyzer must line these up in time. The delay comes from sound travel and gear processing. If it is wrong, the phase reading is meaningless.','Correct latency compensation aligns the two analyzer channels so the transfer function shows true phase and coherence rather than a delayed, smeared result.','A technician runs the analyzer''s delay finder, which inserts, for example, 12 ms to match the acoustic path, then reads accurate phase across frequency.','Measurement',ARRAY['Main-to-sub timing','Maximum-length sequence measurement','Measurement noise floor','Measurement-position dependency']::text[],ARRAY['Skipping the delay-finder step, so phase and coherence traces are unreliable.','Re-using an old delay value after moving the microphone or changing processing.','Confusing system processing latency with the acoustic propagation delay to the mic.']::text[],ARRAY['Setting the internal delay before tuning a system with a dual-channel analyzer.','Re-measuring delay after adding a DSP block that changes latency.','Troubleshooting a jumpy phase trace caused by wrong time alignment.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement latency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'adcd1ebe-b2a7-4efa-9565-c7bb29bb7766','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='adcd1ebe-b2a7-4efa-9565-c7bb29bb7766') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='adcd1ebe-b2a7-4efa-9565-c7bb29bb7766');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea71a73b-9c56-4db2-97eb-b16ece4ad672','Measurement microphone calibration','Measurement microphone calibration establishes a microphone''s sensitivity by applying a known sound pressure from a reference acoustic calibrator or pistonphone and recording the resulting output. It ties readings to defined standards for measurement microphones and sound calibrators so absolute levels are traceable.','Calibration finds out how sensitive a measurement microphone is. A calibrator makes a known, steady sound level at the mic. You then set the analyzer so its reading matches that level. Now your absolute decibel readings can be trusted.','It makes sound-level readings accurate and traceable by referencing the microphone''s output to a known applied pressure rather than an assumed sensitivity.','A technician places a calibrator producing 94 dB SPL at 1 kHz over the mic and sets the analyzer to read 94 dB, fixing the sensitivity for the session.','Measurement',ARRAY['Measurement noise floor','Near-field loudspeaker measurement','Measurement-position dependency','Multitone testing']::text[],ARRAY['Trusting a nominal sensitivity from the datasheet instead of calibrating the actual microphone.','Calibrating with a poorly fitting adapter that leaks and lowers the applied level.','Forgetting free-field versus pressure response corrections for the microphone type.']::text[],ARRAY['Referencing an analyzer to absolute SPL before compliance measurements.','Checking calibration drift at the start of a measurement day.','Setting up a class-1 sound level meter with its calibrator.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement microphone calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea71a73b-9c56-4db2-97eb-b16ece4ad672','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea71a73b-9c56-4db2-97eb-b16ece4ad672') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea71a73b-9c56-4db2-97eb-b16ece4ad672');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '79a6a74e-5b64-435f-b3f5-fcb4d1bdfd9e','Measurement noise floor','The measurement noise floor is the residual level of ambient acoustic noise plus electrical self-noise present when no test signal is applied, setting the lowest level a measurement can resolve. Useful data must sit above this floor, expressed as an adequate signal-to-noise or coherence margin.','The noise floor is the background level with no test signal playing. It comes from room noise and gear hiss. Your measurement signal must rise well above it. Below the floor, the readings are just noise, not real data.','It defines the sensitivity limit of a measurement and tells the technician how much level or averaging is needed for trustworthy results.','If the room floor is 40 dB SPL, a technician raises the test signal or averages more so the measurement sits 15 to 20 dB above the floor for good coherence.','Measurement',ARRAY['Measurement latency','Maximum-length sequence measurement','Measurement microphone calibration','Measurement signal versus program material']::text[],ARRAY['Trusting data at frequencies where the signal barely exceeds the noise floor.','Ignoring low coherence that flags noise-dominated regions.','Blaming the system for dips that are actually the noise floor limiting the reading.']::text[],ARRAY['Judging whether low-frequency data is valid in a noisy venue.','Deciding how much averaging to apply during a measurement.','Explaining ragged high-frequency traces caused by low signal-to-noise.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement noise floor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '79a6a74e-5b64-435f-b3f5-fcb4d1bdfd9e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='79a6a74e-5b64-435f-b3f5-fcb4d1bdfd9e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='79a6a74e-5b64-435f-b3f5-fcb4d1bdfd9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '790c3c09-f760-4be9-9e9e-a0866dff76f2','Measurement signal versus program material','This distinction contrasts controlled, known test stimuli (such as swept sines, MLS, pink noise, or multitone) used for repeatable measurement against real music or speech (program material) used to judge subjective performance. Test signals give analyzable, repeatable data; program material reveals perceived results but is not a controlled reference.','Measurement signals are known test sounds like sweeps or pink noise. They give repeatable numbers. Program material is real music or speech. It shows how the system sounds, but it is not a controlled test. Good tuning uses both.','It clarifies when to use a defined stimulus for objective, repeatable measurement versus when to use real program to check perceived tonal balance and behavior.','A technician tunes response with pink noise or a sweep on an analyzer, then plays familiar music to confirm the result sounds right in the room.','Measurement',ARRAY['Multitone testing','Maximum-length sequence measurement','Measurement noise floor','Measurement latency']::text[],ARRAY['Trying to read a stable transfer function from constantly changing music.','Judging a system only by test traces without listening to program material.','Assuming pink-noise flatness equals a good subjective balance in every room.']::text[],ARRAY['Choosing pink noise versus music while setting system EQ.','Explaining why an analyzer needs a known stimulus for phase data.','Verifying an aligned system with reference tracks.']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement signal versus program material');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '790c3c09-f760-4be9-9e9e-a0866dff76f2','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='790c3c09-f760-4be9-9e9e-a0866dff76f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='790c3c09-f760-4be9-9e9e-a0866dff76f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b6353309-502e-4e80-8731-9ac34cdc912b','Measurement-position dependency','Measurement-position dependency is the fact that a system''s measured magnitude and phase response change with the microphone''s location because of path-length differences, reflections, and room modes. A single position is not representative, so multiple positions or spatial averaging are used.','Where you put the microphone changes what you measure. Reflections and room modes differ from seat to seat. One position does not describe the whole room. Technicians measure several spots and average them.','Recognizing position dependency prevents over-correcting for a local artifact and guides spatial averaging so decisions reflect the audience area, not one point.','A technician takes several measurements across the seating area and averages them, avoiding an EQ notch aimed at a dip that only exists at one microphone spot.','Measurement',ARRAY['Modal decomposition','Measurement noise floor','Microphone-loudspeaker geometry','Merging near-field and far-field responses']::text[],ARRAY['Tuning aggressively to fix a null that exists only at one microphone position.','Assuming one central measurement represents the whole audience.','Ignoring room modes that make low-frequency readings vary strongly with position.']::text[],ARRAY['Deciding how many microphone positions to capture for room tuning.','Explaining why a deep dip disappears when the mic moves.','Applying spatial averaging before setting system EQ.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement-position dependency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b6353309-502e-4e80-8731-9ac34cdc912b','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b6353309-502e-4e80-8731-9ac34cdc912b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b6353309-502e-4e80-8731-9ac34cdc912b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8177903f-44e5-4233-9d7b-912a119da438','Merging near-field and far-field responses','Merging near-field and far-field responses combines a close-microphone low-frequency measurement (free of room reflections) with a farther gated or anechoic measurement (valid at higher frequencies) to produce one full-range loudspeaker response. The two are level-matched and spliced in a frequency region where both are valid.','This method builds one full-range speaker curve from two measurements. A close mic captures clean bass without room echoes. A farther, gated mic captures the highs. The two are matched in level and joined in the middle. The result covers the whole range.','It yields an accurate full-bandwidth loudspeaker response without an anechoic chamber by using each measurement where it is valid and stitching them together.','A technician takes a near-field woofer measurement, adds baffle-step and diffraction corrections, and splices it to a gated far-field measurement around 200 to 500 Hz.','Measurement',ARRAY['Near-field loudspeaker measurement','Magnitude summation','Measurement-position dependency','Modal decomposition']::text[],ARRAY['Splicing without correcting near-field level for radiating area and baffle step.','Choosing a merge frequency where one measurement is already invalid.','Ignoring the near-field distance limit set by the radiator size.']::text[],ARRAY['Building a full-range curve for a loudspeaker design without an anechoic chamber.','Combining woofer and gated tweeter data into one response.','Validating a simulated response against merged measurements.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Merging near-field and far-field responses');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8177903f-44e5-4233-9d7b-912a119da438','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8177903f-44e5-4233-9d7b-912a119da438') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8177903f-44e5-4233-9d7b-912a119da438');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a90bf23-b421-4bec-8ec9-4b450849c052','Microphone-loudspeaker geometry','Microphone-loudspeaker geometry is the spatial relationship (distance and angle) between microphones and loudspeakers that governs how much loudspeaker output re-enters the microphone and thus the available acoustic gain before feedback. Keeping the mic close to the talker while keeping loudspeakers far from the mic raises the potential acoustic gain before feedback.','This is how mics and speakers are placed relative to each other. If a speaker points at a mic and sits close, feedback comes easily. Keeping speakers far from mics and mics close to talkers helps. Good geometry raises how loud you can go safely.','It sets the physical limit on how much gain a sound reinforcement system can produce before feedback, before any electronic processing.','A technician moves floor monitors out of a vocal mic''s rear pattern and keeps the singer close to the mic, gaining several decibels before feedback.','System Design',ARRAY['Monitor gain before feedback','Loudspeaker aiming','Open-loop versus closed-loop behavior','Measurement-position dependency']::text[],ARRAY['Placing loudspeakers behind or aimed at open microphones, inviting feedback.','Letting talkers work far from the mic, which forces more gain and less headroom.','Relying on a feedback suppressor to fix poor placement instead of fixing geometry first.']::text[],ARRAY['Positioning stage monitors relative to vocal mics.','Setting lectern mic and loudspeaker placement in a meeting room.','Explaining feedback that starts when a performer walks toward a speaker.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microphone-loudspeaker geometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a90bf23-b421-4bec-8ec9-4b450849c052','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a90bf23-b421-4bec-8ec9-4b450849c052') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a90bf23-b421-4bec-8ec9-4b450849c052');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f70e296a-85d3-485e-a648-3cc7a7818433','Minimum-phase derivation','Minimum-phase derivation computes the phase response uniquely determined by a system''s magnitude response, valid for minimum-phase systems whose poles and zeros lie inside the unit circle. It is obtained from the Hilbert transform of the log-magnitude spectrum, and any excess (non-minimum) phase must be added separately.','For minimum-phase systems, the magnitude curve alone fixes the phase. Math called the Hilbert transform derives that phase from the log magnitude. Extra delay or all-pass behavior is not included. This helps separate fixable response from pure time delay.','It lets a technician find the phase tied to a magnitude response and distinguish minimum-phase behavior (correctable by EQ) from excess phase such as pure delay.','Analysis software derives the minimum-phase curve from a measured magnitude; where measured phase matches it, EQ can correct the response, unlike a fixed time delay.','DSP',ARRAY['Modal decomposition','Maximum-length sequence measurement','Matrix operations','Open-loop versus closed-loop behavior']::text[],ARRAY['Assuming every system is minimum-phase and can be fully corrected by EQ.','Treating pure delay (excess phase) as something EQ can fix.','Forgetting that only stable systems with all zeros inside the unit circle are minimum-phase.']::text[],ARRAY['Deciding whether a response dip is EQ-correctable or a phase artifact.','Separating driver behavior from crossover time offsets.','Interpreting minimum-phase overlays in measurement software.']::text[],'Advanced','phase_min(w) = -H{ ln|H(w)| }   (H = Hilbert transform)','The minimum-phase response is the negative Hilbert transform of the natural log of the magnitude response.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minimum-phase derivation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f70e296a-85d3-485e-a648-3cc7a7818433','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f70e296a-85d3-485e-a648-3cc7a7818433') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f70e296a-85d3-485e-a648-3cc7a7818433');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eed1580f-ee70-4bdd-b2ba-927fa28fe78e','Modal decomposition','Modal decomposition expresses a room''s low-frequency sound field as a sum of normal modes (standing-wave resonances), each with a characteristic frequency, damping, and spatial pressure pattern. Below the Schroeder frequency these discrete modes dominate the response and vary strongly with position.','A room''s bass behavior can be broken into standing-wave patterns called modes. Each mode has its own frequency and shape in the room. These modes cause bass peaks and dips that move with location. Understanding them explains uneven low end.','It explains and predicts uneven low-frequency response in rooms by identifying the individual resonances that create peaks, dips, and position-dependent bass.','A technician identifies an axial mode at, say, 45 Hz from room dimensions, then repositions subwoofers or the listening spot to reduce that mode''s effect.','Room Acoustics',ARRAY['Measurement-position dependency','Magnitude summation','Minimum-phase derivation','Outdoor propagation']::text[],ARRAY['Trying to EQ away a deep modal null, which mostly wastes headroom without filling the dip.','Assuming modes are audible across the whole spectrum instead of mainly below the Schroeder frequency.','Ignoring that mode levels change with both source and listener position.']::text[],ARRAY['Diagnosing boomy or uneven bass in a control room.','Choosing subwoofer and seat positions to tame room modes.','Explaining why bass differs from seat to seat.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal decomposition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eed1580f-ee70-4bdd-b2ba-927fa28fe78e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eed1580f-ee70-4bdd-b2ba-927fa28fe78e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eed1580f-ee70-4bdd-b2ba-927fa28fe78e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dea64d28-f6d8-4531-9a65-24501bc1f026','Monitor gain before feedback','Monitor gain before feedback is the maximum gain a stage monitor system can reach before the loop from loudspeaker back to open microphone becomes unstable and rings. It depends on microphone-loudspeaker geometry, directivity, number of open mics, and room acoustics, and is described by potential acoustic gain relationships.','This is how loud a stage monitor can get before it howls. Sound from the monitor leaks back into the mic. When that loop reaches unity, feedback starts. Better placement, fewer open mics, and directional gear raise this limit.','It sets the practical loudness limit for foldback monitoring and guides placement, mic choice, and mix decisions to maximize usable level.','A technician gains a few decibels before feedback by using a cardioid mic, aiming the monitor into its null, and muting unused channels; each doubling of open mics costs about 3 dB.','System Design',ARRAY['Microphone-loudspeaker geometry','Open-loop versus closed-loop behavior','Loudspeaker aiming','Maximum power transfer']::text[],ARRAY['Leaving unused microphones open, since each doubling of open mics lowers gain before feedback by about 3 dB.','Pushing monitor level past the ring point instead of fixing placement.','Relying only on notch EQ rather than improving geometry and directivity.']::text[],ARRAY['Setting wedge levels at soundcheck without triggering feedback.','Choosing mic pattern and monitor placement for a vocalist.','Deciding how many mics to leave live during a panel event.']::text[],'Intermediate','NOM penalty (dB) ~= 10 * log10(N_open mics)','Adding open microphones reduces available gain; the loss in decibels is about ten times the base-ten log of the number of open microphones.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Monitor gain before feedback');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dea64d28-f6d8-4531-9a65-24501bc1f026','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dea64d28-f6d8-4531-9a65-24501bc1f026') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dea64d28-f6d8-4531-9a65-24501bc1f026');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '74533a9f-8cce-4d37-aa6e-0f86f8d5fde3','Multicast','Multicast is a network delivery model in which a single transmitted packet stream is delivered to multiple subscribed receivers using a group (Class D) IP address, rather than being duplicated per receiver as in unicast. Switches and routers manage membership through protocols such as IGMP, and audio-over-IP systems use it to distribute streams to many endpoints efficiently.','Multicast sends one stream that many receivers can subscribe to at once. The network copies it only where needed. This saves bandwidth compared with sending a separate copy to each device. Audio networks use it to feed many endpoints.','It efficiently delivers the same audio stream to many receivers at once without the sender making a separate copy for each, saving bandwidth.','An AES67 or Dante system sends a shared stream by multicast; the technician enables IGMP snooping on switches so only subscribed ports receive it.','Networking',ARRAY['Link aggregation','Network topology','Network clock domains','Networked-audio troubleshooting']::text[],ARRAY['Running multicast without IGMP snooping, so streams flood every port and swamp the network.','Confusing multicast with broadcast, which reaches all hosts regardless of subscription.','Overusing multicast for streams that only one device needs, where unicast is simpler.']::text[],ARRAY['Distributing shared audio channels across a large Dante or AES67 network.','Configuring switches with IGMP snooping to control stream flooding.','Troubleshooting audio dropouts caused by uncontrolled multicast traffic.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multicast');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '74533a9f-8cce-4d37-aa6e-0f86f8d5fde3','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='74533a9f-8cce-4d37-aa6e-0f86f8d5fde3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='74533a9f-8cce-4d37-aa6e-0f86f8d5fde3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0dc1c8ba-4631-44b3-a047-5536c2b47ed4','Multitone testing','Multitone testing excites a device under test with a signal containing many simultaneous, carefully chosen tones and analyzes the output spectrum for the tones plus distortion and noise falling between them. It measures frequency response, distortion, and noise quickly in a single capture.','Multitone testing plays many tones at once through a device. Software then looks at the output spectrum. The original tones show response; energy between them shows distortion and noise. It measures a lot in one fast capture.','It provides a fast, simultaneous measurement of frequency response, distortion, and noise using one composite stimulus instead of many separate sweeps.','A technician runs a multitone through a codec or converter and reads response at the tone bins while distortion products appear in the gaps between tones.','Measurement',ARRAY['Maximum-length sequence measurement','Measurement signal versus program material','Measurement noise floor','Measurement microphone calibration']::text[],ARRAY['Choosing tone frequencies that let distortion products land on top of test tones, hiding them.','Ignoring the crest factor, so a high-peak multitone clips the device.','Assuming a single multitone replaces all targeted distortion tests.']::text[],ARRAY['Fast production testing of converters or codecs.','Checking a signal chain''s response and distortion in one measurement.','Evaluating perceptual codec behavior with music-like multitone stimuli.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multitone testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0dc1c8ba-4631-44b3-a047-5536c2b47ed4','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0dc1c8ba-4631-44b3-a047-5536c2b47ed4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0dc1c8ba-4631-44b3-a047-5536c2b47ed4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2c11e62-4ffa-401a-a45e-c60cbaa6cd16','Near-field loudspeaker measurement','Near-field loudspeaker measurement places the microphone very close to a radiator (much less than a wavelength and less than the radiator''s size away) so direct sound dominates over room reflections. It gives a reflection-free low-frequency response but is valid only up to a frequency set by the radiator''s dimensions.','Near-field measurement puts the mic right at the driver. Being so close, direct sound overwhelms room echoes. This gives clean bass data without a special chamber. It only works up to a frequency set by the driver''s size.','It captures a loudspeaker''s low-frequency response free of room reflections without needing an anechoic chamber, for design and verification.','A technician places the mic almost touching a woofer''s dust cap, measures clean output down low, then merges it with a gated far-field measurement for the full range.','Measurement',ARRAY['Merging near-field and far-field responses','Measurement-position dependency','Measurement microphone calibration','Magnitude summation']::text[],ARRAY['Using near-field data above its valid frequency limit set by radiator size.','Forgetting to add baffle-step and diffraction corrections for real-world response.','Placing the mic off-center on a large cone, biasing the reading.']::text[],ARRAY['Measuring a subwoofer''s low end in a normal room.','Gathering woofer data for a merged full-range curve.','Verifying a driver''s low-frequency alignment during design.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field loudspeaker measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2c11e62-4ffa-401a-a45e-c60cbaa6cd16','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2c11e62-4ffa-401a-a45e-c60cbaa6cd16') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2c11e62-4ffa-401a-a45e-c60cbaa6cd16');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3ecdd401-b5e3-46bf-86cd-dfcd29dcf2d9','Network clock domains','A network clock domain is a set of audio-over-IP devices that share one common time and sample reference, typically distributed by the Precision Time Protocol (IEEE 1588 / PTP) with an elected grandmaster (leader) clock. Devices in the same domain stay sample-synchronous; bridging different domains requires alignment or clock conversion.','A clock domain is a group of networked devices sharing one master clock. The Precision Time Protocol spreads that timing over the network. Devices in the same domain stay perfectly in step. Mixing separate domains needs careful clock handling.','Clock domains keep all devices sample-synchronous so audio streams combine without clicks, drift, or slips across the network.','A technician confirms one PTP grandmaster leads the Dante or AES67 network, keeping all endpoints in a single clock domain before routing streams.','Networking',ARRAY['Multicast','Link aggregation','Network topology','Networked-audio troubleshooting']::text[],ARRAY['Allowing two competing grandmaster clocks, which fights over sync and causes dropouts.','Assuming devices on the same switch are automatically in the same clock domain.','Bridging two domains without proper clock alignment, causing slips and clicks.']::text[],ARRAY['Setting the master clock for a Dante or AES67 network.','Interconnecting two audio networks that use different clock references.','Diagnosing periodic clicks traced to a clock-domain conflict.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Network clock domains');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3ecdd401-b5e3-46bf-86cd-dfcd29dcf2d9','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3ecdd401-b5e3-46bf-86cd-dfcd29dcf2d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3ecdd401-b5e3-46bf-86cd-dfcd29dcf2d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8c969601-c8e0-45dc-95b3-7e6fb5142e56','Network topology','Network topology is the arrangement of nodes and the links between them, such as star, ring, mesh, or tree, describing both physical cabling and logical data paths. The chosen topology affects bandwidth, latency, fault tolerance, and how failures propagate.','Network topology is the shape of a network: how devices connect. Common shapes include star, ring, and mesh. The shape affects speed, delay, and what happens when a link fails. Audio networks usually use a star through switches.','Topology choice determines a network''s resilience, bandwidth, and failure behavior, guiding how audio devices and switches are cabled.','A technician builds a switched star for a Dante system and adds a separate secondary network for redundancy, avoiding loops that would break a simple ring.','Networking',ARRAY['Link aggregation','Multicast','Network clock domains','Networked-audio troubleshooting']::text[],ARRAY['Creating an accidental loop in a star network without loop protection, causing a broadcast storm.','Confusing physical topology (cabling) with logical topology (data flow).','Assuming a daisy chain scales like a switched star for large systems.']::text[],ARRAY['Planning switch layout for a large networked-audio system.','Choosing between redundant star and ring approaches.','Explaining how a single failure affects each topology.']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Network topology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8c969601-c8e0-45dc-95b3-7e6fb5142e56','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8c969601-c8e0-45dc-95b3-7e6fb5142e56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8c969601-c8e0-45dc-95b3-7e6fb5142e56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '36938be9-847b-4de1-80e9-a0348794477d','Networked-audio troubleshooting','Networked-audio troubleshooting is the systematic diagnosis of faults in audio-over-IP systems, checking physical links, switch configuration (VLANs, IGMP snooping, QoS), clock/PTP status, subscriptions, and latency settings. It isolates whether a problem is cabling, network configuration, clocking, or device setup.','This is finding faults in a networked audio system. You check cables, switch settings, the clock, and the stream subscriptions in order. The goal is to pin down the real cause. It could be a bad cable, a wrong setting, or a clock conflict.','It restores reliable audio by locating the true fault among cabling, switch configuration, clocking, and device settings instead of guessing.','Facing dropouts, a technician checks link lights and cable, confirms one PTP master, verifies IGMP snooping, then checks subscriptions and latency to isolate the cause.','Networking',ARRAY['Network clock domains','Multicast','Network topology','Link aggregation']::text[],ARRAY['Changing several settings at once, so the real cause stays hidden.','Overlooking clock (PTP) conflicts as a source of periodic dropouts.','Ignoring switch QoS and IGMP settings and blaming the audio devices.']::text[],ARRAY['Chasing intermittent audio dropouts on a show network.','Diagnosing why a subscribed stream is not received.','Isolating a clock conflict causing clicks across devices.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Networked-audio troubleshooting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '36938be9-847b-4de1-80e9-a0348794477d','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='36938be9-847b-4de1-80e9-a0348794477d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='36938be9-847b-4de1-80e9-a0348794477d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5b0a545-a367-4d19-88a2-e3e383833129','Open-loop versus closed-loop behavior','Open-loop behavior describes a system''s response with no feedback path, while closed-loop behavior includes feedback that compares output to a reference and corrects the difference. Negative feedback trades raw open-loop gain for lower distortion, flatter response, and greater stability; excess feedback with the wrong phase can cause oscillation.','Open loop means no feedback: the system just runs on its input. Closed loop feeds part of the output back to correct itself. Feedback lowers distortion and steadies the response. Too much feedback with bad timing can make it oscillate.','The distinction explains how feedback shapes amplifier and control behavior, improving accuracy and stability while setting the conditions that risk oscillation.','An amplifier''s huge open-loop gain is tamed by negative feedback to give precise, low-distortion closed-loop gain; a technician watches phase margin to avoid instability.','Control Systems',ARRAY['Monitor gain before feedback','Output-current limiting','Minimum-phase derivation','Maximum power transfer']::text[],ARRAY['Assuming more negative feedback is always better, ignoring stability and phase margin.','Confusing acoustic feedback (howl) with electronic negative feedback in a circuit.','Expecting open-loop and closed-loop gain to be the same.']::text[],ARRAY['Understanding why an amplifier uses negative feedback.','Explaining stability limits in a control or servo loop.','Relating feedback concepts to acoustic feedback on stage.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Open-loop versus closed-loop behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5b0a545-a367-4d19-88a2-e3e383833129','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5b0a545-a367-4d19-88a2-e3e383833129') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5b0a545-a367-4d19-88a2-e3e383833129');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f131a4c6-dc2c-44f1-9168-626b9ecd7257','Out fills','Out fills are loudspeakers deployed to the outer sides of a main system to extend horizontal coverage to wide seating areas that the mains do not reach. They are aimed and often delayed and level-matched so their coverage blends with the mains without excessive overlap.','Out fills are extra speakers on the far sides of the stage. They cover wide seats that the main speakers miss. They are aimed outward and matched to the mains. Good out fills widen coverage without muddying the middle.','They extend even coverage to wide audience areas beyond the mains'' pattern, improving consistency for side seating.','A technician flies out fills angled to cover the far house-left and house-right seats, sets level and delay so their edge blends with the mains'' coverage.','System Design',ARRAY['Loudspeaker aiming','Main-to-sub timing','Magnitude summation','Microphone-loudspeaker geometry']::text[],ARRAY['Overlapping out fills too far into the mains'' coverage, causing combing and uneven level.','Skipping delay and level matching, so the transition sounds disjointed.','Aiming out fills into reflective side walls instead of the seats.']::text[],ARRAY['Covering wide seating in a broad venue.','Filling side sections a narrow main array cannot reach.','Blending side coverage into the main system smoothly.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Out fills');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f131a4c6-dc2c-44f1-9168-626b9ecd7257','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f131a4c6-dc2c-44f1-9168-626b9ecd7257') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f131a4c6-dc2c-44f1-9168-626b9ecd7257');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '86c2f30e-8121-4f9a-b1e1-6e11c825c757','Outdoor propagation','Outdoor propagation describes how sound spreads in open air, dominated by inverse-square spreading loss of about 6 dB per doubling of distance from a point source, plus frequency-dependent air absorption and effects of ground, wind gradients, and temperature gradients. Standardized methods predict this attenuation for environmental and system planning.','Outdoors, sound spreads out and gets weaker with distance. A point source loses about 6 dB each time distance doubles. Air also absorbs high frequencies over long runs. Wind, temperature, and the ground bend and change the sound too.','It predicts how level and tone change with distance outdoors so systems and noise impact can be planned realistically without room reverberation.','A technician estimates that a point source dropping 6 dB per distance doubling loses 6 dB from 10 m to 20 m, then adds air absorption to predict high-frequency loss at range.','Acoustics',ARRAY['Modal decomposition','Loudspeaker aiming','Magnitude summation','Out fills']::text[],ARRAY['Applying 6 dB per doubling to line sources, which lose closer to 3 dB per doubling in their near field.','Ignoring air absorption, which strongly cuts high frequencies over long distances.','Overlooking wind and temperature gradients that bend sound and change level downrange.']::text[],ARRAY['Predicting level at the back of an outdoor festival field.','Estimating noise reaching neighbors beyond a venue.','Planning delay towers based on distance loss.']::text[],'Intermediate','dL = 20 * log10(r2 / r1)   (point source, free field)','The level change equals twenty times the base-ten log of the ratio of the two distances, giving about 6 dB loss per doubling.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Outdoor propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '86c2f30e-8121-4f9a-b1e1-6e11c825c757','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='86c2f30e-8121-4f9a-b1e1-6e11c825c757') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='86c2f30e-8121-4f9a-b1e1-6e11c825c757');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f71d3504-3f74-42f8-afd3-02c39668d375','Output-current limiting','Output-current limiting is a power-amplifier protection scheme that caps the current delivered to the load so output devices stay within their safe operating area during low-impedance or short-circuit conditions. It engages under fault or overload to prevent thermal or second-breakdown destruction of the output transistors.','Output-current limiting stops an amplifier from pushing too much current. Into a short or a very low load, current would soar and destroy the output parts. The limiter caps it to a safe value. This protects the amplifier during faults.','It protects the amplifier''s output devices from destructive overcurrent when the load impedance drops too low or a short occurs.','When a speaker cable shorts, current limiting holds output current within the transistors'' safe operating area until the fault clears or protection mutes the channel.','Electrical',ARRAY['Maximum power transfer','Loudspeaker load calculations','Open-loop versus closed-loop behavior','Logarithms']::text[],ARRAY['UNSAFE: Defeating or bypassing an amplifier''s current-limiting/protection circuit, which can destroy output devices and create a shock or fire hazard.','UNSAFE: Driving a load below the amplifier''s rated minimum impedance so limiting engages constantly, overheating the amplifier.','Mistaking protective current limiting for clipping or a broken channel.','Ignoring that constant limiting on a low load signals a wiring or load-calculation error.']::text[],ARRAY['Understanding why an amplifier mutes or reduces output into a shorted cable.','Diagnosing distortion caused by limiting into an under-impedance load.','Explaining amplifier protection during a fault condition.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Output-current limiting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f71d3504-3f74-42f8-afd3-02c39668d375','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f71d3504-3f74-42f8-afd3-02c39668d375') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f71d3504-3f74-42f8-afd3-02c39668d375');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '725ce2f3-bd67-4495-bd4d-f69e4feee7bd','Packet reordering','Packet reordering is the process by which a receiver restores the correct order of network packets that arrived out of sequence, using the sequence numbers carried in each packet. In audio-over-IP it is handled inside the receive (jitter) buffer before samples are converted back to a continuous stream.','Data on a network is split into small packets. Packets can arrive in the wrong order. The receiver reads a number in each packet. It uses those numbers to put them back in order before playback.','It ensures a decoded audio stream plays in the original time order even when the network delivers packets out of sequence. It works together with a buffer that also absorbs timing jitter.','A technician sizes the receive buffer (often 1-10 ms) so that late or swapped packets can be reordered before playout; too small a buffer drops reordered packets and causes clicks.','Audio Networking',ARRAY['Packetized audio','Quality of service','Redundant networking','Sample-accurate synchronization','Real-time Transport Protocol']::text[],ARRAY['Assuming packets always arrive in the order they were sent','Confusing reordering with error correction; reordering does not recreate lost packets','Setting the buffer so small that reordering cannot occur, causing dropouts']::text[],ARRAY['Diagnosing intermittent clicks on a Dante or AES67 stream across a routed network','Choosing receiver latency on a stadium audio-over-IP link with multiple switch hops','Explaining why a congested Wi-Fi path corrupts audio while a wired path does not']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Packet reordering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '725ce2f3-bd67-4495-bd4d-f69e4feee7bd','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='725ce2f3-bd67-4495-bd4d-f69e4feee7bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='725ce2f3-bd67-4495-bd4d-f69e4feee7bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '747adc9d-c97d-4988-a83a-81fa03958b65','Packetized audio','Packetized audio is digital audio carried as discrete network packets, each holding a block of audio samples plus header information such as a timestamp and sequence number. In professional audio it is typically transported using RTP over IP networks.','Packetized audio means sound is sent over a network in small chunks. Each chunk holds a few samples of audio. Each chunk also carries a time stamp and a number. The receiver uses these to rebuild the sound stream.','It lets continuous audio travel over standard IP networks that move data in packets, so audio can share the same infrastructure as other network traffic.','A technician sets the packet time (for example 1 ms or 0.125 ms in AES67) to trade lower latency against higher packet-rate overhead when configuring an audio-over-IP device.','Audio Networking',ARRAY['Packet reordering','Quality of service','Sample-rate effects on network load','Real-time Transport Protocol','Redundant networking']::text[],ARRAY['Thinking packetized audio is a compressed format; PCM samples are usually sent uncompressed','Ignoring header overhead when estimating bandwidth','Assuming smaller packets are always better, overlooking the higher packet rate they create']::text[],ARRAY['Configuring AES67 packet time to interoperate between two vendors'' devices','Estimating switch load for a 64-channel audio-over-IP feed','Troubleshooting latency budget on a broadcast contribution link']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Packetized audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '747adc9d-c97d-4988-a83a-81fa03958b65','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='747adc9d-c97d-4988-a83a-81fa03958b65') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='747adc9d-c97d-4988-a83a-81fa03958b65');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd42546e-6dae-4440-8529-1457e12fa93a','Parallel amplifier operation','Parallel amplifier operation connects two or more amplifier output stages or channels so that their outputs sum in current into a shared load, increasing available current and reducing the effective minimum load impedance each amplifier must drive. It requires manufacturer-approved wiring and closely matched channels to prevent circulating currents.','Parallel operation ties two amplifier outputs together to one load. This lets them share the current for a demanding, low-impedance speaker load. It only works safely when the maker approves it. The channels must also be closely matched.','It provides more current and power into very low impedance loads, such as long lines of paralleled subwoofers, than a single channel can safely supply.','A technician follows the amplifier manual to strap two channels in parallel per its wiring diagram, verifies gain and polarity match, and respects the stated minimum load before driving a low-impedance array.','Amplifiers',ARRAY['Reactive loudspeaker loads','Bridge-mode operation','Load impedance','Peak voltage','Damping factor']::text[],ARRAY['UNSAFE: Directly tying together amplifier outputs that are not designed for parallel operation, which creates large circulating currents and can destroy the outputs or start a fire','UNSAFE: Driving the paralleled pair below its rated minimum load impedance, causing overheating and shutdown or failure','Assuming any two channels can be paralleled without matching gain and polarity','Confusing parallel operation, which halves load impedance, with bridge mode, which doubles output voltage']::text[],ARRAY['Powering a large low-impedance subwoofer array from one amplifier chassis','Reading an amplifier service manual to confirm parallel wiring is supported','Diagnosing thermal shutdown on an amp wired into too low a load']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parallel amplifier operation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd42546e-6dae-4440-8529-1457e12fa93a','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd42546e-6dae-4440-8529-1457e12fa93a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd42546e-6dae-4440-8529-1457e12fa93a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '052c8c9b-9be4-4560-8d04-788bfe3e8259','Parallel digital audio','Parallel digital audio is a transmission format in which the individual bits of each audio sample are carried simultaneously over separate conductors, usually accompanied by a clock line. It contrasts with serial interfaces such as AES3, which send bits one after another on a single pair.','In parallel digital audio, all the bits of one sample travel at the same time. Each bit uses its own wire. A separate clock wire marks each sample. This was used before serial links replaced it for most connections.','It allowed early digital audio equipment to move samples between nearby devices at high rates without fast serial encoding, at the cost of many conductors.','A technician meeting legacy converters or early PCM gear may encounter a parallel bus, but modern installs use serial interfaces like AES3 or MADI over one or two conductors instead.','Digital Interfaces',ARRAY['Serial digital audio','AES3','MADI','Word clock','Reflections in digital cables']::text[],ARRAY['Assuming all digital audio interfaces are serial','Confusing a multi-conductor parallel bus with a multichannel serial link like MADI','Thinking more conductors automatically means better quality']::text[],ARRAY['Interfacing with vintage or specialised converters that expose a parallel PCM bus','Explaining why AES3 replaced parallel connections for interconnection','Understanding historical digital audio interface design in training']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parallel digital audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '052c8c9b-9be4-4560-8d04-788bfe3e8259','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='052c8c9b-9be4-4560-8d04-788bfe3e8259') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='052c8c9b-9be4-4560-8d04-788bfe3e8259');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45c7a12d-ec83-4514-b175-6e998cf77628','Peak sound pressure','Peak sound pressure is the greatest instantaneous absolute value of the sound pressure over a stated time interval, expressed in pascals or, as a level, referenced to 20 micropascals. Sound level meters report it as peak sound pressure level, most often C-weighted (LCpeak).','Peak sound pressure is the single highest pressure a sound reaches at any instant. It is not an average. Meters show it as a peak level in decibels. It is used to catch short, loud bursts that averages miss.','It captures brief, high-energy transients such as impacts or gunshots that time-averaged levels would understate, which matters for hearing-damage risk assessment.','Using an IEC 61672 sound level meter, a technician reads LCpeak during a loud transient; a peak sound pressure of 20 Pa corresponds to a peak level of 120 dB re 20 microPa.','Acoustic Measurement',ARRAY['Peak voltage','Sound pressure level','C-weighting','Crest factor','Random-incidence calibration']::text[],ARRAY['Confusing peak sound pressure with RMS or time-averaged sound pressure','UNSAFE: Judging hearing risk from short impulses using only an average level, which can under-report peaks and lead to unsafe exposure','Forgetting to note the frequency weighting (usually C) applied to a peak reading']::text[],ARRAY['Measuring impulsive noise such as pyrotechnics for hearing-safety compliance','Comparing peak versus RMS levels on a percussion-heavy programme','Setting limiter thresholds to control short transients']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak sound pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45c7a12d-ec83-4514-b175-6e998cf77628','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45c7a12d-ec83-4514-b175-6e998cf77628') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45c7a12d-ec83-4514-b175-6e998cf77628');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc2696dc-6ce8-4f0c-a2be-f1cd4a0c1b72','Peak voltage','Peak voltage is the maximum instantaneous value that a voltage waveform reaches, measured from the zero reference. For an undistorted sinusoid it equals the RMS voltage multiplied by the square root of two.','Peak voltage is the highest voltage a signal reaches at any instant. For a clean sine wave it is about 1.41 times the RMS value. Peak-to-peak voltage is twice the peak. Knowing the peak matters for headroom and safety.','It sets the maximum swing a circuit, cable, or amplifier output must handle without clipping and defines electrical stress on components and insulation.','For a 100 V RMS sine at an amplifier output, the peak voltage is about 141 V; a technician allows headroom above this when rating connectors and insulation.','Electrical Measurement',ARRAY['Peak sound pressure','RMS voltage','Crest factor','Peak-to-peak voltage','Reactive loudspeaker loads']::text[],ARRAY['UNSAFE: Treating an RMS voltage rating as the maximum voltage present; the peak is about 1.41 times higher on a sine and can exceed shock or insulation limits','Applying the 1.414 factor to non-sinusoidal or clipped waveforms, where it does not hold','Confusing peak with peak-to-peak voltage']::text[],ARRAY['Rating loudspeaker cable and connectors for a high-power amplifier output','Setting oscilloscope scaling to capture a transient without clipping the display','Explaining why a meter reading RMS understates the instantaneous stress on components']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak voltage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc2696dc-6ce8-4f0c-a2be-f1cd4a0c1b72','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc2696dc-6ce8-4f0c-a2be-f1cd4a0c1b72') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc2696dc-6ce8-4f0c-a2be-f1cd4a0c1b72');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e338602c-0cd0-4bb4-94a9-e26608b4cf28','Phasors','A phasor is a complex number that represents a sinusoidal quantity of a single frequency by its amplitude and phase, holding the frequency implicit. It lets steady-state AC signals be added and manipulated with algebra instead of trigonometry.','A phasor is a way to describe a steady sine signal using just its size and phase. It is drawn as an arrow at an angle. Adding signals becomes adding arrows. This is much easier than adding sine waves directly.','It simplifies steady-state AC analysis, so engineers can combine signals of the same frequency and compute impedance, gain, and phase by complex arithmetic.','A technician represents a signal as a phasor of magnitude and angle to predict how two same-frequency signals sum, such as the partial cancellation between two loudspeakers.','Signal Analysis',ARRAY['Polar coordinates','Radians versus degrees','Radiation reactance','Complex impedance','Phase']::text[],ARRAY['Trying to add phasors of different frequencies, which is not valid','Mixing degrees and radians when computing phase angles','Forgetting that a phasor gives magnitude and phase, not the instantaneous time value']::text[],ARRAY['Analysing how two same-frequency signals combine or cancel at a listening position','Computing complex impedance of a reactive load','Teaching AC circuit behaviour with rotating-vector diagrams']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phasors');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e338602c-0cd0-4bb4-94a9-e26608b4cf28','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e338602c-0cd0-4bb4-94a9-e26608b4cf28') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e338602c-0cd0-4bb4-94a9-e26608b4cf28');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e1fa58a3-c5d4-4615-80d4-f34c301d5f4f','Polar coordinates','Polar coordinates locate a point in a plane by a distance (radius) from an origin and an angle measured from a reference direction. They convert to rectangular coordinates by x equals r cosine theta and y equals r sine theta.','Polar coordinates place a point using a distance and an angle. The distance is how far from the centre. The angle is the direction. This suits things that spread out around a point, like a microphone pattern.','They describe direction-and-distance data naturally, which is why microphone and loudspeaker directivity is plotted on polar graphs.','A technician reads a microphone polar plot where radius shows relative sensitivity and angle shows the sound''s direction of arrival around the capsule.','Mathematics',ARRAY['Polar measurement','Phasors','Radians versus degrees','Rectangular coordinates','Directivity']::text[],ARRAY['Reading the polar radius as physical distance rather than relative level on a directivity plot','Mixing degrees and radians for the angle','Confusing the reference direction (0 degrees) between different plots']::text[],ARRAY['Interpreting a cardioid microphone directivity plot','Plotting a loudspeaker''s horizontal coverage','Converting a measured angle and radius into x-y positions']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polar coordinates');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e1fa58a3-c5d4-4615-80d4-f34c301d5f4f','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e1fa58a3-c5d4-4615-80d4-f34c301d5f4f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e1fa58a3-c5d4-4615-80d4-f34c301d5f4f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '936977ee-5064-40ef-b12b-ba00b5064142','Polar measurement','Polar measurement is the process of measuring a transducer''s sensitivity or output as a function of angle around it, producing a polar (directivity) pattern. It is used to characterise microphone pickup patterns and loudspeaker coverage.','Polar measurement checks how a microphone or speaker behaves at different angles. The device or source is rotated step by step. The level is recorded at each angle. The result is a plot of pattern versus direction.','It quantifies directional behaviour so a technician can predict pickup or coverage and choose or aim equipment correctly.','A technician rotates a microphone in known angle steps against a fixed source, logs the level at each angle, and plots the result to confirm a cardioid or supercardioid pattern.','Acoustic Measurement',ARRAY['Polar coordinates','Directivity','Random-incidence calibration','Reference calibration','Real-time analysis']::text[],ARRAY['Measuring at a single frequency and assuming the pattern holds across the band','Ignoring room reflections that corrupt off-axis readings','Not keeping source distance and level constant while rotating']::text[],ARRAY['Verifying a microphone''s advertised polar pattern in an anechoic space','Mapping a loudspeaker''s horizontal and vertical coverage for a design','Checking a mic''s off-axis response before choosing it for a live source']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polar measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '936977ee-5064-40ef-b12b-ba00b5064142','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='936977ee-5064-40ef-b12b-ba00b5064142') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='936977ee-5064-40ef-b12b-ba00b5064142');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e8f214e4-4f8e-482d-b57f-dabdecda23ab','Precision Time Protocol','Precision Time Protocol (PTP) is a network protocol defined by IEEE 1588 that synchronises clocks across a packet network to sub-microsecond accuracy by exchanging timestamped messages between a grandmaster and slave clocks. Audio-over-IP systems such as AES67 use the IEEE 1588-2008 (version 2) media profile.','Precision Time Protocol keeps clocks on a network in step. One device acts as the master clock. Others measure the tiny travel time of its time-stamped messages. They then correct their own clocks. This lets audio devices share a common sample clock.','It gives networked audio devices a shared, highly accurate time reference so their sample clocks align and streams stay in sync without a separate word-clock cable.','A technician sets one device as PTP grandmaster and enables the AES67 media profile on the rest, then confirms all units lock to it before routing audio.','Audio Networking',ARRAY['Sample-accurate synchronization','Word clock','Redundant networking','Quality of service','Packetized audio']::text[],ARRAY['Running two grandmasters or mismatched PTP profiles, so devices fail to lock','Confusing PTP with NTP, which is far less accurate','Not prioritising PTP traffic with QoS, causing clock instability under load']::text[],ARRAY['Bringing up an AES67 network and choosing the grandmaster','Bridging Dante and AES67 devices that need a common PTP domain','Troubleshooting clock drift when switch QoS is misconfigured']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Precision Time Protocol');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e8f214e4-4f8e-482d-b57f-dabdecda23ab','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e8f214e4-4f8e-482d-b57f-dabdecda23ab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e8f214e4-4f8e-482d-b57f-dabdecda23ab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4410e65e-246c-4fe8-a7ed-5ab22717fd01','Probability density','Probability density is the value of a probability density function (PDF) for a continuous random variable; it describes probability per unit of the variable, not probability at a point. The probability of an interval equals the area under the PDF over that interval, and the total area equals one.','For continuous data, the chance of any exact value is basically zero. Probability density shows how likely values are near a point. To get a real probability, you find the area under the curve over a range. The whole area equals one.','It provides a continuous model of how likely different values are, underpinning statistics used in measurement uncertainty and noise analysis.','A technician modelling measurement noise as Gaussian uses its density to find the probability a reading falls within a chosen range by computing the area under the curve.','Statistics',ARRAY['Probability distributions','Regression','Ratios','Standard deviation','Random-incidence calibration']::text[],ARRAY['Reading a density value as the probability of an exact outcome','Forgetting that density can exceed one while the total area still equals one','Confusing the density function with its cumulative distribution']::text[],ARRAY['Modelling the spread of repeated acoustic measurements','Describing background noise amplitude statistics','Estimating the chance a level reading lands in a target window']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Probability density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4410e65e-246c-4fe8-a7ed-5ab22717fd01','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4410e65e-246c-4fe8-a7ed-5ab22717fd01') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4410e65e-246c-4fe8-a7ed-5ab22717fd01');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f64ebc0-fe7a-4b82-999a-33bad08b679f','Probability distributions','A probability distribution describes how probability is spread over the possible values of a random variable, whether discrete (a probability mass function) or continuous (a probability density function). Common examples in audio measurement include the Gaussian (normal) and uniform distributions.','A probability distribution shows how likely each outcome is. Some variables take separate values, like counts. Others take any value in a range, like a level. The distribution names the pattern, such as normal or uniform.','It gives a mathematical shape to random behaviour, letting technicians reason about noise, measurement scatter, and uncertainty.','A technician assuming repeated readings follow a normal distribution uses its mean and standard deviation to state a result with an uncertainty range.','Statistics',ARRAY['Probability density','Regression','Ratios','Standard deviation','Random-incidence calibration']::text[],ARRAY['Assuming data are normal without checking','Mixing up discrete mass functions with continuous density functions','Confusing the distribution''s spread with its central value']::text[],ARRAY['Characterising the scatter of repeated SPL measurements','Modelling quantisation error as a uniform distribution','Setting confidence limits on a calibration result']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Probability distributions');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f64ebc0-fe7a-4b82-999a-33bad08b679f','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f64ebc0-fe7a-4b82-999a-33bad08b679f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f64ebc0-fe7a-4b82-999a-33bad08b679f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4ab0eb94-fbda-4879-9517-838c1f582d79','Proportionality','Proportionality is a fixed multiplicative relationship between two quantities; in direct proportion one equals a constant times the other, while in inverse proportion one equals a constant divided by the other. The constant is the constant of proportionality.','Two quantities are proportional when they change together by a fixed rule. In direct proportion, doubling one doubles the other. In inverse proportion, doubling one halves the other. A fixed constant links them.','It expresses many physical laws in audio, such as how sound pressure falls with distance, in a simple, predictable form.','Sound pressure in a free field is inversely proportional to distance, so a technician expects about a 6 dB drop each time the distance from a point source doubles.','Mathematics',ARRAY['Ratios','Radiation resistance','Inverse-square law','Peak voltage','Regression']::text[],ARRAY['Confusing direct with inverse proportion','Assuming a relationship is proportional when it is not linear','Forgetting that intensity, not pressure, follows the inverse-square law']::text[],ARRAY['Predicting level change with distance from a source','Scaling gain settings that track linearly with a control','Explaining why doubling amplifier voltage quadruples power into a fixed load']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Proportionality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4ab0eb94-fbda-4879-9517-838c1f582d79','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4ab0eb94-fbda-4879-9517-838c1f582d79') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4ab0eb94-fbda-4879-9517-838c1f582d79');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '518e632e-093b-4c84-88fa-26800c4ffd55','Psychoacoustic smoothing','Psychoacoustic smoothing is fractional-octave averaging of a measured frequency response so that the displayed resolution approximates the frequency-resolving ability of human hearing rather than the fine detail of the raw measurement. Common settings use one-third to one-sixth octave, and some tools vary resolution with frequency.','A raw frequency measurement shows very fine detail. The ear does not hear all of it. Psychoacoustic smoothing averages the curve in bands. The result looks more like what we actually perceive. This makes real problems easier to see.','It presents measured response in a way that correlates with what a listener hears, so a technician tunes for perceived tone instead of chasing narrow ripples that are inaudible.','When tuning a system, a technician applies about one-sixth-octave smoothing to reveal broad tonal trends while ignoring narrow peaks that reflect room detail rather than audible problems.','Signal Analysis',ARRAY['Real-time analysis','Reference-channel delay','Fractional-octave analysis','Critical bands','Reference calibration']::text[],ARRAY['Assuming a heavily smoothed curve shows fine phase or narrow resonance detail','Comparing two measurements taken with different smoothing settings','Over-smoothing until real narrow-band problems disappear']::text[],ARRAY['Tuning a PA so the displayed response matches perceived tonal balance','Comparing measurements while keeping smoothing consistent','Deciding whether a narrow dip needs correction or is inaudible']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Psychoacoustic smoothing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '518e632e-093b-4c84-88fa-26800c4ffd55','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='518e632e-093b-4c84-88fa-26800c4ffd55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='518e632e-093b-4c84-88fa-26800c4ffd55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5738518f-40d7-42fb-84ad-0426ce2a515b','Quality of service','Quality of service (QoS) is a set of network mechanisms that prioritise selected traffic so time-critical data receives preferential forwarding under congestion. Audio-over-IP relies on DiffServ marking (DSCP) and, at layer 2, IEEE 802.1Q priority, to protect clock and media streams.','A busy network can delay or drop data. Quality of service marks important traffic so switches handle it first. In audio networks, the clock and the audio get high priority. This keeps sound flowing smoothly under load.','It ensures low, predictable latency and low packet loss for audio and clock traffic even when the same network carries other data.','A technician configures switches so PTP clock packets get the highest priority and audio media a high priority, following the AES67 or vendor DSCP recommendations before going live.','Audio Networking',ARRAY['Packetized audio','Packet reordering','Precision Time Protocol','Redundant networking','Sample-rate effects on network load']::text[],ARRAY['Assuming a fast network needs no QoS; congestion still causes drops without it','Marking media higher priority than the clock, which can destabilise synchronisation','Enabling QoS on some switches but not all in the path']::text[],ARRAY['Configuring managed switches for a Dante or AES67 deployment','Sharing a network between audio and control or IT traffic','Diagnosing dropouts that appear only during network congestion']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quality of service');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5738518f-40d7-42fb-84ad-0426ce2a515b','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5738518f-40d7-42fb-84ad-0426ce2a515b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5738518f-40d7-42fb-84ad-0426ce2a515b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '82533bec-725d-4867-91f7-a8924ab3744f','Radians versus degrees','Radians and degrees are two units for measuring angles: a full circle is 2 pi radians or 360 degrees, so one radian equals 180 divided by pi, about 57.30 degrees. The radian is the SI-derived unit and is defined as the ratio of arc length to radius.','Angles can be measured two ways. Degrees split a circle into 360 parts. Radians measure the angle by arc length over radius. A full circle is 2 pi radians. One radian is about 57.3 degrees.','Choosing the right unit avoids errors, since most math and DSP functions expect radians while everyday plots often use degrees.','Before entering a phase angle into a calculator or DSP function, a technician converts 90 degrees to pi over 2 radians so the trigonometric result is correct.','Mathematics',ARRAY['Phasors','Polar coordinates','Phase','Angular frequency','Ratios']::text[],ARRAY['Leaving a calculator in the wrong angle mode and getting wrong trig results','Assuming DSP or programming trig functions take degrees; most take radians','Forgetting the factor pi when converting between the two units']::text[],ARRAY['Entering phase angles into a measurement or DSP tool','Converting a plotted phase in degrees for a calculation','Computing angular frequency, which uses radians per second']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radians versus degrees');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '82533bec-725d-4867-91f7-a8924ab3744f','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='82533bec-725d-4867-91f7-a8924ab3744f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='82533bec-725d-4867-91f7-a8924ab3744f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0c679504-b19a-4c93-8df1-eab99dc431ec','Radiation reactance','Radiation reactance is the imaginary (reactive) part of the acoustic radiation impedance seen by a vibrating surface, representing the co-vibrating air mass that stores energy rather than radiating it. For a rigid piston in an infinite baffle it dominates at low frequencies and behaves as an added (radiation) mass.','When a cone moves, it drags nearby air with it. That air stores energy instead of sending it away as sound. Radiation reactance describes this effect. At low frequencies it acts like extra mass on the cone.','It accounts for the air load that adds effective mass to a driver, shifting resonance and affecting low-frequency behaviour in loudspeaker design.','For a 0.1 m radius piston at 100 Hz in air, the radiation reactance corresponds to an added air mass of roughly 3 grams, which lowers the driver''s resonance slightly.','Acoustics',ARRAY['Radiation resistance','Radiation impedance','Reactive loudspeaker loads','Phasors','Acoustic impedance']::text[],ARRAY['Treating the reactance as lost or radiated energy; it is stored, not radiated','Ignoring the added radiation mass when predicting driver resonance','Assuming it stays constant with frequency']::text[],ARRAY['Modelling a woofer''s effective moving mass including air load','Explaining why a driver''s resonance shifts when baffled','Analysing low-frequency radiation impedance in enclosure design']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiation reactance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0c679504-b19a-4c93-8df1-eab99dc431ec','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0c679504-b19a-4c93-8df1-eab99dc431ec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0c679504-b19a-4c93-8df1-eab99dc431ec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd88ad49a-bd05-4556-95b5-88fe0863e5e4','Radiation resistance','Radiation resistance is the real (resistive) part of the acoustic radiation impedance seen by a vibrating surface; it represents energy actually radiated away as sound. For a rigid piston in an infinite baffle at low frequencies it rises with the square of frequency.','Radiation resistance is the part of the air load that turns cone motion into real sound. It measures how well a surface radiates. At low frequencies a small source radiates poorly. Its radiation resistance rises quickly with frequency.','It quantifies how effectively a driver couples its motion into radiated sound, explaining why small sources are inefficient radiators at low frequencies.','For a 0.1 m radius piston at 100 Hz in air, the mechanical radiation resistance is about 0.22 newton-seconds per metre, which is small and reflects poor low-frequency radiating efficiency.','Acoustics',ARRAY['Radiation reactance','Radiation impedance','Reactive loudspeaker loads','Acoustic impedance','Proportionality']::text[],ARRAY['Confusing radiation resistance with the loudspeaker''s electrical voice-coil resistance','Assuming a small source radiates bass efficiently','Forgetting that the low-frequency resistance grows with frequency squared']::text[],ARRAY['Explaining why small drivers need large excursion or enclosures for bass','Estimating radiated acoustic power from piston motion','Comparing radiating efficiency of different driver sizes']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiation resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd88ad49a-bd05-4556-95b5-88fe0863e5e4','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d88ad49a-bd05-4556-95b5-88fe0863e5e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d88ad49a-bd05-4556-95b5-88fe0863e5e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee05a101-3888-4aa8-8dc6-51520ddeae4e','Random-incidence calibration','Random-incidence calibration adjusts or corrects a measurement microphone so its response is flat for sound arriving from all directions equally, as in a diffuse field. It contrasts with free-field calibration, which assumes sound arriving from one direction.','A measurement mic can be set for sound from one direction or from all around. Random-incidence calibration is for sound from every direction at once. This suits echoey rooms. It corrects the mic for a diffuse field.','It makes a microphone read accurately in reverberant or diffuse sound fields where energy arrives from many directions, such as reverberation-room measurements.','For diffuse-field room measurements, a technician selects a random-incidence microphone or applies the diffuse-field correction so high-frequency readings are not overstated.','Acoustic Measurement',ARRAY['Reference calibration','Polar measurement','Free-field microphone','Diffuse field','Peak sound pressure']::text[],ARRAY['Using a free-field microphone in a diffuse field without the correction, biasing high-frequency readings','Assuming all measurement mics behave the same at high frequencies regardless of incidence','Confusing random-incidence with pressure-field calibration']::text[],ARRAY['Measuring sound in a reverberation room','Choosing between free-field and random-incidence mics for a task','Correcting high-frequency response for diffuse-field measurements']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Random-incidence calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee05a101-3888-4aa8-8dc6-51520ddeae4e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee05a101-3888-4aa8-8dc6-51520ddeae4e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee05a101-3888-4aa8-8dc6-51520ddeae4e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2b1ca40e-0279-4324-8850-8f6f8b1afa2b','Ratios','A ratio expresses the relative size of two quantities as a quotient of one to the other. In audio, ratios underlie decibel comparisons, compression settings, and impedance or turns relationships.','A ratio compares two amounts by dividing one by the other. It says how many times bigger one is. Audio uses ratios everywhere. Decibels, compression, and transformer turns are all ratios.','Ratios give a scale-independent way to compare levels and quantities, which is why audio uses logarithms of ratios (decibels) so widely.','A compressor set to a 4:1 ratio reduces output so that a 4 dB rise above threshold at the input yields only a 1 dB rise at the output.','Mathematics',ARRAY['Proportionality','Decibel','Regression','Peak voltage','Signal-to-noise ratio']::text[],ARRAY['Confusing a ratio with a difference','Forgetting that a decibel is based on a logarithm of a ratio, not a plain ratio','Inverting the order of the two quantities in the ratio']::text[],ARRAY['Setting a compressor''s ratio for dynamics control','Reading signal-to-noise or impedance ratios on a spec sheet','Understanding decibel comparisons as ratios of power or voltage']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ratios');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2b1ca40e-0279-4324-8850-8f6f8b1afa2b','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2b1ca40e-0279-4324-8850-8f6f8b1afa2b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2b1ca40e-0279-4324-8850-8f6f8b1afa2b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb31cdd3-18a4-4899-b025-9845944e7a53','Reactive loudspeaker loads','A reactive loudspeaker load is one whose impedance has significant reactance, so it varies with frequency and makes current and voltage fall out of phase. Real loudspeakers combine voice-coil inductance, mechanical resonance, and enclosure effects, presenting an amplifier with a complex, frequency-dependent load.','A loudspeaker is not a simple resistor. Its impedance changes with frequency. Current and voltage can fall out of step. This is a reactive load. It makes the amplifier work harder at some frequencies.','Understanding the reactive nature of speaker loads lets a technician match amplifiers correctly and avoid overheating or instability from difficult impedance dips.','A technician checks a loudspeaker''s minimum impedance across frequency, not just its nominal rating, and keeps it at or above the amplifier''s rated minimum load.','Amplifiers',ARRAY['Parallel amplifier operation','Radiation reactance','Load impedance','Damping factor','Complex impedance']::text[],ARRAY['UNSAFE: Loading an amplifier below its rated minimum impedance because the impedance dips well under the nominal rating, causing overheating or failure','Treating an 8-ohm nominal speaker as a constant 8-ohm resistor','Ignoring phase angle, which increases amplifier stress even when impedance magnitude looks safe']::text[],ARRAY['Selecting an amplifier for a speaker with a deep impedance dip','Explaining amplifier heating on reactive loads with high phase angle','Verifying safe total impedance when paralleling speakers']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reactive loudspeaker loads');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb31cdd3-18a4-4899-b025-9845944e7a53','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb31cdd3-18a4-4899-b025-9845944e7a53') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb31cdd3-18a4-4899-b025-9845944e7a53');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec075b0f-ed7a-47d9-8810-b671ecfcc51d','Real-time analysis','Real-time analysis (RTA) displays the spectrum of a signal continuously across a bank of parallel filters, most commonly one-third-octave bands, updating live as the sound changes. It shows how energy is distributed across frequency at each moment.','A real-time analyser shows the sound''s frequency content as it happens. It splits the signal into frequency bands. Each band shows its level on a bar. The display updates live as the sound changes.','It gives an immediate picture of tonal balance and problem frequencies so a technician can judge a room, source, or system by eye in real time.','A technician plays pink noise through a PA and reads the one-third-octave RTA to spot broad peaks or dips in the room response before fine-tuning.','Signal Analysis',ARRAY['Psychoacoustic smoothing','Reference-channel delay','Ringing out a system','Fractional-octave analysis','Reference calibration']::text[],ARRAY['Expecting an RTA to reveal phase or fine timing information, which it does not show','Expecting broad one-third-octave bands to resolve narrow room modes accurately','Assuming a flat RTA guarantees good sound without checking phase and coverage']::text[],ARRAY['Checking PA tonal balance with pink noise','Identifying broad problem frequencies in a room','Monitoring spectrum live during a performance']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Real-time analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec075b0f-ed7a-47d9-8810-b671ecfcc51d','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec075b0f-ed7a-47d9-8810-b671ecfcc51d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec075b0f-ed7a-47d9-8810-b671ecfcc51d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a7d6f1b7-3c61-4e6d-a569-c1b2c9416536','Redundant networking','Redundant networking provides two independent network paths so audio keeps flowing if one path fails, using either duplicate independent networks or seamless packet-level protection switching. In audio-over-IP, Dante offers glitch-free dual-network redundancy and SMPTE ST 2022-7 defines seamless protection switching between two streams.','Redundant networking runs audio over two separate paths at once. If one path fails, the other keeps working. The switch-over causes no gap in sound. This protects live and broadcast audio from single failures.','It removes single points of failure so a cable, switch, or link fault does not interrupt the audio.','A technician wires each device''s primary and secondary ports to two physically separate switches so a failure on one network leaves audio uninterrupted on the other.','Audio Networking',ARRAY['Quality of service','Precision Time Protocol','Packet reordering','Sample-accurate synchronization','Packetized audio']::text[],ARRAY['Connecting primary and secondary to the same switch, which defeats the redundancy','Assuming redundancy replaces good QoS and clocking; it does not','Believing redundancy protects against a device''s own internal failure']::text[],ARRAY['Designing a broadcast or touring network with no single point of failure','Configuring Dante primary and secondary networks','Applying SMPTE ST 2022-7 seamless switching in an IP broadcast plant']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Redundant networking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a7d6f1b7-3c61-4e6d-a569-c1b2c9416536','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a7d6f1b7-3c61-4e6d-a569-c1b2c9416536') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a7d6f1b7-3c61-4e6d-a569-c1b2c9416536');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6a443a3-1c41-4d96-8594-ada3274ca175','Reference calibration','Reference calibration sets the absolute level accuracy of a measurement chain by applying a known acoustic level from a sound calibrator, so readings map correctly to sound pressure level. A calibrator typically produces a stable tone, such as 94 dB or 114 dB at 1 kHz.','A measurement system must know true levels. Reference calibration feeds a known sound into the microphone. A calibrator makes a fixed tone at a known level. The system is then adjusted to read that level correctly.','It anchors the whole measurement chain to a traceable reference so decibel readings are absolute and trustworthy.','Before measuring, a technician fits an acoustic calibrator to the microphone and adjusts the meter to read 94 dB at 1 kHz, then checks it again afterward.','Acoustic Measurement',ARRAY['Random-incidence calibration','Reference-channel delay','Sound pressure level','Peak sound pressure','Real-time analysis']::text[],ARRAY['Skipping the after-measurement calibration check that catches drift','Using the wrong calibrator coupler or microphone size, causing level errors','Assuming a device holds calibration indefinitely without verification']::text[],ARRAY['Calibrating a sound level meter before a noise survey','Verifying measurement accuracy before and after a test','Setting absolute SPL reference for a room measurement']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6a443a3-1c41-4d96-8594-ada3274ca175','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6a443a3-1c41-4d96-8594-ada3274ca175') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6a443a3-1c41-4d96-8594-ada3274ca175');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3cb2da09-f4ab-4a43-b28f-34770d660b99','Reference-channel delay','Reference-channel delay is the time alignment applied to the reference input of a dual-channel (transfer-function) measurement so that the reference and measurement signals arrive coincident at the analyser. Correct delay compensates for the acoustic propagation and processing time between the two paths.','A dual-channel analyser compares two signals: a reference and the measured sound. The measured sound arrives later because it travels through the air. Reference-channel delay lines them up in time. Only then is the comparison correct.','It aligns the reference and measurement paths in a transfer-function measurement so phase and coherence readings are valid.','A technician runs the analyser''s delay finder to add, say, 12 ms to the reference, matching a microphone about 4 metres from the loudspeaker before reading the response.','Signal Analysis',ARRAY['Real-time analysis','Psychoacoustic smoothing','Reference calibration','Transfer function measurement','Sample-accurate synchronization']::text[],ARRAY['Leaving the delay at zero, which corrupts phase and coherence readings','Re-finding delay after moving the mic but forgetting to update it','Confusing this internal reference alignment with a loudspeaker delay setting']::text[],ARRAY['Setting up a dual-FFT transfer-function measurement of a PA','Aligning reference delay after repositioning the measurement microphone','Explaining bad coherence caused by an unset reference delay']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference-channel delay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3cb2da09-f4ab-4a43-b28f-34770d660b99','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3cb2da09-f4ab-4a43-b28f-34770d660b99') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3cb2da09-f4ab-4a43-b28f-34770d660b99');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '908cf638-26a8-479d-b708-d07383fc0fc7','Reflections in digital cables','Reflections in digital cables occur when a cable''s characteristic impedance is not matched to the source and load, so part of the signal energy bounces back at the mismatch. In digital audio this degrades signal integrity and increases jitter and bit errors, which is why AES3 specifies 110-ohm and coaxial S/PDIF or MADI specify 75-ohm impedance.','A digital signal travels down a cable as a fast pulse. If the cable and connectors do not have the matching impedance, part of the pulse bounces back. These reflections blur the signal. They can add timing jitter or cause bit errors.','Matching cable impedance prevents reflections that would corrupt high-speed digital audio, keeping the received signal clean over distance.','A technician uses proper 110-ohm cable for balanced AES3 and 75-ohm coax for S/PDIF or MADI, avoiding ordinary analog cable that causes reflections and dropouts.','Digital Interfaces',ARRAY['Parallel digital audio','AES3','MADI','Characteristic impedance','Jitter']::text[],ARRAY['Using an analog microphone cable for AES3 instead of 110-ohm digital cable','Substituting standard patch coax for 75-ohm digital coax','Assuming a short cable never suffers reflection problems at high data rates']::text[],ARRAY['Choosing correct cable for an AES3 or MADI run','Diagnosing intermittent digital dropouts caused by impedance mismatch','Explaining why digital cables are impedance-rated while analog cables are not']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reflections in digital cables');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '908cf638-26a8-479d-b708-d07383fc0fc7','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='908cf638-26a8-479d-b708-d07383fc0fc7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='908cf638-26a8-479d-b708-d07383fc0fc7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24eab71a-800a-439b-8f5e-beafac862fdd','Regression','Regression is a statistical method that fits a model relating a response variable to one or more predictor variables, most commonly a straight line found by least squares. The fitted line minimises the sum of squared vertical distances between the data and the line.','Regression finds the best-fit line through data points. It shows how one quantity depends on another. The line is chosen to be as close as possible to all points. It lets you predict values and see trends.','It summarises the relationship between measured variables and supports prediction and calibration from experimental data.','A technician fits a regression line to calibration points relating meter reading to true level, then uses the line''s slope and intercept to correct future readings.','Statistics',ARRAY['Probability distributions','Probability density','Ratios','Proportionality','Standard deviation']::text[],ARRAY['Assuming a strong fit proves one variable causes the other','Extrapolating the line far beyond the measured data range','Fitting a straight line to clearly nonlinear data']::text[],ARRAY['Building a calibration curve from measured points','Estimating a trend in repeated measurements','Relating a control setting to a measured output level']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Regression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24eab71a-800a-439b-8f5e-beafac862fdd','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24eab71a-800a-439b-8f5e-beafac862fdd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24eab71a-800a-439b-8f5e-beafac862fdd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8efa5af8-b73c-401c-a7b8-dd100c411c60','Ringing out a system','Ringing out a system is the process of finding and taming the frequencies at which a sound system starts to feed back, by slowly raising gain until feedback begins and reducing those frequencies with equalisation. It raises the usable gain before feedback for microphones in a live space.','In a live room, turning a mic up too far causes feedback squeal. Ringing out finds those problem frequencies first. You raise the gain slowly until it just rings. Then you cut those frequencies with EQ. This lets you run louder safely.','It increases how much microphone gain a system can use before feedback, improving intelligibility and level in a live room.','A technician slowly raises a vocal mic''s gain until it just begins to ring, then narrowly cuts each ringing frequency with a graphic or parametric EQ, repeating until stable.','Live Sound',ARRAY['Real-time analysis','Feedback','Gain before feedback','Graphic equalizer','Parametric equalizer']::text[],ARRAY['UNSAFE: Letting sustained feedback build to full volume, which can damage drivers and hearing; bring gain up only to the onset of ringing','Cutting frequencies too widely, which dulls the sound instead of solving feedback','Assuming one ring-out holds after microphones or people move']::text[],ARRAY['Setting up microphones before a speech or performance','Maximising monitor level without feedback on stage','Retuning after a room''s occupancy or mic placement changes']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ringing out a system');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8efa5af8-b73c-401c-a7b8-dd100c411c60','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8efa5af8-b73c-401c-a7b8-dd100c411c60') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8efa5af8-b73c-401c-a7b8-dd100c411c60');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ee94138-8f1a-4e7e-b89a-04fb9a46ec5b','Sample-accurate synchronization','Sample-accurate synchronization aligns multiple audio devices or streams so their samples correspond to the exact same instants, with no offset of even a single sample. In networked audio it depends on a shared, high-precision clock reference such as PTP.','Many devices must play in perfect step. Sample-accurate sync means they agree down to a single sample. There is no tiny offset between them. This needs a shared, very precise clock across all devices.','It keeps multichannel and multi-device audio phase-coherent, preventing the timing errors that would smear imaging or cause comb filtering.','A technician locks all networked devices to one PTP grandmaster so a signal split across several units stays sample-aligned and phase-coherent at the outputs.','Audio Networking',ARRAY['Precision Time Protocol','Word clock','Redundant networking','Reference-channel delay','Packet reordering']::text[],ARRAY['Assuming devices on the same network are automatically sample-aligned without a shared clock','Mixing devices locked to different clock sources','Confusing low latency with sample-accurate alignment; they are not the same']::text[],ARRAY['Splitting one source across multiple networked processors','Ensuring phase coherence in a large multichannel system','Locking recorders and consoles to a common clock for a live capture']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sample-accurate synchronization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ee94138-8f1a-4e7e-b89a-04fb9a46ec5b','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ee94138-8f1a-4e7e-b89a-04fb9a46ec5b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ee94138-8f1a-4e7e-b89a-04fb9a46ec5b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '76494f00-9073-4bb1-90fe-2cc1b04313a2','Sample-rate effects on network load','Sample-rate effects on network load describe how raising the audio sample rate increases the data each channel produces, and thus the bandwidth and packet load on an audio network. The uncompressed data rate scales directly with sample rate, bit depth, and channel count.','Higher sample rates capture more data each second. That data must travel over the network. Doubling the sample rate roughly doubles the bandwidth per channel. More channels and higher bit depth add more still.','It helps a technician budget network bandwidth and switch capacity so an audio-over-IP system does not run out of headroom at high sample rates.','At 48 kHz, 24-bit, 64 channels the payload is about 74 Mbit/s (48000 x 24 x 64); moving to 96 kHz roughly doubles that before packet overhead is added.','Audio Networking',ARRAY['Packetized audio','Quality of service','Sample-accurate synchronization','Packet reordering','Redundant networking']::text[],ARRAY['Ignoring the extra bandwidth when raising sample rate on many channels','Forgetting packet and protocol overhead on top of the raw payload','Assuming a link that handles 48 kHz will always handle 96 kHz at the same channel count']::text[],ARRAY['Planning switch and link capacity for a high-channel-count system','Deciding whether to run 96 kHz given available bandwidth','Diagnosing congestion after raising the project sample rate']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sample-rate effects on network load');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '76494f00-9073-4bb1-90fe-2cc1b04313a2','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='76494f00-9073-4bb1-90fe-2cc1b04313a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='76494f00-9073-4bb1-90fe-2cc1b04313a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8db02831-ff18-49d3-a2d4-97faf3b2a1e4','Sample-rate mismatch across devices','A fault condition where two connected digital audio devices operate at different sampling frequencies, or at the same nominal frequency but from unsynchronized clocks, causing sample slips, clicks, dropouts, or pitch and timing errors in the transferred signal.','Digital gear samples sound many times each second. That speed is the sample rate. When two devices use different rates, or clocks that are not locked together, the audio breaks. You may hear clicks, gaps, or wrong pitch.','Recognizing this failure lets a technician keep every digital device on one shared clock so audio moves between them cleanly.','A tech picks one device as clock master, locks the others to it over word clock or an AES11 reference, and sets the same project rate, such as 48 kHz, on every unit.','Digital Audio',ARRAY['Synchronization','Word clock','Sample rate conversion','Serial digital audio','Jitter','Digital audio reference signal']::text[],ARRAY['Assuming two units both set to 48 kHz are synchronized; the same rate still needs one shared clock reference','Leaving each device on its own internal clock, which causes periodic clicks or slips','Forgetting that a 44.1 versus 48 kHz mismatch shifts pitch and speed unless a sample-rate converter is used']::text[],ARRAY['A digital mixer feeds a recorder that clicks once per second until both lock to a common clock','A 44.1 kHz interface is patched into a 48 kHz console and the audio plays fast','Several networked audio devices must all follow one grandmaster clock']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sample-rate mismatch across devices');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8db02831-ff18-49d3-a2d4-97faf3b2a1e4','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8db02831-ff18-49d3-a2d4-97faf3b2a1e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8db02831-ff18-49d3-a2d4-97faf3b2a1e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5672b8fe-2372-4030-8218-51dcc0b8b29f','Scalar versus vector quantities','A scalar is a physical quantity fully described by a magnitude and unit alone, while a vector requires both a magnitude and a direction; examples are temperature and sound pressure (scalars) versus particle velocity and force (vectors).','A scalar is a value with size only, like temperature or loudness. A vector has both size and direction, like a push or air-particle motion. Vectors add head to tail, so direction changes the result. Scalars just add as plain numbers.','The distinction tells a technician which quantities carry direction, so combinations like summing sound arrivals or forces are handled correctly.','When two speakers send sound to one seat, the pressures add as scalars at that point, but the particle velocities add as vectors because each arrives from a different direction.','Physics Fundamentals',ARRAY['Sound pressure','Particle velocity','Sound intensity','Phase','Spherical coordinates']::text[],ARRAY['Treating a directional quantity such as velocity or force as if it were a plain number','Adding vector magnitudes directly instead of accounting for their directions','Believing sound intensity is a scalar; it is a vector because it has a direction of energy flow']::text[],ARRAY['Explaining why sound intensity measurements need a direction while an SPL reading does not','Combining forces on a rigged speaker where angles matter','Introducing why phase and direction change how two signals sum']::text[],'Beginner','|v| = √(v_x² + v_y² + v_z²)','The magnitude of a vector equals the square root of the sum of the squares of its components along each axis.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scalar versus vector quantities');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5672b8fe-2372-4030-8218-51dcc0b8b29f','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5672b8fe-2372-4030-8218-51dcc0b8b29f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5672b8fe-2372-4030-8218-51dcc0b8b29f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75d2b0cb-8b81-4b11-acf1-558527efd70e','Scientific notation','A way of writing numbers as a coefficient whose absolute value is at least 1 and less than 10, multiplied by an integer power of ten, used to express very large or very small values compactly.','Scientific notation writes big or tiny numbers in a short form. You use one digit before the decimal point, times ten to a power. For example, 20,000 becomes 2 times ten to the fourth. It keeps track of size without long strings of zeros.','It lets technicians write and compare the wide range of audio values, from picofarads to megahertz, without error-prone strings of zeros.','A 20 kHz upper hearing limit is written 2 × 10⁴ Hz, and a 47 pF capacitor is 4.7 × 10⁻¹¹ F, making unit prefixes and calculations easier.','Math Fundamentals',ARRAY['Decibel','Unit prefixes','Logarithm','Order of magnitude','Tolerance']::text[],ARRAY['Leaving the coefficient outside the 1-to-10 range, such as writing 20 × 10³ instead of 2 × 10⁴','Getting the sign of the exponent wrong for small numbers','Miscounting decimal places when converting to or from standard form']::text[],ARRAY['Recording a capacitance in farads on a datasheet','Comparing frequencies spanning hertz to megahertz','Converting between unit prefixes such as micro, milli, and kilo']::text[],'Beginner','N = m × 10ⁿ,  1 ≤ |m| < 10,  n ∈ ℤ','A number equals a coefficient m, whose absolute value is at least one and less than ten, times ten raised to an integer power n.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scientific notation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75d2b0cb-8b81-4b11-acf1-558527efd70e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75d2b0cb-8b81-4b11-acf1-558527efd70e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75d2b0cb-8b81-4b11-acf1-558527efd70e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a60a3468-8a38-460f-aadc-57c35ea49771','Serial digital audio','The transmission of digital audio as a single stream of bits sent one after another over one conductor pair, as opposed to parallel transmission; the two-channel professional form is defined by the AES3 interface standard.','Serial means the bits travel one at a time down a single line. Digital audio is usually sent this way. The pro two-channel version is the AES3 standard, often on XLR cable. It carries left, right, and extra data in one stream.','Sending audio serially over one cable pair keeps wiring simple and reliable over distance, which is why professional digital interconnects use it.','A tech runs an AES3 signal from a console to an amplifier over one balanced XLR pair, carrying both audio channels plus status and user data in the same bitstream.','Digital Audio',ARRAY['AES3','S/PDIF','Word clock','Sample-rate mismatch across devices','Synchronization','Subframe']::text[],ARRAY['Assuming a standard microphone XLR cable is ideal for AES3; the interface specifies 110-ohm balanced cable','Confusing consumer S/PDIF with professional AES3, which differ in level and connectors','Forgetting that the receiver recovers its clock from the embedded stream']::text[],ARRAY['Wiring an AES3 digital output from a mixer to a processor','Choosing 110-ohm cable for a reliable digital run','Explaining how one pair carries two audio channels plus embedded data']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Serial digital audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a60a3468-8a38-460f-aadc-57c35ea49771','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a60a3468-8a38-460f-aadc-57c35ea49771') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a60a3468-8a38-460f-aadc-57c35ea49771');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1db4ef0c-f15e-4593-9275-9ac834ab55db','Series and parallel loads','Two ways of connecting electrical loads such as loudspeakers: in series the same current passes through each and resistances add, while in parallel the same voltage appears across each and the reciprocals of resistance add, lowering total impedance.','Loads can be wired in a chain (series) or side by side (parallel). In series the resistances add up, so total goes higher. In parallel the total drops below the smallest one. Wiring several speakers in parallel can push impedance too low for the amplifier.','Knowing these rules lets a technician predict the total impedance a set of speakers presents, keeping it within the amplifier''s safe range.','Two 8-ohm speakers in parallel give 4 ohms (1/(1/8 + 1/8)); the same two in series give 16 ohms, so the tech chooses the wiring the amplifier can drive safely.','Electrical Fundamentals',ARRAY['Impedance','Ohm''s law','Source-load interaction','Damping factor','Amplifier load rating']::text[],ARRAY['UNSAFE: Wiring too many speakers in parallel so total impedance falls below the amplifier''s minimum rating, overheating the amplifier','Reversing the rules and expecting parallel wiring to raise impedance','Adding parallel resistances directly instead of adding their reciprocals']::text[],ARRAY['Calculating total impedance before connecting multiple speakers to one amplifier channel','Deciding series versus parallel wiring for a pair of drivers','Checking that a paralleled speaker bank stays at or above the amplifier''s rated minimum load']::text[],'Intermediate','Series: R_T = R₁ + R₂ + … + Rₙ ;  Parallel: 1/R_T = 1/R₁ + 1/R₂ + … + 1/Rₙ','In series, total resistance is the sum of the individual resistances. In parallel, the reciprocal of total resistance is the sum of the reciprocals of the individual resistances.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Series and parallel loads');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1db4ef0c-f15e-4593-9275-9ac834ab55db','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1db4ef0c-f15e-4593-9275-9ac834ab55db') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1db4ef0c-f15e-4593-9275-9ac834ab55db');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3d60faff-f963-43d5-b246-f3ed7f6f8dd1','Signal ground versus safety ground','Signal ground is the zero-volt reference for audio circuits, whereas safety ground (the equipment grounding conductor, or protective earth) bonds exposed metal chassis to earth through the third pin of the AC plug so a fault current trips the breaker instead of shocking a person.','Signal ground is the zero-volt point audio is measured against. Safety ground is different. It ties metal cases to earth through the third pin on the power plug. If a live wire touches the case, safety ground carries the fault and trips the breaker. That protects you from shock.','The two grounds serve different jobs: signal ground keeps audio quiet, while safety ground protects people from electric shock during a fault.','To stop a ground-loop hum a tech breaks the signal-ground path, for example by lifting the cable shield at one end, and never disconnects the AC safety ground pin.','Electrical Safety',ARRAY['Ground loop','Equipment grounding conductor','Ground lift','Balanced interconnection','Shield','Protective earth']::text[],ARRAY['UNSAFE: Removing or defeating the AC safety-ground pin (a ''ground-lift'' adapter) to cure hum; this leaves the chassis able to become live and can be fatal','Confusing signal ground with safety ground and treating them as interchangeable','Lifting the audio shield at both ends, which removes the intended single-point reference']::text[],ARRAY['Tracing a 60 Hz hum caused by a ground loop between two racks','Deciding whether to lift a cable shield versus never lifting the mains earth','Explaining why a pin-1 fix belongs on the signal path, not the power cord']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Signal ground versus safety ground');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3d60faff-f963-43d5-b246-f3ed7f6f8dd1','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3d60faff-f963-43d5-b246-f3ed7f6f8dd1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3d60faff-f963-43d5-b246-f3ed7f6f8dd1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aeea63a6-9ffd-4984-95a3-bc9e1a9bd474','Sine and cosine relationships','The two fundamental trigonometric functions describing circular and oscillatory motion; they share the same shape but are offset by 90 degrees, obey the identity sin²θ + cos²θ = 1, and together describe the amplitude and phase of a sinusoid.','Sine and cosine are the basic wave shapes. They look identical but are shifted by 90 degrees. A cosine is just a sine that starts a quarter cycle earlier. Squared and added, they always equal one. Audio uses them to describe a wave''s size and timing.','These relationships underlie how technicians describe a pure tone''s amplitude and phase and how phase differences add or cancel signals.','Two identical tones 90 degrees apart combine as a sine plus a cosine; using sin²θ + cos²θ = 1, their sum has 1.41 times (3 dB) the amplitude of one alone.','Math Fundamentals',ARRAY['Phase','Sinusoid','Radian','Fourier analysis','Phasor']::text[],ARRAY['Thinking sine and cosine are unrelated rather than the same wave shifted 90 degrees','Mixing degrees and radians when evaluating the functions','Forgetting that a 90-degree phase shift converts one into the other']::text[],ARRAY['Explaining why a quarter-wavelength delay shifts phase by 90 degrees','Describing how phase offsets change the sum of two tones','Introducing phasors and the real and imaginary parts of a signal']::text[],'Beginner','sin²θ + cos²θ = 1 ;  cosθ = sin(θ + 90°)','The square of the sine plus the square of the cosine of an angle always equals one. A cosine equals a sine advanced by ninety degrees.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sine and cosine relationships');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aeea63a6-9ffd-4984-95a3-bc9e1a9bd474','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aeea63a6-9ffd-4984-95a3-bc9e1a9bd474') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aeea63a6-9ffd-4984-95a3-bc9e1a9bd474');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3a106075-6b7a-4a8e-8027-9c794d54c635','Slow weighting','A standardized exponential time weighting for sound level meters using a time constant of 1 second, which averages rapid level changes so the displayed sound level is steadier and easier to read than with Fast weighting.','Slow is a setting on a sound level meter. It smooths the reading using a one-second time constant. The number moves slowly and is easy to read. Fast weighting, at 125 milliseconds, reacts more quickly to short sounds.','Slow weighting gives a stable, readable level for fluctuating sound, which suits general environmental and occupational noise checks.','A tech switches the meter to Slow (S) to read a steady A-weighted level of, say, 88 dB(A) in a venue, because the one-second averaging stops the display from jumping.','Metering',ARRAY['Sound-level meter time weighting','Fast weighting','Time constant','A-weighting','Equivalent continuous level']::text[],ARRAY['Comparing a Slow reading against a Fast reading and expecting the same value for a changing sound','Confusing time weighting (Slow/Fast) with frequency weighting (A/C/Z)','Assuming Slow captures brief peaks; short transients need Fast or peak measurement']::text[],ARRAY['Reading a stable venue sound level for a noise report','Choosing Slow versus Fast when a display fluctuates too much to read','Explaining why two meters differ when set to different time weightings']::text[],'Beginner','τ_S = 1 s (exponential-average time constant)','Slow weighting applies an exponential running average of the squared signal with a time constant of one second.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Slow weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3a106075-6b7a-4a8e-8027-9c794d54c635','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3a106075-6b7a-4a8e-8027-9c794d54c635') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3a106075-6b7a-4a8e-8027-9c794d54c635');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d3cfaab-cc1a-46c1-8dce-4a61fd7a4244','Sound-level meter time weighting','The standardized exponential averaging a sound level meter applies to the squared signal before display, selectable as Fast (125 ms time constant) or Slow (1 s time constant), which sets how quickly the reading responds to level changes.','Time weighting controls how fast a meter reacts. Fast uses a 125-millisecond time constant and follows quick changes. Slow uses one second and gives a steadier number. It is different from A or C frequency weighting, which shapes tone, not speed.','Time weighting standardizes the meter''s response speed so readings are repeatable and comparable between instruments and operators.','For impulsive machine noise a tech uses Fast to catch quick rises, but for a fluctuating crowd a tech uses Slow so the 1-second averaging steadies the display.','Metering',ARRAY['Slow weighting','Fast weighting','Impulse weighting','Time averaging','A-weighting','Peak level']::text[],ARRAY['Confusing time weighting (Fast/Slow) with frequency weighting (A/C/Z)','Assuming exponential time weighting captures true peaks; peak hold is a separate function','Reporting a level without stating the time weighting used']::text[],ARRAY['Selecting Fast or Slow before logging a venue''s sound level','Explaining why two operators got different numbers using different settings','Documenting the meter configuration in a compliance noise report']::text[],'Intermediate','τ_F = 125 ms ;  τ_S = 1 s','Fast weighting uses an exponential-average time constant of 125 milliseconds; Slow weighting uses one second.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-level meter time weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d3cfaab-cc1a-46c1-8dce-4a61fd7a4244','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d3cfaab-cc1a-46c1-8dce-4a61fd7a4244') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d3cfaab-cc1a-46c1-8dce-4a61fd7a4244');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '488be216-0da9-462c-829f-1c989574f44e','Source-load interaction','The way a driving source''s output impedance and the connected load''s input impedance divide the signal voltage, so the load actually receives only the fraction Z_L/(Z_S + Z_L) of the source''s open-circuit voltage.','Every output has some internal resistance, and every input has some too. Together they act like a voltage divider. The load only gets part of the source''s voltage. If the load impedance is much higher than the source''s, almost all the voltage transfers.','Understanding this interaction lets a technician keep signal transfer efficient and predictable, following the modern rule of low source and high load impedance for voltage transfer.','A 150-ohm source feeding a 10 k-ohm input delivers 10000/(150 + 10000) = 98.5 percent of its voltage, so level loss is negligible; a much lower load would drop the level.','Electrical Fundamentals',ARRAY['Impedance','Impedance bridging','Series and parallel loads','Voltage divider','Damping factor','Loading']::text[],ARRAY['Trying to impedance-match (equal source and load) for line-level audio, which halves the voltage; modern practice bridges instead','Ignoring that a low-impedance load pulls down the source voltage','Assuming an output can drive any number of paralleled inputs without level loss']::text[],ARRAY['Fanning one line output to several inputs and checking for level drop','Choosing bridging over matching for a line-level connection','Explaining why a passive splitter loads a microphone and lowers its output']::text[],'Intermediate','V_L = V_S × Z_L / (Z_S + Z_L)','The voltage delivered to the load equals the source''s open-circuit voltage times the load impedance divided by the sum of the source and load impedances.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source-load interaction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '488be216-0da9-462c-829f-1c989574f44e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='488be216-0da9-462c-829f-1c989574f44e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='488be216-0da9-462c-829f-1c989574f44e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1b23dc69-976d-4371-9cf3-f14da16eaacc','Spanning tree','A network protocol, originally standardized as IEEE 802.1D, that prevents bridging loops in an Ethernet network by selecting a loop-free active topology and putting redundant links into a blocking state until they are needed.','Ethernet networks can form loops when there are backup links. Loops cause broadcast storms that flood the network. Spanning tree solves this. It shuts off the extra links, leaving one clear path. If the main path fails, a blocked link switches on.','Spanning tree keeps a switched network loop-free while allowing redundant cabling, so an audio network stays stable and can recover from a link failure.','On a networked audio system a tech confirms switches run rapid spanning tree so a redundant cable does not create a loop, while noting that convergence delays can still disrupt tightly timed audio streams.','Networking',ARRAY['Ethernet','VLAN','Broadcast storm','Audio over IP','Rapid Spanning Tree Protocol','Network switch']::text[],ARRAY['Assuming redundant Ethernet cabling is safe without a loop-prevention protocol enabled','Confusing classic STP with the faster Rapid STP that most modern switches use','Ignoring that spanning-tree reconvergence can briefly interrupt real-time audio transport']::text[],ARRAY['Building a redundant audio network without creating a switching loop','Diagnosing a network-wide flood traced to an accidental cable loop','Deciding whether spanning tree or a dedicated redundancy scheme fits a live audio network']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spanning tree');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1b23dc69-976d-4371-9cf3-f14da16eaacc','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1b23dc69-976d-4371-9cf3-f14da16eaacc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1b23dc69-976d-4371-9cf3-f14da16eaacc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1d35512d-5db7-404f-a100-923722eaea95','Spatial averaging for system tuning','A measurement technique that combines frequency responses captured at several nearby listening positions into one averaged curve, reducing the influence of position-specific peaks and dips so the technician tunes to the response common across the seating area.','One microphone position shows peaks and dips unique to that spot. Moving a few feet changes them. Spatial averaging takes readings from several seats and blends them. The result shows what most listeners really hear. You then tune to that shared response.','Averaging over positions stops a technician from chasing narrow, seat-specific artifacts and reveals the consistent trends worth correcting for the whole audience.','A tech captures transfer-function measurements at six seats across a section, averages them, and applies equalization only to the broad trends that persist across all the positions.','System Tuning',ARRAY['Transfer-function averaging','System equalization versus room correction','Target curves','Comb filtering','Measurement microphone','Spatial sampling']::text[],ARRAY['Equalizing a sharp dip seen at only one microphone position that disappears a few feet away','Averaging too few positions to represent the seating area','Spacing measurement points so far apart that the average blurs real, audible differences between zones']::text[],ARRAY['Tuning a main loudspeaker system across a seating block','Deciding which response features are worth correcting versus ignoring','Comparing several seats to find the response common to the audience']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial averaging for system tuning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1d35512d-5db7-404f-a100-923722eaea95','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1d35512d-5db7-404f-a100-923722eaea95') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1d35512d-5db7-404f-a100-923722eaea95');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b6e9fb12-e041-49c2-9968-875d9222ab5c','Spectrograph','A measurement display that shows how a signal''s frequency content evolves over time, plotting time on one axis and frequency on the other with color or brightness indicating level at each point; the resulting image is a spectrogram.','A spectrograph shows sound in three ways at once. Time runs along one axis and frequency along the other. Color or brightness shows how loud each frequency is. It reveals patterns you cannot see on a plain level meter, like a rising tone or a resonance.','It lets a technician see how energy at each frequency changes over time, exposing feedback tones, reverberant tails, and noises a single spectrum snapshot would miss.','A tech watches a spectrograph during a soundcheck to spot a narrow horizontal line that builds up, identifying the exact ringing frequency to notch out before feedback occurs.','Signal Analysis',ARRAY['Spectrum analyzer','Fast Fourier transform','Feedback','Waterfall plot','Reverberation time','Time-frequency analysis']::text[],ARRAY['Confusing a spectrograph (time versus frequency) with a spectrum analyzer (a single frequency snapshot)','Misreading the color scale, which represents level, not a separate quantity','Choosing an FFT window that trades away the time or frequency detail the task needs']::text[],ARRAY['Hunting a ringing feedback frequency during a soundcheck','Visualizing a room''s decay after an impulse','Identifying intermittent noise buried in a recording']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectrograph');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b6e9fb12-e041-49c2-9968-875d9222ab5c','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b6e9fb12-e041-49c2-9968-875d9222ab5c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b6e9fb12-e041-49c2-9968-875d9222ab5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9e99b9d9-4ee2-49eb-9ce7-30d95a426496','Spherical coordinates','A three-dimensional coordinate system that locates a point by a radial distance from the origin and two angles, an inclination and an azimuth, rather than by three Cartesian distances; it is the natural frame for describing radiation and directivity around a source.','Spherical coordinates describe a point using one distance and two angles. The distance is how far from the center. The angles say which direction. This suits sound, because loudspeakers and microphones radiate or pick up around a sphere. It maps directions cleanly.','This coordinate frame lets technicians describe and measure how a source radiates in every direction, which is central to directivity and polar-pattern data.','A polar or balloon measurement reports level as a function of the two angles at a fixed radius, so a tech reads coverage at, for example, 30 degrees off-axis directly from the spherical data.','Math Fundamentals',ARRAY['Polar pattern','Directivity','Balloon data','Azimuth and elevation','Cartesian coordinates','Spinorama-style data']::text[],ARRAY['Swapping the inclination and azimuth angles, which mislabels the direction','Mixing physics and math conventions for which symbol is which angle without stating it','Forgetting the radius must be held constant when comparing directional levels']::text[],ARRAY['Interpreting a loudspeaker''s balloon directivity data','Reading a microphone polar pattern by angle','Setting up angular measurement points around a source']::text[],'Intermediate','x = r sinθ cosφ,  y = r sinθ sinφ,  z = r cosθ','A point''s Cartesian coordinates come from its radius, its inclination angle from the vertical axis, and its azimuth angle around that axis.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical coordinates');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9e99b9d9-4ee2-49eb-9ce7-30d95a426496','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9e99b9d9-4ee2-49eb-9ce7-30d95a426496') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9e99b9d9-4ee2-49eb-9ce7-30d95a426496');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2da98e00-4785-4a6d-b424-9c5c54bfe24c','Spinorama-style data','A standardized set of loudspeaker frequency-response curves derived from a dense sphere of measurements, defined by ANSI/CTA-2034, that presents on-axis response, listening window, early reflections, sound power, and the directivity indices on one graph to summarize a speaker''s on- and off-axis behavior.','Spinorama is a standard way to graph a loudspeaker''s sound. It comes from many measurements taken all around the speaker. One chart then shows the direct sound, the reflected sound, and the total power. It lets you judge tone and coverage from a single picture.','It gives technicians and reviewers a repeatable, standardized picture of both direct and off-axis response, which predicts how a speaker will sound in a real room.','A tech reads a speaker''s Spinorama to check for a smooth, flat listening window and a steadily sloping sound-power curve, signs the off-axis response will not color the room.','Loudspeaker Measurement',ARRAY['Directivity index','Sound power','Listening window','Early reflections','Frequency response','Off-axis response']::text[],ARRAY['Judging a speaker from the on-axis curve alone and ignoring the off-axis and sound-power curves','Assuming a flat on-axis response guarantees smooth off-axis behavior','Treating the trademarked ''Spinorama'' name as if it were the standard itself rather than the CTA-2034 method']::text[],ARRAY['Comparing two studio monitors from published measurement data','Predicting how a speaker''s off-axis sound will interact with a room','Explaining why directivity, not just on-axis flatness, drives perceived quality']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spinorama-style data');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2da98e00-4785-4a6d-b424-9c5c54bfe24c','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2da98e00-4785-4a6d-b424-9c5c54bfe24c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2da98e00-4785-4a6d-b424-9c5c54bfe24c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '894b07df-e3de-4a00-ab1b-a4127caf94b8','Stage spill','Unwanted acoustic sound from stage sources, such as monitor wedges, backline amplifiers, and drums, that leaks into microphones or radiates into the audience and mixes with the intended reinforced sound.','On stage, monitors and amps make their own sound. Some of it leaks into the vocal mics or spills to the crowd. This is stage spill. It muddies the main mix and can cause feedback. Controlling it keeps the front-of-house sound clean.','Managing stage spill preserves mix clarity and gain before feedback, because leaked stage sound competes with and colors the reinforced signal.','A tech reduces spill by using directional microphones, lowering wedge levels, switching to in-ear monitors, or angling backline so less of it reaches open vocal mics.','Live Sound',ARRAY['Bleed','Feedback','Gain before feedback','Stage monitor','Microphone polar pattern','In-ear monitoring']::text[],ARRAY['Raising a fader to overcome spill, which usually worsens feedback and muddiness','Using omnidirectional mics on a loud stage where a directional pattern would reject spill','Ignoring that loud wedges are a major spill and feedback source']::text[],ARRAY['A vocal mic picking up the drum kit and guitar amp','Switching a band to in-ear monitors to quiet the stage','Choosing cardioid mics to reject nearby wedge output']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stage spill');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '894b07df-e3de-4a00-ab1b-a4127caf94b8','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='894b07df-e3de-4a00-ab1b-a4127caf94b8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='894b07df-e3de-4a00-ab1b-a4127caf94b8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ae97868-7da6-4a47-bcd7-0d07efc7ed29','Statistical averages','Summary measures of central tendency, most commonly the arithmetic mean (the sum of values divided by their count), used with spread measures to describe a set of measurements such as repeated level or response readings.','An average condenses many numbers into one typical value. The most common is the mean: add the values, then divide by how many there are. Averages help make sense of repeated measurements. They work best alongside a measure of how spread out the data is.','Averaging repeated audio measurements reduces random error and gives a stable, representative value for tuning or reporting.','A tech reads a sound level five times as 87, 88, 86, 89, and 90 dB; the mean is 88 dB, a steadier figure than any single reading.','Math Fundamentals',ARRAY['Mean','Median','Standard deviation','Time averaging','Spatial averaging for system tuning','Root mean square']::text[],ARRAY['Averaging decibel values arithmetically when energy (power) averaging is required, which biases the result','Reporting a mean without any measure of spread','Confusing the mean with the median when the data are skewed']::text[],ARRAY['Combining repeated meter readings into one representative level','Deciding between mean and median for skewed data','Explaining why decibels need energy averaging, not simple arithmetic averaging']::text[],'Beginner','x̄ = (1/N) Σᵢ xᵢ','The arithmetic mean equals the sum of all the values divided by the number of values.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Statistical averages');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ae97868-7da6-4a47-bcd7-0d07efc7ed29','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ae97868-7da6-4a47-bcd7-0d07efc7ed29') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ae97868-7da6-4a47-bcd7-0d07efc7ed29');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2949a17c-ca66-49c2-808b-d4062b2e3686','Subwoofer lobing','The pattern of constructive and destructive interference created when two or more subwoofers radiate the same low-frequency signal, producing directional lobes of reinforcement and nulls of cancellation that vary with position, spacing, and relative timing.','When several subs play the same bass, their sound waves overlap. In some directions they add and get louder. In others they cancel and get quieter. These loud and quiet zones are lobes and nulls. Their spacing and delay control where each one lands.','Understanding lobing lets a technician arrange and time multiple subwoofers to steer bass energy toward the audience and away from the stage or unwanted areas.','A tech builds an end-fire or cardioid subwoofer array, setting spacing and delay so the lobes reinforce toward the crowd and a null points back at the stage.','Acoustics',ARRAY['Comb filtering','Cardioid subwoofer array','End-fire array','Interference','Phase','Coverage']::text[],ARRAY['Spreading subwoofers far apart without accounting for the strong lobing and nulls it creates across the audience','Assuming low frequencies are omnidirectional and immune to array interference','Ignoring that changing spacing or delay moves the nulls into occupied seats']::text[],ARRAY['Designing a directional subwoofer array to keep bass off the stage','Diagnosing uneven bass across a room from spaced subs','Choosing spacing and delay to steer low-frequency coverage']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Subwoofer lobing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2949a17c-ca66-49c2-808b-d4062b2e3686','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2949a17c-ca66-49c2-808b-d4062b2e3686') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2949a17c-ca66-49c2-808b-d4062b2e3686');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17021c29-c3f7-4a0c-b4b3-6beb7cfba31a','Synchronization','The process of aligning the timing of multiple audio or video devices to a common reference so that their clocks, sample edges, or frame boundaries agree, preventing drift, slips, and timing errors across the system.','Synchronization means locking devices to the same timing reference. In digital audio each device samples on a shared clock. That keeps their sample edges lined up. Without it the units drift apart and the audio clicks or loses sync over time.','Synchronization keeps every device in a system on a common time base, which is required for clean digital transfer and for locking audio to video.','A tech distributes a house reference, such as an AES11 digital audio reference signal or word clock, and locks the console, converters, and recorder to it so nothing drifts.','Systems',ARRAY['Word clock','AES11','Sample-rate mismatch across devices','Jitter','Timecode','Genlock']::text[],ARRAY['Confusing sample-accurate clock synchronization with timecode, which addresses positional timing not sample timing','Chaining clock from device to device instead of distributing one master reference','Assuming devices set to the same sample rate are automatically synchronized']::text[],ARRAY['Locking a studio''s converters and console to one house clock','Aligning audio playback to video frames for post-production','Preventing slow drift between two digitally linked recorders']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Synchronization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17021c29-c3f7-4a0c-b4b3-6beb7cfba31a','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17021c29-c3f7-4a0c-b4b3-6beb7cfba31a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17021c29-c3f7-4a0c-b4b3-6beb7cfba31a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '986f4929-68d3-492a-8dd4-2dccd6ff34f8','System equalization versus room correction','Two distinct tuning approaches: system equalization shapes the loudspeaker system''s own direct-sound response and level balance, while room correction targets the combined loudspeaker-plus-room response, often including the effects of reflections and modes at the listening position.','System EQ fixes the speakers themselves and their tonal balance. Room correction goes further. It measures the sound at the seat, including room reflections and bass modes, then tries to fix that combined result. The two solve different problems and can conflict.','Separating the two prevents a technician from using equalization to fix room problems that need acoustic treatment or placement instead.','A tech first equalizes the system''s direct response to a smooth target, then applies limited low-frequency room correction for modal peaks, while treating strong reflections acoustically rather than with EQ.','System Tuning',ARRAY['Target curves','Room modes','Spatial averaging for system tuning','Acoustic treatment','Minimum-phase','Transfer-function averaging']::text[],ARRAY['Trying to equalize away a narrow room-mode null; boosting a cancellation wastes power and cannot fill it','Correcting reflection-caused dips that are not minimum-phase and cannot be fixed by EQ','Applying heavy per-seat room correction that only holds at one measurement point']::text[],ARRAY['Tuning a control room where bass modes dominate','Deciding what to fix with EQ versus with acoustic treatment','Setting a house system''s tonal balance before any room correction']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='System equalization versus room correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '986f4929-68d3-492a-8dd4-2dccd6ff34f8','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='986f4929-68d3-492a-8dd4-2dccd6ff34f8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='986f4929-68d3-492a-8dd4-2dccd6ff34f8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '267ab9b8-9a14-42c5-95a8-40be86d08a4a','System optimization under time constraints','The practical discipline of prioritizing sound-system tuning tasks when available setup time is limited, focusing effort on the adjustments that yield the largest improvement, such as coverage, level balance, and subwoofer alignment, before finer corrections.','Real events give limited setup time. You cannot perfect everything. Optimization under time pressure means fixing the biggest problems first. That usually means coverage, gain structure, and aligning subs to mains. Small tweaks come last, only if time remains.','It helps a technician spend scarce setup time on the changes that matter most to the audience, rather than polishing details that time may not allow.','With thirty minutes before doors, a tech verifies coverage and polarity, sets gain structure, aligns subs to the mains, applies broad tonal EQ, and skips seat-by-seat fine tuning.','Workflow',ARRAY['Gain structure','Coverage','Subwoofer alignment','System equalization versus room correction','Spatial averaging for system tuning','Time alignment']::text[],ARRAY['Spending limited time on narrow EQ tweaks before basic coverage and polarity are confirmed','Skipping subwoofer-to-main alignment, which affects far more seats than fine EQ','Chasing a perfect single-seat response instead of a good result across the audience']::text[],ARRAY['Tuning a festival changeover in a few minutes','Deciding the order of tuning steps under a tight schedule','Triaging which fixes give the most audience-wide benefit first']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='System optimization under time constraints');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '267ab9b8-9a14-42c5-95a8-40be86d08a4a','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='267ab9b8-9a14-42c5-95a8-40be86d08a4a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='267ab9b8-9a14-42c5-95a8-40be86d08a4a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f1e1ace-61e1-48d3-99dd-eda958b40dbf','Target curves','A defined frequency-response shape a technician tunes a sound system toward, typically flat or gently downward-sloping at high frequencies, used as the goal for equalization at the measurement or listening position.','A target curve is the response shape you aim for when tuning. It is often flat, or slightly tilted down toward the highs. Measured sound gets equalized toward this goal. Different venues and tastes use different targets, but the idea is a shared aim.','A target curve gives equalization an objective, repeatable goal, so tuning is consistent between systems, engineers, and sessions.','A tech tunes a room to a target that is flat to about 1 kHz and then slopes gently downward, matching the response commonly preferred for a natural balance in that space.','System Tuning',ARRAY['System equalization versus room correction','Tonal balance versus flatness','Spatial averaging for system tuning','Frequency response','Preferred in-room response','House curve']::text[],ARRAY['Forcing a dead-flat in-room target, which often sounds too bright because rooms and speakers roll off naturally','Treating one target curve as universally correct for every room and genre','Equalizing to the target at a single seat instead of an averaged response']::text[],ARRAY['Setting a tuning goal before equalizing a room','Comparing a measured response against a preferred house curve','Explaining why a sloped target sounds more natural than dead-flat']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Target curves');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f1e1ace-61e1-48d3-99dd-eda958b40dbf','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f1e1ace-61e1-48d3-99dd-eda958b40dbf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f1e1ace-61e1-48d3-99dd-eda958b40dbf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a52899a4-af5e-44dd-b0c2-fe65704e9bd7','Temperature and humidity effects','The influence of air temperature and humidity on sound propagation: temperature sets the speed of sound (about 343 m/s at 20 degrees Celsius, rising with temperature), while humidity chiefly alters high-frequency air absorption, both shifting a system''s timing and tonal balance outdoors.','Air conditions change how sound travels. Warmer air makes sound move faster. That shifts arrival times and delay alignment. Humidity mainly affects the highs. Dry air soaks up high frequencies more, so a system tuned in the afternoon can sound different at night.','Accounting for these effects lets a technician keep delay alignment and tonal balance correct as outdoor conditions change through an event.','The speed of sound near 20 degrees Celsius is about 343 m/s; a 10-degree rise increases it by roughly 6 m/s, enough to shift a long delay time and require realignment.','Acoustics',ARRAY['Speed of sound','Air absorption','Delay alignment','High-frequency attenuation','Time alignment','Outdoor sound']::text[],ARRAY['Assuming the speed of sound is fixed; it changes noticeably with temperature and must be updated in delay calculations','Believing humidity mainly affects bass; its dominant effect is on high-frequency absorption','Setting delay times in the cool morning and never rechecking them as the day warms']::text[],ARRAY['Realigning delay speakers as an outdoor venue warms during the day','Explaining why a system sounds duller over a long throw in dry air','Correcting delay times set at a different temperature']::text[],'Intermediate','c ≈ 331.3 × √(1 + T/273.15)  m/s  (T in °C)','The speed of sound in air roughly equals 331.3 meters per second times the square root of one plus the temperature in Celsius divided by 273.15.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temperature and humidity effects');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a52899a4-af5e-44dd-b0c2-fe65704e9bd7','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a52899a4-af5e-44dd-b0c2-fe65704e9bd7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a52899a4-af5e-44dd-b0c2-fe65704e9bd7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b22b3574-0f7b-4be9-94dc-c366d88d3eaa','Thermal limiting','A protection function in amplifiers and powered loudspeakers that reduces gain or output when internal temperature, often estimated from the signal''s power over time, rises toward a limit, guarding the voice coil or output devices against heat damage.','Sustained high power heats an amplifier and its speakers. Too much heat can burn a voice coil or output stage. Thermal limiting watches this heat build-up. As it nears the limit, the system quietly turns the level down. This protects the gear from damage.','Thermal limiting protects costly output devices and voice coils from overheating during sustained loud passages, extending equipment life and preventing failure.','During a long, loud set a powered speaker''s limiter models coil temperature and pulls back gain before the coil overheats, so a tech hears reduced headroom rather than a blown driver.','Amplification',ARRAY['Limiter','Power compression','Voice coil','Root mean square','Protection circuit','Headroom']::text[],ARRAY['UNSAFE: Bypassing or defeating a thermal-protection circuit to gain output, which risks fire and destroyed drivers','Confusing thermal limiting with peak limiting; thermal limiting responds to average power over time, not instantaneous peaks','Mistaking the gain reduction from thermal limiting for a fault instead of protection']::text[],ARRAY['A powered speaker quietly loses level late in a loud set as it heats up','Explaining why sustained high average power triggers protection but brief peaks do not','Preventing driver damage during long, high-level program material']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal limiting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b22b3574-0f7b-4be9-94dc-c366d88d3eaa','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b22b3574-0f7b-4be9-94dc-c366d88d3eaa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b22b3574-0f7b-4be9-94dc-c366d88d3eaa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f8a870bf-21ef-4b99-9d4a-b443f2692726','Time averaging','Averaging a signal''s energy over a stated time window; in acoustics the equivalent continuous sound level (Leq) is the constant level carrying the same energy as the fluctuating sound over that period, giving a single dose-related value.','Time averaging blends a changing signal over a set period. For noise, this gives the Leq. It is the steady level that holds the same energy as the real, changing sound. One Leq number captures the overall exposure over minutes or hours.','Time averaging produces a single energy-based level, such as Leq, that represents fluctuating sound over a period and underpins noise-exposure and dose measurements.','A tech logs a 15-minute Leq of 92 dB(A) in a venue; that one value summarizes the varying level and feeds directly into an occupational noise-exposure assessment.','Metering',ARRAY['Equivalent continuous level','Sound-level meter time weighting','Noise exposure','Statistical averages','A-weighting','Sound exposure']::text[],ARRAY['Confusing linear time averaging (Leq, equal energy) with exponential time weighting (Fast/Slow)','Averaging decibel values arithmetically instead of averaging energy','Reporting an Leq without stating the averaging time it covers']::text[],ARRAY['Measuring a venue''s Leq for a noise-exposure report','Explaining why Leq differs from an instantaneous Slow reading','Documenting worker sound exposure over a shift']::text[],'Intermediate','L_eq,T = 10 log₁₀[ (1/T) ∫₀ᵀ (p(t)/p₀)² dt ]','The equivalent continuous level equals ten times the base-ten logarithm of the time-averaged squared sound pressure divided by the reference pressure squared.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time averaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f8a870bf-21ef-4b99-9d4a-b443f2692726','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f8a870bf-21ef-4b99-9d4a-b443f2692726') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f8a870bf-21ef-4b99-9d4a-b443f2692726');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c183ab1-18ae-4ad2-80ad-4c859bb6d32b','Tolerance','The permitted deviation of a component''s actual value from its nominal marked value, expressed as a percentage or absolute range; for example a 1000-ohm resistor at 5 percent tolerance may measure anywhere from 950 to 1050 ohms.','No component is exactly its marked value. Tolerance states how far off it may be. A 5 percent resistor can be 5 percent above or below its number. It sets the guaranteed range, not the exact value. Tighter tolerance means less variation.','Tolerance tells a technician how much part-to-part variation to expect, so circuit designs stay within specification despite real components differing from their marked values.','A crossover using 5 percent capacitors may shift its corner frequency by a few percent between units; a tech chooses 1 percent parts where the design needs tighter matching.','Components',ARRAY['Nominal value','Component matching','E-series values','Scientific notation','Precision','Drift']::text[],ARRAY['Assuming a marked value is exact and ignoring the guaranteed range around it','Confusing tolerance (spread around nominal) with temperature drift or aging','Expecting two same-value parts to match precisely when their tolerance bands allow real differences']::text[],ARRAY['Selecting resistor and capacitor tolerance for a crossover','Explaining unit-to-unit variation in filter corner frequency','Reading a datasheet''s tolerance specification before ordering parts']::text[],'Beginner','Value range = X_nom × (1 ± t)','The guaranteed value range equals the nominal value times one plus or minus the fractional tolerance.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tolerance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c183ab1-18ae-4ad2-80ad-4c859bb6d32b','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c183ab1-18ae-4ad2-80ad-4c859bb6d32b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c183ab1-18ae-4ad2-80ad-4c859bb6d32b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fba2b6e5-dde7-484e-8372-39a01bd046df','Tonal balance versus flatness','The distinction between a subjectively pleasing distribution of energy across frequency bands (tonal balance) and a strictly flat measured frequency response; a system can measure flat yet sound unbalanced, and a preferred sound is often gently sloped rather than flat.','Flatness is a measured thing: equal level at every frequency. Tonal balance is how the sound feels across bass, mids, and highs. They are not the same. A flat measurement in a room can sound too bright. Good balance is often slightly tilted, not dead flat.','Separating the two reminds a technician that the goal is a pleasing, natural balance for listeners, not a flat line on a chart for its own sake.','A tech notices a room measures flat but sounds harsh, then tunes to a gently downward-sloping target that listeners judge as better balanced.','System Tuning',ARRAY['Target curves','Frequency response','System equalization versus room correction','Preferred in-room response','Timbre','House curve']::text[],ARRAY['Equating a flat measurement with good sound; a flat in-room response often sounds too bright','Chasing measurement flatness at one seat instead of a pleasing balance across the room','Ignoring that speaker directivity and room effects make flat direct sound and flat in-room response differ']::text[],ARRAY['Deciding a tuning goal when a flat room sounds harsh','Explaining to a client why the system is not tuned dead-flat','Comparing measured flatness against listener-preferred balance']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tonal balance versus flatness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fba2b6e5-dde7-484e-8372-39a01bd046df','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fba2b6e5-dde7-484e-8372-39a01bd046df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fba2b6e5-dde7-484e-8372-39a01bd046df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c48aa6e5-d7c5-4e48-8345-ad8b14251fc8','Transfer-function averaging','Combining several dual-channel transfer-function measurements, each comparing a system''s output to its input, into an averaged magnitude and phase response, typically using coherence to weight or reject unreliable data before averaging.','A transfer function compares a system''s output to its input at each frequency. One measurement alone can be noisy. Averaging several makes the result steadier and easier to trust. Good analyzers also use coherence to drop unreliable data. This gives a cleaner response to tune from.','Averaging transfer functions and weighting by coherence reduces noise and reflection artifacts, giving a technician a reliable magnitude and phase curve to base tuning decisions on.','Using a dual-FFT analyzer, a tech averages several transfer-function captures at a position, letting the coherence value flag and discard measurements corrupted by noise or wind before equalizing.','Signal Analysis',ARRAY['Transfer function','Coherence','Dual-FFT analyzer','Spatial averaging for system tuning','Magnitude and phase','Frequency response']::text[],ARRAY['Averaging measurements with low coherence, which pollutes the result with unreliable data','Confusing transfer-function (input-referenced) measurement with a plain single-channel spectrum','Averaging too few captures to suppress noise, leaving a jittery curve']::text[],ARRAY['Building a stable transfer-function measurement before equalizing a system','Using coherence to reject wind-corrupted outdoor data','Combining repeated captures at one microphone position']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transfer-function averaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c48aa6e5-d7c5-4e48-8345-ad8b14251fc8','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c48aa6e5-d7c5-4e48-8345-ad8b14251fc8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c48aa6e5-d7c5-4e48-8345-ad8b14251fc8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cda3526d-84e5-4e02-aa65-24f43eef6d63','Transformer taps','Selectable connection points on a distribution loudspeaker transformer in a constant-voltage (70V/100V) system, where the chosen primary tap sets the wattage that speaker draws from the line and secondary taps match the driver impedance; the line runs near 70.7V RMS at full amplifier output.','In a 70-volt or 100-volt speaker system, each speaker has a small transformer. Its taps are labeled in watts. You pick a tap to set that speaker''s power and loudness. The line sits near 70.7 volts at full output. All the tap wattages together must stay under the amplifier''s rating.','Taps let a technician set each speaker''s power draw independently on a shared line, distributing many speakers over long cable runs from one amplifier.','A tech taps ceiling speakers at 5W each in a 70V system; twenty speakers draw 100W total, which must stay below the amplifier''s rated power, and halving a tap lowers that speaker''s level by 3 dB.','Electrical Distribution',ARRAY['Constant-voltage distribution','70V line','100V line','Impedance matching','Series and parallel loads','Distributed audio']::text[],ARRAY['UNSAFE: Summing tapped wattages beyond the amplifier''s rated power, overloading and overheating the amplifier and wiring','Confusing the primary wattage taps with the secondary impedance taps','Assuming a 70V line is low-voltage and harmless; at full output it approaches 70.7V RMS and must be wired to code']::text[],ARRAY['Setting per-zone loudness in a distributed ceiling-speaker system','Adding up tapped wattages to size the amplifier','Choosing a lower tap to reduce one speaker''s level by 3 dB']::text[],'Intermediate','Tap power P = V_line² / Z_reflected ;  Σ P_taps < P_amp,rated','Each transformer tap reflects an impedance that draws a set power from the constant-voltage line; the sum of all tap powers must stay below the amplifier''s rated power.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transformer taps');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cda3526d-84e5-4e02-aa65-24f43eef6d63','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cda3526d-84e5-4e02-aa65-24f43eef6d63') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cda3526d-84e5-4e02-aa65-24f43eef6d63');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd1d8ac96-2604-437a-b3bd-69e9be0a17fa','Transmission-line behavior','The behavior of a cable when its length is a significant fraction of the signal wavelength, so voltage and current vary along it and the line''s characteristic impedance and terminations govern reflections; for a lossless line the characteristic impedance is the square root of inductance per length over capacitance per length.','A short cable just passes a signal. But when the cable is long compared with the signal''s wavelength, it acts like a transmission line. The signal can reflect off the far end. Matching the cable and load impedances stops those reflections. This matters for digital and RF signals, not slow analog audio.','Recognizing transmission-line behavior lets a technician terminate digital and RF cables correctly, preventing reflections that corrupt high-speed signals.','For an AES3 digital run a tech uses 110-ohm cable and 110-ohm terminated inputs so the line''s characteristic impedance is matched and reflections do not degrade the bitstream.','Electrical Fundamentals',ARRAY['Characteristic impedance','Impedance matching','Reflection','AES3','Wavelength','Termination']::text[],ARRAY['Applying transmission-line rules to short analog audio runs where the cable is far shorter than the wavelength','Ignoring impedance matching and termination on digital or video cable, causing reflections and errors','Assuming any cable of the right connector works for AES3; characteristic impedance must match']::text[],ARRAY['Choosing correctly terminated 110-ohm cable for AES3','Explaining why long digital runs need matched impedance but short mic cables do not','Diagnosing digital errors traced to unterminated or mismatched cable']::text[],'Advanced','Z₀ = √(L/C)  (lossless line)','The characteristic impedance of a lossless transmission line equals the square root of its inductance per unit length divided by its capacitance per unit length.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transmission-line behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd1d8ac96-2604-437a-b3bd-69e9be0a17fa','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d1d8ac96-2604-437a-b3bd-69e9be0a17fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d1d8ac96-2604-437a-b3bd-69e9be0a17fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4dec7db-6667-4a23-808b-9c7d370a178a','Transparent clocks','In the IEEE 1588 Precision Time Protocol (PTP), a transparent clock is a network device, typically a switch, that measures the time a PTP event message spends passing through it (its residence time) and adds that value to the message''s correctionField, so downstream clocks can subtract the device''s own delay. End-to-end transparent clocks correct only for residence time, while peer-to-peer types also add the measured link delay to each directly connected neighbor.','PTP is a way to sync clocks across a network. A transparent clock is a switch that times how long each message sits inside it. It writes that delay into the message. Downstream devices then remove the switch''s delay for better accuracy.','It keeps network switches from adding hidden, variable delay to timing messages, so synchronized audio devices stay tightly locked to a common clock.','A technician builds a Dante or AES67 network with PTP-aware switches set as transparent clocks, so added switch delay does not degrade sample-clock synchronization across the system.','Networking / Timing',ARRAY['Boundary clock','Precision Time Protocol','Variable latency','AES67','Grandmaster clock','Jitter']::text[],ARRAY['Assuming any switch works for PTP; a switch that is not PTP-aware adds uncorrected variable delay.','Confusing a transparent clock with a boundary clock, which regenerates timing instead of just correcting for its own delay.','Mixing end-to-end and peer-to-peer transparent clocks on one PTP path, which breaks the delay math.']::text[],ARRAY['Specifying network switches for a Dante or AES67 audio-over-IP install.','Troubleshooting sync dropouts caused by a non-PTP-aware switch in the path.','Designing a large venue audio network where many hops must stay time-aligned.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transparent clocks');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4dec7db-6667-4a23-808b-9c7d370a178a','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4dec7db-6667-4a23-808b-9c7d370a178a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4dec7db-6667-4a23-808b-9c7d370a178a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73a885fa-df40-4e66-8032-2bb09d49c263','Trigonometric functions','Trigonometric functions (sine, cosine, tangent and their reciprocals) relate the angles of a right triangle to ratios of its side lengths and, extended to the unit circle, describe periodic oscillation. Sine and cosine model the instantaneous value of a single-frequency (sinusoidal) signal versus time or phase angle.','Trig functions like sine and cosine link an angle to a ratio of triangle sides. Extended to a circle, they repeat in smooth cycles. Sine and cosine describe how a pure tone rises and falls over time. That makes them the math behind waveforms and phase.','They give a precise way to describe periodic motion, so any steady tone can be written, added, and analyzed as sine and cosine parts.','For a sine wave, instantaneous voltage v = V_peak.sin(2.pi.f.t); at f = 1 kHz, V_peak = 1 V, and t = 0.25 ms, v = sin(pi/2) = 1 V, the peak value.','Mathematics',ARRAY['Sine wave','Phase','Vectors','Frequency','Radian','Fourier analysis']::text[],ARRAY['Working in degrees when the formula, calculator, or DSP function expects radians.','Confusing amplitude (the multiplier) with frequency (inside the angle) in v = A.sin(2.pi.f.t).','Forgetting that tangent is undefined where cosine is zero (90 and 270 degrees).']::text[],ARRAY['Writing the equation of a test-tone waveform.','Adding two same-frequency signals to find the combined level and phase.','Understanding how phase angle shifts a sine wave in time.']::text[],'Intermediate','sin(theta) = opposite / hypotenuse;  cos(theta) = adjacent / hypotenuse;  tan(theta) = sin(theta) / cos(theta)','In a right triangle, the sine of an angle equals the opposite side divided by the hypotenuse, the cosine equals the adjacent side divided by the hypotenuse, and the tangent equals the sine divided by the cosine.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Trigonometric functions');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73a885fa-df40-4e66-8032-2bb09d49c263','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73a885fa-df40-4e66-8032-2bb09d49c263') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73a885fa-df40-4e66-8032-2bb09d49c263');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '33784c47-8b0b-4572-b446-c6ec8d45ce8e','Unbalanced signaling','Unbalanced signaling carries an audio signal on a single conductor referenced to a shared ground/shield, using a two-conductor connection such as a TS phone or RCA jack. Because the return path is also the shield, noise coupled onto the cable is not cancelled, so unbalanced runs are kept short.','An unbalanced connection sends audio on one wire, with the shield as the return. It uses two-contact plugs like RCA or TS. Noise picked up along the cable is not cancelled out. So unbalanced cables should stay short, usually a few meters.','It is a simple, low-cost way to connect nearby line- or instrument-level gear where cable runs are short and interference is limited.','A technician links a pedalboard to an amp with a short TS instrument cable, but switches to balanced cabling for any run longer than a few meters to avoid hum and buzz.','Signal Transmission',ARRAY['Balanced signaling','Ground loop','Shield','TS connector','Common-mode rejection','Line level']::text[],ARRAY['Running long unbalanced cables, then blaming the gear for the resulting hum and buzz.','UNSAFE: Lifting the safety/AC ground to silence a ground-loop hum on unbalanced gear removes shock protection and can be lethal; use a proper ground-loop isolator instead.','Assuming a TRS plug is always balanced; it may carry unbalanced stereo (tip/ring/sleeve).','Expecting unbalanced connections to reject noise the way balanced lines do.']::text[],ARRAY['Connecting consumer RCA sources to a mixer.','Wiring a short instrument-to-amp link on stage.','Diagnosing hum introduced by a long unbalanced cable run.']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Unbalanced signaling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '33784c47-8b0b-4572-b446-c6ec8d45ce8e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='33784c47-8b0b-4572-b446-c6ec8d45ce8e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='33784c47-8b0b-4572-b446-c6ec8d45ce8e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9b310274-29df-4479-b5fc-98b05e5518b2','Under-balcony fills','Under-balcony fill loudspeakers are small speakers mounted beneath a balcony overhang to cover seats shadowed from the main system by the balcony soffit. They are usually time-delayed to align with sound arriving from the main array, so the two blend without a distinct echo.','A balcony overhang blocks main-system sound from the seats beneath it. Under-balcony fills are small speakers that cover those shadowed seats. They are delayed so their sound lines up with the main system. This keeps speech clear and avoids a double-sound echo.','They restore even coverage and intelligibility for listeners the main loudspeakers cannot reach because the balcony physically blocks the direct sound.','A technician measures the distance from the main array to the under-balcony area, sets the fills'' delay to match that arrival time (about 2.9 ms per meter), then trims level so the fills reinforce without drawing attention.','Sound Reinforcement',ARRAY['Delay speakers','Coverage','Uniformity','Haas effect','Fill loudspeaker','Time alignment']::text[],ARRAY['Skipping the delay, so the fill sound arrives early and is heard as a separate, distracting source.','Setting fill level too high, which pulls listeners'' attention down to the nearby speaker.','Ignoring under-balcony seats entirely, leaving them with dull, muffled sound.']::text[],ARRAY['Designing coverage for a theater with a deep balcony.','Commissioning a house of worship with rear seating under an overhang.','Tuning delay times during system alignment.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Under-balcony fills');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9b310274-29df-4479-b5fc-98b05e5518b2','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9b310274-29df-4479-b5fc-98b05e5518b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9b310274-29df-4479-b5fc-98b05e5518b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '41bf35cf-3727-4d48-a275-d66889d63e8d','Unicast','Unicast is one-to-one network delivery, in which a packet carries a single destination address and is routed to exactly one receiver. In audio-over-IP it means a separate stream is sent per subscriber, so required bandwidth scales with the number of receivers.','Unicast sends data to one specific device. Each packet has one destination address. To reach many receivers, the sender makes a separate copy for each one. So bandwidth rises as you add more listeners.','It provides direct, addressed delivery to a single endpoint, which is simple and routable, but it is inefficient when the same audio must reach many devices at once.','A technician using Dante may pick unicast for a couple of receivers on a stream, but switches to multicast when many devices need the same channel, to avoid flooding the switch uplink.','Networking',ARRAY['Multicast','Broadcast','IP address','Dante','AES67','Bandwidth']::text[],ARRAY['Assuming unicast and multicast use the same bandwidth; unicast duplicates the stream per receiver.','Using unicast for a one-to-many distribution, then running out of switch or uplink bandwidth.','Confusing unicast (one destination) with broadcast (every device on the subnet).']::text[],ARRAY['Choosing flow type when routing Dante audio channels.','Sizing network bandwidth for a multi-receiver install.','Explaining why adding receivers increased traffic on a unicast stream.']::text[],'Beginner',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Unicast');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '41bf35cf-3727-4d48-a275-d66889d63e8d','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='41bf35cf-3727-4d48-a275-d66889d63e8d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='41bf35cf-3727-4d48-a275-d66889d63e8d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d028aac-e33f-4d8c-9062-cdb68c8c301e','Uniformity','Coverage uniformity is the degree to which sound pressure level and tonal balance stay consistent across a listening area. It is commonly expressed as the variation in decibels between the loudest and quietest covered seats at a given frequency or band, with smaller variation indicating more uniform coverage.','Uniformity means the sound is about equally loud everywhere in the audience. Techs measure the level at many seats. The gap between the loudest and quietest seat, in decibels, shows how uniform it is. A smaller gap means more even coverage.','It sets a design and tuning goal so every listener hears a similar level and tone, not just people near or on-axis to the speakers.','A technician maps sound pressure level at several audience positions; if front-to-back varies by 9 dB, they add delay fills or adjust array splay to bring the spread nearer a plus-or-minus 3 dB target.','Sound Reinforcement',ARRAY['Coverage','Under-balcony fills','Sound pressure level','Directivity','Array','Direct-to-reverberant ratio']::text[],ARRAY['Judging uniformity by ear at one seat instead of measuring several positions.','Chasing perfectly flat coverage and over-processing, when a small, smooth level taper is normal.','Measuring only broadband level and missing tonal, frequency-dependent unevenness.']::text[],ARRAY['Evaluating a design''s predicted coverage in modeling software.','Walking the room with a level meter during commissioning.','Deciding whether delay fills are needed for the back rows.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Uniformity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d028aac-e33f-4d8c-9062-cdb68c8c301e','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d028aac-e33f-4d8c-9062-cdb68c8c301e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d028aac-e33f-4d8c-9062-cdb68c8c301e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e55e5187-9adb-492c-b441-3cd952ae5d8c','Variable latency','Variable latency is delay through a system or network that changes over time rather than staying fixed. In packet networks this jitter arises from queuing, buffering, and routing differences; in audio it can disrupt clock sync and lip-sync unless buffers or timing protocols compensate.','Latency is the delay a signal takes to get through a system. Variable latency means that delay keeps changing. In networks it comes from queuing and buffering. It must be smoothed out, or audio timing and sync suffer.','Recognizing it matters because unstable delay, not just its average, is what causes clicks, dropouts, and loss of synchronization in networked audio.','A technician sets a Dante device''s latency (for example 1 ms) large enough to absorb the network''s worst-case jitter, trading a little extra fixed delay for glitch-free, stable playback.','Networking / Timing',ARRAY['Latency','Jitter','Buffer','Transparent clocks','Precision Time Protocol','Packet loss']::text[],ARRAY['Setting the device latency/buffer too low to save delay, causing dropouts when jitter spikes.','Confusing constant latency (a fixed offset) with variable latency (jitter).','Blaming the audio hardware when heavy non-audio traffic on the switch is the real cause.']::text[],ARRAY['Tuning buffer/latency settings on an audio network.','Diagnosing intermittent clicks on a busy shared network.','Deciding whether a network is stable enough for live audio.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Variable latency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e55e5187-9adb-492c-b441-3cd952ae5d8c','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e55e5187-9adb-492c-b441-3cd952ae5d8c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e55e5187-9adb-492c-b441-3cd952ae5d8c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d120bdb-b689-45e7-970c-ce696e9b0bc4','Variance','Variance is a measure of statistical spread equal to the mean of the squared deviations of values from their average. Its positive square root is the standard deviation, and in audio it underlies noise power, averaging, and measurement repeatability.','Variance shows how spread out a set of numbers is. You find each value''s distance from the average, square it, then take the mean of those squares. A bigger variance means more scatter. Its square root is the standard deviation.','It quantifies how much data varies, letting technicians describe noise, judge measurement stability, and know how much averaging is needed.','For readings 4, 5, 6 dB, the mean is 5; deviations are -1, 0, +1; squared they are 1, 0, 1. Treating these three readings as the complete population, divide by N = 3: variance = 2/3 = 0.67, so standard deviation = 0.82 dB. For a sample estimate you would instead divide by N minus 1.','Statistics',ARRAY['Standard deviation','Mean','Averaging','Vector averaging','Signal-to-noise ratio','RMS']::text[],ARRAY['Forgetting to square the deviations, or forgetting to average them.','Mixing up variance (squared units) with standard deviation (original units).','Using the population divisor N when a sample estimate needs N minus 1.']::text[],ARRAY['Reporting how much repeated level readings scatter.','Deciding how many averages an FFT measurement needs.','Comparing the stability of two noise sources.']::text[],'Intermediate','sigma^2 = (1/N) . sum( (x_i - mu)^2 )','Variance equals the average, over all N values, of the squared difference between each value x_i and the mean mu.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Variance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d120bdb-b689-45e7-970c-ce696e9b0bc4','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d120bdb-b689-45e7-970c-ce696e9b0bc4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d120bdb-b689-45e7-970c-ce696e9b0bc4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9186d2ce-0c7b-46cb-8bd6-f38a13c342e7','Vector averaging','Vector (complex, or coherent) averaging combines repeated frequency-domain measurements by averaging the real and imaginary parts, i.e. magnitude and phase, of each spectral bin. Signal components that are stable in phase add up, while random noise (with random phase) tends to cancel, improving signal-to-noise for a synchronous signal; power (RMS) averaging instead discards phase.','Vector averaging adds up repeated FFT measurements using both level and phase. A steady signal keeps the same phase, so it builds up. Random noise has random phase, so it cancels out. This pulls a repeatable signal out of the noise. Power averaging, by contrast, ignores phase.','It improves measurement signal-to-noise for a signal that is synchronous and phase-stable with the measurement, revealing detail that random-noise power averaging leaves buried.','Measuring a loudspeaker with a repeatable stimulus, a technician uses vector averaging so uncorrelated room noise averages toward zero; power averaging is chosen for random signals like pink noise where phase is not stable.','Measurement',ARRAY['Power averaging','FFT','Coherence','Phase','Vectors','Signal-to-noise ratio']::text[],ARRAY['Using vector averaging on a random signal not synchronized to the measurement, which cancels the signal itself.','Confusing vector (complex) averaging with RMS/power averaging, which keeps only magnitude.','Forgetting that vector averaging needs a stable trigger or phase reference between averages.']::text[],ARRAY['Choosing an averaging mode in FFT analysis software.','Pulling a repeatable impulse response out of a noisy room.','Explaining why phase-stable signals average differently from noise.']::text[],'Advanced','X_avg(f) = (1/N) . sum_{k=1..N} X_k(f)   (complex sum)','The vector average at each frequency is the complex sum of the N individual spectra, divided by N, keeping both magnitude and phase.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vector averaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9186d2ce-0c7b-46cb-8bd6-f38a13c342e7','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9186d2ce-0c7b-46cb-8bd6-f38a13c342e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9186d2ce-0c7b-46cb-8bd6-f38a13c342e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31042989-ccc9-4c63-ac5e-682621332881','Vectors','A vector is a quantity with both magnitude and direction, represented as an arrow or as components along axes. In audio a signal''s amplitude and phase at a frequency form a vector (a phasor), and vectors are added tip-to-tail, or by components, to find the combined result of two signals.','A vector has both a size and a direction. You can draw it as an arrow or list its parts along each axis. In audio, a signal''s level and phase act like a vector. Adding vectors shows how two signals combine.','Vectors give a compact way to handle direction-and-size quantities, so magnitude and phase can be combined correctly instead of just adding levels.','Two equal signals in phase add tip-to-tail to double the amplitude (+6 dB); the same two signals 180 degrees out of phase point opposite ways and cancel to zero.','Mathematics',ARRAY['Vector averaging','Phasor','Phase','Trigonometric functions','Magnitude','Complex number']::text[],ARRAY['Adding only magnitudes and ignoring direction or phase when combining signals.','Confusing a vector (magnitude and direction) with a scalar (magnitude only).','Forgetting that two out-of-phase vectors can partly or fully cancel.']::text[],ARRAY['Working out how two arrivals combine at a mic position.','Understanding phasor diagrams of level and phase.','Learning the math behind constructive and destructive interference.']::text[],'Beginner','|v| = sqrt(x^2 + y^2);  v = (x, y)','A two-dimensional vector has components x and y; its magnitude is the square root of the sum of the squares of its components.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vectors');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31042989-ccc9-4c63-ac5e-682621332881','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31042989-ccc9-4c63-ac5e-682621332881') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31042989-ccc9-4c63-ac5e-682621332881');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '43d4bbf5-5149-4117-b8fc-bb4a74bd838d','Virtual local area networks','A virtual local area network (VLAN) is a logically separated broadcast domain within a physical switched network, defined per IEEE 802.1Q by a 12-bit VLAN identifier (VID) carried in a 4-byte tag (TPID 0x8100) inserted in the Ethernet frame. Valid VIDs run 1 to 4094 (0 and 4095 reserved), letting one physical switch carry several isolated networks.','A VLAN splits one physical network into separate logical networks. Devices in different VLANs cannot talk directly, as if on separate switches. A tag added to each frame marks which VLAN it belongs to. The IEEE 802.1Q standard defines this tag.','VLANs isolate traffic for security, management, and performance, for example keeping audio, control, and office data apart on shared switches without running separate cabling.','A technician puts Dante audio on one VLAN and control/office traffic on another, so non-audio broadcast traffic cannot flood the audio devices while both share the same physical switches.','Networking',ARRAY['Local area network','Unicast','Multicast','Switch','Quality of Service','Broadcast domain']::text[],ARRAY['Assuming devices in different VLANs can reach each other without a router or Layer-3 device.','Forgetting to tag (trunk) the uplink ports, so VLAN traffic does not pass between switches.','Placing PTP/audio and heavy data traffic in the same VLAN and causing timing problems.']::text[],ARRAY['Segmenting audio from office traffic on a shared corporate network.','Configuring trunk ports between switches in a large install.','Isolating a control network for security.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Virtual local area networks');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '43d4bbf5-5149-4117-b8fc-bb4a74bd838d','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='43d4bbf5-5149-4117-b8fc-bb4a74bd838d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='43d4bbf5-5149-4117-b8fc-bb4a74bd838d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fbcf7af5-4bf4-4296-a5cd-1fb57d6926dd','Voltage sensitivity','Voltage sensitivity expresses a transducer''s output, or output level, relative to a reference voltage rather than power. For a loudspeaker it is the sound pressure level at 1 m for a standard 2.83 V RMS drive (equal to 1 W into 8 ohms); for a microphone it is the open-circuit output voltage per pascal of sound pressure, e.g. mV/Pa or dBV re 1 V/Pa.','Sensitivity says how much output you get for a given drive. Voltage sensitivity uses a fixed voltage as the reference, not watts. A loudspeaker''s is the loudness at one meter for 2.83 volts. A microphone''s is the voltage it puts out per unit of sound pressure.','Referencing sensitivity to voltage lets technicians compare devices fairly regardless of impedance, since 2.83 V, or 1 V/Pa, is a fixed drive that does not depend on the load''s ohms.','A speaker rated 90 dB SPL at 2.83 V and 1 m reads about 90 dB at 1 m on that drive; doubling the distance to 2 m drops it roughly 6 dB to about 84 dB.','Measurement / Transducers',ARRAY['Sensitivity','Sound pressure level','Impedance','Microphone','Loudspeaker','dBV']::text[],ARRAY['Treating a 2.83 V rating on a 4-ohm speaker as if it were 1 W; at 4 ohms, 2.83 V is 2 W.','Confusing loudspeaker sensitivity (SPL out) with microphone sensitivity (voltage out).','Ignoring the reference distance (1 m) when comparing SPL sensitivities.']::text[],ARRAY['Comparing loudspeaker efficiency from spec sheets.','Estimating amplifier power needed for a target SPL.','Reading a microphone''s mV/Pa rating when setting preamp gain.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voltage sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fbcf7af5-4bf4-4296-a5cd-1fb57d6926dd','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fbcf7af5-4bf4-4296-a5cd-1fb57d6926dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fbcf7af5-4bf4-4296-a5cd-1fb57d6926dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '68f4ec3a-4856-4217-b2ba-6ac68f2735a6','Voltage-divider effects','The voltage-divider effect is the reduction of signal voltage when a source''s output impedance and the load impedance form a series divider: the load sees only the fraction of the source voltage set by the ratio of load impedance to total (source plus load) impedance. In audio, low source and high load impedances (voltage/impedance bridging) keep this loss small.','Every source has some output impedance, and every load has input impedance. Together they act like a two-resistor divider. The load only gets part of the source''s voltage. To lose almost nothing, the load impedance should be much higher than the source impedance.','Understanding it explains why audio gear is voltage-bridged (low output, high input impedance), so signals transfer with minimal level loss and predictable response.','With a 600-ohm source feeding a 10 k-ohm input, V_out/V_in = 10000/(600+10000) = 0.943, a loss of about 0.5 dB; a 600-ohm load instead gives 0.5, a 6 dB loss.','Circuit Theory',ARRAY['Impedance','Impedance bridging','Output impedance','Input impedance','Loading','Ohm''s law']::text[],ARRAY['Assuming a connection transfers full voltage; every load forms a divider with the source impedance.','Trying to impedance-match (equal impedances) line-level audio, which halves the voltage and loses 6 dB.','Ignoring cumulative loss when paralleling several inputs across one output.']::text[],ARRAY['Explaining why a mic or pickup sounds dull into a low-impedance input.','Choosing a distribution amp instead of paralleling many inputs.','Understanding impedance bridging versus matching in analog audio.']::text[],'Intermediate','V_out = V_in . Z_L / (Z_S + Z_L)','The output voltage equals the source voltage times the load impedance, divided by the sum of the source and load impedances.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voltage-divider effects');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '68f4ec3a-4856-4217-b2ba-6ac68f2735a6','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='68f4ec3a-4856-4217-b2ba-6ac68f2735a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='68f4ec3a-4856-4217-b2ba-6ac68f2735a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9372f1d0-074d-445c-afd6-907c72b83460','Wavelet spectrogram','A wavelet spectrogram (scalogram) is a time-frequency display produced by the continuous wavelet transform, which correlates a signal with scaled and shifted copies of a short mother wavelet. Unlike the fixed resolution of a short-time Fourier transform (STFT) spectrogram, it gives fine time resolution at high frequencies and fine frequency resolution at low frequencies.','A spectrogram shows how a signal''s frequencies change over time. A wavelet spectrogram builds this using small, stretchable wave shapes instead of fixed windows. It sees fast events sharply at high frequencies. It sees pitch clearly at low frequencies. This flexible detail is its main advantage.','It gives a multi-resolution time-frequency view, so short transients and low-frequency detail can both be seen clearly in one picture.','Examining a transient click or a gunshot recording, an analyst uses a scalogram to pinpoint the sharp onset''s timing while still resolving low-frequency content the STFT would smear.','Signal Analysis',ARRAY['Spectrogram','Short-time Fourier transform','Wavelet transform','Time-frequency analysis','Transient','Windowing an impulse response']::text[],ARRAY['Reading the vertical axis as linear frequency; scalograms use scale, which maps non-linearly to frequency.','Expecting uniform resolution like an STFT; wavelet resolution changes with frequency.','Assuming any wavelet works; the mother wavelet choice changes which features stand out.']::text[],ARRAY['Analyzing sharp transients in forensic audio.','Studying how a percussive sound''s spectrum evolves.','Comparing wavelet and STFT views of the same signal.']::text[],'Advanced',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wavelet spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9372f1d0-074d-445c-afd6-907c72b83460','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9372f1d0-074d-445c-afd6-907c72b83460') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9372f1d0-074d-445c-afd6-907c72b83460');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8dc09da0-b194-435f-9f7f-6cbda4509d24','Wind effects','Wind affects outdoor audio in two main ways. Turbulent airflow at a microphone creates broadband low-frequency wind noise (pressure fluctuations at the diaphragm, not true acoustic signal), reduced by windscreens. Vertical wind-speed gradients also refract sound, bending it downward downwind (aiding propagation) and upward upwind (creating a shadow zone), altering levels over distance.','Wind causes two problems outdoors. Air hitting a microphone makes low rumble that is not real sound. A windscreen cuts this noise. Wind also bends sound as it travels. It curves sound down when blowing toward you and up when blowing away. This changes how far sound carries.','Knowing wind effects lets technicians protect microphones from false low-frequency noise and predict how outdoor level and coverage change with wind direction.','For an outdoor shoot or measurement, a technician fits a foam or furry windscreen to keep wind noise out of the recording, and expects a listener upwind of a stage to hear less level than one the same distance downwind.','Acoustics / Measurement',ARRAY['Windscreen','Outdoor sound propagation','Refraction','Shadow zone','Low-frequency noise','Temperature gradient']::text[],ARRAY['Treating wind noise as real bass and trying to EQ it out instead of using a windscreen.','Forgetting that wind gradients, not just distance, change outdoor levels.','Assuming a small foam windscreen is enough in strong wind; a furry or basket type is often needed.','Ignoring wind when taking outdoor sound-level measurements, which the standard limits.']::text[],ARRAY['Recording dialogue or nature sound outdoors.','Taking environmental noise measurements in wind.','Predicting coverage differences at an outdoor concert with steady wind.']::text[],'Intermediate',NULL,NULL,'2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wind effects');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8dc09da0-b194-435f-9f7f-6cbda4509d24','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8dc09da0-b194-435f-9f7f-6cbda4509d24') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8dc09da0-b194-435f-9f7f-6cbda4509d24');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd86a3dcc-7dba-4cf5-b5c9-012b1c59a266','Windowing an impulse response','Windowing (time-gating) an impulse response means multiplying a measured impulse response by a time window that keeps the direct-sound arrival and early portion while tapering later samples to zero, removing room reflections. The windowed impulse response yields a quasi-anechoic frequency response, but the window length sets the lowest reliable frequency, roughly the reciprocal of the window duration.','A measured impulse response contains the direct sound plus room reflections. Windowing keeps the early direct part and fades out the reflections. The result acts like an echo-free measurement. But a shorter window loses low-frequency detail. The lowest usable frequency is about one over the window length.','It lets a technician measure a loudspeaker''s own response inside a normal room by excluding reflections, without needing an anechoic chamber.','With a reflection arriving 5 ms after the direct sound, a technician ends the window just before 5 ms; that roughly 5 ms window makes results valid only above about 200 Hz (1 divided by 0.005 s).','Measurement / DSP',ARRAY['Impulse response','Quasi-anechoic measurement','Time gating','Window function','Reflection','Frequency response']::text[],ARRAY['Trusting low-frequency data below 1 over the window length; that range is not valid after gating.','Setting the gate after a strong reflection, so the reflection contaminates the response.','Using a hard rectangular cutoff that adds ripple; a tapered window edge is cleaner.','Confusing impulse-response time-windowing with FFT input windowing, though both use window functions.']::text[],ARRAY['Measuring a loudspeaker''s direct response in a reflective room.','Setting a gate time in acoustic measurement software.','Deciding the valid frequency range of a quasi-anechoic measurement.']::text[],'Advanced','f_min ~= 1 / T_window','The lowest reliably measured frequency is about one divided by the length of the time window in seconds.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Windowing an impulse response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd86a3dcc-7dba-4cf5-b5c9-012b1c59a266','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d86a3dcc-7dba-4cf5-b5c9-012b1c59a266') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d86a3dcc-7dba-4cf5-b5c9-012b1c59a266');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '002c5930-9fea-4d2b-b437-6e3e184b7cfe','Z-transforms','The Z-transform maps a discrete-time sequence x[n] into a function X(z) of the complex variable z, defined as the sum of x[n] times z to the power minus n. It is the discrete-time counterpart of the Laplace transform and the core tool for analyzing digital filters, where pole and zero locations in the z-plane (relative to the unit circle) set stability and frequency response.','The Z-transform turns a digital signal or filter into a formula in a complex variable z. It is the discrete-time version of the Laplace transform. Engineers use it to design and analyze digital filters. Where its poles and zeros sit shows how the filter behaves and whether it is stable.','It provides a compact algebra for discrete systems, turning convolution into multiplication and revealing filter stability and frequency response from pole and zero positions.','A designer writing a digital filter''s transfer function H(z) checks that all poles lie inside the unit circle (|z| < 1) to guarantee the filter is stable before implementing it.','DSP Mathematics',ARRAY['Discrete-time signal','Digital filter','Transfer function','Poles and zeros','Laplace transform','Unit circle']::text[],ARRAY['Ignoring the region of convergence, which is needed to invert X(z) uniquely.','Assuming poles on or outside the unit circle are fine; that makes an IIR filter unstable.','Confusing z (a complex variable) with only a one-sample delay symbol.','Mixing up the Z-transform with the discrete Fourier transform, a sampled special case on the unit circle.']::text[],ARRAY['Designing or analyzing a digital IIR filter.','Checking filter stability from pole locations.','Relating a difference equation to its frequency response.']::text[],'Advanced','X(z) = sum_{n=-inf..inf} x[n] . z^(-n)','The Z-transform of a sequence is the sum, over all sample indices n, of each sample x[n] multiplied by z raised to the power minus n.','2db4060a-e6e7-4745-b913-33fc37deee4d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Z-transforms');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '002c5930-9fea-4d2b-b437-6e3e184b7cfe','2db4060a-e6e7-4745-b913-33fc37deee4d',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='002c5930-9fea-4d2b-b437-6e3e184b7cfe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='002c5930-9fea-4d2b-b437-6e3e184b7cfe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99ad756e-4c0e-4777-9814-e09af1ee214d','Acoustic compression','The progressive fall of a loudspeaker''s acoustic output below the level a linear system would produce as drive power increases, caused mainly by voice-coil heating that raises the coil''s resistance and reduces the current it draws. It is expressed in decibels as the shortfall between measured output and the expected linear output at a given input power.','Push more power into a speaker and its output should rise the same amount. It does not, once the voice coil gets hot. The hot coil resists current, so the speaker gets quieter than expected. This lost loudness is called acoustic, or power, compression.','It quantifies how much a driver loses sensitivity under real high-power use, which matters for predicting maximum sound level and thermal behavior in sound-reinforcement systems.','A technician measures sensitivity at low power, then at high power; if a 10 dB power increase yields only 8 dB more output, the driver shows 2 dB of power compression.','Loudspeaker Measurement',ARRAY['Compression-limited output','Continuous power handling','Crest-factor degradation','Distortion-limited output','Burst SPL']::text[],ARRAY['Confusing acoustic (power) compression with dynamic-range compression from a signal processor; they are unrelated effects.','Assuming output rises decibel-for-decibel with input power at all levels.','Ignoring voice-coil temperature, which is the main driver of the effect.']::text[],ARRAY['Predicting the real maximum SPL of a touring line-array element at rated power.','Explaining why a PA sounds less dynamic during sustained loud passages.','Comparing driver datasheets that list power-compression figures at rated power.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99ad756e-4c0e-4777-9814-e09af1ee214d','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99ad756e-4c0e-4777-9814-e09af1ee214d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99ad756e-4c0e-4777-9814-e09af1ee214d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '02a2e1c5-a79b-4135-a0e2-c4c827817de3','Acoustic holography','A measurement and reconstruction technique in which the sound pressure sampled over a surface (the hologram plane), often in the near field of a source, is transformed to reconstruct the full three-dimensional sound field, including pressure, particle velocity, and intensity on other surfaces. Near-field acoustical holography uses the spatial Fourier transform of near-field pressure to recover both propagating and evanescent field components.','Microphones sample the sound close to a vibrating object across a grid. Math then rebuilds the whole sound field around it. This shows where sound comes from and how it flows. Engineers use it to map noise sources on machines and speakers.','It lets engineers locate and visualize sound sources and radiation patterns on a vibrating body, supporting noise-source identification and loudspeaker or machinery diagnostics.','A technician scans a microphone array over a device''s surface, then software back-propagates the data to produce a color map showing which panels radiate the most sound.','Acoustic Measurement',ARRAY['Active intensity','Acoustic-power determination','Anechoic measurement','Complex frequency response','Acoustical metrology']::text[],ARRAY['Believing a single microphone at one point can map a full field; holography needs spatial sampling.','Sampling too coarsely, so the spatial detail (evanescent waves) is lost.','Measuring too far from the source, which discards the near-field information the method relies on.']::text[],ARRAY['Mapping which parts of a loudspeaker cabinet radiate unwanted panel resonances.','Identifying dominant noise sources on an engine or appliance in R&D.','Visualizing the radiation pattern of a musical instrument.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic holography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '02a2e1c5-a79b-4135-a0e2-c4c827817de3','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='02a2e1c5-a79b-4135-a0e2-c4c827817de3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='02a2e1c5-a79b-4135-a0e2-c4c827817de3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9a4d78d7-9a29-4434-b3cd-82d14c600d6e','Acoustic-power determination','The measurement of the total sound power radiated by a source, expressed as a sound power level in decibels referenced to one picowatt (1 pW). It is found either by integrating sound intensity over a surface enclosing the source, or by measuring sound pressure over such a surface in a qualified reverberation or anechoic environment and applying the standardized environmental corrections.','Sound power is the total acoustic energy a source sends out each second. Unlike sound pressure, it does not depend on where you listen. Engineers measure it in special rooms or with intensity probes. It rates how loud a machine or speaker truly is.','It gives a single, room-independent rating of how much acoustic energy a device emits, used for noise labeling of products and for comparing sources fairly.','Integrating a measured intensity of 1 mW/m-squared over a 0.1 m-squared enclosing surface gives 0.1 mW of sound power; that is a sound power level of about 80 dB re 1 pW.','Acoustic Measurement',ARRAY['Active intensity','Anechoic-room method','Comparison method','Acoustical metrology','Acoustic holography']::text[],ARRAY['Confusing sound power (source property, watts) with sound pressure (level at a point, pascals).','Reporting a sound power level without stating the reference of 1 picowatt.','Measuring in an unqualified room without the required environmental correction.']::text[],ARRAY['Producing a noise-emission label for a piece of equipment.','Comparing the total output of two fans or motors independently of the test room.','Rating a loudspeaker''s total radiated power in a reverberation chamber.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-power determination');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9a4d78d7-9a29-4434-b3cd-82d14c600d6e','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9a4d78d7-9a29-4434-b3cd-82d14c600d6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9a4d78d7-9a29-4434-b3cd-82d14c600d6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a29d42d1-9211-489e-a7dd-f48935d80c0f','Acoustical metrology','The branch of metrology concerned with acoustic and vibration measurement, covering the definition and realization of acoustic units, the calibration of transducers and instruments, and the traceability of measurements to national and international standards. It underpins the accuracy and uncertainty statements of all acoustic measurements.','Metrology is the science of measurement. Acoustical metrology applies it to sound and vibration. It sets the way we calibrate microphones and meters. It links each result back to a trusted national standard.','It ensures acoustic measurements made in different places and times are accurate, comparable, and traceable to recognized reference standards.','A technician sends a measurement microphone to an accredited lab so its sensitivity is calibrated against a primary standard, giving a traceable correction for field use.','Measurement Science',ARRAY['Calibration hierarchy','Calibration correction','Combined standard uncertainty','Acoustic-power determination','Coverage factor']::text[],ARRAY['Treating any calibration as traceable without an unbroken chain to a national standard.','Reporting measurements without an associated uncertainty.','Assuming a factory calibration remains valid indefinitely with no recalibration interval.']::text[],ARRAY['Setting up a calibration schedule for a fleet of sound level meters.','Explaining why lab results carry stated uncertainties.','Auditing a test facility for traceable measurement practice.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustical metrology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a29d42d1-9211-489e-a7dd-f48935d80c0f','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a29d42d1-9211-489e-a7dd-f48935d80c0f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a29d42d1-9211-489e-a7dd-f48935d80c0f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a89c892d-5dba-4771-b748-8510ab0425ed','Active intensity','The real, time-averaged part of the sound intensity vector, equal to the mean of the product of instantaneous sound pressure and instantaneous acoustic particle velocity, representing the net flow of acoustic energy per unit area. It is expressed in watts per square metre and is the component that carries energy away from a source.','Sound intensity is the flow of sound energy. It moves through an area. Active intensity is the part that carries energy away. It equals the average of pressure times particle velocity. Engineers measure it to find where sound energy goes.','It identifies genuine net energy flow, distinguishing radiating sources from purely reactive near-field oscillation, and is the basis for intensity-based sound power measurement.','A two-microphone intensity probe estimates particle velocity from the pressure difference; multiplying by mean pressure and averaging yields the active intensity in watts per square metre.','Acoustic Measurement',ARRAY['Acoustic-power determination','Acoustic holography','Complex frequency response','Coherence degradation','Acoustical metrology']::text[],ARRAY['Confusing active intensity with reactive intensity, which stores energy and carries none away on average.','Forgetting that intensity is a vector with direction, not just a magnitude.','Using a single microphone; particle velocity needs a pressure gradient from two microphones.']::text[],ARRAY['Mapping energy flow to locate a leak in a noise enclosure.','Measuring sound power in situ without an anechoic room.','Separating a target source from background noise by energy direction.']::text[],'Advanced','I_a = <p(t) * u(t)>','Active intensity equals the time average of instantaneous sound pressure multiplied by instantaneous acoustic particle velocity.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Active intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a89c892d-5dba-4771-b748-8510ab0425ed','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a89c892d-5dba-4771-b748-8510ab0425ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a89c892d-5dba-4771-b748-8510ab0425ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd3d50b83-bd12-4eb3-aebf-dfbcbacff7c7','Anechoic measurement','A measurement made under free-field conditions, in which the surroundings absorb essentially all reflected sound so that only the direct sound from the source reaches the microphone. It is typically performed in an anechoic chamber to obtain the intrinsic frequency response, directivity, or radiated power of a device without room influence.','An anechoic measurement captures only the sound coming straight from the source. The room absorbs almost all reflections. That removes echoes that would color the result. It reveals the true response of a microphone or speaker.','It isolates a device''s own behavior from room effects, giving repeatable free-field data for frequency response, directivity, and sensitivity.','A technician places a loudspeaker in an anechoic chamber and sweeps a test tone; the microphone captures the direct response with no reflections to distort the measured curve.','Acoustic Measurement',ARRAY['Anechoic-room method','Complex frequency response','Acoustic-power determination','Burst SPL','Comparison method']::text[],ARRAY['Assuming a room is anechoic below its cutoff frequency, where the absorbers stop working well.','Placing the microphone too close, so near-field effects distort the free-field reading.','Confusing an anechoic chamber with a merely quiet or sound-isolated room.']::text[],ARRAY['Measuring a studio microphone''s on-axis frequency response.','Characterizing a loudspeaker''s directivity for a data sheet.','Comparing headphones or drivers under repeatable free-field conditions.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Anechoic measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd3d50b83-bd12-4eb3-aebf-dfbcbacff7c7','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d3d50b83-bd12-4eb3-aebf-dfbcbacff7c7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d3d50b83-bd12-4eb3-aebf-dfbcbacff7c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '65ce3553-aef6-4c3a-ab3b-fd747782239a','Anechoic-room method','A standardized procedure for determining a source''s sound power or free-field response by measuring sound pressure at prescribed microphone positions on a surface enclosing the source inside a qualified anechoic or hemi-anechoic room. The room''s free-field qualification and the geometry of the measurement surface are defined so the result meets a stated accuracy grade.','This is a set method for measuring in an anechoic room. Microphones sit at fixed points around the source. The room must first pass a free-field check. Following the steps gives an accurate, repeatable sound power result.','It provides a precision-grade, repeatable way to obtain sound power and free-field data by fixing the room qualification, microphone positions, and calculations.','A technician positions microphones on a hemisphere around a source per the standard, averages the measured levels, and adds the surface-area term to compute the sound power level.','Acoustic Measurement',ARRAY['Anechoic measurement','Acoustic-power determination','Comparison method','Acoustical metrology','Complex frequency response']::text[],ARRAY['Skipping the room''s free-field qualification before trusting results.','Using too few microphone positions for the required accuracy grade.','Applying the full-space formula in a hemi-anechoic (half-space) setup.']::text[],ARRAY['Certifying a product''s sound power for a noise-emission declaration.','Running precision-grade loudspeaker measurements in a qualified chamber.','Comparing measured directivity to a manufacturer specification.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Anechoic-room method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '65ce3553-aef6-4c3a-ab3b-fd747782239a','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='65ce3553-aef6-4c3a-ab3b-fd747782239a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='65ce3553-aef6-4c3a-ab3b-fd747782239a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e45c97be-a327-45b3-b7d7-7e39ab5eb333','Bicoherence','A normalized measure derived from the bispectrum that quantifies the degree of quadratic phase coupling between three frequency components satisfying a sum or difference relation. Its value ranges from zero (no coupling) to one (complete coupling), making it a tool for detecting nonlinear interactions in a signal.','Bicoherence looks for links between three frequencies in a signal. It checks whether two tones combine to create a third with a fixed phase. A value near one means strong nonlinear coupling. A value near zero means the tones are unrelated.','It reveals nonlinear (quadratic) interactions and distortion mechanisms that ordinary power spectra and coherence cannot detect, because those discard phase relationships among frequencies.','Analyzing a distorted amplifier output, a technician computes bicoherence and finds a peak near one at frequencies f1, f2, and f1 plus f2, confirming a nonlinear intermodulation product.','Signal Analysis',ARRAY['Coherence degradation','Coherent distortion','Difference-frequency distortion','Distortion spectrum','Complex frequency response']::text[],ARRAY['Confusing bicoherence with ordinary (linear) coherence between two signals.','Estimating it from a single record; the average over many segments is required.','Reading a high value as proof of a specific circuit fault rather than general nonlinearity.']::text[],ARRAY['Detecting quadratic nonlinearity in an audio device under test.','Studying phase coupling in vibration or biomedical signals.','Distinguishing genuine intermodulation from independent tones.']::text[],'Advanced','b^2(f1,f2) = |B(f1,f2)|^2 / ( <|X(f1)X(f2)|^2> * <|X(f1+f2)|^2> )','Squared bicoherence equals the squared magnitude of the averaged bispectrum divided by the product of the averaged power at the two primary frequencies and the averaged power at their sum frequency.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bicoherence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e45c97be-a327-45b3-b7d7-7e39ab5eb333','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e45c97be-a327-45b3-b7d7-7e39ab5eb333') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e45c97be-a327-45b3-b7d7-7e39ab5eb333');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'de34def7-c82c-474b-8190-cad482f7534d','Burst SPL','The maximum sound pressure level a loudspeaker produces when driven by a short, shaped tone burst rather than a continuous signal, chosen so the device reaches high output before thermal heating or excursion limits fully develop. Standardized burst methods report peak output while keeping distortion within a defined threshold.','A tone burst is a short blast of a test tone. Playing bursts lets a speaker hit high peaks briefly. This avoids overheating the voice coil during the test. Burst SPL is the peak loudness measured this way.','It captures a loudspeaker''s short-term peak output capability, which matters for music with high peaks, without the heating that a continuous test would impose.','Using a shaped burst, a technician raises the drive level until distortion reaches the standard''s limit, then records the peak SPL at one metre as the burst output.','Loudspeaker Measurement',ARRAY['Acoustic compression','Crest-factor degradation','Distortion-limited output','Compression-limited output','Continuous power handling']::text[],ARRAY['Comparing a burst SPL figure directly to a continuous SPL rating as if they were equivalent.','Using a burst too long, which reintroduces the heating the method aims to avoid.','Ignoring the distortion limit that defines when the peak is valid.']::text[],ARRAY['Rating a subwoofer''s peak output for transient bass content.','Comparing short-term headroom between two drivers.','Specifying peak SPL where music crest factor is high.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Burst SPL');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'de34def7-c82c-474b-8190-cad482f7534d','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='de34def7-c82c-474b-8190-cad482f7534d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='de34def7-c82c-474b-8190-cad482f7534d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30d0d260-30a5-41f2-9fb2-f4935fc9bc98','Calibration correction','The value or factor applied to an instrument''s raw reading to compensate for its known deviation from a reference standard, as determined at calibration. Applying the correction brings the indicated value into agreement with the true value within the stated uncertainty.','No meter is perfect. Calibration finds how far off it reads. The correction is the amount you add or subtract to fix that. It makes the instrument''s reading match the true value.','It removes an instrument''s systematic error so measurements are accurate, and it makes results comparable across instruments and over time.','If a calibration certificate shows a sound level meter reads 0.3 dB low, a technician adds 0.3 dB to each field reading to obtain the corrected level.','Measurement Science',ARRAY['Calibration hierarchy','Combined standard uncertainty','Coverage factor','Acoustical metrology','Decision rule']::text[],ARRAY['Confusing a correction with the measurement uncertainty; the correction removes bias, the uncertainty remains.','Applying the correction with the wrong sign, doubling the error.','Assuming one correction applies across all frequencies or ranges.']::text[],ARRAY['Adjusting field readings using a meter''s calibration certificate.','Setting a microphone''s sensitivity value in analysis software.','Documenting corrections in a traceable measurement report.']::text[],'Beginner',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Calibration correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30d0d260-30a5-41f2-9fb2-f4935fc9bc98','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30d0d260-30a5-41f2-9fb2-f4935fc9bc98') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30d0d260-30a5-41f2-9fb2-f4935fc9bc98');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2dd248eb-d47e-40a6-83a1-d7d9a8f6caa2','Calibration hierarchy','The ordered chain of calibrations linking a working instrument, through one or more intermediate reference standards, up to a primary or national measurement standard, with the measurement uncertainty generally increasing at each step down the chain. It establishes metrological traceability for a measurement result.','Calibration works like a ladder. At the top sits a national standard. Each lower rung is calibrated against the one above it. Your working meter is near the bottom. Every rung adds a little more uncertainty.','It provides metrological traceability, so any measurement can be linked through a documented chain back to a recognized primary standard.','A technician''s field calibrator is checked against a lab reference, which itself is calibrated against a national standard, forming an unbroken traceable chain with stated uncertainties.','Measurement Science',ARRAY['Calibration correction','Acoustical metrology','Combined standard uncertainty','Coverage factor','Comparison method']::text[],ARRAY['Assuming traceability exists without documented links to a national standard.','Expecting uncertainty to stay constant down the chain; it normally grows.','Using a working instrument to calibrate a higher-tier reference.']::text[],ARRAY['Documenting traceability for an accredited test laboratory.','Explaining why field instruments carry larger uncertainties than lab references.','Auditing a calibration program for unbroken traceability.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Calibration hierarchy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2dd248eb-d47e-40a6-83a1-d7d9a8f6caa2','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2dd248eb-d47e-40a6-83a1-d7d9a8f6caa2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2dd248eb-d47e-40a6-83a1-d7d9a8f6caa2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fd581dc4-75f6-46db-8de5-472fbbc26c45','Coherence degradation','A drop in the ordinary coherence function below unity in a two-channel (input-output) measurement, indicating that the output is not fully linearly related to the measured input. Common causes include extraneous noise, system nonlinearity, unresolved time delay, and time variance during averaging.','Coherence rates how well an output tracks an input. A value of one means a clean linear link. Lower values signal trouble. Noise, distortion, or a missed delay can drag it down. That drop is coherence degradation.','It flags when a transfer-function measurement is unreliable and points to the cause, so the technician can trust or reject the frequency-response data.','In a dual-channel FFT room measurement, coherence falls at low frequencies where background noise dominates; the technician averages more and boosts level to restore it toward one.','Signal Analysis',ARRAY['Coherent distortion','Complex frequency response','Bicoherence','Active intensity','Distortion residue']::text[],ARRAY['Reading low coherence as a bad device when the real cause is background noise.','Failing to align input and output delay, which lowers coherence artificially.','Computing coherence from a single average, where it falsely reads one.']::text[],ARRAY['Judging the trustworthiness of a room or loudspeaker transfer-function measurement.','Diagnosing why a measured phase response looks noisy.','Setting the delay finder in dual-channel analysis software.']::text[],'Advanced','gamma^2(f) = |Gxy(f)|^2 / ( Gxx(f) * Gyy(f) )','The coherence function equals the squared magnitude of the cross-spectrum between input and output divided by the product of their auto-spectra; degradation is any fall below one.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coherence degradation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fd581dc4-75f6-46db-8de5-472fbbc26c45','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fd581dc4-75f6-46db-8de5-472fbbc26c45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fd581dc4-75f6-46db-8de5-472fbbc26c45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cab2ba0f-195f-4cd3-85a4-a4d6814aee68','Coherent distortion','Distortion products that are correlated with the input signal, such as harmonics and intermodulation components generated by system nonlinearity, as distinct from incoherent noise that bears no fixed relationship to the input. In coherence-based analysis these products can appear within the coherent portion of the output power.','A nonlinear device adds new tones tied to the input. These are harmonics and intermodulation products. Because they track the input, they are called coherent distortion. This sets them apart from random noise, which is unrelated.','It separates signal-related distortion from random noise, helping a technician judge whether unwanted output comes from nonlinearity or from an independent noise source.','Feeding a single tone into an amplifier, a technician sees harmonics locked to that tone; these coherent products contribute to total harmonic distortion, unlike the surrounding noise floor.','Signal Analysis',ARRAY['Coherence degradation','Bicoherence','Distortion spectrum','Distortion residue','Difference-frequency distortion']::text[],ARRAY['Assuming any drop in coherence is caused by noise; nonlinearity also degrades it.','Treating harmonics and random noise as the same kind of error.','Expecting coherence alone to reveal distortion, when it can hide within coherent power.']::text[],ARRAY['Explaining why a nonlinear device lowers measured coherence.','Separating distortion products from the noise floor in a spectrum.','Interpreting transfer-function measurements of a driven, distorting system.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coherent distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cab2ba0f-195f-4cd3-85a4-a4d6814aee68','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cab2ba0f-195f-4cd3-85a4-a4d6814aee68') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cab2ba0f-195f-4cd3-85a4-a4d6814aee68');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2da27215-6cfc-4935-ad46-fdb58154247e','Combined standard uncertainty','The standard uncertainty of a measurement result obtained by combining the individual standard uncertainties of all input quantities through the law of propagation of uncertainty. For uncorrelated inputs it is the square root of the sum of the squared products of each sensitivity coefficient and its input standard uncertainty.','A result depends on several measured inputs. Each input has its own uncertainty. The combined standard uncertainty merges them into one figure. For independent inputs, you square each contribution, add them, and take the square root.','It gives a single standard-deviation-like measure of doubt for a result built from several sources, forming the basis for the reported expanded uncertainty.','Two independent components of 0.2 dB and 0.3 dB combine as the square root of (0.2 squared plus 0.3 squared), giving a combined standard uncertainty of about 0.36 dB.','Measurement Science',ARRAY['Coverage factor','Coverage probability','Calibration correction','Decision rule','Acoustical metrology']::text[],ARRAY['Adding uncertainties directly instead of combining them in quadrature.','Ignoring correlation between inputs, which changes the combination.','Forgetting the sensitivity coefficients when inputs have different units or weights.']::text[],ARRAY['Building an uncertainty budget for a sound level measurement.','Combining microphone, calibrator, and environment uncertainties.','Preparing an accredited calibration certificate.']::text[],'Intermediate','uc(y) = sqrt( sum_i ( (df/dxi)^2 * u(xi)^2 ) )','For uncorrelated inputs, the combined standard uncertainty of the result equals the square root of the sum, over all inputs, of the squared sensitivity coefficient multiplied by the squared standard uncertainty of that input.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Combined standard uncertainty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2da27215-6cfc-4935-ad46-fdb58154247e','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2da27215-6cfc-4935-ad46-fdb58154247e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2da27215-6cfc-4935-ad46-fdb58154247e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db83480f-1988-46f8-92da-4c587d27f5ce','Community-noise equivalent level','A 24-hour cumulative A-weighted noise metric, used chiefly in California land-use and airport noise planning, that adds a 5 dB penalty to sound during the evening (7 p.m. to 10 p.m.) and a 10 dB penalty during the night (10 p.m. to 7 a.m.) before energy-averaging over the full day. It is abbreviated CNEL and expressed in A-weighted decibels.','CNEL rates a location''s noise over a full day. Evening sound counts 5 decibels louder than it is. Night sound counts 10 decibels louder. This reflects how noise bothers people more when they rest. It is common in California planning.','It captures cumulative community noise while penalizing evening and night sound, so land-use planners can set compatible limits near airports and highways.','For a steady 60 dBA environment all day, applying the 5 dB evening and 10 dB night penalties in the energy average yields a CNEL of about 67 dBA.','Environmental Noise',ARRAY['Day–night average sound level','Criterion level','Acoustical metrology','Comparison method','Coverage factor']::text[],ARRAY['Confusing CNEL with Ldn; CNEL adds a separate evening penalty that Ldn does not.','Using the wrong time boundaries for the day, evening, and night periods.','Averaging the decibel values arithmetically instead of on an energy basis.']::text[],ARRAY['Assessing residential compatibility near a California airport.','Preparing a noise element for a city general plan.','Comparing highway noise exposure against a CNEL limit.']::text[],'Intermediate','CNEL = 10*log10( (1/24) * ( 12*10^(Ld/10) + 3*10^((Le+5)/10) + 9*10^((Ln+10)/10) ) )','CNEL is ten times the base-ten logarithm of the 24-hour energy average of the hourly A-weighted levels, with 5 dB added to each of the three evening hours and 10 dB added to each of the nine night hours.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Community-noise equivalent level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db83480f-1988-46f8-92da-4c587d27f5ce','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db83480f-1988-46f8-92da-4c587d27f5ce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db83480f-1988-46f8-92da-4c587d27f5ce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7571c983-6fae-48eb-b139-b06846dce59b','Comparison method','A measurement approach in which an unknown quantity is determined by comparing it, under the same conditions, against a calibrated reference of the same kind, often by substitution. In acoustics it is used, for example, to find a source''s sound power by comparison with a calibrated reference sound source.','The comparison method measures something against a known reference. You test both under the same conditions. The reference value tells you the unknown. It cancels out many errors that affect both alike.','It provides accurate results without an absolute calibration by transferring the reference''s known value to the unknown, cancelling shared systematic effects.','To find a machine''s sound power, a technician measures it and a calibrated reference sound source at the same points, then scales the machine''s level by the reference''s known output.','Measurement Science',ARRAY['Acoustic-power determination','Calibration hierarchy','Calibration correction','Anechoic-room method','Acoustical metrology']::text[],ARRAY['Using a reference that differs in type or directivity from the unknown.','Changing conditions between the reference and unknown measurements.','Assuming the method needs no traceable reference; the reference must be calibrated.']::text[],ARRAY['Measuring sound power with a reference sound source in a normal room.','Calibrating one microphone against a standard by substitution.','Transferring a known value where absolute measurement is impractical.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Comparison method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7571c983-6fae-48eb-b139-b06846dce59b','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7571c983-6fae-48eb-b139-b06846dce59b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7571c983-6fae-48eb-b139-b06846dce59b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ac0c2b4-8649-4229-b2c8-dd992b85b0e1','Complex frequency response','The frequency-dependent transfer function of a system expressed as a complex quantity, carrying both magnitude and phase (equivalently real and imaginary parts) at each frequency. It fully describes a linear time-invariant system''s steady-state response to sinusoids and is estimated from the input-output cross-spectrum divided by the input auto-spectrum.','A system changes both the size and timing of each frequency. The complex frequency response captures both. Magnitude tells how much a tone is boosted or cut. Phase tells how much it is delayed. Together they fully describe a linear system.','It gives a complete picture of how a linear system treats every frequency, so magnitude and phase can be analyzed, corrected, or matched.','A dual-channel analyzer divides output by input across frequency; a technician reads magnitude in decibels and phase in degrees to align a subwoofer with a main speaker.','Signal Analysis',ARRAY['Coherence degradation','Coherent distortion','Active intensity','Anechoic measurement','Comparison method']::text[],ARRAY['Reporting only magnitude and ignoring phase, which is half the response.','Treating a nonlinear or time-varying device as if one transfer function fully describes it.','Neglecting delay alignment, which corrupts the measured phase.']::text[],ARRAY['Time-aligning loudspeakers in a multi-way system.','Designing a correction filter to flatten a response.','Verifying phase behavior across a crossover region.']::text[],'Advanced','H(f) = Gxy(f) / Gxx(f)','The complex frequency response equals the cross-spectrum of input and output divided by the auto-spectrum of the input, yielding magnitude and phase at each frequency.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex frequency response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ac0c2b4-8649-4229-b2c8-dd992b85b0e1','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ac0c2b4-8649-4229-b2c8-dd992b85b0e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ac0c2b4-8649-4229-b2c8-dd992b85b0e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '07372988-7ab1-49ac-a394-bc22f589d133','Compression-limited output','An operating condition in which a loudspeaker''s maximum usable output is set by power (thermal) compression rather than by distortion or excursion, because voice-coil heating reduces sensitivity so that added drive power yields little additional acoustic output. The output approaches a ceiling as the coil heats.','Sometimes a speaker''s loudness limit comes from heat, not distortion. As the voice coil warms, it turns less power into sound. Beyond a point, more power gives almost no more output. That ceiling is compression-limited output.','It identifies when thermal power compression, not distortion or excursion, caps a driver''s output, guiding realistic maximum-level ratings and thermal design.','A technician raises drive power and finds output nearly stops rising while distortion stays low; the driver has reached its compression-limited output due to coil heating.','Loudspeaker Measurement',ARRAY['Acoustic compression','Continuous power handling','Distortion-limited output','Current-limited output','Burst SPL']::text[],ARRAY['Confusing compression-limited output with distortion-limited output; the limiting cause differs.','Assuming more amplifier power always yields more sound level.','Overlooking voice-coil temperature as the controlling factor.']::text[],ARRAY['Explaining why a driver stops getting louder during sustained high power.','Setting a realistic maximum continuous SPL for a sound system.','Comparing thermal versus distortion limits in a driver specification.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compression-limited output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '07372988-7ab1-49ac-a394-bc22f589d133','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='07372988-7ab1-49ac-a394-bc22f589d133') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='07372988-7ab1-49ac-a394-bc22f589d133');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9f97ab79-b1d9-476c-861e-0515c27ffdb2','Continuous power handling','The maximum continuous electrical input power a loudspeaker can withstand over a specified duration without permanent damage, measured with a defined test signal (typically a band-limited noise with a stated crest factor) under standardized conditions. It is a durability rating, not a measure of loudness.','This rates how much steady power a speaker survives. Testers feed a standard noise signal for a set time. If the speaker is undamaged, it passes. The rating is about survival, not how loud it plays.','It defines a safe long-term power limit so systems can be designed and amplifiers matched without thermally or mechanically destroying the driver.','A driver rated for continuous power with a 6 dB crest-factor noise signal for two hours is tested at that level; passing without damage confirms the rating.','Loudspeaker Measurement',ARRAY['Compression-limited output','Acoustic compression','Crest-factor degradation','Distortion-limited output','Burst SPL']::text[],ARRAY['Reading power handling as a loudness spec; it is a durability limit.','Ignoring the test signal and its crest factor, which change the rating.','Comparing ratings measured under different standards as if equivalent.']::text[],ARRAY['Matching an amplifier''s output to a speaker''s safe power limit.','Choosing drivers for a high-duty-cycle installation.','Interpreting a datasheet power rating and its test conditions.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Continuous power handling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9f97ab79-b1d9-476c-861e-0515c27ffdb2','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9f97ab79-b1d9-476c-861e-0515c27ffdb2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9f97ab79-b1d9-476c-861e-0515c27ffdb2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e8f7cb3-7038-403b-a08c-605db0bc1008','Coverage factor','A numerical factor, denoted k, by which the combined standard uncertainty is multiplied to obtain the expanded uncertainty that defines an interval expected to contain a large fraction of the values attributable to the measurand. For an approximately normal distribution, k equal to 2 corresponds to a coverage probability of about 95 percent.','The coverage factor widens the uncertainty to a chosen confidence. You multiply the combined uncertainty by it. This factor is called k. A k of 2 gives about 95 percent confidence. The result is the expanded uncertainty.','It converts a standard uncertainty into an expanded uncertainty at a stated level of confidence, so results can be reported as an interval likely to contain the true value.','With a combined standard uncertainty of 0.36 dB, multiplying by k equal to 2 gives an expanded uncertainty of 0.72 dB at about 95 percent confidence.','Measurement Science',ARRAY['Combined standard uncertainty','Coverage probability','Calibration correction','Decision rule','Acoustical metrology']::text[],ARRAY['Assuming k of 2 always means exactly 95 percent regardless of the distribution.','Reporting expanded uncertainty without stating the coverage factor used.','Confusing the coverage factor with the combined standard uncertainty itself.']::text[],ARRAY['Stating an expanded uncertainty on a calibration certificate.','Reporting a measurement result at 95 percent confidence.','Comparing results that used different coverage factors.']::text[],'Intermediate','U = k * uc(y)','The expanded uncertainty equals the coverage factor multiplied by the combined standard uncertainty of the result.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coverage factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e8f7cb3-7038-403b-a08c-605db0bc1008','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e8f7cb3-7038-403b-a08c-605db0bc1008') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e8f7cb3-7038-403b-a08c-605db0bc1008');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d4bdc9f-f277-43e9-b523-7b7633f0397a','Coverage probability','The fraction, or level of confidence, of the distribution of values reasonably attributable to the measurand that is expected to lie within the interval defined by the expanded uncertainty. It is the confidence level associated with a chosen coverage factor, for example about 95 percent when k equals 2 for a normal distribution.','Coverage probability is the confidence tied to an uncertainty interval. It says how likely the true value falls inside the stated range. A value of 95 percent is common. It pairs with the coverage factor you chose.','It states how much confidence the reported uncertainty interval carries, so users know the likelihood that the true value lies within the quoted bounds.','A report giving a result plus or minus its expanded uncertainty at a coverage probability of 95 percent means the true value is expected to fall in that interval about 19 times in 20.','Measurement Science',ARRAY['Coverage factor','Combined standard uncertainty','Decision rule','Calibration correction','Acoustical metrology']::text[],ARRAY['Confusing coverage probability with the coverage factor; one is a confidence level, the other a multiplier.','Quoting a probability without stating the assumed distribution.','Treating 95 percent as a guarantee rather than a stated confidence level.']::text[],ARRAY['Interpreting the confidence level on a calibration certificate.','Choosing a coverage factor to reach a target confidence.','Explaining measurement results to a client or auditor.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coverage probability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d4bdc9f-f277-43e9-b523-7b7633f0397a','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d4bdc9f-f277-43e9-b523-7b7633f0397a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d4bdc9f-f277-43e9-b523-7b7633f0397a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '554505b4-d413-4a37-a1a6-1a42ce1ad956','Crest-factor degradation','A reduction in a signal''s crest factor, the ratio of its peak amplitude to its RMS value, usually caused by clipping, limiting, or dynamic-range compression that lowers peaks relative to the average level. Because crest factor is often stated in decibels, degradation appears as a smaller peak-to-RMS figure.','Crest factor is the gap between a signal''s peak and its average level. Clipping or heavy compression shrinks the peaks. That narrows the gap. The signal then has a lower crest factor. This loss is crest-factor degradation.','It describes how processing flattens transients, which affects perceived loudness, distortion, and the thermal stress a signal places on amplifiers and drivers.','A signal with a 2 V peak and 0.5 V RMS has a crest factor of 4, or about 12 dB; after limiting cuts the peak to 1 V, the crest factor falls to 2, or about 6 dB.','Signal Analysis',ARRAY['Continuous power handling','Acoustic compression','Compression-limited output','Distortion residue','Burst SPL']::text[],ARRAY['Confusing crest factor with dynamic range or with signal level.','Forgetting that a pure sine wave has a fixed crest factor of about 3 dB.','Assuming crest-factor loss is inaudible; it changes transients and loudness.']::text[],ARRAY['Judging how much limiting is flattening a mix.','Choosing test signals with realistic crest factors for power tests.','Explaining why over-compressed masters sound less dynamic.']::text[],'Intermediate','CF = V_peak / V_rms','Crest factor equals the peak amplitude divided by the RMS value; degradation is any decrease in this ratio.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Crest-factor degradation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '554505b4-d413-4a37-a1a6-1a42ce1ad956','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='554505b4-d413-4a37-a1a6-1a42ce1ad956') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='554505b4-d413-4a37-a1a6-1a42ce1ad956');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e312260e-fdc8-4efb-ae2d-4efa3956fa01','Criterion level','In occupational noise dosimetry, the continuous A-weighted sound level that, if present for the full criterion duration (8 hours), produces a noise dose of 100 percent. Under the United States OSHA occupational noise standard the criterion level is 90 dBA with a 5 dB exchange rate; the NIOSH recommended criterion is 85 dBA with a 3 dB exchange rate.','Noise dosimeters count how much noise a worker gets. The criterion level is the level that fills a full dose in eight hours. OSHA sets it at 90 decibels A-weighted. NIOSH advises a stricter 85 decibels. Louder noise fills the dose faster.','It anchors the noise-dose calculation, defining the reference level and duration for 100 percent dose so worker exposure can be compared against a legal or recommended limit.','At the OSHA criterion level of 90 dBA, 8 hours gives 100 percent dose; with the 5 dB exchange rate, 95 dBA reaches 100 percent dose in just 4 hours.','Noise Exposure',ARRAY['Day–night average sound level','Community-noise equivalent level','Coverage factor','Acoustical metrology','Decision rule']::text[],ARRAY['UNSAFE: Assuming exposure just under the criterion level is always safe; NIOSH warns risk exists below 90 dBA, so use hearing protection.','Confusing the criterion level with the action level; OSHA''s action level is 85 dBA (50 percent dose).','Mixing OSHA''s 5 dB exchange rate with NIOSH''s 3 dB rate in one calculation.']::text[],ARRAY['Configuring a noise dosimeter for an OSHA or NIOSH survey.','Assessing a live-sound engineer''s daily noise dose.','Deciding when a hearing-conservation program is required.']::text[],'Intermediate','T = 8 / 2^((L - Lc)/q)','The allowed time equals 8 hours divided by two raised to the power of the level above the criterion level divided by the exchange rate; full dose occurs at the criterion level for the criterion duration.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Criterion level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e312260e-fdc8-4efb-ae2d-4efa3956fa01','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e312260e-fdc8-4efb-ae2d-4efa3956fa01') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e312260e-fdc8-4efb-ae2d-4efa3956fa01');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '655dd301-417e-4ee4-956d-ca465e862797','Current-limited output','An operating condition in which a power amplifier cannot deliver more output because it has reached its maximum output-current capability, typically when driving a low or reactive load impedance, rather than being limited by its supply voltage. The amplifier''s protection or output devices cap the current before the voltage swing limit is reached.','An amplifier has two limits: voltage and current. Into a low-impedance speaker, current runs out first. The amplifier then cannot push more, even with voltage to spare. This is current-limited output.','It explains why an amplifier falls short of its rated power into difficult loads, guiding proper amplifier-to-load matching and protection design.','An amplifier that meets full power into 8 ohms may hit its current limit into a 2 ohm load, delivering less than the expected fourfold power and possibly triggering protection.','Amplifier Measurement',ARRAY['Compression-limited output','Distortion-limited output','Continuous power handling','Burst SPL','Acoustic compression']::text[],ARRAY['Assuming power always doubles as load impedance halves; current limiting prevents this.','Confusing current limiting with voltage clipping; the limiting cause differs.','Ignoring load reactance, which raises peak current demand.']::text[],ARRAY['Diagnosing why an amplifier underperforms into low-impedance speaker arrays.','Matching an amplifier to a parallel loudspeaker load.','Understanding amplifier protection tripping under heavy bass.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Current-limited output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '655dd301-417e-4ee4-956d-ca465e862797','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='655dd301-417e-4ee4-956d-ca465e862797') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='655dd301-417e-4ee4-956d-ca465e862797');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cac5e229-e26a-4d51-adfb-694cc2b64aef','Day–night average sound level','A 24-hour cumulative A-weighted noise metric, abbreviated DNL or Ldn, that energy-averages the sound level over a full day after adding a 10 dB penalty to sound occurring at night (10 p.m. to 7 a.m.). It is widely used for aircraft and community noise, with the United States FAA treating 65 dB DNL as the threshold of significant residential noise exposure.','DNL rates a place''s noise across a whole day. Night sound counts 10 decibels louder than it is. This reflects how noise disturbs sleep. The FAA calls 65 decibels DNL the point where homes face significant noise.','It provides a single day-long noise descriptor that weights nighttime disturbance, used for airport land-use planning and community noise assessment.','For a steady 60 dBA environment, applying the 10 dB night penalty across the nine night hours in the energy average yields a DNL of about 66 dBA.','Environmental Noise',ARRAY['Community-noise equivalent level','Criterion level','Acoustical metrology','Comparison method','Coverage factor']::text[],ARRAY['Confusing DNL with CNEL; only CNEL adds a separate evening penalty.','Using the wrong night boundaries; the night period runs 10 p.m. to 7 a.m.','Averaging decibels arithmetically instead of on an energy basis.']::text[],ARRAY['Producing an airport noise-exposure contour map.','Assessing residential land-use compatibility near an airport.','Comparing measured community noise against the 65 dB DNL threshold.']::text[],'Intermediate','Ldn = 10*log10( (1/24) * ( 15*10^(Ld/10) + 9*10^((Ln+10)/10) ) )','DNL is ten times the base-ten logarithm of the 24-hour energy average of hourly A-weighted levels, with 10 dB added to each of the nine night hours.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Day–night average sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cac5e229-e26a-4d51-adfb-694cc2b64aef','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cac5e229-e26a-4d51-adfb-694cc2b64aef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cac5e229-e26a-4d51-adfb-694cc2b64aef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '943f8204-0d80-43cb-8e97-f51a73c2f6a2','Decision rule','A documented rule that specifies how measurement uncertainty is taken into account when deciding conformity or non-conformity of a measured value against a specification limit. It defines any guard band and the acceptance and rejection zones, setting the risk of accepting nonconforming items or rejecting conforming ones.','A decision rule tells you how to judge pass or fail near a limit. It accounts for the measurement''s uncertainty. It may add a safety margin called a guard band. This controls the risk of a wrong pass or fail.','It makes conformity decisions explicit and consistent by defining how uncertainty and guard bands affect acceptance, balancing the risks of false accept and false reject.','Using a guard-banded rule, a technician accepts a device only if its reading plus the expanded uncertainty stays inside the specification limit, reducing the chance of passing a bad unit.','Measurement Science',ARRAY['Coverage factor','Combined standard uncertainty','Coverage probability','Calibration correction','Acoustical metrology']::text[],ARRAY['Comparing a reading to a limit while ignoring measurement uncertainty.','Confusing a simple acceptance rule with a guard-banded rule.','Failing to state the decision rule in the report, leaving pass/fail ambiguous.']::text[],ARRAY['Deciding whether a calibrated instrument passes its tolerance.','Setting a guard band for conformity testing near a limit.','Documenting acceptance criteria in a calibration procedure.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Decision rule');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '943f8204-0d80-43cb-8e97-f51a73c2f6a2','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='943f8204-0d80-43cb-8e97-f51a73c2f6a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='943f8204-0d80-43cb-8e97-f51a73c2f6a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '19278045-db0e-480c-8add-0752f40ec64a','Difference-frequency distortion','A form of intermodulation distortion measured by driving a device with two closely spaced high-frequency tones and quantifying the unwanted component that appears at their difference frequency. It is expressed as the ratio of the difference-frequency product to the output level, in percent or decibels.','Feed a device two nearby high tones. A nonlinear device creates a new low tone at their spacing. That new tone should not be there. Its size, compared to the output, is difference-frequency distortion.','It reveals intermodulation nonlinearity using tones near the top of the audio band, exposing distortion that single-tone harmonic tests can miss.','Driving an amplifier with tones at 13 kHz and 14 kHz, a technician measures the 1 kHz difference product; if it is 1 percent of the output, the difference-frequency distortion is 1 percent.','Distortion Measurement',ARRAY['Distortion spectrum','Distortion residue','Coherent distortion','Bicoherence','Distortion-limited output']::text[],ARRAY['Confusing difference-frequency distortion with harmonic distortion; they use different test signals.','Choosing tones too far apart, changing which intermodulation products appear.','Overlooking that the difference product can fall in a sensitive part of the band.']::text[],ARRAY['Testing an amplifier for high-frequency intermodulation.','Comparing distortion behavior beyond a single-tone THD test.','Characterizing nonlinearity near the top of the audio range.']::text[],'Advanced','f_d = f2 - f1','The difference-frequency product appears at the difference between the two applied tone frequencies; the distortion is the ratio of that product''s level to the output level.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Difference-frequency distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '19278045-db0e-480c-8add-0752f40ec64a','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='19278045-db0e-480c-8add-0752f40ec64a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='19278045-db0e-480c-8add-0752f40ec64a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4a29d3d4-024e-403c-a4ac-7cdaa162c287','Distortion residue','The signal that remains after the fundamental (or the intended output) has been removed, typically by a tuned notch filter, in a distortion measurement; it comprises the harmonic and intermodulation products plus noise. In a total-harmonic-distortion-plus-noise measurement, the residue is what is measured against the total signal.','To measure distortion, testers remove the original tone with a notch filter. What is left is the residue. It holds the harmonics, extra products, and noise. Comparing it to the whole signal gives the distortion figure.','It isolates the unwanted content of an output so distortion and noise can be quantified relative to the total signal, as in THD plus noise measurements.','After notching out a 1 kHz test tone, a technician reads the residue at 1 mV against a 1 V output, giving a THD plus noise figure of 0.1 percent.','Distortion Measurement',ARRAY['Distortion spectrum','Difference-frequency distortion','Coherent distortion','Crest-factor degradation','Distortion-limited output']::text[],ARRAY['Assuming the residue is only harmonics; it also contains noise and any hum.','Using a notch that is too wide, which removes real distortion products.','Confusing THD (harmonics only) with THD plus noise (the full residue).']::text[],ARRAY['Measuring THD plus noise on an audio device.','Listening to the residue to identify hum or noise in a device.','Verifying the notch depth in a distortion analyzer.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distortion residue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4a29d3d4-024e-403c-a4ac-7cdaa162c287','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4a29d3d4-024e-403c-a4ac-7cdaa162c287') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4a29d3d4-024e-403c-a4ac-7cdaa162c287');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '658846fd-1279-46c6-ab8f-1e46862a17c1','Distortion spectrum','The frequency-domain representation of the distortion products generated by a device under test, showing the amplitude of each harmonic or intermodulation component versus frequency. It reveals the pattern of distortion, such as whether low-order or high-order harmonics dominate.','A distortion spectrum plots each distortion tone by frequency and size. It shows which harmonics a device adds. Low harmonics often sound mild. High harmonics often sound harsh. The plot shows the whole pattern at once.','It shows not just how much distortion a device produces but its character, since the mix of harmonics affects how the distortion sounds and its likely cause.','A technician runs a 1 kHz tone and views the spectrum; strong second and third harmonics at 2 kHz and 3 kHz indicate the dominant low-order distortion of the device.','Distortion Measurement',ARRAY['Distortion residue','Difference-frequency distortion','Coherent distortion','Distortion-limited output','Complex frequency response']::text[],ARRAY['Judging a device by a single THD number while ignoring the harmonic pattern.','Assuming all harmonics sound equally objectionable.','Overlooking noise and interference lines mixed into the spectrum.']::text[],ARRAY['Diagnosing whether distortion is low-order or high-order.','Comparing the harmonic signatures of two amplifiers.','Identifying the mechanism behind an audible distortion.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distortion spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '658846fd-1279-46c6-ab8f-1e46862a17c1','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='658846fd-1279-46c6-ab8f-1e46862a17c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='658846fd-1279-46c6-ab8f-1e46862a17c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab6c53d6-33a3-4f4a-8ecd-4943256428c4','Distortion-limited output','The maximum output of a device defined by the point at which distortion reaches a specified threshold, such as a stated percentage of total harmonic distortion, rather than by clipping, thermal, or current limits. It gives a usable-output rating tied to a chosen distortion criterion.','A device''s usable output can be set by distortion. You raise the level until distortion hits a chosen limit. That output is the distortion-limited output. It rates loudness at an acceptable cleanliness.','It defines maximum usable output against a distortion criterion, giving a meaningful rating for how loud a device can play while staying acceptably clean.','A technician raises a loudspeaker''s drive until total harmonic distortion reaches 10 percent, then records the resulting SPL as the distortion-limited maximum output.','Loudspeaker Measurement',ARRAY['Compression-limited output','Current-limited output','Distortion spectrum','Distortion residue','Burst SPL']::text[],ARRAY['Comparing distortion-limited ratings that use different distortion thresholds.','Confusing a distortion limit with a thermal or current limit.','Assuming the rating holds across all frequencies rather than at the test frequency.']::text[],ARRAY['Rating a loudspeaker''s maximum clean SPL at a stated distortion limit.','Comparing amplifiers at a fixed THD threshold.','Setting realistic maximum levels for a sound system.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distortion-limited output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab6c53d6-33a3-4f4a-8ecd-4943256428c4','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab6c53d6-33a3-4f4a-8ecd-4943256428c4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab6c53d6-33a3-4f4a-8ecd-4943256428c4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee9bca16-aa5d-4ae0-9a0c-12b8873656c2','Dual-channel measurement','A measurement method that captures a system''s input (reference) and output on two synchronized channels and computes the complex transfer function (magnitude and phase) and coherence between them from their cross- and auto-spectra. Because it references the actual excitation, it works with arbitrary signals such as music or noise, not just fixed test tones.','This method records two signals at once. One is the signal going into a system. The other is the signal coming out. A computer compares them to find how the system changes the sound. It also checks how trustworthy the result is at each frequency. You can even use music as the test signal.','It reveals how a device, loudspeaker, or room alters a signal in level and timing, and its coherence value flags where the result is trustworthy versus corrupted by noise or reflections.','A technician aligns a live sound system by feeding pink noise to the console and a measurement microphone, then reads the transfer-function magnitude and phase to set delay and EQ; using H1 = Gxy/Gxx, coherence above about 0.9 marks reliable data.','Analysis Method',ARRAY['H1 estimator','H2 estimator','Gated measurement','Excess-phase response','Fractional-octave-band level']::text[],ARRAY['Trusting transfer-function data at frequencies where coherence is low.','Forgetting that an unmatched internal delay between the two channels distorts the measured phase.','Assuming the reference channel is clean when it is actually taken after a processor that changes the signal.']::text[],ARRAY['Time-aligning main and delay loudspeakers at a concert.','Measuring a room''s response to tune a monitor system.','Verifying an equalizer''s magnitude and phase in a lab.']::text[],'Intermediate','H(f) = Gxy(f) / Gxx(f);  gamma^2 = |Gxy|^2 / (Gxx*Gyy)','The transfer function equals the input-output cross-spectrum divided by the input auto-spectrum, and coherence equals the squared magnitude of the cross-spectrum divided by the product of the two auto-spectra.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dual-channel measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee9bca16-aa5d-4ae0-9a0c-12b8873656c2','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee9bca16-aa5d-4ae0-9a0c-12b8873656c2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee9bca16-aa5d-4ae0-9a0c-12b8873656c2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8309ef07-d71a-4aa5-a6cc-b36912f6f20b','Dynamic intermodulation distortion','Intermodulation distortion produced when a device cannot follow fast signal changes, typically from slew-rate limiting in amplifiers, revealing transient behavior that steady-state tests miss. It is measured with a test signal combining a 3.15 kHz square wave and a 15 kHz sine wave (the DIM method) and quantifying the new intermodulation products created.','Some gear cannot keep up with very fast signal changes. When that happens, tones mix and create new, unwanted tones. This is called dynamic intermodulation distortion. A special test uses a square wave plus a high sine tone. The test then measures the extra tones that appear.','It exposes fast-signal (slew-rate) weaknesses in amplifiers and processors that a slow single-tone distortion test would not show.','An engineer plays the standard 3.15 kHz square wave and 15 kHz sine wave (4:1 level ratio) through an amplifier and reads the sum of intermodulation products; a well-designed amplifier keeps dynamic intermodulation distortion well below 0.1 percent.','Distortion',ARRAY['Higher-order harmonic distortion','Harmonic distortion profile','Excursion distortion','Flux modulation distortion']::text[],ARRAY['Confusing it with ordinary harmonic distortion measured with one slow tone.','Assuming low steady-state distortion guarantees low dynamic intermodulation distortion.','Ignoring the required low-pass band-limiting of the test signal, which changes the result.']::text[],ARRAY['Bench-testing a power amplifier''s slew-rate behavior.','Comparing op-amp choices for a mixing console input stage.','Diagnosing harsh high-frequency sound that only appears on fast transients.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic intermodulation distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8309ef07-d71a-4aa5-a6cc-b36912f6f20b','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8309ef07-d71a-4aa5-a6cc-b36912f6f20b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8309ef07-d71a-4aa5-a6cc-b36912f6f20b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7157b656-e011-4b99-9469-9be9397ee132','Enveloping surface','A hypothetical closed surface, such as a hemisphere or rectangular box, drawn around a sound source in a sound-power measurement, over which sound pressure is sampled at defined microphone positions. Averaging the pressure over this surface and multiplying by its area yields the source''s radiated sound power.','To find how much sound power a machine makes, you imagine a surface wrapped around it. This can be a dome or a box shape. You measure sound pressure at set points on that surface. From the average level and the surface size, you calculate the total sound power.','It provides the geometric basis for turning many sound-pressure readings around a source into one figure for total radiated sound power.','Following ISO 3744, a technician places microphones on a hemispherical enveloping surface of radius r over a hard floor and computes sound power as the mean surface level plus 10*log10(S/S0), where S = 2*pi*r^2 and S0 = 1 square meter.','Sound Power',ARRAY['Hemispherical measurement','Half-space measurement','Full-space measurement','Far-field measurement']::text[],ARRAY['Using too few microphone positions to represent the surface average.','Choosing an enveloping surface so close to the source that near-field effects bias the reading.','Forgetting that the surface must fully enclose the source over the reflecting plane.']::text[],ARRAY['Rating the sound power of an appliance for a noise label.','Measuring loudspeaker or amplifier fan noise in a lab.','Comparing machine noise emissions against a standard.']::text[],'Intermediate','L_W = L_p_bar + 10*log10(S/S0),  S0 = 1 m^2','The sound power level equals the surface-averaged sound pressure level plus ten times the base-ten logarithm of the measurement surface area divided by one square meter.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Enveloping surface');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7157b656-e011-4b99-9469-9be9397ee132','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7157b656-e011-4b99-9469-9be9397ee132') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7157b656-e011-4b99-9469-9be9397ee132');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a76e54a7-458b-405f-9ae7-9ef1f3741834','Event sound level','The sound exposure level (LAE, or SEL) of a single acoustic event: the constant A-weighted level that, if held for a one-second reference time, would carry the same A-weighted sound energy as the whole event. It compresses a varying event, such as a vehicle pass-by, into one energy-based number.','A single sound event, like a truck driving past, changes over time. The event sound level squeezes all of its energy into one number. It is the steady level that would hold the same energy in just one second. This lets you compare short events fairly, no matter how long each one lasts.','It lets short events of different lengths be compared and combined on an equal-energy basis, which is the standard way to rate transient noise.','A technician measures a train pass-by lasting 20 seconds at an equivalent level of 80 dBA; the event sound level is 80 + 10*log10(20/1) = about 93 dB, using LAE = LAeq,T + 10*log10(T/T0) with T0 = 1 s.','Noise Metrics',ARRAY['Exponential time weighting','Exceedance level','Fractional-octave-band level','Equivalent continuous sound level']::text[],ARRAY['Thinking the event sound level is the peak level of the event; it is an energy total over one second.','Comparing event sound levels of events measured with different frequency weightings.','Confusing it with the equivalent continuous level averaged over the whole measurement period.']::text[],ARRAY['Rating aircraft fly-over noise near an airport.','Assessing a single concert bass hit against a noise limit.','Logging vehicle pass-by events for a traffic noise study.']::text[],'Intermediate','L_AE = 10*log10[ (1/T0) * integral( p_A^2(t)/p0^2 dt ) ];  L_AE = L_Aeq,T + 10*log10(T/T0),  T0 = 1 s','The event sound level equals ten times the base-ten logarithm of the time integral of the squared A-weighted pressure ratio divided by a one-second reference, which also equals the equivalent level plus ten log of the event duration in seconds.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Event sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a76e54a7-458b-405f-9ae7-9ef1f3741834','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a76e54a7-458b-405f-9ae7-9ef1f3741834') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a76e54a7-458b-405f-9ae7-9ef1f3741834');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '472a8863-f070-49c4-9257-e80760c94f75','Exceedance level','A statistical noise descriptor, written Ln, giving the A-weighted sound level that was exceeded for n percent of the measurement time. Common values include L10 (near the higher, intrusive levels) and L90 (near the residual or background level).','Noise usually goes up and down over time. An exceedance level describes this spread with one number. For example, L90 is the level that the noise stayed above for ninety percent of the time. That value marks the quiet background. L10 marks the louder, more intrusive part.','It summarizes fluctuating noise by percentiles, separating steady background (high n) from occasional loud events (low n).','During a survey a technician reports L90 = 42 dBA as the background and L10 = 61 dBA as the intrusive level; because Ln falls as n rises, L10 is always greater than or equal to L90.','Noise Metrics',ARRAY['Event sound level','Exponential time weighting','Percentile level','Fractional-octave-band level']::text[],ARRAY['Reading L90 as a loud level; a high percentage means the quieter background.','Treating exceedance levels as energy averages; they are time-percentile statistics.','Comparing Ln values taken over very different measurement durations as if equal.']::text[],ARRAY['Characterizing neighborhood background noise for a permit.','Judging whether a venue''s bass exceeds a local L10 limit.','Documenting construction-site noise over a work shift.']::text[],'Intermediate','Ln = level exceeded for n% of T;  L10 >= L50 >= L90','The exceedance level Ln is the sound level that the signal stayed above for n percent of the total measurement time, so a smaller percentage always gives a level equal to or higher than a larger percentage.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exceedance level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '472a8863-f070-49c4-9257-e80760c94f75','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='472a8863-f070-49c4-9257-e80760c94f75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='472a8863-f070-49c4-9257-e80760c94f75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d74b685-ba49-4b59-bd07-eb5869cbe773','Excess group delay','The part of a system''s group delay that remains after subtracting the minimum-phase group delay implied by its magnitude response. Group delay itself is the negative rate of change of phase with angular frequency, so excess group delay isolates pure time delay and non-minimum-phase behavior.','Group delay tells how long each frequency is held up as it passes through a system. Part of that delay is unavoidable, set by the frequency shape. Excess group delay is what is left after removing that part. It shows extra delay and unusual timing that the shape alone does not explain.','It separates true propagation or processing delay and non-minimum-phase effects from the delay that the magnitude response already dictates, aiding time alignment and crossover analysis.','After removing a fixed 3.0 ms flight delay from a loudspeaker measurement, a technician finds excess group delay rising by 0.4 ms near the crossover, revealing a non-minimum-phase crossover region; group delay is computed as tau_g = -d(phi)/d(omega).','Phase and Delay',ARRAY['Excess-phase response','Dual-channel measurement','Gated measurement','Far-field measurement']::text[],ARRAY['Mistaking a constant flight-time delay for problematic excess group delay.','Computing group delay from noisy phase without smoothing, giving wild spikes.','Ignoring that low coherence regions make excess group delay meaningless.']::text[],ARRAY['Analyzing crossover phase behavior in a studio monitor.','Aligning subwoofer timing to the main loudspeakers.','Investigating smearing in a digital signal processor.']::text[],'Advanced','tau_excess(omega) = tau_total(omega) - tau_min(omega),  where tau_g = -d(phi)/d(omega)','Excess group delay equals the total group delay minus the minimum-phase group delay, where group delay is the negative derivative of phase with respect to angular frequency.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Excess group delay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d74b685-ba49-4b59-bd07-eb5869cbe773','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d74b685-ba49-4b59-bd07-eb5869cbe773') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d74b685-ba49-4b59-bd07-eb5869cbe773');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e063edc5-cf45-4e7e-8d45-f58c527b2baa','Excess-phase response','The phase left over after subtracting a system''s minimum-phase response (derived from its magnitude via the Hilbert transform) from its total measured phase. It isolates non-minimum-phase content, which for a pure delay appears as phase falling linearly with frequency.','Every system shifts the timing, or phase, of a signal. Some of that shift is fixed by the frequency shape. Excess phase is what remains after removing that fixed part. It exposes pure delay and other timing quirks. A simple delay shows up as phase that drops in a straight line.','It reveals whether a device or loudspeaker behaves as minimum phase or carries extra delay and all-pass effects, which matters for correction and time alignment.','A technician derives the minimum-phase curve from a driver''s magnitude, subtracts it from the measured phase, and finds a straight sloped excess-phase line indicating a pure delay; excess phase is phi_excess = phi_total - phi_min.','Phase and Delay',ARRAY['Excess group delay','Dual-channel measurement','Gated measurement','Higher-order impulse response']::text[],ARRAY['Assuming all systems are minimum phase, so excess phase should be zero.','Confusing a straight-line excess phase (a delay) with a real phase problem.','Deriving minimum phase from a magnitude that is not gated to be reflection-free.']::text[],ARRAY['Checking if a loudspeaker can be corrected by minimum-phase EQ.','Separating flight-time delay from true phase distortion.','Evaluating an all-pass filter''s phase behavior.']::text[],'Advanced','phi_excess(omega) = phi_total(omega) - phi_min(omega)','The excess-phase response equals the total measured phase minus the minimum-phase response computed from the magnitude, leaving only non-minimum-phase and pure-delay behavior.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Excess-phase response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e063edc5-cf45-4e7e-8d45-f58c527b2baa','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e063edc5-cf45-4e7e-8d45-f58c527b2baa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e063edc5-cf45-4e7e-8d45-f58c527b2baa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f57d87d0-19af-488a-97a7-28e155efdb91','Exchange rate','In occupational noise dosimetry, the number of decibels by which the sound level may rise while the permitted exposure time is halved (or must fall while it doubles). United States OSHA rules use a 5 dB exchange rate, while NIOSH and ISO 1999 use a 3 dB (equal-energy) exchange rate.','Louder noise is safe for a shorter time. The exchange rate sets how that trade works. With a 3 decibel rate, every 3 decibel rise cuts the safe time in half. Some United States rules use a 5 decibel rate instead. Hearing scientists prefer the 3 decibel, equal-energy rule.','It defines how loudness and duration trade off when calculating a worker''s daily noise dose and allowable exposure time.','Under NIOSH''s 3 dB rate with an 85 dBA criterion for 8 hours, allowed time halves to 4 hours at 88 dBA and 2 hours at 91 dBA; allowed time T = 8 / 2^((L - L_c)/q) hours.','Noise Exposure',ARRAY['Event sound level','Exponential time weighting','Exceedance level','Fractional-octave-band level']::text[],ARRAY['UNSAFE: Assuming the OSHA 5 dB rate protects hearing as well as the 3 dB rate; the 3 dB equal-energy rule is the health-based standard and is more protective at high levels.','Mixing a 3 dB exchange rate with a criterion level meant for a 5 dB rate.','Treating the exchange rate as the meter''s per-doubling display change rather than a dose rule.']::text[],ARRAY['Setting stage-crew rotation limits at a loud concert.','Programming a noise dosimeter for a factory hearing program.','Comparing OSHA and NIOSH dose results for the same shift.']::text[],'Intermediate','T = 8 / 2^((L - L_c)/q) hours;  Dose = 100 * sum(C_i / T_i)','Allowed exposure time equals eight hours divided by two raised to the level above the criterion divided by the exchange rate, and daily dose is one hundred times the sum of actual times divided by allowed times.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exchange rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f57d87d0-19af-488a-97a7-28e155efdb91','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f57d87d0-19af-488a-97a7-28e155efdb91') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f57d87d0-19af-488a-97a7-28e155efdb91');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '61c24a8b-ad98-46eb-87c8-e8352814851e','Excursion distortion','Nonlinear distortion in a loudspeaker driver caused by large diaphragm and voice-coil displacement, where the motor force factor Bl(x), suspension compliance Cms(x), and coil inductance Le(x) all vary with position. These position-dependent parameters generate harmonic and intermodulation products that grow as excursion increases.','When a speaker cone moves far, its parts stop behaving evenly. The motor strength and the springiness change with cone position. This uneven behavior bends the signal and adds unwanted tones. The distortion grows as the cone swings wider. It is worst at low frequencies and high volume.','It explains why loudspeaker distortion rises steeply at high drive levels and low frequencies, guiding driver design and safe operating limits.','Using a laser and analyzer, a technician measures a woofer''s distortion doubling as excursion goes from 2 mm to 6 mm, tracing it to a falling force factor Bl(x) away from the coil''s rest position.','Loudspeaker Distortion',ARRAY['Excursion-limited output','Flux modulation distortion','Higher-order harmonic distortion','Dynamic intermodulation distortion']::text[],ARRAY['Blaming amplifier clipping for distortion that is really large-signal driver excursion.','Assuming a driver is linear right up to its mechanical limit.','Ignoring that a shifted rest position (offset) makes even-order distortion worse.']::text[],ARRAY['Diagnosing bass distortion in a small sealed subwoofer.','Choosing a driver''s usable output for a design.','Explaining why low notes distort before high notes.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Excursion distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '61c24a8b-ad98-46eb-87c8-e8352814851e','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='61c24a8b-ad98-46eb-87c8-e8352814851e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='61c24a8b-ad98-46eb-87c8-e8352814851e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1219634d-d5c4-41c8-b190-81aee9a4320c','Excursion-limited output','The maximum acoustic output a driver can produce before its diaphragm reaches the linear excursion limit (Xmax), beyond which distortion rises sharply. Because radiated pressure from a piston scales with volume displacement and the square of frequency, this limit sets the usable low-frequency maximum sound pressure level.','A speaker cone can only move so far cleanly. That limit is called maximum linear excursion. Once the cone reaches it, output cannot grow without heavy distortion. This sets the loudest clean bass a driver can make. Bigger cones and longer travel raise this ceiling.','It defines the clean low-frequency headroom of a driver, since bass output is limited by how much air the cone can move, not by heat.','For a driver with cone area Sd = 0.02 m^2 and Xmax = 5 mm, volume displacement Vd = Sd*Xmax = 100 cm^3; half-space peak pressure follows p ~= rho0*Sd*Xmax*(2*pi*f)^2 / (2*pi*r), so output falls fast as frequency drops.','Loudspeaker Output',ARRAY['Excursion distortion','Far-field measurement','Half-space measurement','Flux modulation distortion']::text[],ARRAY['Assuming more amplifier power always yields more clean bass past Xmax.','Confusing the thermal power limit with the excursion (displacement) limit.','Forgetting that maximum clean output falls by about 12 dB per octave as frequency drops.']::text[],ARRAY['Sizing a subwoofer for a target maximum bass level.','Setting a limiter to protect a driver from over-excursion.','Comparing two woofers by their volume displacement.']::text[],'Advanced','V_d = S_d * X_max;   p(r) ~= rho0 * S_d * X_max * (2*pi*f)^2 / (2*pi*r)   (half-space)','Peak volume displacement equals cone area times maximum linear excursion, and the excursion-limited half-space pressure grows with the square of frequency, so maximum clean output drops steeply toward low frequencies.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Excursion-limited output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1219634d-d5c4-41c8-b190-81aee9a4320c','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1219634d-d5c4-41c8-b190-81aee9a4320c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1219634d-d5c4-41c8-b190-81aee9a4320c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b133aa9d-d6d8-45a1-bed6-c80696fb90ea','Exponential time weighting','The running exponential average a sound level meter applies to the squared signal before displaying level, giving recent sound more weight than older sound. Standard settings are Fast (F), with a 125 ms time constant, and Slow (S), with a 1 s time constant, as defined in IEC 61672.','A sound level meter smooths the reading so it does not jump wildly. It uses a running average that fades out older sound. Fast weighting reacts quickly, over about an eighth of a second. Slow weighting reacts gently, over about one second. Fast catches short peaks; Slow gives a steady number.','It sets how quickly the meter responds, letting the reading track brief sounds (Fast) or settle into a steady average (Slow).','A technician switches to Slow (1 s) to get a stable reading of steady machine noise, then to Fast (125 ms) to see short peaks; the meter forms L = 10*log10 of the exponentially averaged squared pressure ratio.','Metering',ARRAY['Event sound level','Exceedance level','Exchange rate','Fractional-octave-band level']::text[],ARRAY['Confusing exponential time weighting (Fast/Slow) with frequency weighting (A/C/Z).','Expecting Fast and Slow to give the same reading on strongly fluctuating noise.','Using Fast when a steady average is needed, causing a jumpy, hard-to-read display.']::text[],ARRAY['Choosing Slow for a steady HVAC noise reading.','Using Fast to catch brief impact-noise peaks.','Setting a sound level meter for a compliance survey.']::text[],'Intermediate','y(t) = (1/tau) * integral_{-inf}^{t} p^2(xi) * e^{-(t-xi)/tau} dxi;  tau_F = 0.125 s, tau_S = 1 s','The weighted output is a running average of past squared pressure that fades exponentially with a time constant tau, equal to 125 milliseconds for Fast and one second for Slow.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exponential time weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b133aa9d-d6d8-45a1-bed6-c80696fb90ea','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b133aa9d-d6d8-45a1-bed6-c80696fb90ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b133aa9d-d6d8-45a1-bed6-c80696fb90ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '520df07c-5858-4cad-9bc5-c118ec2a9fc3','Far-field measurement','A measurement taken far enough from a source that it behaves like a single point: the wavefront is effectively spherical, and sound pressure follows the inverse-square law, dropping 6 dB for each doubling of distance. The required distance is large compared with both the source''s largest dimension and the wavelength.','Close to a loudspeaker, the sound is uneven and hard to judge. Far enough away, it acts like it comes from one point. There, level drops a steady 6 decibels each time you double the distance. This far region gives a clean, repeatable measurement. You must be well past the box size and a wavelength.','It ensures the measured response represents how the source really radiates to a listener, free of near-field interference between parts of the source.','For a 0.3 m tall loudspeaker a technician measures at 2 m, well beyond the source size, and confirms far field by checking that moving from 1 m to 2 m drops the level by about 6 dB.','Measurement Setup',ARRAY['Half-space measurement','Full-space measurement','Enveloping surface','Gated measurement']::text[],ARRAY['Measuring too close, so different drivers have not yet blended into one source.','Assuming any large distance is far field even for very low frequencies.','Ignoring room reflections that dominate once you move far from the source.']::text[],ARRAY['Measuring a loudspeaker''s frequency response for a spec sheet.','Checking coverage from a line array at audience distance.','Verifying inverse-square behavior outdoors.']::text[],'Intermediate','r >> D and r >> lambda;  Delta L = -20*log10(r2/r1) = -6 dB per distance doubling','The measurement distance must be much larger than the source size and the wavelength, and in the far field the level falls twenty log of the distance ratio, which is six decibels per doubling.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Far-field measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '520df07c-5858-4cad-9bc5-c118ec2a9fc3','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='520df07c-5858-4cad-9bc5-c118ec2a9fc3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='520df07c-5858-4cad-9bc5-c118ec2a9fc3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '13099e08-c2c1-4df7-92a2-7dc7ef86d9dc','Farina harmonic separation','A technique using an exponential (logarithmic) sine sweep and an inverse filter so that, after deconvolution, the linear impulse response and each harmonic distortion order appear as separate impulse responses spaced along the time axis. Each harmonic order N appears advanced in time before the linear response, allowing impulse response and distortion to be captured at once.','This method sweeps a tone smoothly from low to high in a special way. After processing, the clean response and the distortion tones land at different times. Each distortion order sits at its own spot before the main response. So one sweep gives both the impulse response and the distortion. Angelo Farina published this in 2000.','It lets a single sweep measurement yield both a room or device impulse response and its individual harmonic distortion components, cleanly separated in time.','A technician runs an exponential sweep from 20 Hz to 20 kHz over 10 s; the second harmonic response appears advanced by Delta_t = T*ln(2)/ln(f2/f1) = 10*0.693/6.908 = about 1.0 s before the linear impulse.','Distortion Analysis',ARRAY['Higher-order impulse response','Hammerstein model','Harmonic distortion profile','Higher-order harmonic distortion']::text[],ARRAY['Using a linear sweep, which does not place harmonics at fixed time offsets.','Making the sweep too short, so harmonic responses overlap the linear one.','Forgetting that background noise still limits the distortion floor you can see.']::text[],ARRAY['Measuring room impulse response and loudspeaker distortion together.','Separating a driver''s 2nd and 3rd harmonic behavior.','Characterizing a nonlinear device with one sweep.']::text[],'Advanced','Delta_t_N = T * ln(N) / ln(f2/f1)','For an exponential sweep, the impulse response of the Nth harmonic appears advanced in time by the sweep duration times the natural log of the harmonic order divided by the natural log of the end-to-start frequency ratio.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Farina harmonic separation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '13099e08-c2c1-4df7-92a2-7dc7ef86d9dc','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='13099e08-c2c1-4df7-92a2-7dc7ef86d9dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='13099e08-c2c1-4df7-92a2-7dc7ef86d9dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd34e7b6-07e6-4f28-93a9-7a58661a5b16','Field reactivity','A property of a sound field describing how much acoustic energy oscillates back and forth locally (reactive intensity) rather than flowing away as net radiated power (active intensity). It is high in the near field of sources and in strong standing-wave fields, and it limits the accuracy of sound intensity measurements.','In some places sound energy just sloshes back and forth without going anywhere. In others it flows steadily outward. Field reactivity measures how much of the first kind is present. It is strong close to a source or between reflecting walls. High reactivity makes sound intensity harder to measure accurately.','It signals where sound intensity measurements are trustworthy, because a highly reactive field can overwhelm the small net energy flow the probe is trying to detect.','Working near a machine, a technician checks the pressure-intensity index; a large gap between the pressure level and the intensity level warns of a highly reactive field, so measurements are moved farther out or judged unreliable.','Sound Intensity',ARRAY['Enveloping surface','Half-space measurement','Hemispherical measurement','Near-field measurement']::text[],ARRAY['Assuming sound pressure equals net energy flow in a reactive field; the two differ near sources.','Trusting intensity results in a strongly reactive field without checking the pressure-intensity index.','Confusing local reactive energy with true radiated sound power.']::text[],ARRAY['Judging whether to trust an intensity probe near a noisy motor.','Setting a valid measurement distance for sound power by intensity.','Explaining odd readings inside a small reverberant enclosure.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Field reactivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd34e7b6-07e6-4f28-93a9-7a58661a5b16','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd34e7b6-07e6-4f28-93a9-7a58661a5b16') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd34e7b6-07e6-4f28-93a9-7a58661a5b16');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2b89299c-42ed-48cd-b117-12f7ed6806fe','Flux modulation distortion','Loudspeaker distortion arising when the alternating voice-coil current modulates the static magnetic flux in the motor gap, dynamically changing the force factor and coil inductance. This produces nonlinear and intermodulation products and is reduced by conductive shorting rings or copper caps on the pole piece.','A speaker motor uses a fixed magnetic field to push the coil. But the coil''s own changing current disturbs that field. This back-and-forth disturbance bends the output and adds unwanted tones. Makers fight it with copper rings or caps in the motor. These stabilize the magnetic field.','It explains a specific source of loudspeaker distortion tied to the motor''s magnetic circuit, guiding designs that stabilize the gap flux.','A technician compares two woofers and finds the one with a copper shorting ring shows markedly lower high-frequency intermodulation distortion, confirming reduced flux modulation.','Loudspeaker Distortion',ARRAY['Excursion distortion','Excursion-limited output','Higher-order harmonic distortion','Dynamic intermodulation distortion']::text[],ARRAY['Confusing flux modulation with heat-related power compression.','Assuming only cone excursion causes driver distortion.','Overlooking that a shorting ring also lowers and stabilizes voice-coil inductance.']::text[],ARRAY['Comparing motor designs for a low-distortion woofer.','Explaining why some drivers add grit at high output.','Evaluating the benefit of a copper pole cap.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flux modulation distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2b89299c-42ed-48cd-b117-12f7ed6806fe','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2b89299c-42ed-48cd-b117-12f7ed6806fe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2b89299c-42ed-48cd-b117-12f7ed6806fe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f341cb02-0f0b-45e7-b25a-32bc52f6f9c4','Fractional-octave-band level','The sound level measured within a fractional-octave band, a filter whose bandwidth is a constant percentage of its center frequency, as specified in IEC 61260. Bands use a base-ten octave ratio of 10^0.3 (about 1.995) or a base-two ratio of 2; a one-third-octave band has a ratio of about 1.259, and each band''s center frequency is the geometric mean of its edges.','A spectrum can be split into bands that get wider at higher frequencies. Each band covers a fixed fraction of an octave, like one third. This matches how we hear, since our ears also work in ratios. The band''s center sits at the geometric middle of its edges. The reference band centers on one kilohertz.','It presents sound in perceptually spaced bands, giving useful spectral detail with fewer bands than a fixed-width analysis and matching how hearing groups frequencies.','A technician runs a one-third-octave analysis to find a room resonance; the band centered on 125 Hz spans about 111-140 Hz, since edges are the center times 10^(1/20) up and down.','Spectrum Analysis',ARRAY['Event sound level','Exceedance level','Exponential time weighting','Constant-percentage bandwidth']::text[],ARRAY['Reading fractional-octave bands as equal-width in hertz; they widen with frequency.','Mixing base-two and base-ten center frequencies without noticing the small difference.','Forgetting that a summed band level should combine bands on an energy basis.']::text[],ARRAY['Using a 1/3-octave real-time analyzer to tune a room.','Measuring noise emission spectra for a report.','Setting graphic-EQ bands to fractional-octave centers.']::text[],'Intermediate','f_m(x) = f_r * G^(x/b);  octave G = 10^0.3 (~1.995) or 2;  1/3-octave ratio = 2^(1/3) ~= 1.2599;  f_m = sqrt(f1*f2)','A band''s center frequency equals the one-kilohertz reference times the octave ratio raised to the band index over the fraction denominator, and the center frequency is the geometric mean of the lower and upper band edges.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fractional-octave-band level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f341cb02-0f0b-45e7-b25a-32bc52f6f9c4','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f341cb02-0f0b-45e7-b25a-32bc52f6f9c4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f341cb02-0f0b-45e7-b25a-32bc52f6f9c4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '03ae2f9e-9efc-4118-b2d3-2864555c75ca','Full-space measurement','A free-field measurement in which the source radiates into a complete sphere of 4*pi steradians, with no nearby reflecting surfaces, as in an anechoic chamber with the source suspended in space. It represents radiation into full space and contrasts with half-space (2*pi) measurements over a reflecting plane.','In a full-space measurement, sound spreads out in every direction. Nothing nearby reflects it back. This is like hanging a speaker in the open air, far from walls and floor. It is the cleanest baseline for how a source radiates. It differs from placing the source on a floor or wall.','It gives a reference radiation condition with no boundary reinforcement, so the measured response reflects the source alone.','In an anechoic chamber a technician measures a suspended loudspeaker in full space, then notes that moving the same source flush to a wall (half space) would add up to about 6 dB of low-frequency boundary gain.','Measurement Setup',ARRAY['Half-space measurement','Hemispherical measurement','Enveloping surface','Far-field measurement']::text[],ARRAY['Comparing a full-space result directly with a half-space one without accounting for boundary gain.','Assuming a normal room approximates free full space at low frequencies.','Forgetting that suspending a source changes its low-frequency loading versus floor placement.']::text[],ARRAY['Measuring a loudspeaker''s true free-field response.','Establishing a reference before predicting in-room behavior.','Testing a driver isolated from all boundaries.']::text[],'Intermediate','S = 4*pi*r^2 (full space);  directivity factor Q = 1 for an omni source in free space','In full space the sound spreads over a sphere whose area is four pi times the radius squared, and an omnidirectional source there has a directivity factor of one.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Full-space measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '03ae2f9e-9efc-4118-b2d3-2864555c75ca','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='03ae2f9e-9efc-4118-b2d3-2864555c75ca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='03ae2f9e-9efc-4118-b2d3-2864555c75ca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa1d091a-bfee-4e69-846c-e499e15fa270','Gated measurement','A technique that time-windows a measured impulse response, keeping only the direct sound and discarding later room reflections, to produce a quasi-anechoic (reflection-free) frequency response in an ordinary room. The window length sets the lowest valid frequency, roughly the reciprocal of the gate time.','In a normal room, reflections bounce back and mess up a measurement. A gated measurement cuts them off in time. It keeps only the first, direct sound. This mimics a room with no echoes. But a short gate loses low-frequency detail. The shortest usable frequency is about one over the gate time.','It lets a technician measure a loudspeaker''s direct response in a real room without an anechoic chamber, by rejecting reflections in the time domain.','With reflections arriving 5 ms after the direct sound, a technician sets a 5 ms gate; the result is valid down to about f_min = 1/0.005 = 200 Hz, below which data is unreliable.','Measurement Technique',ARRAY['Far-field measurement','Dual-channel measurement','Excess-phase response','Enveloping surface']::text[],ARRAY['Trusting gated data below the frequency set by the gate length.','Setting the gate so long that a reflection sneaks inside the window.','Forgetting that a bigger room allows a longer, lower-frequency-valid gate.']::text[],ARRAY['Measuring a loudspeaker''s response in a normal control room.','Getting a quasi-anechoic curve without a chamber.','Separating direct sound from a strong floor bounce.']::text[],'Intermediate','f_min ~= 1 / t_gate','The lowest reliable frequency of a gated measurement is approximately one divided by the gate time, so a shorter reflection-free window loses more low-frequency resolution.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gated measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa1d091a-bfee-4e69-846c-e499e15fa270','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa1d091a-bfee-4e69-846c-e499e15fa270') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa1d091a-bfee-4e69-846c-e499e15fa270');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6dd8079f-07fc-4cd6-9abd-610123ccf132','Guard band','An unused margin of frequency (or level) deliberately left between adjacent bands, channels, or signals to prevent overlap and interference. In audio measurement it appears as empty analysis bins placed around test tones, or as the transition region kept clear so filtering, leakage, or aliasing artifacts do not corrupt a result.','A guard band is empty space left on purpose. It sits between two signals or bands so they do not bleed into each other. In measurements, it keeps clear room around a test tone. That way, filter effects and spillover do not spoil the reading. It is a safety gap.','It protects a wanted signal or measurement band from spilling into or being contaminated by a neighboring one.','In a multitone distortion test a technician leaves several empty analysis bins as a guard band around each tone, so spectral leakage does not hide the small distortion products between the tones.','Spectrum Analysis',ARRAY['Fractional-octave-band level','Higher-order harmonic distortion','Harmonic distortion profile','Dual-channel measurement']::text[],ARRAY['Making the guard band so narrow that leakage still corrupts the result.','Assuming a guard band adds information; it is intentionally empty.','Confusing the measurement guard band with a filter''s passband.']::text[],ARRAY['Designing a multitone signal for distortion testing.','Spacing test tones so their products stay visible.','Leaving margin around a band edge to avoid filter roll-off.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Guard band');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6dd8079f-07fc-4cd6-9abd-610123ccf132','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6dd8079f-07fc-4cd6-9abd-610123ccf132') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6dd8079f-07fc-4cd6-9abd-610123ccf132');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd4b840c2-e60a-474f-a8f6-0160da5f231b','H1 estimator','A frequency response function estimator computed as the input-output cross-spectrum divided by the input auto-spectrum, H1 = Gxy/Gxx. Averaging drives uncorrelated noise on the output toward zero, so H1 is the preferred estimator when noise contaminates the output rather than the input.','The H1 estimator is a way to find how a system changes a signal. It divides one measured spectrum by another. Averaging many runs cancels random noise at the output. So H1 works best when the mess is on the output side. It is the most common choice in practice.','It gives an accurate frequency response when the measurement noise appears mainly at the output, which is the usual case.','Measuring a filter with a noisy output stage, a technician averages many frames and uses H1 = Gxy/Gxx; the result underestimates gain near sharp resonances if input noise is also present.','FRF Estimation',ARRAY['H2 estimator','Hv estimator','Dual-channel measurement','Excess-phase response']::text[],ARRAY['Using H1 when noise is actually on the input, which biases the estimate low at resonances.','Interpreting H1 without checking coherence for measurement quality.','Confusing the input auto-spectrum Gxx with the output auto-spectrum Gyy.']::text[],ARRAY['Measuring a device''s frequency response with a noisy output.','Standard transfer-function measurement in an FFT analyzer.','Modal testing where response sensors are noisy.']::text[],'Advanced','H1(f) = Gxy(f) / Gxx(f)','The H1 estimator equals the cross-spectrum of input and output divided by the auto-spectrum of the input.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='H1 estimator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd4b840c2-e60a-474f-a8f6-0160da5f231b','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d4b840c2-e60a-474f-a8f6-0160da5f231b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d4b840c2-e60a-474f-a8f6-0160da5f231b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ae4db30-600f-4a60-b6aa-d1d8c62ae3aa','H2 estimator','A frequency response function estimator computed as the output auto-spectrum divided by the output-input cross-spectrum, H2 = Gyy/Gyx. Averaging drives uncorrelated noise on the input toward zero, so H2 is preferred when noise contaminates the input rather than the output.','The H2 estimator is another way to find a system''s response. It divides the output spectrum by a cross spectrum. Averaging cancels random noise at the input side. So H2 works best when the mess is on the input. It tends to overstate sharp peaks if output noise is present.','It gives an accurate frequency response when the measurement noise appears mainly at the input, complementing the H1 estimator.','With a noisy excitation signal, a technician averages frames and uses H2 = Gyy/Gyx; near a sharp resonance H2 reads higher than H1, and the true response lies between them.','FRF Estimation',ARRAY['H1 estimator','Hv estimator','Dual-channel measurement','Excess-phase response']::text[],ARRAY['Using H2 when noise is actually on the output, which biases the estimate high at resonances.','Assuming H1 and H2 should always agree; they differ where noise is significant.','Ignoring coherence, which reveals how much H1 and H2 will diverge.']::text[],ARRAY['Measuring response when the excitation is noisy.','Cross-checking an H1 result near resonances.','Modal testing where the force sensor is noisy.']::text[],'Advanced','H2(f) = Gyy(f) / Gyx(f)','The H2 estimator equals the auto-spectrum of the output divided by the cross-spectrum of output and input.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='H2 estimator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ae4db30-600f-4a60-b6aa-d1d8c62ae3aa','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ae4db30-600f-4a60-b6aa-d1d8c62ae3aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ae4db30-600f-4a60-b6aa-d1d8c62ae3aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39619214-3e8a-4ce2-87d2-f3b750d68833','Half-space measurement','A measurement in which the source radiates into a half sphere of 2*pi steradians, bounded by one large reflecting plane, such as a loudspeaker flush-mounted in a wall or placed on a hard floor. It is the standard geometry for engineering-grade sound power methods over a reflecting plane.','In a half-space measurement, sound spreads into half a sphere. One flat surface, like a floor or wall, blocks the other half. This is like a speaker set into a wall. The boundary adds low-frequency energy compared to open air. Many sound-power tests use this setup.','It provides a repeatable radiation condition using a single reflecting plane, matching how many sources are actually used and mounted.','Per ISO 3744 a technician measures a source on a hard floor over a hemispherical surface of radius r and computes sound power using surface area S = 2*pi*r^2.','Measurement Setup',ARRAY['Full-space measurement','Hemispherical measurement','Enveloping surface','Far-field measurement']::text[],ARRAY['Treating a half-space result as identical to a full-space one.','Placing the source above the plane so it is neither true half nor full space.','Using a reflecting plane that is too small to enforce half-space loading at low frequencies.']::text[],ARRAY['Measuring machine sound power over a hard floor.','Testing a flush wall-mounted loudspeaker.','Following ISO 3744 in a hemi-anechoic room.']::text[],'Intermediate','S = 2*pi*r^2 (half space);  L_W = L_p_bar + 10*log10(2*pi*r^2 / S0)','In half space the measurement surface is a hemisphere of area two pi times radius squared, and sound power level is the surface-averaged pressure level plus ten log of that area over one square meter.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Half-space measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39619214-3e8a-4ce2-87d2-f3b750d68833','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39619214-3e8a-4ce2-87d2-f3b750d68833') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39619214-3e8a-4ce2-87d2-f3b750d68833');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '060d75e8-675c-4ec1-a06c-c414805ffb8e','Hammerstein model','A block-oriented model of a nonlinear system consisting of a static (memoryless) nonlinearity followed by a linear time-invariant filter. In its generalized form each harmonic order is assigned its own linear filter, which can be identified directly from an exponential sine-sweep measurement.','The Hammerstein model describes a system that bends signals in two steps. First, a fixed nonlinear stage reshapes the signal instantly. Then a normal filter colors it over time. A generalized version gives each distortion order its own filter. Engineers fit these from a single sweep test.','It provides a compact, identifiable way to represent and predict a nonlinear device''s behavior, especially for loudspeakers and amplifiers.','From one exponential sweep a technician extracts a linear filter for the fundamental and separate filters for the 2nd and 3rd harmonics, building a generalized Hammerstein model of a driver''s distortion.','Nonlinear Modeling',ARRAY['Farina harmonic separation','Higher-order impulse response','Harmonic distortion profile','Higher-order harmonic distortion']::text[],ARRAY['Confusing the Hammerstein order (nonlinearity then filter) with the Wiener order (filter then nonlinearity).','Assuming one model fits at all drive levels; parameters vary with amplitude.','Expecting it to capture memory effects inside the nonlinearity itself.']::text[],ARRAY['Modeling loudspeaker distortion for correction.','Emulating a nonlinear amplifier or effect.','Identifying harmonic filters from a sweep measurement.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hammerstein model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '060d75e8-675c-4ec1-a06c-c414805ffb8e','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='060d75e8-675c-4ec1-a06c-c414805ffb8e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='060d75e8-675c-4ec1-a06c-c414805ffb8e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b25e5349-6f6b-43af-a45b-badd2c82cb4b','Harmonic distortion profile','The set of individual harmonic distortion components (second, third, fourth order, and higher) of a device, shown as amplitudes versus frequency or drive level rather than as a single total figure. Each component dn is the ratio of that harmonic''s level to the fundamental.','A device can add many extra tones, called harmonics. A single distortion number hides their pattern. The harmonic distortion profile shows each one separately. You can see which harmonics dominate and how they change with level. This tells more about the sound than one total figure.','It characterizes the character of distortion, since low even harmonics sound different from high odd ones, information a single total number loses.','Profiling an amplifier at 1 kHz, a technician finds the third harmonic dominant at -60 dB (0.1 percent) while higher orders stay below -80 dB, where dn = A_n / A_1.','Distortion',ARRAY['Higher-order harmonic distortion','Total harmonic distortion','Farina harmonic separation','Dynamic intermodulation distortion']::text[],ARRAY['Judging audibility from total distortion alone, ignoring which harmonics are present.','Assuming all harmonics fall smoothly with order; some devices favor specific ones.','Comparing profiles taken at different drive levels as if equivalent.']::text[],ARRAY['Comparing the distortion character of two amplifiers.','Diagnosing which harmonic a loudspeaker emphasizes.','Documenting distortion versus level for a spec sheet.']::text[],'Intermediate','d_n = A_n / A_1  (each harmonic relative to the fundamental)','Each harmonic distortion component equals the amplitude of that harmonic divided by the amplitude of the fundamental, plotted across order, frequency, or level.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic distortion profile');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b25e5349-6f6b-43af-a45b-badd2c82cb4b','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b25e5349-6f6b-43af-a45b-badd2c82cb4b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b25e5349-6f6b-43af-a45b-badd2c82cb4b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '40abaa0e-ac30-4879-8d02-e4b1f690e0d7','Hemispherical measurement','A sound-power method that samples sound pressure at defined microphone positions on a hemispherical enveloping surface centered on a source that sits on a reflecting plane. The mean surface level plus a term for the hemisphere area gives the radiated sound power.','This method wraps a dome-shaped surface over a source on the floor. Microphones sit at set points on that dome. You average their readings. Then you add a term based on the dome''s size. This gives the total sound power. It is a common way to rate machine noise.','It turns a set of pressure readings over a hemisphere into a single sound-power figure for a source over a reflecting plane.','Following ISO 3744 with a 2 m hemisphere, a technician averages the microphone levels and adds 10*log10(2*pi*2^2 / 1) to convert the surface-average pressure into sound power.','Sound Power',ARRAY['Enveloping surface','Half-space measurement','Full-space measurement','Far-field measurement']::text[],ARRAY['Using too few microphone points to represent the hemisphere.','Forgetting the reflecting plane must be hard and large enough.','Confusing the hemisphere radius with the far-field distance requirement.']::text[],ARRAY['Rating an appliance''s sound power over a hard floor.','Measuring outdoor equipment noise on a reflecting surface.','Following ISO 3744 in a hemi-anechoic room.']::text[],'Intermediate','S = 2*pi*r^2;  L_W = L_p_bar + 10*log10(S/S0),  S0 = 1 m^2','The hemisphere area is two pi times the radius squared, and sound power level equals the surface-averaged sound pressure level plus ten log of that area divided by one square meter.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hemispherical measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '40abaa0e-ac30-4879-8d02-e4b1f690e0d7','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='40abaa0e-ac30-4879-8d02-e4b1f690e0d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='40abaa0e-ac30-4879-8d02-e4b1f690e0d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a50bd5a-111f-4ab3-bb50-ae60e0f4f608','Higher-order harmonic distortion','Distortion energy carried in harmonics above the second and third order, such as the fourth, fifth, and beyond. Per unit energy these high-order components are often more audible and objectionable than low-order harmonics because they fall outside the masking region of the fundamental.','Distortion adds extra tones above the original. The lowest of these, like the second and third, blend in fairly gently. The higher ones sit farther away in pitch. Our ears mask them less, so they sound harsher. A little high-order distortion can be more annoying than more low-order distortion.','It highlights that the order of harmonics, not just the total amount, governs how harsh distortion sounds, guiding design and evaluation.','A technician sees two drivers with equal total distortion, but the one with more fifth- and seventh-order energy sounds harsher; a weighted metric emphasizing high orders confirms it.','Distortion',ARRAY['Harmonic distortion profile','Higher-order impulse response','Excursion distortion','Flux modulation distortion']::text[],ARRAY['Judging harshness by total distortion while ignoring harmonic order.','Assuming higher harmonics are always tiny and negligible.','Forgetting that high-order harmonics of low tones can land in a sensitive hearing range.']::text[],ARRAY['Explaining why two amplifiers with equal THD sound different.','Evaluating driver distortion for perceived harshness.','Setting weighting in a perceptual distortion metric.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Higher-order harmonic distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a50bd5a-111f-4ab3-bb50-ae60e0f4f608','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a50bd5a-111f-4ab3-bb50-ae60e0f4f608') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a50bd5a-111f-4ab3-bb50-ae60e0f4f608');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '930e2d0a-16c4-4092-b6e3-8d564465d8d9','Higher-order impulse response','In the exponential-sweep and Volterra-kernel framework, the separate impulse response associated with each harmonic order extracted from a single measurement. The Nth-order impulse response describes the linear filtering applied to the system''s Nth harmonic component.','One sweep test can be split into several impulse responses. The first is the clean, linear one. The others belong to each distortion order. Each shows how the system filters that harmonic over time. Together they map the device''s nonlinear behavior. This comes from the sweep method.','It captures how a nonlinear system shapes each distortion order in time, enabling detailed modeling and correction beyond a single linear response.','From an exponential sweep a technician isolates the second-order impulse response, sees it decays slower than the linear one, and uses it to model the driver''s second-harmonic behavior.','Distortion Analysis',ARRAY['Farina harmonic separation','Hammerstein model','Higher-order harmonic distortion','Harmonic distortion profile']::text[],ARRAY['Confusing the higher-order impulse responses with echoes in the linear response.','Using a linear sweep, which cannot cleanly separate the orders.','Assuming the second-order impulse response captures all even-harmonic behavior at every level.']::text[],ARRAY['Building a nonlinear model of a loudspeaker.','Studying how each harmonic order rings in time.','Separating distortion orders from one sweep.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Higher-order impulse response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '930e2d0a-16c4-4092-b6e3-8d564465d8d9','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='930e2d0a-16c4-4092-b6e3-8d564465d8d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='930e2d0a-16c4-4092-b6e3-8d564465d8d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b7a24d40-e4a0-40b7-b9a6-01b1623f198e','Holographic measurement','Nearfield acoustic holography: measuring the complex sound pressure over a surface close to a source and using spatial Fourier transforms to reconstruct the full three-dimensional sound field, including surface velocity and radiated power. It maps exactly where and how a source radiates.','This method takes many close-up sound readings across a grid near a source. A computer then rebuilds the whole sound field from them. It can show which parts of a surface radiate sound. It even reveals detail finer than a wavelength. Engineers use it to find noisy spots on machines.','It locates and visualizes the radiating regions of a source and reconstructs its full field, supporting noise-source identification and radiation studies.','A technician scans a pressure grid a few centimeters from a vibrating panel, then reconstructs the surface velocity map to pinpoint the loudest radiating area for treatment.','Sound Field Imaging',ARRAY['Enveloping surface','Field reactivity','Half-space measurement','Near-field measurement']::text[],ARRAY['Scanning too far from the source, losing the near-field detail that gives high resolution.','Using too coarse a grid, which aliases the reconstructed field.','Assuming amplitude alone suffices; the method needs complex (phase-referenced) data.']::text[],ARRAY['Finding the loudest radiating spot on a machine casing.','Mapping a loudspeaker cone''s vibration pattern.','Studying how a structure radiates noise.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Holographic measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b7a24d40-e4a0-40b7-b9a6-01b1623f198e','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b7a24d40-e4a0-40b7-b9a6-01b1623f198e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b7a24d40-e4a0-40b7-b9a6-01b1623f198e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0611433d-63e8-43dd-b22b-03ed873e79e0','Hv estimator','A frequency response function estimator that minimizes the effect of noise on both the input and the output, unlike H1 (output noise) and H2 (input noise). It is computed by a total-least-squares solution, taking the eigenvector tied to the smallest eigenvalue of the spectral matrix, and its result lies between H1 and H2.','Real measurements have noise on both sides at once. The Hv estimator handles that case. It balances the errors on input and output together. Math finds the best fit through a matrix method. Its answer sits between the H1 and H2 results. It is the fairest choice when both signals are noisy.','It gives a more accurate frequency response when both the input and output signals carry noise, a common real-world situation.','With noise on both the drive and response signals, a technician selects Hv; near a resonance it gives a value between H1 (lower) and H2 (higher), avoiding the bias of either.','FRF Estimation',ARRAY['H1 estimator','H2 estimator','Dual-channel measurement','Excess-phase response']::text[],ARRAY['Assuming Hv always differs greatly from H1; they nearly match when coherence is high.','Using Hv without enough averaging to make the spectral matrix reliable.','Confusing Hv (both-sides noise) with a simple average of H1 and H2.']::text[],ARRAY['Measuring response when both signals are noisy.','High-accuracy modal or acoustic transfer-function work.','Cross-checking H1 and H2 near resonances.']::text[],'Advanced','Hv = total-least-squares solution: eigenvector of smallest eigenvalue of the spectral matrix;  H1 <= Hv <= H2','The Hv estimator comes from a total-least-squares fit that finds the eigenvector of the smallest eigenvalue of the input-output spectral matrix, and its magnitude falls between the H1 and H2 estimates.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hv estimator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0611433d-63e8-43dd-b22b-03ed873e79e0','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0611433d-63e8-43dd-b22b-03ed873e79e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0611433d-63e8-43dd-b22b-03ed873e79e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '354b2e90-6f48-42d4-b0a9-ad4dcc09ea4d','Hysteresis error','A measurement error in which the output for a given input depends on whether the input is increasing or decreasing, so the upward and downward curves do not coincide. It is usually reported as the maximum difference between the two curves, expressed as a percentage of full-scale output.','Some instruments give a slightly different reading depending on direction. Going up, the value differs from coming down at the same input. This gap is the hysteresis error. It shows the device remembers its recent history. Engineers report the largest gap as a percentage of full scale.','It quantifies a repeatability limit of sensors and instruments, since a device with hysteresis cannot give one unique output per input.','Calibrating a pressure sensor, a technician records 2.01 V rising and 2.04 V falling at the same input; the hysteresis error is that 0.03 V gap divided by the full-scale span, times 100 percent.','Instrument Error',ARRAY['Guard band','Exponential time weighting','Dual-channel measurement','Fractional-octave-band level']::text[],ARRAY['Confusing hysteresis error with simple non-repeatability or random noise.','Measuring only one direction, so the error stays hidden.','Mixing hysteresis with nonlinearity error, which is a different specification.']::text[],ARRAY['Calibrating a sensor or transducer across its range.','Specifying the accuracy of a measurement instrument.','Diagnosing direction-dependent readings on a meter.']::text[],'Intermediate','Hysteresis (%) = max|y_up - y_down| / y_FS * 100','Hysteresis error equals the largest difference between the increasing and decreasing output curves at the same input, divided by the full-scale output, times one hundred percent.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hysteresis error');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '354b2e90-6f48-42d4-b0a9-ad4dcc09ea4d','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='354b2e90-6f48-42d4-b0a9-ad4dcc09ea4d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='354b2e90-6f48-42d4-b0a9-ad4dcc09ea4d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56cc93f4-238d-411c-8373-9e66f623d142','IEC noise','A shaped test signal for loudspeaker power and endurance testing: pink noise passed through the weighting filter specified in IEC 60268-1 and set to a crest factor of two (about 6 dB). Its spectrum approximates the long-term average of broadcast and music program material.','IEC noise is a special test noise for speakers. It starts as pink noise. A standard filter shapes it to act like real music. Its loudest peaks reach about twice the average. Engineers use it to test how much power a speaker can take.','It provides a repeatable, program-like signal so loudspeaker power-handling and endurance ratings can be compared fairly between products.','A technician drives a woofer with IEC noise at its rated wattage for a fixed time under IEC 60268-5; a crest factor of two means a 100 W average signal peaks near 400 W.','Test Signal',ARRAY['Pink noise','Crest factor','Power handling','M-Noise','Simulated program material']::text[],ARRAY['Confusing IEC noise with plain pink noise; IEC noise is additionally filtered to a program-like spectrum.','Assuming a crest factor of two means 3 dB; two times in voltage is about 6 dB.','UNSAFE: Feeding full-band IEC noise to a bare tweeter; without the crossover filtering the standard assumes, the driver can overheat and fail.']::text[],ARRAY['Rating a woofer''s long-term power handling on a test bench.','Comparing endurance specs between two subwoofers.','Setting a repeatable stress signal for production quality control.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='IEC noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56cc93f4-238d-411c-8373-9e66f623d142','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56cc93f4-238d-411c-8373-9e66f623d142') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56cc93f4-238d-411c-8373-9e66f623d142');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe2d47ae-a728-4a97-8408-ced285ec2c16','Impulse time weighting','A legacy exponential time weighting (''I'') for sound level meters, with a fast rise time constant of about 35 ms and a slow decay of roughly 2.9 dB/s, so brief transients are captured and held for reading. Defined in the older IEC 60651; it is not among the Fast and Slow weightings retained by IEC 61672.','Impulse weighting is an old meter speed setting. It reacts very fast to sudden sounds. Then it falls back slowly, so you can read the peak. It was made for short, sharp noises like hammer blows. Modern meters mostly use Fast and Slow instead.','It let an analog meter react quickly to short impulsive events and then hold the reading long enough to be read before slowly decaying.','A technician measuring a punch press might select Impulse weighting; the 35 ms rise catches the impact while the slow decay holds the reading long enough to note.','Time Weighting',ARRAY['Fast time weighting','Slow time weighting','Sound level meter','Peak sound level','Impulsiveness']::text[],ARRAY['Assuming Impulse weighting equals true peak; peak detection has no averaging time constant.','Using Impulse weighting for modern compliance work; most standards now specify Fast, Slow, or peak.','Thinking the rise and decay share one time constant; the rise is fast and the decay is slow.']::text[],ARRAY['Assessing impulsive machinery noise with an older meter.','Reading historical noise data logged with Impulse weighting.','Comparing legacy Impulse readings against modern Fast readings.']::text[],'Intermediate','L_I(t) = 10*log10( [ (1/tau) * integral_{-inf}^{t} p^2(xi) * e^{-(t-xi)/tau} dxi ] / p_0^2 ),  tau_rise ~= 35 ms','The impulse-weighted level equals ten times the base-ten log of an exponentially time-weighted mean-square pressure, using a 35 millisecond rise time constant, divided by the reference pressure squared.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impulse time weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe2d47ae-a728-4a97-8408-ced285ec2c16','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe2d47ae-a728-4a97-8408-ced285ec2c16') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe2d47ae-a728-4a97-8408-ced285ec2c16');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0079f83b-49cd-41da-9154-72ede8533186','Impulsiveness','The perceptual and measurable character of a sound dominated by short, high-crest transient events such as bangs, clatters, or hammering. In environmental noise assessment under ISO 1996, impulsive sounds receive a rating-level adjustment (a penalty) because they are judged more annoying than steady sound of equal energy.','Impulsiveness describes sound made of short, sharp bursts. Think of hammering or gunshots. These sounds feel more annoying than steady noise at the same level. Noise rules often add a penalty for them. It is both a feeling and something meters can score.','It captures how bursty a sound is, so annoyance-based noise limits can add a penalty for impulsive character.','Assessing a stamping plant under ISO 1996, a technician may add a fixed adjustment (commonly several decibels) to the measured level because the noise is impulsive.','Noise Character',ARRAY['Impulse time weighting','Crest factor','Rating level','Peak sound level','Loudness']::text[],ARRAY['Treating impulsiveness as the same as loudness; a quiet click can still be highly impulsive.','Assuming one universal penalty value; the exact adjustment depends on the standard or local rule.','Confusing impulsiveness with tonality; they are separate sound-character adjustments.']::text[],ARRAY['Rating community noise from a drop forge.','Deciding whether a complaint qualifies for an impulsive penalty.','Characterizing gunfire or fireworks noise.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impulsiveness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0079f83b-49cd-41da-9154-72ede8533186','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0079f83b-49cd-41da-9154-72ede8533186') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0079f83b-49cd-41da-9154-72ede8533186');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2852c22-e1da-479a-b786-9eeb78f9d723','Influence quantity','In metrology, a quantity that is not the measurand itself but affects the relationship between an instrument''s indication and the measurement result, such as ambient temperature, humidity, or supply voltage. Controlling or correcting for influence quantities is central to stating measurement uncertainty.','An influence quantity sways a measurement without being the thing you measure. Temperature and humidity are common examples. They change how the instrument reads. Careful technicians control or correct for them. This keeps results accurate.','It names the outside factors that bias a reading, so they can be held steady, corrected, or included in an uncertainty budget.','When calibrating a microphone, a technician records temperature, static pressure, and humidity as influence quantities and applies the datasheet corrections before reporting the sensitivity.','Metrology Concept',ARRAY['Measurand','Measurement function','Calibration','Measurement uncertainty','Reference conditions']::text[],ARRAY['Confusing an influence quantity with the measurand; the influence quantity is not what you set out to measure.','Ignoring environmental conditions during precision measurements.','Assuming a stated correction applies at all conditions rather than at defined reference conditions.']::text[],ARRAY['Calibrating a sound level meter across a temperature range.','Correcting a pressure microphone reading for barometric pressure.','Building an uncertainty budget for a laboratory measurement.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Influence quantity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2852c22-e1da-479a-b786-9eeb78f9d723','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2852c22-e1da-479a-b786-9eeb78f9d723') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2852c22-e1da-479a-b786-9eeb78f9d723');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9059e6cb-7563-491b-83cd-25cbc57071bd','Integrating sound-level meter','A sound level meter that accumulates sound energy over a measurement period to report sound exposure or sound exposure level, rather than an instantaneous level. It integrates the squared, frequency-weighted sound pressure over time.','This meter adds up sound energy over time. It reports a total dose, not a moment-by-moment level. One common result is sound exposure level. This suits short events like a passing train. The meter captures the whole event in one number.','It measures the total acoustic energy of an event, which suits single events such as vehicle pass-bys or blasts.','A technician measures a jet flyover and reads the A-weighted sound exposure level; that value normalizes the event''s energy to a one-second reference so events of different length can be compared.','Metering Instrument',ARRAY['Integrating-averaging sound-level meter','Sound exposure level','Equivalent continuous sound level','Sound level meter','Time weighting']::text[],ARRAY['Confusing sound exposure level with equivalent continuous level; the exposure level references one second, Leq references the whole period.','Assuming an integrating meter reports instantaneous sound pressure level.','Failing to set the measurement window so the entire event is captured.']::text[],ARRAY['Measuring aircraft flyover noise.','Quantifying a single blast or gunshot event.','Assessing a passing train''s noise exposure.']::text[],'Intermediate','E = integral_0^T p_A^2(t) dt ;  L_E = 10*log10( (1/T_0) * integral_0^T (p_A(t)/p_0)^2 dt ),  T_0 = 1 s','Sound exposure equals the time integral of the squared A-weighted pressure over the event, and sound exposure level is ten times the log of that exposure divided by a one-second reference and the reference pressure squared.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Integrating sound-level meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9059e6cb-7563-491b-83cd-25cbc57071bd','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9059e6cb-7563-491b-83cd-25cbc57071bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9059e6cb-7563-491b-83cd-25cbc57071bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '676154ca-54c4-4bf6-815d-0739734d4b85','Integrating-averaging sound-level meter','A sound level meter that reports the time-average (equivalent continuous) sound level, LAeq,T, by integrating the squared frequency-weighted pressure over the period and dividing by that period. It yields the steady level having the same energy as the fluctuating sound.','This meter gives one average level over a set time. It is called the equivalent continuous level. It stands for a steady sound with the same energy. This makes changing noise easy to summarize. It is the standard tool for noise surveys.','It summarizes fluctuating noise as a single energy-average level for surveys and exposure limits.','A technician logs the equivalent continuous level over an 8-hour shift; a reading of 88 dB(A) represents the total energy of the whole varying workday in one number.','Metering Instrument',ARRAY['Integrating sound-level meter','Equivalent continuous sound level','LZeq','Sound level meter','Time weighting']::text[],ARRAY['Confusing the equivalent continuous level with an arithmetic average of decibels; it is an energy (mean-square) average.','Assuming a short sample represents a long, varying period.','Mixing up integrating (exposure) and integrating-averaging (Leq) instruments.']::text[],ARRAY['Measuring workplace noise over a shift.','Assessing traffic noise for an environmental report.','Checking a venue against an Leq-based ordinance.']::text[],'Intermediate','L_Aeq,T = 10*log10( (1/T) * integral_0^T (p_A(t)/p_0)^2 dt )','The equivalent continuous A-weighted level equals ten times the base-ten log of the time-averaged squared A-weighted pressure divided by the reference pressure squared.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Integrating-averaging sound-level meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '676154ca-54c4-4bf6-815d-0739734d4b85','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='676154ca-54c4-4bf6-815d-0739734d4b85') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='676154ca-54c4-4bf6-815d-0739734d4b85');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ce6a01e-cd9d-433b-ab52-326dad231862','Intensity method','A technique for determining a source''s sound power by measuring sound intensity over a surface enclosing the source and integrating the normal intensity over that surface. Standardized in ISO 9614, it can work in situ and largely rejects steady background noise.','The intensity method finds how much sound power a machine makes. You measure sound flow over a surface around it. Then you add up the flow across that surface. It can work in a normal room, not just a lab. Steady background noise mostly cancels out.','It measures a source''s sound power in the field without an anechoic or reverberation room, even with background noise present.','A technician scans an intensity probe over a grid around a pump; integrating the normal intensity across the measurement surface yields the radiated sound power in watts.','Measurement Method',ARRAY['Intensity probe','Intensity vector','Sound power','Sound intensity','Free field']::text[],ARRAY['Assuming steady background noise adds error; energy flowing in one side and out the other largely cancels.','Ignoring the phase-mismatch and spacing limits that bound the usable frequency range.','Confusing sound intensity with sound pressure; only intensity carries direction.']::text[],ARRAY['Measuring machine sound power on a factory floor.','Locating the loudest region of a running engine.','Grading a product''s sound power for a noise label.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intensity method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ce6a01e-cd9d-433b-ab52-326dad231862','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ce6a01e-cd9d-433b-ab52-326dad231862') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ce6a01e-cd9d-433b-ab52-326dad231862');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eb8a4be4-ee0f-4c8b-b462-e01980201657','Intensity probe','The transducer for sound intensity measurement, most commonly two closely spaced, phase-matched pressure microphones (a p-p probe) separated by a fixed spacer. Sound pressure is taken as the average of the two capsules, and particle velocity is derived from the pressure gradient between them via Euler''s relation. Instrument requirements are set by IEC 61043.','An intensity probe measures how sound energy flows. The common type uses two matched microphones a fixed gap apart. The average of the two gives pressure. The difference between them gives motion of the air. Together they show the direction and size of the sound flow.','It captures both sound pressure and particle velocity at a point so the intensity vector can be computed.','A technician picks a microphone spacer to suit the band: a wider spacer for low frequencies and a narrow one for highs, because the spacing sets the usable frequency range.','Measurement Transducer',ARRAY['Intensity method','Intensity vector','Sound intensity','Particle velocity','Phase mismatch']::text[],ARRAY['Ignoring probe orientation; a p-p probe measures the intensity component along its own axis.','Using one spacer for all frequencies; the spacing limits both the low and high usable range.','Assuming any microphone pair works; the capsules must be closely phase-matched.']::text[],ARRAY['Setting up a sound power scan of a machine.','Mapping sound leaks in a panel or enclosure.','Choosing spacer length for a low-frequency measurement.']::text[],'Advanced','u_r(t) ~= -(1/rho_0) * integral ( (p_2 - p_1) / dr ) dt ;   p ~= (p_1 + p_2)/2','The axial particle velocity is estimated from the negative time integral of the pressure difference between the two microphones, divided by air density and their spacing, while the pressure is their average.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intensity probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eb8a4be4-ee0f-4c8b-b462-e01980201657','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eb8a4be4-ee0f-4c8b-b462-e01980201657') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eb8a4be4-ee0f-4c8b-b462-e01980201657');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3f0d0044-f71b-4941-bf4d-d50c2125ce22','Intensity vector','The time-averaged rate of acoustic energy flow per unit area, equal to the time average of the product of instantaneous sound pressure and particle velocity. It is a vector, with units of watts per square metre, pointing in the direction of net energy transport.','The intensity vector shows sound energy flow at a point. It has both a size and a direction. It equals pressure times air motion, averaged over time. It points the way energy is traveling. This is what an intensity probe measures.','It describes not just how loud a field is, but which way its energy is moving, enabling source location and sound power measurement.','A technician reads the sign of the normal intensity: positive means energy leaving a surface (a source), while negative means energy entering it (a sink or passing sound).','Acoustic Quantity',ARRAY['Intensity probe','Intensity method','Sound power','Particle velocity','Sound pressure']::text[],ARRAY['Confusing intensity with pressure; pressure is a scalar, intensity is a directional vector.','Forgetting intensity is a time average, not an instantaneous product.','Assuming high pressure means high net intensity; in a reactive field, net energy flow can be near zero.']::text[],ARRAY['Mapping energy flow around a loudspeaker.','Separating a source from reflected sound.','Computing sound power from a surface integral of intensity.']::text[],'Advanced','I = (1/T) * integral_0^T p(t) * u(t) dt    [W/m^2]','The sound intensity vector equals the time average, over the measurement period, of the instantaneous sound pressure multiplied by the instantaneous particle velocity vector.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intensity vector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3f0d0044-f71b-4941-bf4d-d50c2125ce22','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3f0d0044-f71b-4941-bf4d-d50c2125ce22') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3f0d0044-f71b-4941-bf4d-d50c2125ce22');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '155a345c-b3ca-48c6-b693-5f009bf3b877','Intermediate precision','The closeness of agreement among results obtained by the same method on identical items in the same laboratory, but under changed conditions such as different operators, equipment, calibrations, or days. Defined in ISO 5725, it lies between repeatability (all conditions fixed) and reproducibility (different laboratories).','Intermediate precision is a middle measure of consistency. It uses the same lab and method over time. But some things change, like the operator or the day. It shows more real-world scatter than a single sitting. It is less scatter than comparing separate labs.','It quantifies how much results drift within one lab over time and staff changes, a more realistic spread than best-case repeatability.','A technician repeats a calibration weekly with different staff and computes the intermediate-precision standard deviation, which feeds the uncertainty budget more honestly than same-day repeatability alone.','Metrology Concept',ARRAY['Repeatability','Reproducibility','Measurement uncertainty','Measurand','Influence quantity']::text[],ARRAY['Confusing intermediate precision with reproducibility; reproducibility involves different laboratories.','Assuming repeatability alone captures real-world spread.','Not stating which conditions were varied when reporting intermediate precision.']::text[],ARRAY['Validating a test method within one laboratory.','Estimating month-to-month measurement spread.','Building an uncertainty budget for accredited testing.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intermediate precision');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '155a345c-b3ca-48c6-b693-5f009bf3b877','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='155a345c-b3ca-48c6-b693-5f009bf3b877') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='155a345c-b3ca-48c6-b693-5f009bf3b877');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6b175057-2aad-4a62-b927-64af84702707','Klippel near-field scanner','A robotic acoustic measurement system by Klippel GmbH that scans sound pressure on a surface close to a loudspeaker, then uses a spherical-wave (holographic) field expansion to compute the complete three-dimensional radiated field, including far-field frequency response and directivity. A field-separation step removes room reflections, so anechoic-equivalent data can be obtained in an ordinary room. ''Klippel'' and ''Near Field Scanner'' are marks of Klippel GmbH, Dresden.','The Klippel Near Field Scanner is a robotic speaker-testing system. It moves a microphone close around the speaker. Software then rebuilds the full sound field in three dimensions. It gives anechoic-style data without an anechoic chamber. Klippel is the company that makes it.','It obtains full-sphere loudspeaker response and directivity, equivalent to an anechoic chamber, using near-field scanning plus a mathematical field expansion.','An engineer mounts a speaker on the scanner''s arm, runs an automated near-field scan, and exports far-field on-axis response and directivity balloons for the datasheet.','Measurement System',ARRAY['Near-field acoustic holography','Anechoic chamber','Directivity','Frequency response','Logarithmic sine sweep']::text[],ARRAY['Thinking it measures only the near field; near-field data are expanded to predict the far field.','Assuming it needs an anechoic room; field separation removes reflections in a normal room.','Treating ''Klippel'' as generic; it is a company and trademark, while the underlying method is spherical-wave holography.']::text[],ARRAY['Generating datasheet directivity for a new loudspeaker.','Comparing prototypes without booking an anechoic chamber.','Supplying full-sphere data for room-simulation software.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Klippel near-field scanner');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6b175057-2aad-4a62-b927-64af84702707','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6b175057-2aad-4a62-b927-64af84702707') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6b175057-2aad-4a62-b927-64af84702707');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '394f5b29-bba0-4dbb-a493-f5a2a38f4b2f','LAFmax','The highest A-weighted, Fast time-weighted sound level reached during a measurement period. The A weighting shapes the spectrum for perceived loudness, and the Fast time weighting uses a 125 ms exponential time constant.','LAFmax is the loudest reading during a measurement. It uses the A filter to shape for loudness. It uses the Fast meter speed. Fast reacts quickly, over about an eighth of a second. The result is the peak of that quick-reacting level.','It captures the maximum short-duration level of an event when a fast-reacting, loudness-weighted reading is required.','A technician checks a venue''s loudest moment against a limit; if LAFmax reaches 103 dB during a song, that exceeds a 100 dB LAFmax cap.','Metering Quantity',ARRAY['LASmax','LCFmax','Fast time weighting','A weighting','Peak sound level']::text[],ARRAY['Confusing LAFmax with peak sound level; peak has no time constant and reads higher.','Mixing up Fast and Slow maxima; Fast reacts faster and usually reads higher on transients.','Assuming LAFmax equals the average level; it is the single loudest time-weighted reading.']::text[],ARRAY['Enforcing a maximum-level clause in an event permit.','Logging the loudest pass-by in a traffic study.','Checking a workplace''s peak time-weighted level.']::text[],'Intermediate','L_AFmax = max over t of 10*log10( [ (1/tau_F) * integral_{-inf}^{t} p_A^2(xi) e^{-(t-xi)/tau_F} dxi ] / p_0^2 ),  tau_F = 125 ms','LAFmax is the largest value over the period of the A-weighted level formed with Fast exponential averaging, whose time constant is 125 milliseconds.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LAFmax');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '394f5b29-bba0-4dbb-a493-f5a2a38f4b2f','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='394f5b29-bba0-4dbb-a493-f5a2a38f4b2f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='394f5b29-bba0-4dbb-a493-f5a2a38f4b2f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8c994ae1-cd52-4a67-8d36-687bc46a0f52','LASmax','The highest A-weighted, Slow time-weighted sound level reached during a measurement period. The Slow time weighting uses a 1-second exponential time constant, so the reading is smoother and usually lower than the Fast maximum on transient sounds.','LASmax is the loudest level with the Slow meter speed. It uses the A filter for loudness. Slow averages over about one second. This smooths out quick spikes. So LASmax is usually lower than the Fast maximum.','It reports a maximum level that is less affected by brief spikes, useful where a smoother indicator is preferred.','A technician reports LASmax for a passing truck; because Slow averages over a second, a 96 dB LASmax may correspond to a higher LAFmax on the same event.','Metering Quantity',ARRAY['LAFmax','LCFmax','Slow time weighting','A weighting','Equivalent continuous sound level']::text[],ARRAY['Comparing LASmax against LAFmax limits as if interchangeable; Slow and Fast are different quantities.','Expecting LASmax to catch brief impulses; the 1 second constant smooths them.','Assuming Slow reads higher than Fast; on transients it reads lower.']::text[],ARRAY['Neighborhood noise assessment with Slow weighting.','Reporting maximum pass-by levels in a survey.','Comparing Fast and Slow maxima of the same event.']::text[],'Intermediate','L_ASmax = max over t of 10*log10( [ (1/tau_S) * integral_{-inf}^{t} p_A^2(xi) e^{-(t-xi)/tau_S} dxi ] / p_0^2 ),  tau_S = 1 s','LASmax is the largest value over the period of the A-weighted level formed with Slow exponential averaging, whose time constant is one second.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LASmax');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8c994ae1-cd52-4a67-8d36-687bc46a0f52','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8c994ae1-cd52-4a67-8d36-687bc46a0f52') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8c994ae1-cd52-4a67-8d36-687bc46a0f52');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2e94f9a3-5cce-416d-b01e-5d51bd34d1d1','LCFmax','The highest C-weighted, Fast time-weighted sound level reached during a measurement period. C weighting is much flatter at low frequencies than A weighting, so LCFmax better reflects loud, bass-heavy peaks.','LCFmax is the loudest level using the C filter and Fast speed. The C filter keeps more low bass than the A filter. So it suits loud, bassy sounds. Fast speed reacts quickly. The result is the peak of that reading.','It captures maximum levels where low-frequency energy matters, such as concerts and cinema, where A weighting would under-read the bass.','A technician measures a nightclub''s bass; LCFmax can read well above the A-weighted maximum because C weighting retains sub-bass energy.','Metering Quantity',ARRAY['LAFmax','LZeq','C weighting','Fast time weighting','Peak sound level']::text[],ARRAY['Comparing C-weighted and A-weighted maxima directly; they weight bass very differently.','Assuming C weighting is perfectly flat; it still rolls off at the low and high extremes.','Using A-weighted limits for bass-heavy sources where C weighting is more appropriate.']::text[],ARRAY['Setting bass limits at a music festival.','Cinema calibration and level checks.','Assessing low-frequency complaints from a venue.']::text[],'Intermediate','L_CFmax = max over t of 10*log10( [ (1/tau_F) * integral p_C^2(xi) e^{-(t-xi)/tau_F} dxi ] / p_0^2 ),  tau_F = 125 ms','LCFmax is the largest value over the period of the C-weighted level formed with Fast exponential averaging, whose time constant is 125 milliseconds.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LCFmax');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2e94f9a3-5cce-416d-b01e-5d51bd34d1d1','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2e94f9a3-5cce-416d-b01e-5d51bd34d1d1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2e94f9a3-5cce-416d-b01e-5d51bd34d1d1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '742812be-6826-4a37-abc8-b71f2aada02b','LZeq','The Z-weighted (flat) equivalent continuous sound level over a period. Z frequency weighting is nominally flat within tolerances from at least 10 Hz to 20 kHz per IEC 61672, so LZeq is the energy-average unweighted level.','LZeq is an average level with no frequency shaping. The Z filter is flat across the audio band. So it treats all frequencies equally. It gives the energy average over the set time. It is the unweighted version of the equivalent continuous level.','It provides an unweighted, spectrum-neutral time-average level, useful for octave-band data and building acoustics.','A technician logs LZeq in octave bands to assess a room; summing the bands gives the overall unweighted level, which A weighting would then reduce at low frequencies.','Metering Quantity',ARRAY['LAeq','Z weighting','Equivalent continuous sound level','Integrating-averaging sound-level meter','Octave band']::text[],ARRAY['Assuming Z weighting is truly flat everywhere; it is flat only within tolerances over a defined band.','Confusing LZeq with LAeq; Z applies no loudness weighting.','Reporting an unweighted level without stating the frequency band.']::text[],ARRAY['Octave-band room acoustics measurements.','Comparing unweighted spectra between rooms.','Providing raw data before applying a weighting.']::text[],'Intermediate','L_Zeq,T = 10*log10( (1/T) * integral_0^T (p_Z(t)/p_0)^2 dt )','The Z-weighted equivalent continuous level equals ten times the base-ten log of the time-averaged squared flat-weighted pressure divided by the reference pressure squared.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LZeq');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '742812be-6826-4a37-abc8-b71f2aada02b','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='742812be-6826-4a37-abc8-b71f2aada02b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='742812be-6826-4a37-abc8-b71f2aada02b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c595bfb3-568d-47b3-8fde-0984d42f7f6e','Linearity error','The deviation of an instrument''s indicated level from an ideal proportional (straight-line) response as the input level changes. For sound level meters, IEC 61672 specifies level-linearity error limits across the operating range at a reference frequency.','Linearity error is how far a meter strays from a straight-line response. Ideally, doubling the input doubles the reading. Real devices drift from this at very high or very low levels. That gap is the linearity error. Standards set how large it may be.','It bounds how much an instrument''s gain may vary with signal level, ensuring readings stay proportional across the range.','A technician runs an electrical level-linearity test on a sound level meter; if the reading tracks input within a fraction of a decibel across the range, it meets the class limit.','Measurement Error',ARRAY['Magnitude linearity','Linearity threshold','Level range','Sound level meter','Calibration']::text[],ARRAY['Confusing linearity error with calibration offset; offset is a fixed shift, linearity error changes with level.','Assuming linearity holds at the range extremes, where compression or noise dominates.','Reporting linearity error without stating the reference level and frequency.']::text[],ARRAY['Type-testing a sound level meter to IEC 61672.','Verifying an analyzer''s level accuracy over its range.','Diagnosing readings that drift at high input levels.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linearity error');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c595bfb3-568d-47b3-8fde-0984d42f7f6e','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c595bfb3-568d-47b3-8fde-0984d42f7f6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c595bfb3-568d-47b3-8fde-0984d42f7f6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24f44f15-3b8b-4cfe-b5ba-11fc2adecdbe','Linearity threshold','The signal level marking a boundary of an instrument''s or system''s linear operating range, typically the lowest level (limited by noise) or the highest level (limited by overload) at which the response stays proportional within a stated tolerance. Beyond the threshold, linearity error exceeds the allowed limit.','The linearity threshold marks the edge of the usable straight-line range. Below the low edge, noise spoils the reading. Above the high edge, overload spoils it. Between the edges the device stays proportional. The threshold is where it stops being linear.','It defines the usable input range within which readings can be trusted as proportional.','A technician notes a meter''s lower linearity threshold; measuring a source only a few decibels above it warns that the meter''s own noise may bias the reading.','Measurement Limit',ARRAY['Linearity error','Magnitude linearity','Level range','Noise floor','Overload']::text[],ARRAY['Measuring signals below the lower linearity threshold, where noise inflates the reading.','Assuming a single threshold; there are usually separate low and high linearity limits.','Confusing the linearity threshold with the detection threshold.']::text[],ARRAY['Setting the measurement range on an analyzer.','Judging whether a faint source is within a meter''s linear range.','Documenting an instrument''s usable dynamic range.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linearity threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24f44f15-3b8b-4cfe-b5ba-11fc2adecdbe','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24f44f15-3b8b-4cfe-b5ba-11fc2adecdbe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24f44f15-3b8b-4cfe-b5ba-11fc2adecdbe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b18b38cb-61b2-47bc-8581-13cdf4ba923e','Logarithmic sine sweep','A measurement stimulus whose frequency rises exponentially with time (equal octaves per unit time), used to obtain a system''s impulse and frequency response by deconvolution. Because harmonic-distortion products appear at predictable times ahead of the linear impulse, the method (popularized by Farina, 2000) cleanly separates distortion from the linear response.','A logarithmic sine sweep is a tone that glides upward. Its pitch rises by equal octaves each second. Playing it and processing the recording reveals a system''s response. Its main trick is separating clean response from distortion. Distortion lands at known spots you can trim away.','It measures impulse and frequency response with a high signal-to-noise ratio while isolating harmonic distortion from the linear response.','A technician plays a 20 Hz to 20 kHz log sweep through a speaker, deconvolves the recording into an impulse response, and time-gates out room reflections to read the anechoic-like response.','Test Signal',ARRAY['Impulse response','Frequency response','Total harmonic distortion','Deconvolution','Klippel near-field scanner']::text[],ARRAY['Confusing a logarithmic sweep with a linear sweep; the log sweep spends equal time per octave and concentrates distortion predictably.','Forgetting to window the recording, so room reflections corrupt the response.','Overdriving the system so distortion folds back into the measurement.']::text[],ARRAY['Measuring a loudspeaker''s frequency response in a room.','Capturing a hall''s impulse response for reverberation analysis.','Characterizing an amplifier or DSP transfer function.']::text[],'Advanced','f(t) = f_1 * (f_2/f_1)^{t/T} ;   phase(t) = 2*pi*f_1*T/ln(f_2/f_1) * ( (f_2/f_1)^{t/T} - 1 )','In a logarithmic sweep the instantaneous frequency rises from the start frequency to the end frequency by an exponential law, doubling over equal time intervals.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Logarithmic sine sweep');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b18b38cb-61b2-47bc-8581-13cdf4ba923e','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b18b38cb-61b2-47bc-8581-13cdf4ba923e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b18b38cb-61b2-47bc-8581-13cdf4ba923e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71c7ac23-b52b-48ce-9fad-2318b1ad87f2','Long-term maximum SPL','The highest sound pressure level a loudspeaker can sustain over a long test interval without exceeding stated distortion or protection limits or suffering thermal or mechanical failure. IEC 60268-21 specifies a long-term maximum SPL measurement using a program-like signal held for an extended period.','This is the loudest a speaker can play and hold for a long time. Heat building up in the coil limits it. Allowed distortion also limits it. Short bursts can go louder. This number reflects sustained, safe output.','It states a realistic sustained loudness limit set by heating and long-term distortion, not a brief peak.','A technician runs the IEC 60268-21 long-term test with a program-like signal for the specified duration and records the level at which the driver reaches its distortion or thermal limit.','Loudspeaker Rating',ARRAY['Maximum continuous SPL','Maximum peak SPL','Maximum linear SPL','Power compression','IEC noise']::text[],ARRAY['Confusing long-term maximum SPL with peak SPL; peaks can be much higher and briefer.','Ignoring power compression, which lowers sustained output as the coil heats.','Assuming the rating holds indefinitely; it is defined for a specified test duration.']::text[],ARRAY['Specifying sustained output for a touring PA box.','Comparing thermal limits between loudspeakers.','Sizing a system for continuous background music.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Long-term maximum SPL');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71c7ac23-b52b-48ce-9fad-2318b1ad87f2','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71c7ac23-b52b-48ce-9fad-2318b1ad87f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71c7ac23-b52b-48ce-9fad-2318b1ad87f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b4b06ac-321b-4fd8-96d1-36f272c1fc6c','M-Noise','A proprietary broadband test signal (M-Noise, developed by Meyer Sound) whose crest factor increases with frequency to mimic the peak-to-average behaviour of real music, unlike pink noise''s roughly constant crest factor. It is the stimulus used in the AES75 procedure for measuring a loudspeaker''s maximum linear sound level. ''M-Noise'' is a trademark of Meyer Sound Laboratories.','M-Noise is a special test signal that behaves like music. Its peaks grow sharper at higher frequencies. Plain pink noise does not do that. It drives a speaker the way real songs do. Meyer Sound created it, and it is their trademark.','It tests loudspeakers with a music-like signal so measured maximum output better predicts real program performance.','Following AES75, a technician raises the M-Noise playback level step by step until the speaker''s response deviates from its low-level shape, then records that maximum linear peak level.','Test Signal',ARRAY['Maximum linear sound level','Pink noise','Crest factor','IEC noise','Maximum peak SPL']::text[],ARRAY['Assuming M-Noise is just pink noise; its crest factor rises with frequency.','Treating ''M-Noise'' as generic; it is a Meyer Sound trademark tied to the AES75 method.','Comparing M-Noise figures against pink-noise ratings as if identical.']::text[],ARRAY['Measuring maximum linear sound level under AES75.','Comparing loudspeaker maximum-output claims on equal footing.','Verifying a manufacturer''s published AES75 figure.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='M-Noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b4b06ac-321b-4fd8-96d1-36f272c1fc6c','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b4b06ac-321b-4fd8-96d1-36f272c1fc6c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b4b06ac-321b-4fd8-96d1-36f272c1fc6c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71b86199-347b-4a74-a0f6-d97b5030c647','Magnitude linearity','The property whereby a system''s output magnitude changes in direct proportion to its input magnitude, so gain is independent of level. Deviation from this proportionality is the linearity error; loudspeaker amplitude (magnitude) linearity is assessed in IEC 60268-21.','Magnitude linearity means output rises in step with input. Turn the input up by six decibels and the output rises by six decibels. The gain does not change with level. Real devices lose this at the extremes. The mismatch is called linearity error.','It describes how faithfully a device keeps constant gain across signal levels, a core requirement for accurate reproduction and measurement.','A technician sweeps input level and plots output; a straight line means good magnitude linearity, while curvature at high levels reveals compression.','System Property',ARRAY['Linearity error','Linearity threshold','Total harmonic distortion','Power compression','Maximum linear SPL']::text[],ARRAY['Confusing magnitude linearity with frequency-response flatness; linearity is about level, not frequency.','Assuming a device is linear at all levels; compression and clipping break it.','Equating linearity with low distortion alone; magnitude linearity specifically concerns gain versus level.']::text[],ARRAY['Checking an amplifier''s gain across its range.','Testing loudspeaker output versus drive level.','Verifying a converter''s level accuracy.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnitude linearity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71b86199-347b-4a74-a0f6-d97b5030c647','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71b86199-347b-4a74-a0f6-d97b5030c647') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71b86199-347b-4a74-a0f6-d97b5030c647');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e93f717-1a06-47e3-935a-97b8d7631240','Maximum acoustic output','The greatest acoustic level a loudspeaker or driver can produce under stated conditions before reaching a defined limit such as distortion, excursion, thermal, or protection. It is an umbrella term; specific standardized forms include the maximum linear, long-term, and peak SPL of IEC 60268-21.','Maximum acoustic output is the loudest a speaker can go. A limit stops it, such as distortion or overheating. It is a broad term. More exact ratings name the exact limit. Examples are peak, continuous, and linear maximum levels.','It gives a headline figure for how loud a device can get, refined by the specific standardized maximum-SPL quantities.','A technician treats a bare ''maximum acoustic output'' claim with caution and asks which standardized measure (peak, long-term, or linear) and conditions it refers to.','Loudspeaker Rating',ARRAY['Maximum linear SPL','Maximum peak SPL','Maximum continuous SPL','Maximum usable SPL','Sound pressure level']::text[],ARRAY['Comparing ''maximum output'' figures without knowing the measurement conditions.','Assuming it means undistorted output; the limit may allow high distortion.','Treating a peak figure as a sustainable level.']::text[],ARRAY['Reading a loudspeaker datasheet headline spec.','Comparing marketing SPL claims between products.','Deciding what follow-up specs to request from a vendor.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum acoustic output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e93f717-1a06-47e3-935a-97b8d7631240','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e93f717-1a06-47e3-935a-97b8d7631240') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e93f717-1a06-47e3-935a-97b8d7631240');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5ae6fb2-49ad-4bb4-81bc-f5bc7112cb57','Maximum continuous SPL','The highest sound pressure level a loudspeaker can sustain continuously with a program-like signal without exceeding thermal, excursion, or distortion limits. It corresponds closely to the long-term maximum SPL of IEC 60268-21 and is usually measured with shaped noise of a defined crest factor.','This is the loudest a speaker can play non-stop. Heat in the voice coil sets the main limit. Distortion and cone travel also limit it. It uses a music-like noise for testing. Brief peaks can go louder than this.','It states the sustained loudness a loudspeaker can hold safely for continuous use.','A technician drives the box with a defined-crest-factor noise and raises the level until it nears its thermal or distortion limit; a typical spec might read 126 dB at 1 m.','Loudspeaker Rating',ARRAY['Long-term maximum SPL','Maximum peak SPL','Power compression','IEC noise','Crest factor']::text[],ARRAY['Confusing continuous SPL with peak SPL; peaks can be 6 dB or more higher.','Ignoring the crest factor of the test signal, which strongly affects the figure.','Assuming the rating survives poor ventilation; heat limits change with cooling.']::text[],ARRAY['Sizing a PA for sustained levels.','Comparing continuous output between speakers.','Setting safe long-term levels for a fixed install.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum continuous SPL');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5ae6fb2-49ad-4bb4-81bc-f5bc7112cb57','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5ae6fb2-49ad-4bb4-81bc-f5bc7112cb57') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5ae6fb2-49ad-4bb4-81bc-f5bc7112cb57');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '237cd1d5-fd9c-4ab5-ab21-7899c85d5077','Maximum linear SPL','The highest sound pressure level at which a loudspeaker''s output stays within a defined tolerance of its low-level (linear) frequency response, before compression or distortion changes the response shape. It is measured by increasing level until the transfer-function magnitude or coherence deviates beyond the allowed limit, as in AES75 and IEC 60268-21.','This is the loudest a speaker can play while still sounding like itself. At low levels its response has a set shape. As it gets louder, that shape starts to change. The level just before it changes too much is the maximum. Above it, the speaker distorts or compresses.','It gives an output figure that reflects clean, faithful reproduction, not just raw loudness at any distortion.','Following AES75, a technician steps the level up until the measured response deviates from the reference by more than the set tolerance, then records the maximum linear peak level.','Loudspeaker Rating',ARRAY['Maximum linear sound level','Maximum linear output','M-Noise','Magnitude linearity','Power compression']::text[],ARRAY['Confusing maximum linear SPL with peak SPL; the linear figure caps distortion, the peak does not.','Ignoring the tolerance value used, which changes the result.','Assuming all vendors apply the same deviation criterion.']::text[],ARRAY['Comparing loudspeakers on clean output.','Verifying an AES75 published figure.','Choosing a monitor that stays accurate when loud.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum linear SPL');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '237cd1d5-fd9c-4ab5-ab21-7899c85d5077','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='237cd1d5-fd9c-4ab5-ab21-7899c85d5077') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='237cd1d5-fd9c-4ab5-ab21-7899c85d5077');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '02186897-21bc-4a57-9bf8-38611206e901','Maximum linear output','The greatest output a loudspeaker or transducer can deliver while remaining within a defined tolerance of its small-signal, linear behaviour. In loudspeaker acoustics it is effectively the maximum linear SPL; the term stresses that gain and response stay proportional up to that point.','Maximum linear output is the most a device can give while staying faithful. Up to this point, output tracks input in proportion. Its response shape holds steady. Past it, distortion or compression sets in. It marks the top of clean operation.','It marks the top of the range where a device behaves proportionally and reproduces the signal faithfully.','A technician uses the maximum linear output to set a safe operating ceiling, keeping program peaks below it so the system never leaves its linear range.','Loudspeaker Rating',ARRAY['Maximum linear SPL','Maximum linear sound level','Magnitude linearity','Linearity error','Headroom']::text[],ARRAY['Treating maximum linear output as the absolute maximum; the device can produce more, but not linearly.','Confusing it with maximum electrical input power.','Assuming it is independent of the tolerance criterion chosen.']::text[],ARRAY['Setting a system''s clean operating ceiling.','Specifying a transducer''s linear range.','Aligning limiter thresholds below the linear maximum.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum linear output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '02186897-21bc-4a57-9bf8-38611206e901','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='02186897-21bc-4a57-9bf8-38611206e901') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='02186897-21bc-4a57-9bf8-38611206e901');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fdac5500-0c82-471d-bf7b-36b2cd5b88c8','Maximum linear sound level','The specific quantity defined by AES75-2022: the maximum sound level a loudspeaker can produce with the M-Noise signal while its transfer-function magnitude and coherence stay within the standard''s limits relative to a low-level reference. It is reported as a peak SPL referenced to a stated distance.','Maximum linear sound level is the exact term from the AES75 standard. It uses the music-like M-Noise signal. The level rises until the speaker''s response drifts too far. That last good level is the result. It is given as a peak level at a set distance.','It provides a standardized, independently verifiable maximum-level figure that allows fair, like-for-like loudspeaker comparison.','A technician follows AES75 exactly (M-Noise, defined distance, step increase, magnitude and coherence stop criteria) and publishes the resulting maximum linear peak level at 1 m.','Loudspeaker Rating',ARRAY['Maximum linear SPL','Maximum linear output','M-Noise','Maximum peak SPL','Transfer function']::text[],ARRAY['Using the term loosely; AES75 fixes the signal, distance, and stop criteria.','Comparing an AES75 figure against a pink-noise or peak figure as if identical.','Omitting the reference distance when quoting the level.']::text[],ARRAY['Publishing a datasheet figure to AES75.','Cross-checking a vendor''s AES75 claim.','Standardizing internal loudspeaker test reports.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum linear sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fdac5500-0c82-471d-bf7b-36b2cd5b88c8','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fdac5500-0c82-471d-bf7b-36b2cd5b88c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fdac5500-0c82-471d-bf7b-36b2cd5b88c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1161120-cc50-4db2-ae64-5229747d4fe1','Maximum peak SPL','The highest instantaneous peak sound pressure level a loudspeaker can produce, capturing brief transients rather than a sustained average. Because program peaks exceed the average by the signal''s crest factor, peak SPL is typically several decibels above continuous or long-term SPL. IEC 60268-21 addresses short-term and peak SPL measurement.','Maximum peak sound level is the loudest instant a speaker can hit. It captures brief spikes, not steady loudness. Music peaks rise above the average level. So it is usually well above the steady level. It shows transient capability.','It describes a loudspeaker''s short-transient headroom, important for punchy program such as drums or effects.','A technician measures peak SPL with a high-crest-factor signal; if continuous SPL is 120 dB and the crest factor is 6 dB, peaks may reach about 126 dB.','Loudspeaker Rating',ARRAY['Maximum continuous SPL','Long-term maximum SPL','Crest factor','Peak sound level','M-Noise']::text[],ARRAY['Treating peak SPL as a sustainable level; it applies only to brief transients.','Ignoring crest factor when comparing peak and continuous figures.','Assuming peak SPL implies low distortion; it may not.']::text[],ARRAY['Assessing transient headroom for cinema effects.','Comparing peak capability of PA boxes.','Setting peak limiters to protect drivers.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum peak SPL');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1161120-cc50-4db2-ae64-5229747d4fe1','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1161120-cc50-4db2-ae64-5229747d4fe1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1161120-cc50-4db2-ae64-5229747d4fe1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c01fd83-bb33-46d2-badd-26cbf2d40dba','Maximum usable SPL','The highest sound pressure level at which a device stays useful because distortion remains below a stated threshold. For measurement microphones it is the SPL at a specified total harmonic distortion (for example 3 %); for loudspeakers it is the level before distortion or response deviation makes output unusable.','Maximum usable sound level is the loudest a device stays useful. Above it, distortion grows too large. For measurement microphones it is set at a chosen distortion amount. For speakers it is where sound quality breaks down. It marks the top of trustworthy use.','It marks the level ceiling set by acceptable distortion, beyond which the device''s output is no longer trustworthy.','A technician reads a measurement microphone''s maximum SPL spec, such as 146 dB at 3 % distortion, and keeps expected peaks below it to avoid capsule overload.','Rating Limit',ARRAY['Maximum linear SPL','Total harmonic distortion','Overload','Maximum acoustic output','Linearity error']::text[],ARRAY['Comparing maximum usable SPL figures without noting the distortion percentage.','Assuming a microphone''s stated maximum SPL is distortion-free.','Confusing a sensor''s maximum usable SPL with a loudspeaker''s output rating.']::text[],ARRAY['Selecting a measurement microphone for loud sources.','Rating a loudspeaker''s usable ceiling.','Avoiding overload when measuring machinery or blasts.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum usable SPL');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c01fd83-bb33-46d2-badd-26cbf2d40dba','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c01fd83-bb33-46d2-badd-26cbf2d40dba') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c01fd83-bb33-46d2-badd-26cbf2d40dba');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '88800969-a014-4189-b0d3-72a3b574e920','Measurand','In metrology, the quantity intended to be measured. Its full specification includes the kind of quantity and a description of the object or phenomenon carrying it, and may require stating the conditions under which it is defined.','The measurand is the exact quantity you intend to measure. It is not the instrument or the reading. It is the true value you are after. Defining it well includes the object and conditions. Everything else exists to estimate it.','It pins down precisely what is being measured, so instruments, corrections, and uncertainty all refer to the same target.','Before measuring, a technician defines the measurand exactly, for example the A-weighted equivalent level at a stated point over a stated time, so the result is unambiguous.','Metrology Concept',ARRAY['Measurement function','Influence quantity','Measurement uncertainty','Intermediate precision','Calibration']::text[],ARRAY['Confusing the measurand with the instrument reading; the reading is only an estimate of it.','Defining the measurand too vaguely, so results cannot be compared.','Forgetting that the measurand''s definition may include conditions like temperature or time.']::text[],ARRAY['Writing a measurement procedure.','Stating exactly what a certificate reports.','Resolving disputes over what a spec actually measures.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurand');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '88800969-a014-4189-b0d3-72a3b574e920','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='88800969-a014-4189-b0d3-72a3b574e920') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='88800969-a014-4189-b0d3-72a3b574e920');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35c2fcbc-e38c-429c-ab7d-814c4c956199','Measurement function','In metrology, the function that relates the input quantities of a measurement model to the output quantity, so that inserting the input quantity values yields the measured value of the measurand. It is the calculating relationship at the heart of indirect measurements and of uncertainty propagation.','The measurement function is the formula that turns inputs into a result. You feed in the measured inputs. It computes the quantity you want. It is central to indirect measurements. It also guides how errors combine into uncertainty.','It expresses, as a formula, how a measured value is computed from its inputs, so both the result and its uncertainty can be derived.','A technician measuring sound power from intensity uses a measurement function that integrates intensity over area; propagating each input''s uncertainty through that function gives the result''s uncertainty.','Metrology Concept',ARRAY['Measurand','Influence quantity','Measurement uncertainty','Intermediate precision','Calibration']::text[],ARRAY['Confusing the measurement function with a simple calibration factor; it can involve several input quantities.','Forgetting that uncertainty must be propagated through the function.','Treating an empirical fit as exact when it carries its own uncertainty.']::text[],ARRAY['Deriving a quantity from several measured inputs.','Propagating uncertainty in a calibration.','Documenting how a reported value is computed.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35c2fcbc-e38c-429c-ab7d-814c4c956199','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35c2fcbc-e38c-429c-ab7d-814c4c956199') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35c2fcbc-e38c-429c-ab7d-814c4c956199');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f8a7f7cb-f9f8-428a-b118-84832ee2adae','Measurement model','The mathematical relation linking the measurand (output quantity) to the input quantities on which it depends, written generally as Y = f(X1, ..., Xn). It is the basis for computing a measured value and for propagating uncertainty from the inputs to the result.','A measurement model is the equation that ties your answer to the things you actually read. It says how the wanted value depends on each input. You use it to work out the result. It also shows how input errors flow into the final number.','It formalizes how a result is calculated from measured inputs so that both the value and its uncertainty can be derived consistently.','To find sound power from intensity, a technician writes W = I times S, where I is intensity and S is area; measuring I = 0.01 W/m^2 over S = 2 m^2 gives W = 0.02 W.','Metrology Concept',ARRAY['Measurand','Measurement result','Measurement uncertainty','Metrology','Input quantity']::text[],ARRAY['Confusing the model function with a single reading; the model is the relation, not one value.','Forgetting that every input carries uncertainty that the model must propagate.','Leaving out correction terms (offsets, environmental factors) that belong in the model.']::text[],ARRAY['Deriving sound power from measured intensity and surface area.','Computing THD from measured harmonic amplitudes.','Setting up an uncertainty budget for a calibration report.']::text[],'Intermediate','Y = f(X_1, X_2, ..., X_n)','The output quantity equals a defined function of the input quantities it depends on.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f8a7f7cb-f9f8-428a-b118-84832ee2adae','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f8a7f7cb-f9f8-428a-b118-84832ee2adae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f8a7f7cb-f9f8-428a-b118-84832ee2adae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0cc22264-a58b-4e4e-b5ce-3af245031d09','Measurement result','A set of quantity values attributed to a measurand together with any other available relevant information, generally expressed as a single measured value and its associated measurement uncertainty. Without a stated uncertainty (and unit), a reported value is incomplete.','A measurement result is more than one number. It is the measured value plus how sure you are of it. You should always give the unit too. A value with no uncertainty is only half an answer.','It communicates both the estimated value of a quantity and the doubt around it, so others can judge fitness for purpose.','A calibrated microphone sensitivity might be reported as 12.3 mV/Pa with an expanded uncertainty of 0.4 mV/Pa (k = 2), meaning the true value very likely lies within that band.','Metrology Concept',ARRAY['Measured value','Measurement uncertainty','Measurand','Coverage factor','Measurement model']::text[],ARRAY['Reporting a bare number with no uncertainty or unit.','Treating the last displayed digit as exact rather than uncertain.','Confusing the measured value alone with the full result.']::text[],ARRAY['Writing a calibration certificate for a sound level meter.','Recording an SPL reading for a compliance report.','Comparing two labs'' results for the same standard.']::text[],'Beginner',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement result');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0cc22264-a58b-4e4e-b5ce-3af245031d09','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0cc22264-a58b-4e4e-b5ce-3af245031d09') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0cc22264-a58b-4e4e-b5ce-3af245031d09');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55ca7b9f-1381-4f78-a8fe-d902e3d93475','Measurement tolerance','The total permissible variation of a quantity, defined by the difference between its upper and lower specification limits, within which a product or measured value is accepted. It is a specification requirement, distinct from measurement uncertainty, which describes doubt about the measured value itself.','A tolerance is the allowed range for a value. It is set by a spec, like plus or minus one decibel. Anything inside the range passes. Do not mix it up with uncertainty, which is doubt about your reading, not the allowed limits.','It sets the accept-or-reject boundaries for a quantity so parts or measurements can be judged conforming or not.','If a Class 1 sound calibrator must output 94.0 dB with a tolerance of +/-0.3 dB, a reading of 94.2 dB is inside the tolerance band and passes.','Metrology Concept',ARRAY['Measurement uncertainty','Specification limit','Conformance','Measurement result','Guard band']::text[],ARRAY['Treating tolerance and uncertainty as the same thing; one is an allowed range, the other is measurement doubt.','Ignoring measurement uncertainty when deciding if a value is inside tolerance.','Assuming a reading exactly on the limit clearly conforms without a guard band.']::text[],ARRAY['Judging whether a calibrator output conforms to its rated level.','Setting pass/fail limits on a production loudspeaker test.','Deciding conformance near a specification edge.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement tolerance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55ca7b9f-1381-4f78-a8fe-d902e3d93475','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55ca7b9f-1381-4f78-a8fe-d902e3d93475') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55ca7b9f-1381-4f78-a8fe-d902e3d93475');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1598c618-b94d-4b68-93cd-31bdfb2786cd','Metrological traceability','This is a characteristic of a measurement result that lets its value be tied back to a stated reference through a fully documented, gap-free sequence of calibrations. Each calibration in that sequence adds its own known share to the total measurement uncertainty. The reference is normally a national or international measurement standard that realizes the relevant SI unit.','Traceability means your reading links back to a trusted standard. It follows an unbroken chain of calibrations. Each link adds a little uncertainty. This chain usually ends at a national lab that holds the official unit.','It gives measurements a defensible link to recognized standards so results are comparable and trustworthy across labs and countries.','A field sound calibrator is calibrated against a lab reference, which is calibrated against a national standard; the documented chain makes a 94.0 dB output traceable to the SI pascal.','Metrology Concept',ARRAY['Calibration','Primary standard','Measurement standard','Measurement uncertainty','Metrology']::text[],ARRAY['Thinking a calibration sticker alone proves traceability without a documented chain.','Assuming traceability removes uncertainty; every link adds to it.','Believing traceability to any device is enough, rather than to a recognized reference/standard.']::text[],ARRAY['Auditing a calibration lab''s certificates.','Ensuring test-floor instruments trace to national standards.','Defending measurement validity in a compliance dispute.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Metrological traceability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1598c618-b94d-4b68-93cd-31bdfb2786cd','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1598c618-b94d-4b68-93cd-31bdfb2786cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1598c618-b94d-4b68-93cd-31bdfb2786cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e8dc67f-aeaa-4121-a343-1f842dccf9cc','Metrology','Metrology is the science of measurement together with its practical use. It embraces every theoretical and hands-on part of measuring, no matter the level of uncertainty or the field where it is applied. Its scope runs from defining units and realizing them through to establishing traceability and quantifying uncertainty.','Metrology is the science of measuring things. It covers how units are defined and realized. It also covers how sure we are of results. In audio it underpins every calibrated meter and standard.','It provides the shared framework of units, standards, and uncertainty that makes measurements consistent and comparable worldwide.','A technician applies metrology when scheduling instrument calibrations, keeping traceability records, and stating uncertainty on a measured microphone sensitivity.','Metrology Concept',ARRAY['Measurement','Metrological traceability','Measurement uncertainty','Calibration','Primary standard']::text[],ARRAY['Treating metrology as only calibration, rather than the whole science of measurement.','Ignoring uncertainty, which is central to metrology.','Assuming it applies only to labs, not to everyday field measurements.']::text[],ARRAY['Planning a calibration program for a test lab.','Explaining why measurement uncertainty matters in reports.','Relating audio measurements to SI units.']::text[],'Beginner',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Metrology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e8dc67f-aeaa-4121-a343-1f842dccf9cc','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e8dc67f-aeaa-4121-a343-1f842dccf9cc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e8dc67f-aeaa-4121-a343-1f842dccf9cc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b8ba1dd4-1db2-440c-bbbc-a89c72ad3f3a','Modal distortion','Frequency-response and time-response irregularity caused by resonant modes rather than by the source signal itself, such as room standing-wave modes at low frequencies or mechanical break-up modes of a loudspeaker diaphragm. These resonances add peaks, dips, and decay tails that are not part of the intended signal.','Modal distortion comes from resonances, not from the signal. A room''s standing waves boom at some low notes. A speaker cone can also break into vibration patterns. These add peaks, dips, and ringing that were never in the source.','Naming this effect helps technicians separate resonance-driven response errors from true source or electronic distortion.','Measuring a small control room, a technician sees a strong peak near 45 Hz from a room length mode; the waterfall plot shows it ringing after the signal stops.','Distortion Metric',ARRAY['Room mode','Standing wave','Waterfall plot','Cone break-up','Resonance']::text[],ARRAY['Blaming electronics for a low-frequency peak that is actually a room mode.','Trying to fix modal ringing with equalization alone, which cannot remove the decay tail.','Confusing modal distortion (resonant response error) with nonlinear harmonic distortion.']::text[],ARRAY['Diagnosing low-frequency boom in a studio.','Interpreting a loudspeaker waterfall for cone break-up.','Explaining response dips from standing waves.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b8ba1dd4-1db2-440c-bbbc-a89c72ad3f3a','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b8ba1dd4-1db2-440c-bbbc-a89c72ad3f3a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b8ba1dd4-1db2-440c-bbbc-a89c72ad3f3a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b96f2f63-ba2c-47d4-ba1a-25f32bad9d7a','Modulation distortion','A form of intermodulation distortion in which a low-frequency tone amplitude-modulates a higher-frequency tone passed through the device under test, producing sidebands around the high-frequency carrier. The SMPTE method uses a 60 Hz and 7 kHz pair at a 4:1 amplitude ratio, and the result is expressed as the ratio of sideband energy to carrier amplitude.','Modulation distortion is a type of intermodulation. A low tone rides on top of a high tone through the gear. The device wrongly makes the high tone swell and shrink. This adds new tones, called sidebands, around the high one. The standard test mixes 60 hertz and 7 kilohertz at a four-to-one level.','It reveals nonlinearity by showing how one tone unwantedly modulates another, which correlates well with audible distortion on complex signals.','Using the SMPTE stimulus, a technician reads 0.05% modulation distortion when the 60 Hz-induced sidebands around the 7 kHz tone total 0.0005 of the carrier amplitude.','Distortion Metric',ARRAY['Intermodulation distortion','SMPTE IMD','Total harmonic distortion','Sideband','Nonlinearity']::text[],ARRAY['Confusing SMPTE modulation distortion with THD; they use different stimuli and reveal different nonlinearities.','Using the wrong tone ratio; the SMPTE pair is specified at 4:1 low-to-high amplitude.','Assuming a low THD guarantees low intermodulation distortion.']::text[],ARRAY['Bench-testing an amplifier for intermodulation.','Comparing SMPTE IMD across signal-chain components.','Investigating harshness not captured by THD.']::text[],'Advanced','IMD_mod (%) = 100 * sqrt(sum(A_sideband^2)) / A_carrier','Modulation distortion percent equals one hundred times the root-sum-square of the sideband amplitudes divided by the high-frequency carrier amplitude.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modulation distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b96f2f63-ba2c-47d4-ba1a-25f32bad9d7a','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b96f2f63-ba2c-47d4-ba1a-25f32bad9d7a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b96f2f63-ba2c-47d4-ba1a-25f32bad9d7a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '421fbe16-a5bf-4a43-98cb-573cd3e7846f','Multiple coherence','A function, between 0 and 1, that gives the fraction of an output signal''s power spectral density explained by the linear influence of all measured inputs together in a multiple-input, single-output system. A value near 1 means the inputs jointly account for the output; a lower value indicates unmeasured inputs, noise, or nonlinearity.','Multiple coherence tells you how much of an output your inputs explain together. It runs from zero to one. One means the inputs fully account for the output. A low value means noise, nonlinearity, or a missing input.','It quantifies how well a set of inputs collectively predicts an output, guiding whether the measured inputs are sufficient.','In a two-source noise study, a multiple coherence of 0.9 at 200 Hz means the two measured sources jointly explain 90% of the receiver''s spectral power there.','Coherence Function',ARRAY['Ordinary coherence','Partial coherence','Power spectral density','Multiple-input system','Frequency response function']::text[],ARRAY['Interpreting multiple coherence per input; it is a joint measure for all inputs together.','Assuming a low value always means noise, when it can also mean a missing input or nonlinearity.','Confusing it with partial coherence, which conditions out other inputs.']::text[],ARRAY['Source identification with several correlated inputs.','Checking if measured inputs explain a structure''s vibration.','Validating a multiple-input transfer-function model.']::text[],'Advanced','gamma^2_{y:x}(f) = 1 - S_yy.x(f) / S_yy(f)','Multiple coherence equals one minus the ratio of the output spectrum remaining after removing all inputs to the total output spectrum.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multiple coherence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '421fbe16-a5bf-4a43-98cb-573cd3e7846f','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='421fbe16-a5bf-4a43-98cb-573cd3e7846f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='421fbe16-a5bf-4a43-98cb-573cd3e7846f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '98b38e63-8b27-40d0-b629-d25dfff7fcaa','Multitone coherence','In multitone testing, where many sinusoids at distinct frequencies are applied at once and analyzed by FFT, a coherence-based measure that distinguishes signal-correlated output from noise by comparing energy at excited bins with energy appearing at unexcited bins. It supports fast, simultaneous measurement of gain, distortion, and noise.','Multitone testing plays many tones at once and reads them with an FFT. Coherence here checks how much output lines up with the input tones. Energy landing between the tones is distortion or noise. This lets one quick capture measure level, distortion, and noise together.','It enables rapid, simultaneous characterization of a device across many frequencies while separating true response from noise and distortion.','A technician plays a 31-tone signal; energy at the excited bins gives frequency response, while energy in the empty bins between them reveals distortion and noise in one measurement.','Coherence Function',ARRAY['Multitone testing','Intermodulation distortion','FFT analysis','Ordinary coherence','Signal-to-noise ratio']::text[],ARRAY['Placing tones on harmonically related bins, so distortion falls on excited bins and hides.','Ignoring windowing and synchronous sampling, which cause spectral leakage between bins.','Assuming a single capture with poor coherence is still a clean measurement.']::text[],ARRAY['Fast end-of-line audio device testing.','Measuring response and distortion in one FFT capture.','Screening converters with a multitone stimulus.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multitone coherence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '98b38e63-8b27-40d0-b629-d25dfff7fcaa','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='98b38e63-8b27-40d0-b629-d25dfff7fcaa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='98b38e63-8b27-40d0-b629-d25dfff7fcaa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac299be0-4a61-42ca-947e-7482afde611f','Near-field acoustic holography','A technique that measures complex sound pressure over a surface very close to a source (the hologram plane), then uses a spatial Fourier transform and an acoustic propagator to reconstruct the full three-dimensional sound field, including evanescent waves. Because it captures evanescent components, its spatial resolution can be finer than the acoustic wavelength.','Near-field acoustic holography scans sound pressure just off a source. It records both level and phase on a grid. Math then rebuilds the whole 3D sound field. Because it catches close-up fading waves, it can see detail smaller than a wavelength.','It locates and images sound sources on a vibrating object with high spatial detail, aiding noise diagnosis and radiation studies.','Scanning close to an engine cover, a technician maps hot spots of radiation; the reconstruction shows which panel area radiates most at 400 Hz.','Acoustic Holography',ARRAY['Near-field scanner','Evanescent wave','Spatial Fourier transform','Sound intensity','Beamforming']::text[],ARRAY['Scanning too far from the source, losing the evanescent waves that give high resolution.','Using too coarse a grid, causing spatial aliasing.','Assuming it works like far-field beamforming; it exploits near-field information instead.']::text[],ARRAY['Imaging noise sources on machinery panels.','Studying loudspeaker cone radiation patterns.','Locating leaks or rattles on a vibrating structure.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field acoustic holography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac299be0-4a61-42ca-947e-7482afde611f','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac299be0-4a61-42ca-947e-7482afde611f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac299be0-4a61-42ca-947e-7482afde611f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a414fcb2-6361-400c-8f3d-f496cbe714e0','Near-field correction','An adjustment applied to a close-microphone (near-field) loudspeaker measurement so that it predicts the far-field on-axis response. It scales the near-field level and accounts for source size and radiation so the low-frequency response, measured free of room reflections, can be joined to a valid far-field curve.','A near-field correction fixes a close-up speaker measurement. Measuring right at the cone avoids room echoes at low notes. But the raw close level is not the far-field level. The correction rescales it so it matches what you would hear at a distance.','It lets a reflection-free near-field low-frequency measurement be converted to the far-field response it represents.','After a near-field woofer measurement, a technician applies the level correction and splices it to a gated far-field curve to build a full anechoic response.','Near-field Measurement',ARRAY['Near-field-far-field splice','Near-field acoustic holography','Baffle step','Anechoic response','Gated measurement']::text[],ARRAY['Using near-field data at frequencies where the radiator is large versus the wavelength, where the method fails.','Skipping the level correction and reading near-field SPL as far-field SPL.','Ignoring diffraction and baffle effects that differ between near and far field.']::text[],ARRAY['Building a full-range anechoic loudspeaker curve.','Measuring woofer response without an anechoic chamber.','Combining near-field and gated data.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a414fcb2-6361-400c-8f3d-f496cbe714e0','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a414fcb2-6361-400c-8f3d-f496cbe714e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a414fcb2-6361-400c-8f3d-f496cbe714e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aea0f2dc-85d5-431c-b776-e9689c1a97dd','Near-field scanner','An instrument, often robotic, that samples sound pressure (and sometimes velocity) at many points over a surface close to a source to support near-field holography or a near-field-to-far-field transformation. The Klippel Near Field Scanner is a commercial example that computes full three-dimensional far-field directivity from scanned data; Near Field Scanner and NFS are trademarks of Klippel GmbH.','A near-field scanner moves a microphone over many points close to a source. It records the sound field on a grid. Software then rebuilds the full radiation, including the far-field pattern. The Klippel Near Field Scanner is one well-known product; that name is a Klippel trademark.','It automates dense near-field sampling so the complete radiated field and far-field directivity can be reconstructed without an anechoic chamber.','A technician mounts a loudspeaker on the scanner; it samples a spherical shell of points and outputs the full anechoic frequency response and directivity in a normal room.','Near-field Measurement',ARRAY['Near-field acoustic holography','Near-field correction','Directivity','Spherical wave expansion','Anechoic response']::text[],ARRAY['Under-sampling the surface, which aliases the reconstructed field.','Assuming any near-field microphone traverse is a calibrated holography scan.','Treating the Klippel trademark name as a generic method name.']::text[],ARRAY['Measuring loudspeaker directivity without an anechoic room.','Separating direct sound from room reflections by field expansion.','Building 3D radiation data for simulation.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field scanner');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aea0f2dc-85d5-431c-b776-e9689c1a97dd','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aea0f2dc-85d5-431c-b776-e9689c1a97dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aea0f2dc-85d5-431c-b776-e9689c1a97dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5052c1ac-776e-4748-8b60-e91fa9a1f020','Near-field–far-field splice','A method of building a full-range loudspeaker frequency response by joining a reflection-free near-field low-frequency measurement to a far-field or time-gated measurement at higher frequencies. The two curves are level-matched and spliced at a transition frequency where both are valid.','This method joins two speaker measurements into one curve. The close-up measurement is trusted at low notes, free of room echo. A gated measurement is trusted higher up. You match their levels and stitch them at a chosen crossover frequency.','It yields a full-bandwidth quasi-anechoic response in an ordinary room by using each measurement where it is accurate.','A technician splices a near-field woofer curve to a 1 m gated curve near 300 Hz, matching levels in the overlap to form one seamless response.','Near-field Measurement',ARRAY['Near-field correction','Gated measurement','Baffle step','Anechoic response','Transition frequency']::text[],ARRAY['Splicing where neither curve is valid, creating a false bump or dip.','Failing to level-match the two curves in the overlap region.','Ignoring baffle-step differences between near-field and far-field data.']::text[],ARRAY['Producing full-range curves without an anechoic chamber.','Combining woofer and gated tweeter data.','Publishing quasi-anechoic loudspeaker responses.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field–far-field splice');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5052c1ac-776e-4748-8b60-e91fa9a1f020','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5052c1ac-776e-4748-8b60-e91fa9a1f020') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5052c1ac-776e-4748-8b60-e91fa9a1f020');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'de0e82ab-9479-4495-9b20-6e8795758d56','Noise dose','The percentage of a permitted daily noise exposure that a person accumulates, combining sound level and duration. Under the US OSHA rule (29 CFR 1910.95), 100% dose equals eight hours at 90 dBA using a 5 dB exchange rate; NIOSH instead recommends 85 dBA for eight hours with a 3 dB exchange rate.','Noise dose is how much of your daily noise limit you have used, as a percent. It adds up loudness and time. Under the US OSHA rule, 100 percent is eight hours at 90 A-weighted decibels. Louder sound uses up the limit much faster.','It converts a varying day of noise into one accountable number for hearing-conservation and legal compliance.','By OSHA rules, 2 hours at 100 dBA has a reference duration T = 8/2^((100-90)/5) = 2 hours, so C/T = 2/2 = 1, giving a 100% dose from that period alone.','Noise Exposure',ARRAY['Time-weighted average','Exchange rate','Criterion level','Sound exposure level','Noise dosimeter']::text[],ARRAY['UNSAFE: Assuming brief very loud exposures are harmless; loud sound accrues dose fast and can damage hearing.','Mixing OSHA (90 dBA, 5 dB) and NIOSH (85 dBA, 3 dB) criteria in one calculation.','Forgetting that dose depends on both level and time, not level alone.','Reading dose without knowing which exchange rate the meter uses.']::text[],ARRAY['Assessing a live-sound engineer''s daily exposure.','Setting break schedules for loud venues.','Comparing OSHA and NIOSH results from a dosimeter.']::text[],'Intermediate','D = 100 * (C_1/T_1 + C_2/T_2 + ... + C_n/T_n),  T = 8 / 2^((L-90)/5)','Dose percent equals one hundred times the sum, over each exposure, of actual time divided by the reference duration allowed at that level; the reference duration is eight hours divided by two raised to the level-minus-ninety over five.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise dose');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'de0e82ab-9479-4495-9b20-6e8795758d56','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='de0e82ab-9479-4495-9b20-6e8795758d56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='de0e82ab-9479-4495-9b20-6e8795758d56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7e447d1-7e31-4a4d-a555-fc68346116ad','Noncoherent distortion','Output signal components that are not linearly related to (not coherent with) the input stimulus, including random noise and irregular, non-repeatable artifacts such as rub-and-buzz. It corresponds to the part of the output spectrum not explained by the coherence with the input, equal to (1 - coherence) times the output spectrum.','Noncoherent distortion is output that does not track the input in a fixed way. It includes random noise and stray rattles. Coherence measurement can separate it. It is the share of the output that the input does not cleanly explain.','It isolates noise-like and non-repeatable defects from stable harmonic distortion, which is coherent with the stimulus.','On a loudspeaker sweep, a coherence of 0.8 at 3 kHz means 20% of the output power there is noncoherent, flagging possible rub-and-buzz or noise.','Distortion Metric',ARRAY['Ordinary coherence','Rub and buzz','Harmonic distortion','Signal-to-noise ratio','Power spectral density']::text[],ARRAY['Confusing noncoherent distortion with harmonic distortion, which is coherent and repeatable.','Assuming low coherence always means a fault, when it can be background noise.','Averaging too few records, which biases the coherence estimate.']::text[],ARRAY['Detecting rub-and-buzz on a loudspeaker line.','Separating noise from stable distortion in a sweep.','Judging transducer defects with coherence.']::text[],'Advanced','S_noncoh(f) = (1 - gamma^2_xy(f)) * S_yy(f)','The noncoherent output power equals one minus the input-output coherence, multiplied by the total output power spectral density.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noncoherent distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7e447d1-7e31-4a4d-a555-fc68346116ad','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7e447d1-7e31-4a4d-a555-fc68346116ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7e447d1-7e31-4a4d-a555-fc68346116ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd325fef9-a3d5-4384-a9ae-7fb83a84827c','Nonlinear impulse response','A set of impulse responses that separately capture a device''s harmonic distortion orders, obtained mainly with the exponential sine-sweep (logarithmic chirp) method, in which higher harmonics appear as distinct impulse responses at earlier (negative) times. It extends the single linear impulse response into a family describing nonlinear behavior.','A normal impulse response describes only the clean, linear behavior. The nonlinear impulse response adds the distortion parts. A log sine sweep neatly splits each harmonic into its own impulse. You can then study each distortion order on its own.','It lets a technician measure the linear response and each harmonic distortion order together from one swept-sine capture.','Using an exponential sweep, a technician deconvolves the recording and reads the second-harmonic impulse appearing before the linear one, isolating that distortion order.','Distortion Metric',ARRAY['Exponential sine sweep','Impulse response','Harmonic distortion','Deconvolution','Volterra series']::text[],ARRAY['Using a linear (not logarithmic) sweep, which does not separate the harmonics in time.','Truncating the pre-arrival region and discarding the harmonic impulses.','Assuming the extracted harmonics behave linearly; they scale with drive level.']::text[],ARRAY['Characterizing loudspeaker distortion from a sweep.','Separating harmonic orders for analysis.','Building nonlinear device models.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlinear impulse response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd325fef9-a3d5-4384-a9ae-7fb83a84827c','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d325fef9-a3d5-4384-a9ae-7fb83a84827c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d325fef9-a3d5-4384-a9ae-7fb83a84827c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9194771b-9ee7-4f49-8631-354dee248eff','Octave-band level','The sound pressure level measured within a single octave-wide passband filter, whose upper edge frequency is twice its lower edge. Octave and fractional-octave filters are specified by IEC 61260 (and ANSI S1.11), with standard nominal centre frequencies such as 31.5, 63, 125, 250, 500, 1000 Hz and so on.','An octave-band level is the sound level inside one octave-wide filter. An octave means the top edge is double the bottom edge. Meters use a set of these bands to show the spectrum. Standard band centers include 63, 125, 250, 500, and 1000 hertz.','It breaks broadband sound into standard frequency bands so spectral content can be compared against limits and between measurements.','A technician reads 78 dB in the 1 kHz octave band; that value equals ten times the log of the mean-square pressure passed by that filter over the reference pressure squared.','Spectral Level',ARRAY['One-third-octave band','Sound pressure level','Spectrum analyzer','A-weighting','Centre frequency']::text[],ARRAY['Adding band levels arithmetically instead of on an energy (mean-square) basis.','Confusing octave with one-third-octave bands, which are three times narrower.','Mixing base-two and base-ten filter definitions when comparing meters.']::text[],ARRAY['Measuring noise spectra for compliance.','Setting graphic-equalizer bands by octave.','Comparing background noise across frequency.']::text[],'Beginner','L_band = 10*log10( p_band_rms^2 / p_0^2 ),  f_upper / f_lower = 2','The octave-band level equals ten times the base-ten log of the band''s mean-square pressure divided by the reference pressure squared, over a band whose upper edge is twice its lower edge.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Octave-band level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9194771b-9ee7-4f49-8631-354dee248eff','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9194771b-9ee7-4f49-8631-354dee248eff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9194771b-9ee7-4f49-8631-354dee248eff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ed7ba982-c6b8-4558-989e-29002ab79d85','Partial coherence','A conditioned coherence function, between 0 and 1, giving the correlation between an output and one input after the linear effects of the other inputs have been removed (conditioned out). It isolates the unique contribution of a single input in a multiple-input system.','Partial coherence measures how one input alone links to the output. First it removes the effect of the other inputs. Then it shows what is left from that one input. It runs from zero to one, like other coherence measures.','It separates the individual contribution of each input when several correlated inputs drive one output.','With two correlated noise sources, conditioning out source A leaves a partial coherence of 0.4 for source B at 500 Hz, showing B''s unique share there.','Coherence Function',ARRAY['Multiple coherence','Ordinary coherence','Conditioned spectrum','Multiple-input system','Source identification']::text[],ARRAY['Confusing partial coherence with ordinary coherence, which ignores the other inputs.','Wrong conditioning order, which changes the interpretation.','Assuming inputs are uncorrelated, making conditioning unnecessary when it is not.']::text[],ARRAY['Ranking correlated noise sources.','Isolating one path''s contribution in vibration analysis.','Building conditioned transfer-function models.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Partial coherence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ed7ba982-c6b8-4558-989e-29002ab79d85','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ed7ba982-c6b8-4558-989e-29002ab79d85') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ed7ba982-c6b8-4558-989e-29002ab79d85');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a75af915-bf4d-41d9-a17c-4ff08140f42b','Peak power','The maximum instantaneous power delivered to a load during a waveform. For a sinusoid across a resistive load, the instantaneous peak power equals the peak voltage squared divided by the resistance, which is twice the average (RMS-based) power.','Peak power is the highest instant power reached by a signal. For a pure sine into a resistor, it is the peak voltage squared over the resistance. That value is twice the average power. Do not confuse it with vague marketing ''peak'' ratings.','It describes the momentary power maximum, which matters for headroom, transient handling, and device stress.','A sine of 28.3 V peak into 8 ohms gives peak power = 28.3^2 / 8 = 100 W, while the average power is 50 W.','Power Rating',ARRAY['Average power','RMS power','Crest factor','Headroom','Peak-to-average ratio']::text[],ARRAY['Confusing peak power with average (continuous) power; for a sine, peak is twice the average.','Trusting unspecified ''peak music power'' marketing figures.','Using peak voltage where RMS voltage is required, or vice versa.']::text[],ARRAY['Sizing amplifier headroom for transients.','Interpreting datasheet power ratings.','Assessing short-term device stress.']::text[],'Intermediate','P_peak = V_peak^2 / R = 2 * P_avg  (sinusoid, resistive load)','For a sine into a resistor, peak instantaneous power equals the peak voltage squared divided by the resistance, which is twice the average power.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak power');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a75af915-bf4d-41d9-a17c-4ff08140f42b','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a75af915-bf4d-41d9-a17c-4ff08140f42b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a75af915-bf4d-41d9-a17c-4ff08140f42b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cfd14bd8-7efd-4162-b43b-050eaa1d500a','Peak-to-average ratio','The ratio of a signal''s peak value to its average value, often expressed in decibels. For power it is peak power over average power; for amplitude the related crest factor is the peak divided by the RMS value, which for a sine is the square root of two, about 3.01 dB.','Peak-to-average ratio compares the biggest value to the typical value of a signal. It is often given in decibels. For amplitude, the related crest factor is peak over RMS. A pure sine has a crest factor of about three decibels.','It indicates how ''peaky'' a signal is, which drives headroom needs and power-handling requirements.','A signal with peak power 10 times its average power has a peak-to-average ratio of 10*log10(10) = 10 dB, so 10 dB of headroom is needed above the average level.','Power Rating',ARRAY['Crest factor','Peak power','RMS','Headroom','Dynamic range']::text[],ARRAY['Mixing power ratio (10 log) with amplitude ratio (20 log) forms.','Confusing peak-to-average power ratio with amplitude crest factor.','Assuming all program material has the same crest factor as a sine.']::text[],ARRAY['Setting broadcast or PA headroom.','Comparing crest factors of program material.','Specifying amplifier power for peaky signals.']::text[],'Intermediate','PAPR_dB = 10*log10(P_peak / P_avg);  Crest factor = V_peak / V_rms','Peak-to-average power ratio in decibels equals ten times the log of peak power over average power; the amplitude crest factor is peak voltage over rms voltage.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak-to-average ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cfd14bd8-7efd-4162-b43b-050eaa1d500a','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cfd14bd8-7efd-4162-b43b-050eaa1d500a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cfd14bd8-7efd-4162-b43b-050eaa1d500a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2567ce57-eec9-47f5-9041-d477332a480b','Percentile level','A statistical descriptor of a fluctuating sound, LN, equal to the A-weighted level exceeded for N percent of the measurement time. Common values are L10 (a near-maximum level often used for traffic), L50 (the median), and L90 (a residual or background level).','A percentile level describes noise that goes up and down. L-N is the level exceeded for N percent of the time. L10 is close to the louder moments. L90 is close to the quiet background. L50 is the middle value.','It summarizes time-varying environmental noise beyond a single average, capturing both peaks and background.','Over a one-hour road survey, L10 = 72 dBA means the level exceeded 72 dBA for 10% of the hour, while L90 might be the 55 dBA background.','Spectral Level',ARRAY['Equivalent continuous level','Residual sound','Statistical level','Environmental noise','Sound level meter']::text[],ARRAY['Confusing L10 (higher level) with L90 (lower level); a bigger index means quieter.','Treating percentile level as an energy average like Leq.','Ignoring the time weighting used to sample the levels.']::text[],ARRAY['Traffic and community noise surveys.','Characterizing background versus intrusive noise.','Reporting environmental noise statistics.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Percentile level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2567ce57-eec9-47f5-9041-d477332a480b','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2567ce57-eec9-47f5-9041-d477332a480b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2567ce57-eec9-47f5-9041-d477332a480b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71b13cd3-72e8-4681-8bcd-2c60ef232cfa','Perceptual rub and buzz','A loudspeaker defect metric that detects audible rub-and-buzz using a psychoacoustic model of masking, so only defects loud enough to be heard are flagged. Rub-and-buzz itself is impulsive, high-order distortion from mechanical faults such as a rubbing voice coil or loose particles; the perceptual approach reduces false rejects on production lines. Klippel is a trademark of Klippel GmbH.','Rub and buzz is a harsh defect from a speaker rubbing or rattling. A plain distortion test can flag faults no one would hear. The perceptual version uses a hearing model to check what is actually audible. This cuts false rejects on the factory line. The name Klippel is a company trademark.','It ties a pass/fail rub-and-buzz test to human hearing, so inaudible defects do not cause needless rejects.','On an end-of-line test, a unit shows high-order distortion but the perceptual metric marks it below the masking threshold, so it passes as inaudible.','Distortion Metric',ARRAY['Rub and buzz','Masking threshold','High-order distortion','Noncoherent distortion','End-of-line testing']::text[],ARRAY['Assuming any measurable high-order distortion is audible; masking may hide it.','Confusing the perceptual metric with a simple high-pass distortion measure.','Treating the trademark name as the generic method.']::text[],ARRAY['Production-line loudspeaker screening.','Reducing false rejects from inaudible defects.','Diagnosing mechanical rattles in transducers.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Perceptual rub and buzz');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71b13cd3-72e8-4681-8bcd-2c60ef232cfa','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71b13cd3-72e8-4681-8bcd-2c60ef232cfa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71b13cd3-72e8-4681-8bcd-2c60ef232cfa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db80a746-4ce7-4907-ab29-3817463ad9ef','Pink-noise power test','A loudspeaker power-handling test that drives the unit with band-limited pink noise of a specified crest factor and spectral shape for a defined period, to check for thermal or mechanical failure. AES2-1984 and IEC 60268-5 specify such tests, typically using pink noise with a 6 dB crest factor and a shaped spectrum representing program material.','This test stresses a speaker with pink noise for a set time. Pink noise has equal energy in each octave. The signal is shaped and given a fixed crest factor. If the speaker overheats or fails, it does not pass. Standards like AES2 define the exact signal.','It rates how much continuous power a loudspeaker can handle without thermal or mechanical damage, using a repeatable stimulus.','Following AES2-1984, a technician applies shaped pink noise at the rated power for the specified hours; a driver that survives without failure passes its power rating.','Power Test',ARRAY['Power-test noise','Crest factor','Pink noise','Power handling','Thermal compression']::text[],ARRAY['UNSAFE: Running an unshaped or excessive-crest signal that overstresses and damages the driver.','Using white noise instead of the specified shaped pink noise.','Ignoring the required crest factor, which changes the thermal stress.']::text[],ARRAY['Rating loudspeaker power handling.','Comparing drivers under a standard stress test.','Qualifying a design for continuous use.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pink-noise power test');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db80a746-4ce7-4907-ab29-3817463ad9ef','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db80a746-4ce7-4907-ab29-3817463ad9ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db80a746-4ce7-4907-ab29-3817463ad9ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '09f77fda-eb7a-455c-a586-5a65de7df90c','Power-test noise','A standardized shaped noise signal used to test the power handling of audio equipment, made by filtering pink noise with a defined weighting network to simulate typical program spectra, and set to a specified crest factor. IEC 60268-1 defines such a simulated-programme test signal.','Power-test noise is a special noise signal for stress tests. It starts as pink noise and is then filtered to look like real music. It also has a set crest factor. Using this standard signal makes power tests repeatable across labs.','It provides a repeatable, program-like stimulus so power-handling tests give comparable results between devices and labs.','A technician generates the IEC 60268-1 shaped noise, sets its crest factor, and applies it at rated power to stress-test an amplifier or loudspeaker consistently.','Power Test',ARRAY['Pink-noise power test','Crest factor','Simulated programme material','Power handling','Weighting network']::text[],ARRAY['Using raw pink noise without the specified shaping filter.','Setting the wrong crest factor, changing the stress level.','Assuming all standards use the same power-test spectrum.']::text[],ARRAY['Standardized amplifier stress testing.','Loudspeaker power-handling qualification.','Cross-lab comparison of power ratings.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Power-test noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '09f77fda-eb7a-455c-a586-5a65de7df90c','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='09f77fda-eb7a-455c-a586-5a65de7df90c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='09f77fda-eb7a-455c-a586-5a65de7df90c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1d9ffac5-3a4b-45e1-9864-11a7e68692ea','Pressure–intensity index','In sound intensity measurement, the difference between the sound pressure level and the sound intensity level at a point, indicating how reactive the field is. The related residual (pressure-residual-intensity) index, measured for the probe in a purely reactive field per IEC 61043, sets the instrument''s dynamic capability and the ISO 9614 field-quality criteria.','This index is the pressure level minus the intensity level at a point. A big gap means a very reactive, difficult field. The probe''s own residual gap, measured in a special test, limits how much difference it can handle. Standards use it to check if a measurement is trustworthy.','It flags when a sound field is too reactive for reliable intensity measurement given the probe''s capability.','If the measured pressure-intensity index is 12 dB but the probe''s residual index gives a dynamic capability of only 10 dB, the ISO 9614 criterion is not met and the reading is rejected.','Sound Intensity',ARRAY['Sound intensity','Residual intensity index','Dynamic capability','ISO 9614','Reactivity']::text[],ARRAY['Ignoring the residual index, so readings in over-reactive fields are trusted wrongly.','Confusing the field pressure-intensity index with the probe''s residual index.','Assuming a small index is always fine without checking the standard''s criterion.']::text[],ARRAY['Validating sound power by intensity per ISO 9614.','Checking field quality before accepting intensity data.','Selecting a probe for a reactive environment.']::text[],'Advanced','F_pI = L_p - L_I','The pressure-intensity index equals the sound pressure level minus the sound intensity level at the measurement point.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure–intensity index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1d9ffac5-3a4b-45e1-9864-11a7e68692ea','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1d9ffac5-3a4b-45e1-9864-11a7e68692ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1d9ffac5-3a4b-45e1-9864-11a7e68692ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f0619463-b558-4698-9af5-898321222bea','Pressure–pressure intensity probe','A sound intensity probe that uses two closely spaced pressure microphones and estimates particle velocity from the pressure gradient between them via Euler''s equation, giving intensity as the product of the mean pressure and estimated velocity. Finite spacing causes a low-frequency phase-mismatch error and a high-frequency finite-difference error; performance is governed by IEC 61043.','This probe uses two pressure mics set very close together. The pressure gap between them shows how fast the air moves. Pressure times air speed gives the sound intensity. The mic spacing limits the useful frequency range. The two mics must be closely phase matched.','It measures sound intensity, and hence direction and sound power, using two matched pressure microphones.','A technician fits a 12 mm spacer for mid frequencies; below the useful band, tiny phase mismatch between the two microphones inflates the low-frequency intensity error.','Sound Intensity',ARRAY['Pressure-velocity intensity probe','Sound intensity','Phase mismatch','Finite-difference error','Euler''s equation']::text[],ARRAY['Using one spacer for all frequencies; spacing trades off low- and high-frequency errors.','Ignoring microphone phase matching, the main low-frequency error source.','Assuming the finite-difference estimate is exact at high frequencies.']::text[],ARRAY['Measuring sound power in the field.','Mapping intensity around machinery.','Choosing microphone spacing for a frequency range.']::text[],'Advanced','I ~= -( (p_1+p_2)/2 ) * (1/(rho*d)) * integral (p_2 - p_1) dt','Intensity equals the average of the two microphone pressures times the particle velocity, where velocity comes from the time-integrated pressure difference divided by air density and spacing.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure–pressure intensity probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f0619463-b558-4698-9af5-898321222bea','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f0619463-b558-4698-9af5-898321222bea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f0619463-b558-4698-9af5-898321222bea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cfaaa09a-a73b-4b28-be11-1f8027b20357','Pressure–velocity intensity probe','A sound intensity probe that pairs a pressure microphone with a direct particle-velocity sensor, so intensity is the product of measured pressure and measured velocity without a finite-difference approximation. The Microflown transducer, a hot-wire velocity sensor from Microflown Technologies, is a common example, offering a wide bandwidth in a small package.','This probe measures pressure and particle velocity directly. It does not work out velocity from two microphones. Multiplying the two signals gives the intensity. The Microflown sensor is a well known example. It measures velocity with a tiny heated wire. It works over a wide frequency range.','It measures sound intensity directly, avoiding the finite-difference and spacing errors of two-microphone probes.','A technician uses a Microflown-based probe to measure intensity down to low frequencies where a spaced two-microphone probe would suffer phase-mismatch errors.','Sound Intensity',ARRAY['Pressure-pressure intensity probe','Sound intensity','Particle velocity','Microflown','Near-field acoustic holography']::text[],ARRAY['Assuming it needs a microphone spacing; it measures velocity directly.','Skipping calibration of the velocity sensor''s magnitude and phase.','Treating the Microflown trademark as the generic method name.']::text[],ARRAY['Wide-band intensity measurement.','Low-frequency intensity where spacing errors bite.','Compact in-situ intensity probing.']::text[],'Advanced','I(t) = p(t) * u(t),  I_avg = <p*u>','Instantaneous intensity equals measured pressure times measured particle velocity; time-averaging gives the net intensity.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure–velocity intensity probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cfaaa09a-a73b-4b28-be11-1f8027b20357','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cfaaa09a-a73b-4b28-be11-1f8027b20357') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cfaaa09a-a73b-4b28-be11-1f8027b20357');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e154184-ee18-47d8-a23d-f47a75637220','Primary standard','A measurement standard established using a primary reference measurement procedure, or created as an artifact chosen by convention, having the highest metrological quality and whose value is accepted without reference to other standards of the same kind. It sits at the top of the traceability chain for its quantity.','A primary standard is the top reference for a quantity. Its value is accepted on its own, not by comparing to another standard. It has the highest measurement quality. Other standards are calibrated down from it. It anchors the traceability chain.','It provides the highest-level reference from which all lower standards and working instruments derive their traceability.','A national lab''s primary standard for sound pressure, realized by reciprocity calibration of laboratory microphones, anchors the chain that a technician''s field calibrator ultimately traces to.','Metrology Concept',ARRAY['Metrological traceability','Secondary standard','Measurement standard','Calibration','Metrology']::text[],ARRAY['Calling any high-accuracy device a primary standard; it must have the defined top-level status.','Assuming a primary standard has no uncertainty; it has the lowest, not zero.','Confusing a primary standard with a working reference on the test floor.']::text[],ARRAY['Understanding the top of a calibration hierarchy.','Explaining how field instruments trace to national labs.','Auditing a laboratory''s reference standards.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Primary standard');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e154184-ee18-47d8-a23d-f47a75637220','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e154184-ee18-47d8-a23d-f47a75637220') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e154184-ee18-47d8-a23d-f47a75637220');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a3fc3b52-5333-426c-b10c-1b5b1970b8ea','Prominent discrete tone','A tonal component in a product''s noise emission judged prominent by an objective criterion, using the tone-to-noise ratio or the prominence ratio against the surrounding critical band. In common implementations (ISO 7779, ECMA-74, ANSI S1.13), a tone above roughly 1 kHz is prominent if its tone-to-noise ratio exceeds about 8 dB or its prominence ratio exceeds about 9 dB, with more demanding thresholds at lower frequencies.','A prominent discrete tone is a clear single-pitch whine in a product''s noise. Standards decide ''prominent'' with objective ratios, not opinion. One compares the tone to the noise right around it. Above about one kilohertz, a tone-to-noise ratio over roughly eight decibels usually counts as prominent.','It gives an objective, repeatable way to decide whether an annoying pure-tone component in equipment noise must be reported or controlled.','Analyzing a server''s noise, a technician finds a 2 kHz tone with a 10 dB tone-to-noise ratio, exceeding the ~8 dB threshold, so it is declared a prominent discrete tone.','Tonal Assessment',ARRAY['Tone-to-noise ratio','Prominence ratio','Critical band','Tonality','Sound power']::text[],ARRAY['Judging prominence by ear instead of the standard''s objective ratio.','Using a fixed threshold at all frequencies; low-frequency thresholds are stricter.','Confusing tone-to-noise ratio with prominence ratio; they are defined differently.']::text[],ARRAY['Assessing information-technology equipment noise.','Declaring tonal components on a noise label.','Diagnosing a pure-tone whine in a product.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Prominent discrete tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a3fc3b52-5333-426c-b10c-1b5b1970b8ea','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a3fc3b52-5333-426c-b10c-1b5b1970b8ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a3fc3b52-5333-426c-b10c-1b5b1970b8ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f28048a2-f0df-4953-96df-4644591fafd9','Random error','The component of measurement error that varies unpredictably in replicate measurements of the same quantity, equal to the total error minus the systematic error. Its expected value is zero, it is characterized by a dispersion such as standard deviation, and averaging more readings reduces it.','Random error is the part of error that jumps around between repeated readings. It has no fixed direction, unlike bias. On average it cancels toward zero. Taking more readings and averaging shrinks it. It is described by spread, such as standard deviation.','It names the unpredictable, averaging-reducible part of error, distinct from fixed systematic bias.','Repeating an SPL reading ten times, a technician sees scatter of about 0.3 dB; averaging the ten values reduces the random component by the square root of ten.','Metrology Concept',ARRAY['Systematic error','Measurement error','Standard deviation','Measurement uncertainty','Repeatability']::text[],ARRAY['Assuming averaging removes systematic error; it only reduces random error.','Confusing random error with a mistake or blunder.','Treating a single reading''s scatter as the full uncertainty, ignoring bias.']::text[],ARRAY['Deciding how many readings to average.','Separating scatter from bias in results.','Estimating repeatability of a measurement.']::text[],'Beginner','e_random = e_total - e_systematic;  u_mean = s / sqrt(n)','Random error equals total error minus systematic error; averaging n readings reduces the random uncertainty of the mean by the square root of n.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Random error');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f28048a2-f0df-4953-96df-4644591fafd9','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f28048a2-f0df-4953-96df-4644591fafd9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f28048a2-f0df-4953-96df-4644591fafd9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '295c325f-a00b-4cf1-8c64-b83447f16e73','Rating level','The A-weighted equivalent continuous sound level of a source over a stated period, increased by adjustments (penalties) that account for tonal, impulsive, or other especially annoying characteristics of the noise. It is the quantity compared against environmental-noise limits.','A rating level is a measured noise level plus penalties. Pure tones or bangs get added decibels because they annoy people more. The final number is what gets checked against local noise limits. It is not just the raw meter reading.','It converts a raw noise measurement into a figure that better reflects human annoyance, so authorities can judge a source fairly against legal limits.','A technician measures a plant at 48 dB(A) equivalent level; because a clear tone is audible, a +5 dB tonal penalty gives a rating level of 53 dB(A) for comparison with a 55 dB limit.','Environmental Metric',ARRAY['A weighting','Equivalent continuous level','Tonality','Threshold level','Slow time weighting']::text[],ARRAY['Comparing the raw equivalent level to a limit and forgetting the tonal or impulsive penalty.','Assuming the adjustments are always +5 dB; the value depends on the standard and the assessment method.','Confusing rating level with a simple maximum reading; it is a period-averaged, adjusted quantity.']::text[],ARRAY['Assessing whether an industrial site meets a night-time noise ordinance.','Documenting a tonal penalty for a transformer hum near homes.','Preparing a noise-impact report for a planning application.']::text[],'Advanced','L_r = L_Aeq,T + K_T + K_I + K_R','The rating level equals the A-weighted equivalent continuous level over the assessment period plus adjustments for tonal, impulsive, and other special character.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rating level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '295c325f-a00b-4cf1-8c64-b83447f16e73','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='295c325f-a00b-4cf1-8c64-b83447f16e73') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='295c325f-a00b-4cf1-8c64-b83447f16e73');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c797312d-7041-43a7-a00e-e665c3070476','Reactive intensity','The imaginary part of the complex sound intensity, representing local oscillating energy that surges back and forth without a net time-averaged flow of acoustic power. It dominates in the near field of sources and in standing-wave fields.','Reactive intensity is sound energy that sloshes back and forth. It does not travel away as net power. It is strong very close to a source. Meters must separate it from the real, outward-flowing energy.','It flags near-field and standing-wave conditions where energy is stored locally rather than radiated, warning that sound-power results from that region may be unreliable.','When mapping a machine, a technician sees high reactive intensity within a few centimetres of the surface, so the probe is moved outward until the active (real) intensity dominates before logging sound power.','Sound Intensity',ARRAY['Residual intensity','Spacer distance','Surface scanning','Sound-power source','Reverberation-room method']::text[],ARRAY['Treating the total measured intensity as net radiated power in the near field.','Ignoring that strong reactive fields raise the phase demands on the probe.','Assuming reactive intensity carries energy away; its time-average net flow is zero.']::text[],ARRAY['Measuring sound power close to a vibrating panel.','Diagnosing standing waves inside a duct or cavity.','Deciding how far from a source to place an intensity probe.']::text[],'Advanced','I(w) = (1/2)*P(w)*U*(w);  active I_a = (1/2)*Re{P*U*},  reactive I_r = (1/2)*Im{P*U*}','The reactive intensity is the imaginary part of one-half the product of the complex pressure and the complex conjugate of the particle velocity.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reactive intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c797312d-7041-43a7-a00e-e665c3070476','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c797312d-7041-43a7-a00e-e665c3070476') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c797312d-7041-43a7-a00e-e665c3070476');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3b2d8aeb-ce61-4aef-b07a-5040a4f8f06e','Reference sound source','A stable, broadband aerodynamic sound source whose sound power output has been calibrated and certified, used as a known reference in comparison and substitution methods for determining the sound power of other sources. Its performance and calibration are specified by ISO 6926.','A reference sound source is a calibrated noise maker. Its exact sound power is already known. Engineers use it to check a room or to compare against an unknown machine. It gives measurements a trusted starting point.','It provides a traceable, repeatable acoustic output so that a test room can be characterized or an unknown source''s power found by direct comparison.','In a comparison test, a technician runs the reference source of known 90 dB sound power level, notes the room''s response, then substitutes the machine and scales its reading against that reference.','Reference Source',ARRAY['Sound-power source','Reverberation-room method','Reference standard','Secondary standard','Surface scanning']::text[],ARRAY['Assuming any loudspeaker can serve as a reference source without ISO 6926 calibration.','Forgetting that the source needs periodic recalibration to stay traceable.','Confusing the reference sound source with a reference microphone or calibrator.']::text[],ARRAY['Qualifying a reverberation room before sound-power testing.','Comparing an appliance''s sound power to a certified source.','Checking measurement consistency between two laboratories.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference sound source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3b2d8aeb-ce61-4aef-b07a-5040a4f8f06e','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3b2d8aeb-ce61-4aef-b07a-5040a4f8f06e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3b2d8aeb-ce61-4aef-b07a-5040a4f8f06e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ecc8808d-6500-4b76-a0d1-047b0e100f15','Reference standard','A measurement standard, of the highest metrological quality available at a given location or organization, from which measurements made there are derived. Working instruments are calibrated against it rather than against a national or primary standard directly.','A reference standard is a lab''s best measuring benchmark. Everyday tools are checked against it. It sits below the national standard but above the working gear. It anchors the lab''s accuracy.','It gives a facility a single, trusted anchor for calibrations, keeping all its working instruments consistent and traceable to higher standards.','A calibration lab keeps a reference microphone calibrated by a national institute, then uses it to calibrate the working microphones technicians take into the field.','Metrology',ARRAY['Secondary standard','Reference sound source','Standard uncertainty','Systematic error','Repeatability']::text[],ARRAY['Confusing a reference standard with a primary (national) standard.','Using a reference standard for daily field work, wearing down its accuracy.','Assuming it never needs recalibration or traceability records.']::text[],ARRAY['Maintaining traceability in a calibration laboratory.','Calibrating working sound level meters against a lab reference.','Auditing a quality system for measurement traceability.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference standard');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ecc8808d-6500-4b76-a0d1-047b0e100f15','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ecc8808d-6500-4b76-a0d1-047b0e100f15') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ecc8808d-6500-4b76-a0d1-047b0e100f15');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e9d295eb-50e2-4104-b51e-58af757fb59f','Reference-channel measurement','A dual-channel analysis method in which one channel captures the reference (excitation or input) signal and a second captures the system''s response, so the complex ratio of the two yields a transfer function independent of the source spectrum. It underlies dual-FFT tools used for live sound and acoustics.','This method records two signals at once. One is the source signal sent in. The other is what comes out. Dividing output by input gives the system''s response. The source''s own shape then cancels out.','It lets a technician measure a device or room using any signal, even music, because the reference channel removes the excitation spectrum from the result.','Using a dual-FFT analyzer, a technician feeds the console output to the reference input and a measurement mic to the other; the software shows the loudspeaker''s magnitude and phase versus frequency.','Measurement Method',ARRAY['Test-signal spectrum','Reflection-free window','Time-delay spectrometry','Time resolution','Reference standard']::text[],ARRAY['Forgetting to time-align the reference and measurement channels, which corrupts phase.','Assuming a poor coherence result is still a valid transfer function.','Confusing the reference channel with a simple loopback for latency only.']::text[],ARRAY['Aligning a live sound system with a dual-FFT analyzer.','Measuring a loudspeaker''s frequency response using music as the signal.','Verifying delay times between subwoofers and main arrays.']::text[],'Advanced','H(f) = G_xy(f) / G_xx(f)','The transfer function equals the cross-power spectrum of the reference and response channels divided by the auto-power spectrum of the reference channel.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference-channel measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e9d295eb-50e2-4104-b51e-58af757fb59f','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e9d295eb-50e2-4104-b51e-58af757fb59f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e9d295eb-50e2-4104-b51e-58af757fb59f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a674f0b4-0794-4488-a823-3ba8f099dafc','Reflection-free window','A time interval in an impulse-response measurement that begins at the arrival of the direct sound and ends just before the first significant reflection, used to obtain a quasi-anechoic frequency response. Its length sets the lowest frequency that can be resolved reliably.','This is a slice of the recorded impulse. It keeps only the direct sound and cuts off room echoes. That lets you measure a speaker as if in an open field. A shorter window loses low-frequency detail.','It removes room reflections from a measurement so a loudspeaker''s true response can be seen without building a full anechoic chamber.','If the first reflection arrives 5 ms after the direct sound, the technician windows out to about 5 ms, giving trustworthy data only above roughly 1/0.005 s = 200 Hz.','Measurement Method',ARRAY['Time-delay spectrometry','Reference-channel measurement','Time resolution','Test-signal spectrum','Reactive intensity']::text[],ARRAY['Trusting low-frequency data below the window''s frequency limit.','Placing the window boundary after a reflection has already entered.','Forgetting that a longer window needs the mic farther from surfaces.']::text[],ARRAY['Measuring a loudspeaker outdoors or in a normal room.','Comparing on-axis response free of floor bounce.','Setting gate times in an impulse-response analyzer.']::text[],'Advanced','f_min ~ 1 / t_w','The lowest reliably resolved frequency is approximately the reciprocal of the reflection-free window length.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reflection-free window');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a674f0b4-0794-4488-a823-3ba8f099dafc','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a674f0b4-0794-4488-a823-3ba8f099dafc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a674f0b4-0794-4488-a823-3ba8f099dafc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '62a13168-41d0-4eb8-a5c5-536cf901d120','Repeatability','The closeness of agreement between successive measurement results of the same quantity carried out under the same conditions: same method, same operator, same instrument, same location, and short time interval. It expresses the precision of a measurement under those unchanged conditions.','Repeatability is how close repeat readings are. You keep everything the same: same person, tool, and place. You measure again right away. Tight agreement means good repeatability.','It quantifies short-term precision, showing how much a result scatters when nothing about the setup is deliberately changed.','A technician measures a source ten times without changing anything and finds a standard deviation of 0.2 dB; that spread is reported as the repeatability of the measurement.','Metrology',ARRAY['Reproducibility','Standard uncertainty','Systematic error','Reference standard','Secondary standard']::text[],ARRAY['Confusing repeatability (same conditions) with reproducibility (changed conditions).','Treating good repeatability as proof of accuracy; a repeatable result can still be biased.','Changing operator or instrument mid-test and still calling it repeatability.']::text[],ARRAY['Reporting the precision of a sound-power test rig.','Validating that a meter gives stable repeat readings.','Writing an uncertainty budget for a calibration.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Repeatability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '62a13168-41d0-4eb8-a5c5-536cf901d120','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='62a13168-41d0-4eb8-a5c5-536cf901d120') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='62a13168-41d0-4eb8-a5c5-536cf901d120');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '043c65f7-1ebb-40c0-9b3f-3d74ba7dc8d7','Reproducibility','The closeness of agreement between measurement results of the same quantity obtained under changed conditions, such as different operators, instruments, laboratories, or times. It expresses precision when the measurement is deliberately varied within its defined method.','Reproducibility is agreement across different setups. Different people, tools, or labs measure the same thing. If their results still match closely, it is good. It is a harder test than repeatability.','It shows whether a measurement method gives consistent results beyond one operator or lab, which matters for standards and inter-laboratory comparisons.','Three laboratories test the same loudspeaker and report sound power within 1.0 dB of each other; that between-lab spread is the method''s reproducibility.','Metrology',ARRAY['Repeatability','Standard uncertainty','Systematic error','Reference standard','Reference sound source']::text[],ARRAY['Using reproducibility and repeatability as synonyms.','Ignoring which conditions were changed when quoting the figure.','Assuming a method with good repeatability automatically has good reproducibility.']::text[],ARRAY['Running an inter-laboratory round-robin comparison.','Qualifying a test method for an international standard.','Comparing results between two measurement teams.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reproducibility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '043c65f7-1ebb-40c0-9b3f-3d74ba7dc8d7','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='043c65f7-1ebb-40c0-9b3f-3d74ba7dc8d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='043c65f7-1ebb-40c0-9b3f-3d74ba7dc8d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa88d8ed-68d1-4ab4-97bb-3ac06b7b4fe7','Residual distortion','The distortion and noise inherent in the test equipment itself, generated by the signal source and analyzer rather than by the device under test. It sets the noise-and-distortion floor below which a measured device''s performance cannot be resolved.','Residual distortion is the tester''s own error. The generator and analyzer add tiny distortion. That floor limits what you can measure. A device cleaner than the floor cannot be judged.','It defines the best distortion figure an instrument can measure, so technicians know when a reading reflects the device rather than the test gear.','If an analyzer''s residual THD+N is 0.0005 percent, a device measuring 0.0006 percent is near the floor, so the technician loops the generator to the analyzer to confirm the residual before trusting the result.','Distortion Metric',ARRAY['Second-harmonic distortion','Third-harmonic distortion','Spurious-free dynamic range','Test-signal spectrum','Systematic error']::text[],ARRAY['Reporting a device distortion figure lower than the analyzer''s own residual.','Not checking the loopback residual before measuring very clean devices.','Confusing residual distortion with the device''s actual distortion.']::text[],ARRAY['Verifying an audio analyzer''s floor before a low-distortion test.','Qualifying whether a converter''s distortion is real or instrument-limited.','Selecting a generator clean enough for a given device.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Residual distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa88d8ed-68d1-4ab4-97bb-3ac06b7b4fe7','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa88d8ed-68d1-4ab4-97bb-3ac06b7b4fe7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa88d8ed-68d1-4ab4-97bb-3ac06b7b4fe7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6861e669-e26d-4624-8def-255075478894','Residual intensity','The non-zero sound intensity indicated by an intensity probe when both microphones are exposed to the same sound pressure, which ideally should read zero. It arises from phase mismatch between the microphone channels and defines the instrument''s dynamic capability through the pressure-residual intensity index.','Residual intensity is a false reading. It appears when both mics feel identical sound. The true answer should be zero. Any leftover comes from channel phase errors. It limits how good the probe is.','It measures the probe''s phase accuracy, setting how large a pressure-to-intensity difference can be measured before instrument error dominates.','In a coupler test both mics see the same field; the pressure level minus the residual intensity level gives a pressure-residual intensity index, and a value of 10 dB or more is needed for engineering-grade (ISO 9614-2) work.','Sound Intensity',ARRAY['Reactive intensity','Spacer distance','Surface scanning','Systematic error','Reference sound source']::text[],ARRAY['Assuming the probe reads exactly zero when both mics sense the same pressure.','Working with a pressure-intensity difference beyond the instrument''s dynamic capability.','Skipping the coupler check that establishes the residual intensity index.']::text[],ARRAY['Verifying an intensity probe before a sound-power survey.','Judging whether a reactive field exceeds the probe''s capability.','Documenting instrument phase performance in a test report.']::text[],'Advanced','delta_pI0 = L_p - L_I0  (dB)','The pressure-residual intensity index equals the sound pressure level minus the residual intensity level indicated when both microphones sense the same pressure field.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Residual intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6861e669-e26d-4624-8def-255075478894','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6861e669-e26d-4624-8def-255075478894') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6861e669-e26d-4624-8def-255075478894');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8261fbd-d9fa-4617-a79b-a351f9dd0304','Reverberation-room method','A method of determining a source''s sound power by measuring the space-averaged sound pressure level produced in a highly reverberant (diffuse-field) test room of known acoustic properties. ISO 3741 specifies this as a precision (grade 1) procedure.','This method finds sound power inside an echoey room. The room spreads sound evenly everywhere. You average the pressure level around the room. From that and the room data you compute total power.','It yields accurate, standardized sound power values in a diffuse field, useful for broadband sources that do not need directional information.','A technician runs an appliance in a qualified reverberation room, averages the level over several microphone positions, and adds a room correction to obtain the sound power level in decibels re 1 pW.','Sound Power Method',ARRAY['Reference sound source','Sound-power source','Surface scanning','Reverberation time','Reference standard']::text[],ARRAY['Expecting directivity data from a diffuse-field method that gives only total power.','Using a room that fails the qualification for field diffuseness.','Forgetting the room and reference-source corrections in the calculation.']::text[],ARRAY['Rating the sound power of a household appliance.','Comparing broadband noise emission between products.','Meeting a purchasing specification stated in sound power level.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverberation-room method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8261fbd-d9fa-4617-a79b-a351f9dd0304','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8261fbd-d9fa-4617-a79b-a351f9dd0304') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8261fbd-d9fa-4617-a79b-a351f9dd0304');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b93cc84-27f8-42f6-85e6-d4b44963c85f','Second-harmonic distortion','A nonlinear distortion product appearing at exactly twice the frequency of a pure sine input signal, caused by asymmetry in a device''s transfer characteristic. Its amplitude relative to the fundamental, expressed as a percentage or in decibels, quantifies the second-order nonlinearity.','Second-harmonic distortion is an extra tone. It sits at double the test tone''s frequency. It comes from a lopsided response. Its size versus the main tone shows how bad it is.','It isolates second-order nonlinearity, which often signals asymmetric clipping or bias errors in amplifiers, transducers, and converters.','Feeding a 1 kHz sine, a technician measures the 2 kHz component at 0.1 percent of the fundamental (about -60 dB), reporting 0.1 percent second-harmonic distortion.','Distortion Metric',ARRAY['Third-harmonic distortion','Residual distortion','Total harmonic distortion','Spurious-free dynamic range','Test-signal spectrum']::text[],ARRAY['Confusing a single harmonic percentage with total harmonic distortion.','Mistaking a spurious tone or mains hum for the true second harmonic.','Measuring below the analyzer''s residual distortion floor.']::text[],ARRAY['Characterizing an amplifier''s low-order distortion.','Diagnosing asymmetric clipping in a signal chain.','Comparing loudspeaker harmonic distortion by order.']::text[],'Intermediate','HD2 = A2 / A1  (x100 for percent);  in dB = 20*log10(A2/A1)','Second-harmonic distortion is the amplitude of the component at twice the fundamental frequency divided by the amplitude of the fundamental.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Second-harmonic distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b93cc84-27f8-42f6-85e6-d4b44963c85f','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b93cc84-27f8-42f6-85e6-d4b44963c85f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b93cc84-27f8-42f6-85e6-d4b44963c85f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'de66d25a-3dff-4085-9949-dae72087926b','Secondary standard','A measurement standard established through calibration against a primary standard of the same quantity. It transfers the value from the primary standard to working reference standards and instruments with a known, added uncertainty.','A secondary standard is calibrated from a primary one. It carries the primary''s value down the chain. Each step adds a little uncertainty. It is a middle rung of traceability.','It spreads a primary standard''s accuracy across labs and instruments without exposing the fragile primary standard to routine use.','A national lab calibrates a secondary reference microphone against its primary standard; regional labs then use that secondary to calibrate the meters technicians carry.','Metrology',ARRAY['Reference standard','Standard uncertainty','Repeatability','Reproducibility','Systematic error']::text[],ARRAY['Treating a secondary standard as if it had zero added uncertainty.','Confusing secondary with reference or working standard roles.','Skipping recalibration against the primary standard on schedule.']::text[],ARRAY['Maintaining a calibration chain in a metrology lab.','Transferring a value from a national standard to field tools.','Building a traceability pyramid for an audit.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Secondary standard');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'de66d25a-3dff-4085-9949-dae72087926b','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='de66d25a-3dff-4085-9949-dae72087926b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='de66d25a-3dff-4085-9949-dae72087926b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '63086e2c-eb08-47d2-91d0-c1eb88a70275','Shaped-noise test','A test that excites a device with random noise whose spectrum has been filtered to a specified shape, such as pink noise or the program-simulating noise defined in IEC 60268-1, so that the stimulus resembles real audio program material. It is used for power handling, thermal, and maximum-level testing.','A shaped-noise test uses filtered noise. Its spectrum is bent to match real music. Flat white noise would stress the treble too much. The shaped signal loads a device more realistically.','It stresses a device the way real program material does, giving fairer power-handling and maximum-output results than a single tone or flat noise.','To rate a loudspeaker''s power handling, a technician drives it for hours with IEC program-simulating noise at the rated power and checks for damage or excess compression.','Test Signal',ARRAY['Test-signal spectrum','Short-term maximum SPL','Spectral crest factor','Reference-channel measurement','Third-harmonic distortion']::text[],ARRAY['Using flat white noise and over-stressing the high-frequency driver.','Ignoring the crest factor the standard specifies for the noise.','Assuming a single-tone rating predicts real program power handling.']::text[],ARRAY['Power-handling endurance testing of a loudspeaker.','Measuring maximum sound pressure level with realistic content.','Thermal testing of a driver''s voice coil.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shaped-noise test');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '63086e2c-eb08-47d2-91d0-c1eb88a70275','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='63086e2c-eb08-47d2-91d0-c1eb88a70275') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='63086e2c-eb08-47d2-91d0-c1eb88a70275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '333e4a40-35a2-4f67-9a94-d9324d663050','Short-term maximum SPL','The highest sound pressure level a loudspeaker or system can produce under a brief measurement that does not invoke long-term thermal effects, with the level limited by defined performance thresholds for compression, nonlinear distortion, and impulsive distortion. IEC 60268-21 defines this output-based measurement.','Short-term maximum SPL is a peak loudness rating. It uses a brief test signal. Heat build-up is not the limit here. Distortion and compression limits set the ceiling. It shows what a speaker can do in short bursts.','It states how loud a system can play briefly before distortion or compression exceeds set limits, guiding system design and honest specifications.','Using IEC 60268-21, a technician raises the drive level until compression or distortion crosses the chosen limits and records the resulting SPL, for example 121 dB at 1 m, as the short-term maximum.','Output Metric',ARRAY['Shaped-noise test','Spectral crest factor','Third-harmonic distortion','Test-signal spectrum','Second-harmonic distortion']::text[],ARRAY['Confusing short-term maximum SPL with long-term (thermally limited) maximum SPL.','Quoting a peak SPL without stating the distortion and compression limits used.','Assuming the figure is continuous output the system can sustain indefinitely.']::text[],ARRAY['Specifying a loudspeaker''s peak output for a venue design.','Comparing headroom claims between products fairly.','Verifying a manufacturer''s maximum SPL rating.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Short-term maximum SPL');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '333e4a40-35a2-4f67-9a94-d9324d663050','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='333e4a40-35a2-4f67-9a94-d9324d663050') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='333e4a40-35a2-4f67-9a94-d9324d663050');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea98eca5-6eef-4717-afe4-80cf738ea8e7','Slow time weighting','An exponential time-averaging characteristic in a sound level meter that uses a one-second time constant, giving a slowly responding, well-smoothed reading of fluctuating sound. It is one of the standardized time weightings defined in IEC 61672-1, denoted ''S''.','Slow time weighting smooths the meter''s needle. It averages sound over about one second. Fast changes are ironed out. It is easier to read steady levels this way. Meters mark this setting as ''S''.','It steadies a fluctuating reading so an operator can note a representative level, useful for varying environmental and occupational noise.','A technician sets a meter to ''S'' when logging traffic noise; the one-second averaging keeps the display steady enough to read, showing about 62 dB(A) instead of a jittery number.','Measurement Weighting',ARRAY['Time-weighting sound-level meter','Time resolution','A weighting','Rating level','Short-term maximum SPL']::text[],ARRAY['Comparing a Slow reading directly to a Fast reading of the same fluctuating sound.','Using Slow weighting to capture short impulsive peaks it will under-read.','Assuming Slow (1 s) and Fast (0.125 s) give identical results for steady tones.']::text[],ARRAY['Logging steady environmental noise levels.','Reading a fluctuating machine noise for a survey.','Following a standard that specifies ''S'' weighting.']::text[],'Intermediate','L(t) = 10*log10{ (1/(p0^2 * tau)) * integral_{-inf}^{t} p^2(x) * e^{-(t-x)/tau} dx },  tau_S = 1 s','The slow-weighted level is ten times the base-ten log of an exponentially time-averaged squared pressure using a one-second time constant, referenced to 20 micropascals.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Slow time weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea98eca5-6eef-4717-afe4-80cf738ea8e7','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea98eca5-6eef-4717-afe4-80cf738ea8e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea98eca5-6eef-4717-afe4-80cf738ea8e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e3c9fbe-7662-4aa0-a7be-31699558c97c','Sound-power source','A source characterized by the total acoustic power it radiates, expressed as a sound power level in decibels relative to one picowatt, rather than by the sound pressure it produces at a point. Sound power is a property of the source itself, independent of the room or distance.','A sound-power source is rated by total energy output. It is not tied to one listening spot. Pressure changes with distance and room. Power does not. It describes the source alone.','It lets products be compared by an intrinsic emission figure that does not depend on how far away you stand or what room you are in.','A technician reports a fan as having a sound power level of 85 dB re 1 pW, a fixed source property, rather than a pressure level that would change with distance.','Sound Power',ARRAY['Reference sound source','Reverberation-room method','Surface scanning','Sound pressure level','Reactive intensity']::text[],ARRAY['Confusing sound power (source property) with sound pressure (position-dependent).','Quoting a sound power level as if it were a level at one metre.','Using the wrong reference; sound power is referenced to 1 pW, not 20 micropascals.']::text[],ARRAY['Labelling appliance noise emission on a data sheet.','Comparing machinery noise independent of test distance.','Feeding source data into a room noise prediction.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-power source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e3c9fbe-7662-4aa0-a7be-31699558c97c','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e3c9fbe-7662-4aa0-a7be-31699558c97c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e3c9fbe-7662-4aa0-a7be-31699558c97c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '531befbc-87b3-4c5a-b023-5c7d45d838b4','Spacer distance','The fixed separation between the two microphone diaphragms in a pressure-pressure sound intensity probe, used in a finite-difference approximation to estimate the pressure gradient and hence particle velocity. The spacer length sets the probe''s usable frequency range.','The spacer distance is the gap between two mics. The probe uses the pressure difference across it. That gives particle velocity. A short spacer suits high frequencies; a long spacer suits low ones.','It sets the length over which the pressure gradient is estimated, trading low-frequency accuracy against high-frequency validity in the finite-difference method.','For a 125 Hz to 5 kHz survey a technician fits a 12 mm spacer; swapping to a 50 mm spacer extends coverage down toward 31.5 Hz but lowers the high-frequency limit.','Sound Intensity',ARRAY['Residual intensity','Reactive intensity','Surface scanning','Sound-power source','Time resolution']::text[],ARRAY['Using one spacer across the whole audio band and losing accuracy at the extremes.','Exceeding the high-frequency limit set by the spacer length.','Forgetting the spacer choice interacts with the residual intensity index.']::text[],ARRAY['Selecting a probe spacer for a low-frequency machine survey.','Splitting a wide-band measurement into spacer-appropriate ranges.','Setting up an intensity probe for sound-power scanning.']::text[],'Advanced','u_r(t) ~ -(1/(rho0 * delta_r)) * integral [p2(t) - p1(t)] dt','Particle velocity is approximated by integrating the pressure difference between the two microphones divided by air density times the spacer distance.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spacer distance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '531befbc-87b3-4c5a-b023-5c7d45d838b4','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='531befbc-87b3-4c5a-b023-5c7d45d838b4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='531befbc-87b3-4c5a-b023-5c7d45d838b4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f9650c22-63bc-437b-8853-207beb1278d5','Spectral crest factor','The ratio of the peak magnitude of a signal''s magnitude spectrum to the mean magnitude across the analyzed band, indicating how tonal (peaky) versus noise-like (flat) the spectrum is. A high spectral crest factor marks a strong discrete spectral component.','Spectral crest factor compares a spectrum''s tallest peak to its average. A big ratio means a strong single tone. A small ratio means flat, noise-like content. It is the crest factor idea applied across frequency.','It gives a quick number for how much a spectrum is dominated by tones, useful in noise analysis and audio feature extraction.','Analyzing fan noise, a technician finds a spectral crest factor of 8 in one band, flagging a prominent tone worth investigating, versus about 1.5 for a smooth broadband band.','Spectral Metric',ARRAY['Tonality','Test-signal spectrum','Crest factor','Spurious-free dynamic range','Shaped-noise test']::text[],ARRAY['Confusing the spectral (frequency-domain) crest factor with the time-domain peak-to-RMS crest factor.','Comparing values without stating the analysis band and resolution.','Treating it as a calibrated tonality metric rather than a rough indicator.']::text[],ARRAY['Screening a noise spectrum for prominent tones.','Extracting audio features for classification.','Comparing tonal content between operating states of a machine.']::text[],'Advanced','C_spec = max|X(f)| / mean|X(f)|','The spectral crest factor equals the peak magnitude of the spectrum divided by the average magnitude over the analyzed frequency band.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral crest factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f9650c22-63bc-437b-8853-207beb1278d5','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f9650c22-63bc-437b-8853-207beb1278d5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f9650c22-63bc-437b-8853-207beb1278d5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '58191751-4059-422b-950d-2f32c4153c39','Spurious-free dynamic range','The ratio, in decibels, between the amplitude of the wanted fundamental signal (or full-scale level) and the amplitude of the largest single spurious spectral component within a stated band. It quantifies how far the worst discrete spur sits below the desired signal, especially in converters and analyzers.','Spurious-free dynamic range is the gap to the worst false tone. It compares the wanted signal to the biggest spur. A larger gap is better. It matters most for converters and spectrum analyzers.','It captures the single worst spectral artifact, which can matter more than average noise when a stray tone would be audible or mislead a measurement.','An analyzer shows a 0 dBFS tone with the largest spur at -95 dBFS, so the spurious-free dynamic range is 95 dB, meaning any real signal component above that floor is trustworthy.','Dynamic Range Metric',ARRAY['Residual distortion','Second-harmonic distortion','Third-harmonic distortion','Signal-to-noise ratio','Test-signal spectrum']::text[],ARRAY['Confusing spurious-free dynamic range with overall signal-to-noise ratio.','Not stating whether the reference is the fundamental (dBc) or full scale (dBFS).','Ignoring the analysis bandwidth, which changes which spur is largest.']::text[],ARRAY['Specifying an analog-to-digital converter for measurement use.','Judging whether a spur in a spectrum is instrument-generated.','Comparing spectral cleanliness of two signal generators.']::text[],'Advanced','SFDR = 20*log10(A_fund / A_spur)  (dBc), or referenced to full scale (dBFS)','Spurious-free dynamic range is the level difference in decibels between the fundamental, or full scale, and the largest single spurious spectral component.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spurious-free dynamic range');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '58191751-4059-422b-950d-2f32c4153c39','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='58191751-4059-422b-950d-2f32c4153c39') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='58191751-4059-422b-950d-2f32c4153c39');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99aeebc9-3940-4ac5-a52e-458261c9ae47','Standard uncertainty','The uncertainty of a measurement result expressed as a standard deviation. A Type A standard uncertainty is evaluated statistically from repeated observations, while a Type B is evaluated from other information such as calibration data or specifications.','Standard uncertainty is doubt stated as one standard deviation. Type A comes from repeated readings. Type B comes from other data, like a calibration sheet. It is the building block of an uncertainty budget.','It puts every source of measurement doubt on a common footing (a standard deviation) so they can be combined into an overall uncertainty.','From ten readings a technician gets a standard deviation of 0.3 dB; the Type A standard uncertainty of the mean is 0.3 divided by the square root of ten, about 0.095 dB.','Metrology',ARRAY['Repeatability','Reproducibility','Systematic error','Reference standard','Secondary standard']::text[],ARRAY['Reporting a full expanded uncertainty when a single standard uncertainty was asked for.','Forgetting to divide the standard deviation by the square root of n for the mean.','Treating a Type B estimate as less valid than a Type A.']::text[],ARRAY['Building an uncertainty budget for a calibration.','Combining scatter and calibration data into one figure.','Reporting measurement uncertainty in a test certificate.']::text[],'Intermediate','Type A: u(x) = s(x_bar) = s / sqrt(n)','A Type A standard uncertainty of the mean equals the sample standard deviation divided by the square root of the number of independent readings.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Standard uncertainty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99aeebc9-3940-4ac5-a52e-458261c9ae47','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99aeebc9-3940-4ac5-a52e-458261c9ae47') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99aeebc9-3940-4ac5-a52e-458261c9ae47');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0798417e-a562-473c-b55f-69d7e4c494e4','Surface scanning','A sound-intensity method in which the probe is moved at a steady speed over a defined measurement surface enclosing a source, so the average normal intensity times the surface area gives the radiated sound power. ISO 9614-2 standardizes this scanning procedure.','Surface scanning sweeps a probe over a source. You cover an imaginary shell around it. The probe reads energy flowing outward. Adding it over the whole surface gives total sound power.','It measures sound power in ordinary rooms, even with background noise, by integrating outward intensity over a surface rather than needing a special chamber.','A technician scans a machine along evenly spaced paths over a boxed surface at a constant hand speed; the software integrates normal intensity over the area to report the sound power level.','Sound Power Method',ARRAY['Reactive intensity','Residual intensity','Spacer distance','Sound-power source','Reverberation-room method']::text[],ARRAY['Scanning at an uneven speed, which biases the spatial average.','Leaving gaps in surface coverage so parts of the source are missed.','Ignoring the pressure-residual intensity index check that validates the field.']::text[],ARRAY['Measuring machine sound power on a factory floor.','Testing a source in situ where it cannot be moved to a lab.','Mapping which faces of an enclosure radiate the most power.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface scanning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0798417e-a562-473c-b55f-69d7e4c494e4','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0798417e-a562-473c-b55f-69d7e4c494e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0798417e-a562-473c-b55f-69d7e4c494e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6086ec47-f10f-48a9-93f3-bf4d396f1988','Systematic error','The component of measurement error that, in replicate measurements, stays constant or varies in a predictable way, producing a consistent bias in the results. Unlike random error, it does not average out with repeated readings and must be corrected or accounted for.','Systematic error is a steady bias. It pushes readings the same way each time. Repeating the measurement will not cancel it. You must find and correct it. Random error is different; it averages out.','Identifying it lets a technician apply corrections and separate a fixed bias from ordinary random scatter in an uncertainty analysis.','A meter reads 2 dB high because of an uncalibrated microphone; the technician applies a -2 dB correction so the systematic error no longer biases every result.','Metrology',ARRAY['Standard uncertainty','Repeatability','Reproducibility','Reference standard','Residual distortion']::text[],ARRAY['Expecting repeated readings to average out a systematic bias.','Confusing systematic error (bias) with random error (scatter).','Reporting only random uncertainty and ignoring a known offset.']::text[],ARRAY['Correcting a consistent offset from an uncalibrated sensor.','Separating bias from scatter in an uncertainty budget.','Investigating why two instruments disagree by a fixed amount.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Systematic error');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6086ec47-f10f-48a9-93f3-bf4d396f1988','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6086ec47-f10f-48a9-93f3-bf4d396f1988') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6086ec47-f10f-48a9-93f3-bf4d396f1988');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a05b66cb-6495-4a84-ba4a-e815b76a089e','Test-signal spectrum','The distribution of a measurement excitation signal''s energy across frequency, which determines what parts of a device''s behavior a test can reveal. Common choices include a single sine, white noise, pink noise, swept sine, and maximum-length sequences.','The test-signal spectrum is how a test signal''s energy spreads over frequency. A single tone probes one frequency. Noise or a sweep probes many at once. The choice shapes what the test can show.','It defines the frequency coverage and stress of a test, so the signal is matched to the property being measured, whether distortion, response, or power handling.','For a full frequency response, a technician picks a logarithmic swept sine so energy covers the whole band; for a single-frequency distortion figure, a pure 1 kHz sine is used instead.','Test Signal',ARRAY['Shaped-noise test','Spectral crest factor','Reference-channel measurement','Second-harmonic distortion','Reflection-free window']::text[],ARRAY['Using white noise when a device needs pink noise for a fair per-octave load.','Expecting harmonic distortion figures from a broadband noise stimulus.','Ignoring the signal''s crest factor when setting drive levels.']::text[],ARRAY['Choosing a stimulus for a loudspeaker response measurement.','Selecting pink noise for a per-octave power test.','Deciding between a sine and a sweep for distortion tests.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Test-signal spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a05b66cb-6495-4a84-ba4a-e815b76a089e','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a05b66cb-6495-4a84-ba4a-e815b76a089e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a05b66cb-6495-4a84-ba4a-e815b76a089e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c39b901a-5762-4557-870d-f5ab08bb178b','Third-harmonic distortion','A nonlinear distortion product appearing at exactly three times the frequency of a pure sine input, arising from symmetric (odd-order) nonlinearity in a device''s transfer characteristic. Its amplitude relative to the fundamental, in percent or decibels, quantifies the third-order nonlinearity.','Third-harmonic distortion is an extra tone at triple the test frequency. It comes from symmetric non-linearity, like clipping that is equal on the top and bottom. Its size versus the main tone rates it. Odd harmonics often sound harsher than even ones.','It isolates odd-order nonlinearity, which commonly points to symmetric compression or clipping in amplifiers and transducers.','With a 1 kHz sine input, a technician measures the 3 kHz component at 0.05 percent of the fundamental (about -66 dB) and reports 0.05 percent third-harmonic distortion.','Distortion Metric',ARRAY['Second-harmonic distortion','Residual distortion','Total harmonic distortion','Spurious-free dynamic range','Test-signal spectrum']::text[],ARRAY['Confusing a single harmonic figure with total harmonic distortion.','Mistaking a mains-related spur for the true third harmonic.','Measuring near or below the analyzer''s residual distortion floor.']::text[],ARRAY['Characterizing an amplifier''s odd-order distortion.','Diagnosing symmetric clipping in a signal chain.','Comparing loudspeaker distortion by harmonic order.']::text[],'Intermediate','HD3 = A3 / A1  (x100 for percent);  in dB = 20*log10(A3/A1)','Third-harmonic distortion is the amplitude of the component at three times the fundamental frequency divided by the amplitude of the fundamental.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Third-harmonic distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c39b901a-5762-4557-870d-f5ab08bb178b','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c39b901a-5762-4557-870d-f5ab08bb178b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c39b901a-5762-4557-870d-f5ab08bb178b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3210fe4-3630-4a58-9ec1-b07bd7f739fb','Threshold level','In noise dosimetry, the sound level below which a personal sound exposure meter does not accumulate noise dose. Sound at or above the threshold contributes to the measured exposure, while quieter sound is excluded; common regulatory thresholds are 80 dB(A).','The threshold level is a cut-off for a noise dose meter. Sound below it does not count toward exposure. Sound above it does. A common value is 80 dB(A). It stops quiet periods from adding to the dose.','It excludes low, harmless sound from a worker''s accumulated noise dose so exposure figures reflect genuinely hazardous levels under a chosen regulation.','A technician sets an 80 dB(A) threshold on a dosimeter per OSHA; a lunch break at 70 dB(A) adds nothing to the dose, while shop noise at 90 dB(A) accumulates toward the limit.','Noise Exposure',ARRAY['Rating level','Slow time weighting','A weighting','Time-weighting sound-level meter','Short-term maximum SPL']::text[],ARRAY['UNSAFE: Setting the threshold too high so real hazardous exposure is under-counted and hearing protection is wrongly deemed unnecessary.','Confusing the threshold level with the criterion level or the exchange rate.','Assuming all regulations use the same threshold; OSHA and other schemes differ.']::text[],ARRAY['Configuring a dosimeter for an occupational noise survey.','Comparing exposure results under different regulatory thresholds.','Explaining why quiet breaks do not add to a worker''s dose.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Threshold level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3210fe4-3630-4a58-9ec1-b07bd7f739fb','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3210fe4-3630-4a58-9ec1-b07bd7f739fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3210fe4-3630-4a58-9ec1-b07bd7f739fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e01c17e-52af-4b82-9fcc-b81794ddeee0','Time resolution','The smallest time interval a measurement or analysis can distinguish, set in spectral analysis by the analysis window length. It is inversely related to frequency resolution, so finer time detail necessarily gives coarser frequency detail.','Time resolution is how finely a measurement tells events apart in time. In a spectrum analyzer it depends on window length. Short windows see fast changes but blur frequency. It is a trade-off you cannot beat.','It governs whether short events, like a transient or a gap, can be separated in time, and it forces a deliberate trade-off with frequency resolution.','A technician using a 4096-point FFT at 48 kHz gets a window of about 85 ms, so events closer than that blur together; a shorter window sharpens timing but widens each frequency bin.','Analysis Property',ARRAY['Reflection-free window','Reference-channel measurement','Time-delay spectrometry','Slow time weighting','Test-signal spectrum']::text[],ARRAY['Expecting fine time and fine frequency resolution at the same time.','Confusing time resolution with the sampling interval alone.','Ignoring how window length sets the achievable timing detail.']::text[],ARRAY['Choosing an FFT size for a spectrogram of a transient.','Setting a gate window in an impulse-response measurement.','Balancing time and frequency detail in room analysis.']::text[],'Intermediate','delta_t ~ 1/delta_f  (delta_t * delta_f ~ 1);  for an FFT: delta_f = f_s/N = 1/T','Time resolution is roughly the reciprocal of frequency resolution; for a discrete Fourier transform the frequency bin width equals the sample rate divided by the number of points.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e01c17e-52af-4b82-9fcc-b81794ddeee0','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e01c17e-52af-4b82-9fcc-b81794ddeee0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e01c17e-52af-4b82-9fcc-b81794ddeee0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea9d8dbb-5ee3-4ddc-bbb2-36679daf2b72','Time-delay spectrometry','A measurement technique, introduced by Richard Heyser, that excites a system with a linearly swept sine wave and analyzes the response through a tracking bandpass filter offset in time by the acoustic propagation delay. This time offset rejects reflections and noise, yielding a quasi-anechoic frequency response.','Time-delay spectrometry sends a smooth rising tone into a system. A moving filter follows the sweep, delayed by the sound''s travel time. Because reflections arrive later, they fall outside the filter. That gives a clean, echo-free response.','It measures a loudspeaker or room response free of reflections and background noise without an anechoic chamber, by exploiting the delay between direct sound and reflections.','A technician measures a loudspeaker in a normal room using time-delay spectrometry; setting the tracking filter delay to the direct-path arrival time excludes the floor bounce from the frequency-response curve.','Measurement Method',ARRAY['Reflection-free window','Reference-channel measurement','Time resolution','Test-signal spectrum','Reverberation-room method']::text[],ARRAY['Setting the wrong propagation delay, which shifts the effective time window incorrectly.','Assuming it needs an anechoic room; its whole point is to avoid one.','Confusing the swept-sine tracking method with a simple gated FFT.']::text[],ARRAY['Measuring loudspeaker response in a reflective room.','Obtaining quasi-anechoic data without a chamber.','Separating direct sound from reflections in system tuning.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-delay spectrometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea9d8dbb-5ee3-4ddc-bbb2-36679daf2b72','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea9d8dbb-5ee3-4ddc-bbb2-36679daf2b72') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea9d8dbb-5ee3-4ddc-bbb2-36679daf2b72');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eaca8218-2bec-4c67-8bfa-698047b47c03','Time-weighting sound-level meter','A sound level meter that applies a standardized exponential time weighting, Fast (125 ms) or Slow (1000 ms), to the squared sound pressure before displaying the level. The time constant sets how quickly the reading responds to changes in the sound.','This meter smooths its reading over time. Fast uses a 0.125 second setting; Slow uses 1 second. A longer setting steadies the display. The chosen weighting is stated with the result, like dB(A) Slow.','It gives a readable, standardized measure of fluctuating sound, with the Fast or Slow setting chosen to suit how quickly the sound changes.','A technician selects Fast weighting to follow speech-like fluctuations and Slow weighting for steady plant noise, always reporting the setting, for example 78 dB(A) Fast.','Metering Instrument',ARRAY['Slow time weighting','A weighting','Threshold level','Rating level','Time resolution']::text[],ARRAY['Comparing Fast and Slow readings of the same fluctuating sound as if equal.','Relying on exponential time weighting to capture very short impulses accurately.','Confusing exponential time weighting with time-averaged (equivalent continuous) level.']::text[],ARRAY['Selecting Fast or Slow for a given noise character.','Reading fluctuating environmental noise on a meter.','Following a standard that specifies a time weighting.']::text[],'Intermediate','L(t) = 10*log10{ (1/(p0^2 * tau)) * integral_{-inf}^{t} p^2(x) * e^{-(t-x)/tau} dx };  tau_F = 0.125 s, tau_S = 1 s','The time-weighted level is ten times the base-ten log of the exponentially averaged squared pressure, using a 0.125-second (Fast) or one-second (Slow) time constant, referenced to 20 micropascals.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-weighting sound-level meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eaca8218-2bec-4c67-8bfa-698047b47c03','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eaca8218-2bec-4c67-8bfa-698047b47c03') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eaca8218-2bec-4c67-8bfa-698047b47c03');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0adae9eb-32df-4e50-9e52-8f24f2dcde5f','Tonality','A psychoacoustic attribute describing how prominent audible tonal (pitch-like) components are within a broadband sound. It is quantified by metrics such as the tone-to-noise ratio and the prominence ratio defined in ECMA-74, and by tonality models such as DIN 45681 and hearing-model methods.','Tonality is how much a sound has a clear pitch inside noise. A whine in a fan is a tonal component. Metrics score how strongly a tone stands out. Prominent tones raise annoyance even at modest levels.','It captures the extra annoyance of pure-tone components that a plain level measurement misses, supporting noise limits and product sound-quality work.','Analyzing a laptop fan, a technician computes a tone-to-noise ratio of 8 dB at 3 kHz, which exceeds the prominence criterion, so the tone is flagged as a prominent discrete tone for redesign.','Psychoacoustic Metric',ARRAY['Rating level','Spectral crest factor','Test-signal spectrum','Third-harmonic distortion','A weighting']::text[],ARRAY['Assuming a tone is inaudible just because its level is low; tonality can still make it prominent.','Mixing up tone-to-noise ratio and prominence ratio, which use different reference bands.','Reporting tonality without stating which standard or model was used.']::text[],ARRAY['Evaluating fan or motor whine in product sound quality.','Applying a tonal penalty in an environmental noise assessment.','Comparing tonal annoyance between design prototypes.']::text[],'Advanced','Tone-to-noise ratio: delta_L_T = L_t - L_n (dB);  Prominence ratio: PR = 10*log10( P_m / ((P_{m-1} + P_{m+1})/2) )','The tone-to-noise ratio is the tone level minus the masking-noise level in its critical band; the prominence ratio compares the power in the tone''s critical band to the average of the two neighbouring bands.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tonality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0adae9eb-32df-4e50-9e52-8f24f2dcde5f','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0adae9eb-32df-4e50-9e52-8f24f2dcde5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0adae9eb-32df-4e50-9e52-8f24f2dcde5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3277933c-9f96-4d55-8d94-3dfab59bf6ac','Traceability','Traceability is a property by which a measurement result can be connected to a stated reference through an unbroken, fully documented series of calibrations. Every step in that series contributes a known amount to the total measurement uncertainty. The reference is typically an SI unit maintained by a national or international measurement standard.','Traceability links your reading back to an official standard. It works through an unbroken chain of calibrations. Each step in the chain adds a small, known amount of doubt. The chain shows that your meter can be trusted.','It gives measurements a common, documented reference so results from different labs, instruments, and times can be fairly compared and trusted.','A technician sends a sound calibrator to an accredited lab; the returned certificate ties it to national standards and states its uncertainty, making field SPL readings defensible.','Metrology',ARRAY['Metrological traceability','Calibration hierarchy','Uncertainty budget','Reference standard','Working standard','Transfer standard']::text[],ARRAY['Thinking a calibration certificate alone proves traceability, without an unbroken and documented chain to a reference.','Assuming traceability guarantees small uncertainty; it only requires that the uncertainty be stated at each step.','Confusing traceability with plain accuracy or with a manufacturer''s factory calibration sticker.']::text[],ARRAY['Preparing measurement gear for an accredited or legally defensible noise survey.','Auditing a calibration lab''s paperwork before trusting its certificates.','Explaining why field SPL data must trace to a national standard.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Traceability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3277933c-9f96-4d55-8d94-3dfab59bf6ac','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3277933c-9f96-4d55-8d94-3dfab59bf6ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3277933c-9f96-4d55-8d94-3dfab59bf6ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ce48d45-326a-4766-9861-60ac5fd7cb0f','Transfer standard','A transfer standard is a measurement standard or device used as an intermediary to compare two other measurement standards, carrying a quantity value from one to the other. In audio metrology a stable reference, such as a precision microphone or a Zener voltage reference, is often used this way.','A transfer standard is a stable go-between. It carries a known value from one standard to another. Labs use it to compare standards without moving the main one. It must stay steady during the trip.','It lets a value be compared or moved between standards or labs when the primary standard cannot be shared directly.','To check a lab''s SPL calibrator, a technician uses a stable reference microphone as a transfer standard, comparing it against a higher-level standard and then against working gear.','Metrology',ARRAY['Reference standard','Working standard','Primary standard','Traceability','Calibration hierarchy','Secondary standard']::text[],ARRAY['Confusing a transfer standard with a primary standard; the transfer unit only carries a value, it does not define the unit.','Using an unstable device as a transfer standard, so drift during transport corrupts the comparison.','Assuming the transfer standard''s own uncertainty can be ignored in the chain.']::text[],ARRAY['Comparing two calibration labs'' pressure or voltage standards.','Round-robin interlaboratory comparisons of microphone calibration.','Moving a reference value between a national lab and a field calibration kit.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transfer standard');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ce48d45-326a-4766-9861-60ac5fd7cb0f','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ce48d45-326a-4766-9861-60ac5fd7cb0f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ce48d45-326a-4766-9861-60ac5fd7cb0f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2b8d9a2d-5dd6-4911-9f23-8ccf68d372a2','Transfer-function estimator','A transfer-function estimator computes a system''s frequency response from measured input and output signals using averaged spectra, typically ratios of cross- and auto-spectra. The common forms are H1, which assumes noise only on the output, H2, which assumes noise only on the input, and Hv, a weighted combination of the two.','This tool finds how a system changes a signal across frequency. It compares the input and output using averaged spectra. The H1 form works best when noise sits on the output. The H2 form works best when noise sits on the input.','It gives a noise-robust estimate of magnitude and phase response, and its choice sets how measurement noise biases the result.','Measuring a loudspeaker with dual-channel FFT, a technician picks the H1 estimator because room noise appears mainly at the output microphone, which reduces bias in the response.','Signal Analysis',ARRAY['H1 estimator','H2 estimator','Hv estimator','Coherence degradation','Dual-channel measurement','Complex frequency response']::text[],ARRAY['Assuming H1 and H2 give the same answer; they differ when both channels carry noise.','Ignoring coherence, which shows how trustworthy the estimate is at each frequency.','Using too few averages, so random noise leaves the response estimate biased and noisy.']::text[],ARRAY['Measuring a room or loudspeaker response with a dual-channel FFT analyzer.','Tuning a sound system with transfer-function software such as Smaart or SATlive.','Choosing an estimator when input versus output noise dominates.']::text[],'Advanced','H1(f) = Sxy(f) / Sxx(f) ;  H2(f) = Syy(f) / Syx(f)','The H1 estimate is the cross-spectrum of input and output divided by the input auto-spectrum. The H2 estimate is the output auto-spectrum divided by the cross-spectrum of output and input.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transfer-function estimator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2b8d9a2d-5dd6-4911-9f23-8ccf68d372a2','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2b8d9a2d-5dd6-4911-9f23-8ccf68d372a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2b8d9a2d-5dd6-4911-9f23-8ccf68d372a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '88b24029-ae3d-49d7-a7bf-bb17b3be0b60','Transient intermodulation distortion','Transient intermodulation distortion (TIM) is nonlinear distortion produced when a fast input transient briefly drives an amplifier past its slew-rate limit, so the negative-feedback loop momentarily loses control and generates intermodulation products. It is a dynamic effect tied to signal rate of change, not to steady-state amplitude alone.','TIM happens when a signal changes faster than an amplifier can follow. For a moment the feedback cannot correct the output. This creates unwanted new tones. It is measured with a fast square wave mixed with a high tone.','The concept explains why an amplifier with good steady-state specs can still sound harsh on fast transients, and it guides slew-rate design.','Using the DIM test, a technician feeds a 3.18 kHz square wave plus a 15 kHz sine at a 4:1 ratio and reads the summed intermodulation products as a percentage of the 15 kHz output.','Distortion',ARRAY['Dynamic intermodulation distortion','Slew rate','Intermodulation distortion','Negative feedback','Difference-frequency distortion']::text[],ARRAY['Believing low steady-state THD guarantees low TIM; TIM depends on slew rate and transients.','Blaming negative feedback itself, when the real cause is insufficient slew rate ahead of the loop.','Confusing TIM with static intermodulation, which uses two steady tones, not a fast transient.']::text[],ARRAY['Evaluating a power amplifier''s behavior on sharp musical transients.','Comparing amplifier slew-rate designs during a bench test.','Diagnosing harshness that standard THD tests do not reveal.']::text[],'Advanced','DIM (%) = (100 / V2) * sqrt( sum of Vn^2 )','Dynamic intermodulation distortion percent equals one hundred times the square root of the summed squared amplitudes of the intermodulation products, divided by the output high-frequency sine amplitude.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transient intermodulation distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '88b24029-ae3d-49d7-a7bf-bb17b3be0b60','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='88b24029-ae3d-49d7-a7bf-bb17b3be0b60') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='88b24029-ae3d-49d7-a7bf-bb17b3be0b60');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'de329376-9406-4ed5-8267-5e90a8b186ee','Type A evaluation','A Type A evaluation of measurement uncertainty is the estimation of an uncertainty component by the statistical analysis of measured values obtained under defined conditions. It typically uses the experimental standard deviation of the mean computed from repeated readings.','A Type A check finds doubt from repeated measurements. You take many readings and study their spread. More readings and a tighter spread mean less doubt. It uses statistics on your own data.','It quantifies the random part of uncertainty directly from repeated data, giving an evidence-based standard uncertainty.','Reading a 1 kHz level ten times gives a standard deviation of 0.2 dB; the Type A standard uncertainty of the mean is 0.2/sqrt(10), about 0.063 dB.','Measurement Uncertainty',ARRAY['Type B evaluation','Standard uncertainty','Combined standard uncertainty','Uncertainty budget','Repeatability']::text[],ARRAY['Thinking Type A means ''random'' and Type B means ''systematic''; the split is about method, not error type.','Using the sample standard deviation instead of the standard deviation of the mean for the uncertainty of an average.','Taking too few readings, which makes the statistical estimate itself unreliable.']::text[],ARRAY['Estimating uncertainty from repeated SPL or level readings.','Building an uncertainty budget for a calibration.','Deciding how many repeat measurements are enough.']::text[],'Intermediate','u(x_bar) = s / sqrt(n) ,  s = sqrt( (1/(n-1)) * sum( (xi - x_bar)^2 ) )','The standard uncertainty of the mean equals the sample standard deviation divided by the square root of the number of readings.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Type A evaluation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'de329376-9406-4ed5-8267-5e90a8b186ee','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='de329376-9406-4ed5-8267-5e90a8b186ee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='de329376-9406-4ed5-8267-5e90a8b186ee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9c396946-c11a-4956-862f-92b335c48f0d','Type B evaluation','A Type B evaluation of measurement uncertainty is the estimation of an uncertainty component by means other than the statistical analysis of a current series of observations. It draws on information such as calibration certificates, manufacturer specifications, handbook data, or experience, usually with an assumed probability distribution.','A Type B check finds doubt without new repeated readings. Instead it uses known information. That can be a spec sheet or a calibration paper. You turn that information into a standard uncertainty.','It captures uncertainty sources that cannot be, or need not be, evaluated statistically, so the budget stays complete.','A datasheet gives a meter tolerance of plus or minus 0.3 dB with no distribution stated; assuming a rectangular distribution, the Type B standard uncertainty is 0.3/sqrt(3), about 0.17 dB.','Measurement Uncertainty',ARRAY['Type A evaluation','Standard uncertainty','Coverage factor','Uncertainty budget','Combined standard uncertainty']::text[],ARRAY['Assuming Type B is less valid than Type A; both are legitimate and combine the same way.','Forgetting to divide a tolerance by the square root of three for a rectangular distribution before combining.','Double-counting a source already covered by a Type A estimate.']::text[],ARRAY['Turning a datasheet tolerance into a standard uncertainty.','Including calibration-certificate uncertainty in a budget.','Estimating uncertainty when repeated measurements are impractical.']::text[],'Intermediate','u = a / sqrt(3)   (rectangular distribution of half-width a)','For a rectangular distribution with half-width a, the standard uncertainty equals the half-width divided by the square root of three.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Type B evaluation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9c396946-c11a-4956-862f-92b335c48f0d','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9c396946-c11a-4956-862f-92b335c48f0d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9c396946-c11a-4956-862f-92b335c48f0d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f3fc859a-9019-415b-8f9d-743c7533b987','Uncertainty budget','An uncertainty budget is a structured statement listing every source of measurement uncertainty, the standard uncertainty of each, how each is evaluated and how they are combined, and the resulting combined and expanded uncertainty. It records the measurement model, sensitivity coefficients, assumed distributions, degrees of freedom, and coverage factor.','An uncertainty budget is an organized list of every source of doubt. It shows the size of each source. It shows how they add together. The end result is one clear uncertainty for the measurement.','It makes an uncertainty estimate transparent and repeatable, so others can check, reproduce, or improve it.','For an SPL calibration, a technician tabulates calibrator uncertainty, meter resolution, and repeatability, combines them in quadrature, and multiplies by k=2 for a roughly 95% expanded uncertainty.','Measurement Uncertainty',ARRAY['Combined standard uncertainty','Standard uncertainty','Coverage factor','Type A evaluation','Type B evaluation','Measurement model']::text[],ARRAY['Adding uncertainties linearly instead of combining independent ones in quadrature.','Leaving out a real source, such as resolution or operator effects, so the budget understates doubt.','Reporting an expanded uncertainty without stating the coverage factor or confidence level.']::text[],ARRAY['Preparing the stated uncertainty on a calibration certificate.','Meeting ISO/IEC 17025 requirements for a test report.','Finding which source dominates a measurement''s uncertainty.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Uncertainty budget');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f3fc859a-9019-415b-8f9d-743c7533b987','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f3fc859a-9019-415b-8f9d-743c7533b987') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f3fc859a-9019-415b-8f9d-743c7533b987');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a38c2466-9680-43da-ab12-6c0657628d8b','Unwrapped phase','Unwrapped phase is a phase-versus-frequency curve in which the artificial plus or minus 360 degree (2 pi) jumps produced by the arctangent computation have been removed by adding or subtracting whole cycles, giving a continuous phase function. It reveals the true accumulated phase and underlies the calculation of group delay.','Measured phase normally jumps by a full turn at certain points. These jumps are not real; they come from the math. Unwrapping removes them to give a smooth curve. This smooth phase shows the true delay through a system.','It restores a continuous phase record so slope-based quantities like group delay and time alignment can be read correctly.','After an FFT measurement, a technician unwraps the phase, then takes its slope near a crossover to read a group delay of about 2.5 ms.','Signal Analysis',ARRAY['Group delay','Excess-phase response','Complex frequency response','Excess group delay','Minimum phase']::text[],ARRAY['Reading raw wrapped-phase slope as delay, which the 360 degree jumps corrupt.','Unwrapping across a low-coherence region, where noise creates false jumps that accumulate.','Confusing unwrapped phase with minimum-phase or excess-phase, which are separate ideas.']::text[],ARRAY['Extracting group delay from a measured frequency response.','Time-aligning drivers in a multi-way loudspeaker.','Interpreting phase in dual-channel FFT measurements.']::text[],'Intermediate','tau_g(w) = - d phi(w) / d w','Group delay equals the negative slope of the unwrapped phase with respect to angular frequency.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Unwrapped phase');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a38c2466-9680-43da-ab12-6c0657628d8b','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a38c2466-9680-43da-ab12-6c0657628d8b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a38c2466-9680-43da-ab12-6c0657628d8b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bec35321-8676-4c76-aac8-267ec12caa0a','Voltage-limited output','Voltage-limited output is the condition in which a device''s maximum output is set by the largest voltage swing it can deliver, typically the amplifier supply-rail voltage minus internal losses, so it clips when the signal demands more. For a loudspeaker system it fixes the highest achievable level in the range where the amplifier clips before the driver reaches thermal or excursion limits.','Every amplifier has a top voltage it can reach. This is set by its power supply. When the signal needs more, the tops of the wave get cut off. That clipping sets the loudest clean output.','It identifies the amplifier voltage ceiling as the factor capping clean output, separating it from current, thermal, or excursion limits.','An amplifier that swings 40 Vrms into 8 ohms is voltage-limited at 40^2/8 = 200 W; beyond that it clips, so more level needs more supply voltage, not a bigger heatsink.','Output Limits',ARRAY['Current-limited output','Compression-limited output','Excursion-limited output','Distortion-limited output','Maximum linear SPL']::text[],ARRAY['Adding a bigger heatsink to gain level when the limit is voltage, not heat.','UNSAFE: Driving a voltage-limited amplifier into hard clipping for extra loudness, which sends excess high-frequency energy that can burn out tweeters.','Confusing voltage limiting with current limiting into low-impedance loads.']::text[],ARRAY['Sizing an amplifier to reach a target SPL for a given loudspeaker.','Diagnosing why a system cannot get louder without distortion.','Choosing between more supply voltage or a more sensitive loudspeaker.']::text[],'Intermediate','Pmax = Vrms^2 / R = (Vpk/sqrt(2))^2 / R','Maximum output power equals the maximum RMS output voltage squared divided by the load resistance.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voltage-limited output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bec35321-8676-4c76-aac8-267ec12caa0a','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bec35321-8676-4c76-aac8-267ec12caa0a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bec35321-8676-4c76-aac8-267ec12caa0a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7db49b63-0192-47ff-bf8b-fc91997ebd78','Volterra series','A Volterra series represents a nonlinear system with memory as a sum of multidimensional convolution integrals, each using a Volterra kernel of increasing order; the first-order term is ordinary linear convolution and higher-order terms capture nonlinear interactions. It generalizes the impulse response to weakly nonlinear systems.','A Volterra series is a math model for gentle nonlinear systems. It builds on the idea of the impulse response. The first part is the normal linear behavior. Higher parts add the nonlinear extras and the memory.','It provides a formal way to model and predict distortion in weakly nonlinear devices while keeping the system''s memory effects.','An engineer identifies the first- and second-order Volterra kernels of a small amplifier to predict its second-harmonic distortion versus frequency before designing a compensator.','Nonlinear Modeling',ARRAY['Wiener model','Wiener–Hammerstein model','Hammerstein model','Higher-order impulse response','Nonlinear impulse response']::text[],ARRAY['Applying it to strongly nonlinear or clipping systems, where the series converges poorly.','Ignoring how kernel size and identification cost explode at higher orders.','Treating the first-order kernel as the whole response and missing the nonlinear terms.']::text[],ARRAY['Modeling weakly nonlinear amplifier or transducer distortion.','Designing nonlinear distortion compensation.','Analyzing higher-order impulse responses from sine-sweep tests.']::text[],'Advanced','y(t) = sum_{n=1..inf} integral...integral h_n(t1,...,tn) * product_{i=1..n} x(t - ti) dt1...dtn','The output is the sum over all orders of the n-fold convolution of the nth Volterra kernel with n delayed copies of the input.','525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volterra series');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7db49b63-0192-47ff-bf8b-fc91997ebd78','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7db49b63-0192-47ff-bf8b-fc91997ebd78') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7db49b63-0192-47ff-bf8b-fc91997ebd78');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '206cad51-7fdb-4805-8648-cc3012c28aa7','Wiener model','A Wiener model is a block-oriented nonlinear model consisting of a linear time-invariant dynamic block followed by a static, memoryless nonlinearity. The dynamics act on the input first, then the nonlinear function shapes the result.','A Wiener model splits a nonlinear system into two blocks. First comes a linear filter with memory. After it comes a simple nonlinear curve with no memory. The order, filter then curve, defines the model.','It gives a simple, identifiable structure for systems whose dynamics precede a nonlinear stage, which eases modeling and correction.','A technician models a driver as a Wiener system: a linear filter for its frequency response feeding a soft-clipping curve, then fits both blocks from swept-sine data.','Nonlinear Modeling',ARRAY['Hammerstein model','Wiener–Hammerstein model','Volterra series','Nonlinear impulse response','Higher-order impulse response']::text[],ARRAY['Swapping the block order with a Hammerstein model, which puts the nonlinearity first.','Assuming any nonlinear system fits a single Wiener structure.','Forgetting the gain ambiguity between the linear block and the nonlinearity during identification.']::text[],ARRAY['Modeling a loudspeaker or amplifier as filter-then-nonlinearity.','Building a compact nonlinear model for real-time correction.','Comparing block-oriented models during system identification.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wiener model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '206cad51-7fdb-4805-8648-cc3012c28aa7','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='206cad51-7fdb-4805-8648-cc3012c28aa7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='206cad51-7fdb-4805-8648-cc3012c28aa7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f0e349f-56e5-4b89-8ca3-e0b888506e49','Wiener–Hammerstein model','A Wiener–Hammerstein model is a block-oriented nonlinear model with a linear-nonlinear-linear structure: a linear time-invariant block, then a static nonlinearity, then a second linear time-invariant block. It combines a Wiener front end with a Hammerstein back end.','This model uses three blocks in a row. A linear filter comes first. A simple nonlinear curve sits in the middle. A second linear filter comes last. It captures dynamics on both sides of the nonlinearity.','It models systems whose nonlinear stage is surrounded by dynamics on both the input and output sides, which single-block models miss.','An engineer fits a Wiener-Hammerstein model to a distortion pedal: an input filter, a clipping curve, then an output tone filter, identified from sweep measurements.','Nonlinear Modeling',ARRAY['Wiener model','Hammerstein model','Volterra series','Nonlinear impulse response','Higher-order impulse response']::text[],ARRAY['Trying to identify it without resolving how the linear dynamics split between the two filters.','Reducing it to a plain Wiener or Hammerstein model when both filters matter.','Ignoring gain and delay ambiguities among the three blocks.']::text[],ARRAY['Modeling guitar distortion or overdrive circuits.','Benchmark nonlinear system-identification tasks.','Modeling a transducer with input and output filtering around its nonlinearity.']::text[],'Advanced',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wiener–Hammerstein model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f0e349f-56e5-4b89-8ca3-e0b888506e49','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f0e349f-56e5-4b89-8ca3-e0b888506e49') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f0e349f-56e5-4b89-8ca3-e0b888506e49');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39f4f1ef-dd4a-436a-b94f-a904e94cabce','Window leakage','Window leakage, also called spectral leakage, is the spreading of a signal''s energy from its true frequency into neighboring DFT bins, caused by analyzing a finite record whose length is not an exact whole number of the signal''s cycles. Applying a tapered window instead of a rectangular one reduces the leakage at the cost of a wider main lobe.','An FFT looks at a short slice of a signal. If the slice does not hold whole cycles, its energy smears. This smearing spreads into nearby frequency bins. A window tapers the slice edges to reduce it.','Understanding leakage tells the technician why nearby tones and noise appear where they should not, and why window choice trades resolution against leakage.','Measuring a 1 kHz tone that is not bin-centered, a technician applies a Hann window so the skirts drop faster, keeping a small nearby harmonic from being buried by leakage.','Signal Analysis',ARRAY['Window function','Spectral resolution','Time resolution','Gated measurement','Higher-order harmonic distortion']::text[],ARRAY['Using a rectangular window for non-periodic captures, which maximizes leakage.','Assuming a window removes leakage; it only reshapes and reduces it while widening the main lobe.','Blaming a device for spurious bins that are really analysis leakage.']::text[],ARRAY['Reading an FFT spectrum for harmonics or spurious tones.','Choosing a window for a spectrum or distortion measurement.','Explaining smeared spectral peaks to a trainee.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Window leakage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39f4f1ef-dd4a-436a-b94f-a904e94cabce','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39f4f1ef-dd4a-436a-b94f-a904e94cabce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39f4f1ef-dd4a-436a-b94f-a904e94cabce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a49d9c55-ecfc-4803-bdcf-316abb9adfcf','Working standard','A working standard is a measurement standard used routinely to calibrate or verify measuring instruments and systems in day-to-day work. It sits below the reference standard in the calibration hierarchy and is itself calibrated against that higher-level standard.','A working standard is the everyday reference tool. Technicians use it often to check other instruments. It is not the top standard in the lab. A higher reference standard keeps it calibrated.','It protects the more precious reference standard from wear by taking on the routine calibration duty.','A technician uses a class-1 sound calibrator as a working standard to check field SPL meters daily, while a rarely used lab reference standard calibrates the calibrator.','Metrology',ARRAY['Reference standard','Transfer standard','Primary standard','Secondary standard','Traceability','Calibration hierarchy']::text[],ARRAY['Treating the working standard as the top of the chain instead of a routinely used tool.','Skipping the working standard''s own recalibration against a reference standard.','Using a working standard beyond its accuracy class for high-stakes calibrations.']::text[],ARRAY['Daily field checks of sound-level meters.','Routine verification on a calibration bench.','Setting up a lab''s calibration hierarchy.']::text[],'Intermediate',NULL,NULL,'525bdc16-2acc-4b5b-aaa6-781ddb284216' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Working standard');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a49d9c55-ecfc-4803-bdcf-316abb9adfcf','525bdc16-2acc-4b5b-aaa6-781ddb284216',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a49d9c55-ecfc-4803-bdcf-316abb9adfcf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a49d9c55-ecfc-4803-bdcf-316abb9adfcf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2475f77e-9bbb-4541-9026-3ba949be3086','AES17','AES17 is the Audio Engineering Society standard method for measuring the analog and digital performance of digital audio equipment, such as converters, recorders, and interfaces. It specifies test signals, a standard measurement bandwidth, and a defined low-pass filter so that figures like dynamic range, THD+N, and frequency response are obtained consistently between labs.','AES17 is a rulebook from the Audio Engineering Society. It tells engineers how to measure digital audio gear. It sets the test tones, the filter, and the frequency band to use. This lets different labs compare their results fairly.','It exists to make measurements of digital audio devices repeatable and comparable, by fixing the signals, bandwidth, and filtering used during a test.','A technician testing a converter follows AES17 by applying the specified band-limited test signal and 20 kHz low-pass filter before reading dynamic range or THD+N.','Measurement Standard',ARRAY['THD+N','Dynamic range','DFT','Accuracy','AES75']::text[],ARRAY['Assuming any THD+N number is comparable without checking it was measured to AES17 conditions.','Omitting the standard measurement bandwidth or low-pass filter, which changes noise readings.','Confusing AES17, a measurement method, with a digital audio interface format like AES3.']::text[],ARRAY['Publishing a DAC''s dynamic-range spec that buyers can trust.','Comparing THD+N between two audio interfaces on equal terms.','Setting up an Audio Precision analyzer to a recognized method.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AES17');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2475f77e-9bbb-4541-9026-3ba949be3086','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2475f77e-9bbb-4541-9026-3ba949be3086') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2475f77e-9bbb-4541-9026-3ba949be3086');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45a5616e-2f2f-4946-8b93-51da4e5a26c5','AES75','AES75 is the Audio Engineering Society standard for measuring the maximum linear sound levels that a loudspeaker system or driver can produce, using a music-like noise signal called M-Noise. The level is raised in steps until the transfer function''s magnitude or coherence changes by more than a defined amount, marking the maximum linear output.','AES75 is an Audio Engineering Society standard for loudspeaker output. It measures how loud a speaker can play while staying clean. It uses a special noise signal called M-Noise. The level rises step by step until the speaker''s response changes too much.','It provides one repeatable, verifiable way to state a loudspeaker''s maximum output, replacing vague or inconsistent peak-SPL claims from makers.','A technician plays M-Noise through the speaker, raises the level in steps, and records the last level before the measured magnitude or coherence shifts past the standard''s limit.','Measurement Standard',ARRAY['M-Noise','Coherence','Crest factor','AES17','Transfer function']::text[],ARRAY['Treating an AES75 maximum linear level as a peak or a marketing ''max SPL'' figure.','Using ordinary pink noise instead of the defined M-Noise signal.','Ignoring the coherence stop condition and pushing the speaker into distortion.']::text[],ARRAY['Comparing the honest maximum output of two touring loudspeakers.','Verifying a manufacturer''s published maximum-level claim.','Specifying speakers for a venue by reproducible output data.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AES75');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45a5616e-2f2f-4946-8b93-51da4e5a26c5','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45a5616e-2f2f-4946-8b93-51da4e5a26c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45a5616e-2f2f-4946-8b93-51da4e5a26c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7847abe0-5328-49ab-96a2-072304d618fe','ANSI S1 series','The ANSI S1 series is the group of American National Standards on acoustics maintained through the Acoustical Society of America, covering measurement instruments and terminology. It includes standards for sound level meters, octave-band and fractional-octave filters, calibrators, and preferred frequencies used in acoustic measurement.','The ANSI S1 series is a group of American sound standards. The Acoustical Society of America keeps them up to date. They spell out rules for sound level meters, filters, calibrators, and set frequencies. Engineers use them so sound readings match across the United States.','It exists to standardize how acoustic instruments are built, calibrated, and specified in the United States, supporting consistent noise and sound measurement.','A technician checks that a sound level meter meets ANSI S1.4 and its octave filters meet ANSI S1.11 before trusting field noise readings.','Measurement Standard',ARRAY['Sound level meter','Octave-band filter','IEC 61672','Background sound level','Accuracy']::text[],ARRAY['Assuming an ANSI S1 standard is identical to its IEC counterpart, though they are closely harmonized.','Citing ''ANSI S1'' without the specific part number for the instrument in use.','Confusing the S1 acoustics series with unrelated ANSI electrical standards.']::text[],ARRAY['Selecting a Type 1 sound level meter for a U.S. noise survey.','Verifying octave-band filter tolerances before a room measurement.','Choosing preferred one-third-octave center frequencies for reporting.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ANSI S1 series');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7847abe0-5328-49ab-96a2-072304d618fe','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7847abe0-5328-49ab-96a2-072304d618fe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7847abe0-5328-49ab-96a2-072304d618fe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '745ba066-d0c0-4ec6-9d18-dddfa068665e','Accelerometer','An accelerometer is a transducer that produces an electrical output proportional to the acceleration of the surface it is mounted on. In audio and vibration work it is most often a piezoelectric type, whose sensitivity is stated in units such as millivolts per metre per second squared or per g.','An accelerometer is a sensor that measures vibration. You fix it to a surface, and it outputs a voltage. The voltage follows how fast the surface speeds up or slows down. Engineers use it to study how things shake.','It converts mechanical vibration into a measurable electrical signal, letting technicians analyze how structures, panels, and loudspeaker parts move.','A technician bonds an accelerometer to a cabinet panel; with a sensitivity of 10 mV per m/s^2, a 100 mV output means the panel sees 10 m/s^2 of acceleration.','Transducer',ARRAY['Piezoelectric sensor','Vibration analysis','Cumulative spectral decay','Sensitivity','FFT']::text[],ARRAY['Adding a heavy accelerometer to a light panel, which mass-loads and changes the vibration.','Ignoring the mounting method, since poor coupling limits usable high-frequency range.','Confusing acceleration output with velocity or displacement without integration.']::text[],ARRAY['Finding a buzzing panel resonance on a loudspeaker enclosure.','Measuring floor vibration under a studio isolation platform.','Modal testing of a structure with an instrumented hammer.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Accelerometer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '745ba066-d0c0-4ec6-9d18-dddfa068665e','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='745ba066-d0c0-4ec6-9d18-dddfa068665e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='745ba066-d0c0-4ec6-9d18-dddfa068665e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3af9fb81-5b7c-4714-890a-fa0424f837c8','Accuracy','Accuracy is the closeness of agreement between a measured value and the true or accepted reference value of the quantity being measured. In metrology it is a qualitative concept; the numerical spread is expressed through measurement uncertainty, not as a single ''accuracy'' figure.','Accuracy is how close a reading is to the real value. A very accurate meter reads near the truth. It is a general idea, not one exact number. The spread of possible error is called uncertainty.','It describes how trustworthy a measurement result is, guiding whether an instrument is fit for a given test.','A technician calibrates a meter against a reference; if it reads 1.002 V for a true 1.000 V, the small error shows good accuracy for that point.','Metrology Concept',ARRAY['Precision','Measurement uncertainty','Calibration','Adjustment','Accelerometer']::text[],ARRAY['Confusing accuracy (closeness to truth) with precision (repeatability of readings).','Quoting accuracy as a single number, when it is a qualitative concept.','Assuming a high-resolution display automatically means a highly accurate reading.']::text[],ARRAY['Deciding if a handheld meter is good enough for a calibration check.','Explaining why a repeatable meter can still read the wrong value.','Reviewing an instrument datasheet''s stated tolerance.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Accuracy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3af9fb81-5b7c-4714-890a-fa0424f837c8','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3af9fb81-5b7c-4714-890a-fa0424f837c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3af9fb81-5b7c-4714-890a-fa0424f837c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99c94b0a-0589-4c40-b332-f28e9d7a0a2e','Acoustic delay','Acoustic delay is the time taken for sound to travel a given distance through air, equal to that distance divided by the speed of sound. It underlies the propagation delay between a source and a microphone or listener and is central to aligning loudspeakers in time.','Acoustic delay is the time sound needs to travel through air. Sound is slow compared to electricity. Farther distance means more delay. Engineers use it to line up speakers so their sound arrives together.','It quantifies how long sound takes to reach a point, which is essential for time-aligning loudspeakers and interpreting measurement arrival times.','For a listener 3.43 m from a speaker with sound speed 343 m/s, the acoustic delay is 3.43 / 343 = 0.01 s, or 10 ms.','Acoustic Measurement',ARRAY['Speed of sound','Time alignment','Propagation delay','Impulse response','Acoustic emission']::text[],ARRAY['Using a fixed speed of sound while ignoring that it rises with air temperature.','Confusing acoustic delay in air with electronic or processing delay in a signal chain.','Forgetting that microphone distance adds delay in measurement setups.']::text[],ARRAY['Setting delay on a rear fill so its sound aligns with the main array.','Interpreting the arrival time of a peak in a room impulse response.','Estimating distance from a measured delay in seconds.']::text[],'Beginner','t = d / c','Acoustic delay equals the propagation distance divided by the speed of sound in the medium.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic delay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99c94b0a-0589-4c40-b332-f28e9d7a0a2e','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99c94b0a-0589-4c40-b332-f28e9d7a0a2e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99c94b0a-0589-4c40-b332-f28e9d7a0a2e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b3165bc9-c433-4de1-bb1d-39136b90792c','Acoustic emission','Acoustic emission is the class of transient elastic (stress) waves generated by the rapid release of energy from a localized source within a material, such as crack growth or friction. In testing it is detected by surface-mounted piezoelectric sensors and analyzed to locate and characterize active defects.','Acoustic emission is the tiny burst of sound a material makes when it is stressed. A crack forming releases a quick wave of energy. Sensors on the surface pick up these waves. Engineers use them to find hidden damage.','It lets technicians detect and locate active flaws in structures or components without stopping their operation, by listening for stress-wave bursts.','A technician mounts several piezoelectric sensors on a vessel; comparing arrival times of an emission burst lets software triangulate the crack''s location.','Signal Analysis',ARRAY['Piezoelectric sensor','Accelerometer','Transient','Acoustic delay','Nondestructive testing']::text[],ARRAY['Confusing acoustic emission (internally generated stress waves) with applied ultrasonic testing.','Ignoring background mechanical noise, which masks true emission events.','Assuming a louder emission always means a more severe defect.']::text[],ARRAY['Monitoring a pressure vessel for crack growth during a proof test.','Detecting delamination in a composite panel under load.','Locating a leak by its continuous emission signature.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b3165bc9-c433-4de1-bb1d-39136b90792c','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b3165bc9-c433-4de1-bb1d-39136b90792c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b3165bc9-c433-4de1-bb1d-39136b90792c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '053d7f54-a756-42db-ba92-a3d2c626662b','Adjustment','Adjustment is the act of tuning a measuring system so that its readings line up with known values of the measured quantity. This differs from calibration, which merely establishes how readings relate to reference values without changing the instrument.','Adjustment means setting an instrument so it reads correctly. You change it until it shows the right values. This is different from calibration. Calibration only measures the error; adjustment fixes it.','It brings an instrument''s readings into line with reference values, so that later measurements start from a correct baseline.','After calibration shows a meter reads 0.98 V for a true 1.00 V, a technician adjusts its gain trim until it reads 1.00 V.','Metrology Concept',ARRAY['Calibration','Accuracy','Measurement uncertainty','Reference value','Sensitivity']::text[],ARRAY['Using ''calibration'' and ''adjustment'' as synonyms, though they are separate steps.','Adjusting an instrument without first calibrating to know the true error.','Assuming an adjusted instrument no longer needs periodic calibration.']::text[],ARRAY['Trimming an analyzer''s reference level after a calibration check.','Zeroing a meter before a series of measurements.','Restoring correct readings on drifted lab equipment.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Adjustment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '053d7f54-a756-42db-ba92-a3d2c626662b','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='053d7f54-a756-42db-ba92-a3d2c626662b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='053d7f54-a756-42db-ba92-a3d2c626662b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee052110-794d-4e1e-9f69-6ad301d90c1a','Artificial ear','An artificial ear is an acoustic coupler that presents an earphone with an acoustic load and cavity resembling the average human ear, with a calibrated measurement microphone at its base. Standardized ear simulators let earphones and hearing aids be measured under repeatable, human-representative conditions.','An artificial ear is a device that mimics a real ear for testing. An earphone plays into it. A built-in microphone measures the sound. Because its shape is standardized, results can be compared between labs.','It provides a standardized, human-like acoustic load so that earphone and hearing-aid measurements are repeatable and comparable.','A technician seats an earphone on an IEC 60318-1 ear simulator and reads its frequency response from the coupler microphone.','Test Fixture',ARRAY['Ear simulator','Occluded-ear coupler','Artificial mouth','Measurement microphone','Coupler']::text[],ARRAY['Assuming all couplers are interchangeable, when different IEC 60318 parts model different fits.','Neglecting a proper seal, which corrupts low-frequency measurements.','Confusing an artificial ear with a full head-and-torso simulator.']::text[],ARRAY['Measuring headphone frequency response for a datasheet.','Verifying hearing-aid output on a standardized coupler.','Comparing earbud response between two production units.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Artificial ear');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee052110-794d-4e1e-9f69-6ad301d90c1a','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee052110-794d-4e1e-9f69-6ad301d90c1a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee052110-794d-4e1e-9f69-6ad301d90c1a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3963eb32-c03b-41b6-8d18-4fd6a7fe6ec6','Artificial mouth','An artificial mouth is a calibrated loudspeaker in an enclosure whose radiating aperture and directivity approximate those of the human mouth. Standardized to ITU-T Recommendation P.51, it provides a repeatable talker for testing telephones, microphones, and speech systems.','An artificial mouth is a small speaker built to act like a talking mouth. It has a mouth-shaped opening and known sound pattern. Engineers use it as a standard talker. This lets them test phones and microphones fairly.','It supplies a repeatable, human-like speech source so that microphones, telephones, and speech systems can be measured consistently.','A technician drives an ITU-T P.51 artificial mouth with a calibrated signal to test a headset microphone''s response at a defined mouth reference point.','Test Fixture',ARRAY['Artificial ear','Mouth reference point','Head and torso simulator','Speech intelligibility','Measurement microphone']::text[],ARRAY['Ignoring the defined mouth reference point where the field is calibrated.','Assuming any small loudspeaker matches the standardized mouth directivity.','Confusing the artificial mouth (a source) with the artificial ear (a receiver).']::text[],ARRAY['Testing a smartphone''s uplink microphone response.','Measuring a conference microphone with a repeatable talker.','Evaluating a headset boom microphone at a fixed mouth distance.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Artificial mouth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3963eb32-c03b-41b6-8d18-4fd6a7fe6ec6','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3963eb32-c03b-41b6-8d18-4fd6a7fe6ec6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3963eb32-c03b-41b6-8d18-4fd6a7fe6ec6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e1636797-2b90-4e9d-bf95-acebf37294e3','Auditory filterbank','An auditory filterbank is a set of overlapping bandpass filters that models the frequency analysis performed by the cochlea, with bandwidths that widen toward high frequencies. Gammatone filters spaced on an ERB or Bark scale are a common implementation used in hearing models and perceptual audio analysis.','An auditory filterbank is a model of how the ear splits sound into frequency bands. The inner ear acts like many overlapping filters. This model copies that behavior. Its bands get wider at higher frequencies, just like real hearing.','It reproduces the ear''s frequency-resolving behavior so that analysis and perceptual models weight sound the way human hearing does.','A technician runs a signal through a gammatone filterbank spaced on the ERB scale to estimate loudness or masking as a listener would perceive it.','Perceptual Model',ARRAY['Critical band','Bark scale','ERB','Gammatone filter','Constant-Q transform']::text[],ARRAY['Using equal-width bands, which ignores the ear''s frequency-dependent resolution.','Confusing an auditory filterbank with a plain fixed-bandwidth graphic-EQ filter set.','Assuming filter phase does not matter for perceptual modeling in all cases.']::text[],ARRAY['Building a loudness or masking model for perceptual audio coding.','Front-end processing for a speech-recognition feature extractor.','Predicting how a listener will hear two closely spaced tones.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory filterbank');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e1636797-2b90-4e9d-bf95-acebf37294e3','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e1636797-2b90-4e9d-bf95-acebf37294e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e1636797-2b90-4e9d-bf95-acebf37294e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8fe65218-fa00-4c10-8124-cf91fd2420df','BL','BL, the force factor of an electrodynamic transducer, is the product of the magnetic flux density in the gap and the effective length of voice-coil wire in that field. It relates coil current to the mechanical force produced, and coil velocity to the back-EMF generated, with units of tesla-metres (newtons per ampere).','BL is the motor strength of a speaker. It multiplies the magnet''s field by the wire length in that field. A bigger BL turns current into more push. It is a key number for how a speaker moves.','It quantifies the electromechanical coupling of a driver''s motor, setting how efficiently current becomes cone force.','For a driver with BL of 8 T*m carrying 2 A of coil current, the motor force is 8 x 2 = 16 N.','Transducer Parameter',ARRAY['Force factor','Voice coil','Thiele-Small parameters','Cms','Complex impedance']::text[],ARRAY['Treating BL as constant, though it falls as the coil leaves the gap at large excursion.','Confusing the force-factor role (F = BL*I) with the back-EMF role (voltage = BL*velocity).','Mixing up units, since tesla-metres equal newtons per ampere.']::text[],ARRAY['Reading a driver datasheet to compare motor strength.','Diagnosing distortion from BL loss at high excursion.','Using Thiele-Small data to model a subwoofer.']::text[],'Advanced','F = (B*l) * I','The motor force equals the force factor, which is flux density times coil length in the gap, multiplied by the coil current.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BL');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8fe65218-fa00-4c10-8124-cf91fd2420df','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8fe65218-fa00-4c10-8124-cf91fd2420df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8fe65218-fa00-4c10-8124-cf91fd2420df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1ad32de-81cb-45c5-9c72-50996972b5ee','Background sound level','The background sound level is the sound pressure level present at a location from all sources other than the one under study, measured while that source is off. It sets the noise floor that limits how accurately a source''s own level can be measured.','The background sound level is the noise already in a room. It is everything except the source you want to measure. You measure it with your source turned off. It limits how quietly your source can be measured.','It establishes the ambient noise floor so measured source levels can be judged reliable and, if needed, corrected.','A technician measures 40 dB with the machine off and 52 dB with it on; the 12 dB gap is large enough that background correction is small.','Acoustic Measurement',ARRAY['Background-noise correction','Signal-to-noise ratio','Sound level meter','IEC 61672','Noise floor']::text[],ARRAY['Reporting a source level without checking the background is well below it.','Confusing background sound level with the equipment''s own electrical noise floor.','Measuring background at a different time when ambient noise has changed.']::text[],ARRAY['Checking ambient noise before a sound-power measurement.','Deciding whether a quiet appliance can be measured in a given room.','Documenting site noise for an environmental noise survey.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Background sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1ad32de-81cb-45c5-9c72-50996972b5ee','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1ad32de-81cb-45c5-9c72-50996972b5ee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1ad32de-81cb-45c5-9c72-50996972b5ee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4975a14b-e276-457b-9e04-0f2e26c9cf79','Background-noise correction','Background-noise correction is the adjustment subtracted from a measured level to remove the contribution of ambient noise, based on the difference between the source-plus-background level and the background-alone level. Standards apply the correction as a decibel term derived from that level difference.','Background-noise correction removes room noise from a reading. You compare the level with the source on and off. The gap tells you how much to subtract. This gives a truer level for the source alone.','It recovers the true level of a source when ambient noise adds to the measured value, keeping results accurate.','With a 6 dB gap between source-plus-noise and noise alone, the correction K1 = -10 log(1 - 10^(-0.6)) is about 1.3 dB subtracted from the reading.','Acoustic Measurement',ARRAY['Background sound level','Signal-to-noise ratio','Sound power','ISO 3744','Correction factor']::text[],ARRAY['Applying a correction when the level difference is too small for a valid result.','Adding the correction instead of subtracting it from the measured level.','Assuming correction fixes readings when the source is buried in the noise.']::text[],ARRAY['Correcting a sound-power test for a modest room noise floor.','Reporting a machine''s level after removing ambient contribution.','Deciding a measurement is invalid because the source-to-noise gap is under a few decibels.']::text[],'Intermediate','K1 = -10 * log10(1 - 10^(-0.1*dLp))','The correction equals minus ten times the base-ten log of one minus ten raised to minus one tenth of the level difference.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Background-noise correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4975a14b-e276-457b-9e04-0f2e26c9cf79','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4975a14b-e276-457b-9e04-0f2e26c9cf79') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4975a14b-e276-457b-9e04-0f2e26c9cf79');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2298c6fa-caa2-448e-ad0f-eb1c4343495e','Bispectrum','The bispectrum is a third-order spectral measure formed from the Fourier transforms of a signal at two frequencies and their sum, revealing statistical dependence and phase coupling between frequency components. It is the double Fourier transform of the third-order cumulant and is used in higher-order spectral analysis.','The bispectrum studies how three frequencies in a signal relate. It checks whether two frequencies and their sum are linked in phase. Ordinary spectra cannot show this. It helps reveal nonlinear behavior in a system.','It detects quadratic phase coupling and nonlinearity that the ordinary power spectrum cannot show, aiding diagnosis of nonlinear systems.','A technician computes the bispectrum of a machine vibration signal; a strong peak at a frequency pair signals nonlinear coupling between those components.','Signal Analysis',ARRAY['Power spectrum','Bicoherence','Higher-order statistics','Cyclostationary analysis','DFT']::text[],ARRAY['Expecting the bispectrum to show simple linear signals, where it is essentially zero.','Skipping averaging, which is needed to estimate the expectation reliably.','Confusing the bispectrum with the ordinary two-dimensional power spectrum.']::text[],ARRAY['Detecting nonlinear phase coupling in machinery vibration.','Analyzing quadratic interactions in a biomedical or acoustic signal.','Distinguishing a genuinely nonlinear source from a linear one.']::text[],'Advanced','B(f1,f2) = E[ X(f1) * X(f2) * conj(X(f1+f2)) ]','The bispectrum is the expected value of the spectrum at one frequency times the spectrum at a second frequency times the complex conjugate of the spectrum at their sum.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bispectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2298c6fa-caa2-448e-ad0f-eb1c4343495e','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2298c6fa-caa2-448e-ad0f-eb1c4343495e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2298c6fa-caa2-448e-ad0f-eb1c4343495e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f88c0329-9259-46e9-a766-ffe065f4956f','Blackman window','The Blackman window is a tapering function applied to a signal block before Fourier analysis, formed from a constant plus two cosine terms. Its classic coefficients give very low spectral side lobes at the cost of a wider main lobe, reducing leakage in spectrum measurements.','The Blackman window is a shape used before an FFT. It smoothly tapers a block of samples to zero at the ends. This lowers spectral leakage, so nearby tones are cleaner. The trade-off is slightly poorer frequency resolution.','It reduces spectral leakage in Fourier analysis by tapering the data block, trading frequency resolution for much lower side lobes.','A technician selects a Blackman window on an FFT analyzer to keep a strong tone from masking a weak nearby tone during a spectrum measurement.','Windowing',ARRAY['Windowing','Spectral leakage','Hann window','Hamming window','DFT']::text[],ARRAY['Assuming a window improves resolution, when it actually widens the main lobe.','Forgetting to compensate amplitude for the window''s coherent gain.','Mixing up the classic Blackman coefficients with the exact-Blackman variant.']::text[],ARRAY['Resolving a low-level harmonic near a large fundamental on an analyzer.','Reducing leakage when the signal is not periodic in the FFT block.','Choosing a window to lower side lobes in a distortion measurement.']::text[],'Intermediate','w[n] = 0.42 - 0.5*cos(2*pi*n/(N-1)) + 0.08*cos(4*pi*n/(N-1))','Each window sample equals 0.42 minus 0.5 times the cosine of one cycle across the block plus 0.08 times the cosine of two cycles across the block.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Blackman window');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f88c0329-9259-46e9-a766-ffe065f4956f','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f88c0329-9259-46e9-a766-ffe065f4956f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f88c0329-9259-46e9-a766-ffe065f4956f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ebe7165e-458d-4245-908a-3f1f7dc5ca5f','Boundary-condition model','A boundary-condition model specifies the physical constraints imposed at the edges of an acoustic or vibrational domain in a simulation, such as a rigid wall (zero normal velocity), a pressure-release surface (zero pressure), or a radiating boundary. These conditions are required to solve the wave or structural equations for transducers, enclosures, and measurement spaces.','A boundary-condition model sets the rules at the edges of a simulated space. It says how sound behaves at a wall or opening. A hard wall reflects; a soft one lets sound escape. These rules let the model solve the physics.','It defines how a modeled acoustic or mechanical domain behaves at its edges, which is required to compute a valid solution for transducer and room simulations.','A technician modeling a loudspeaker sets the cabinet walls as rigid and the mouth as a radiating boundary before running the acoustic simulation.','Modeling Concept',ARRAY['Finite element method','Boundary element method','Radiation impedance','Complex impedance','Half-space measurement']::text[],ARRAY['Leaving a radiating boundary as rigid, which traps energy that should escape.','Confusing a physical measurement boundary with a modeled boundary condition.','Assuming one boundary condition fits every frequency and geometry.']::text[],ARRAY['Setting wall and opening conditions in a loudspeaker cabinet simulation.','Modeling a half-space with a rigid ground plane for radiation.','Defining a radiating boundary in a room acoustics finite-element model.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary-condition model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ebe7165e-458d-4245-908a-3f1f7dc5ca5f','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ebe7165e-458d-4245-908a-3f1f7dc5ca5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ebe7165e-458d-4245-908a-3f1f7dc5ca5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '50239f0c-daf3-4b7a-8309-673ad803c7a3','Cms','Cms is the mechanical compliance of a loudspeaker driver''s suspension, a Thiele-Small parameter equal to the diaphragm displacement produced per unit of applied force. It is the reciprocal of mechanical stiffness and is expressed in metres per newton.','Cms is how easily a speaker''s suspension moves. It is the give of the cone''s springy parts. A high Cms means a soft, loose suspension. It is one of the standard Thiele-Small numbers.','It describes the springiness of a driver''s suspension, which helps set its resonance frequency and low-frequency behavior.','For a suspension that moves 0.5 mm under 1 N of force, Cms = 0.0005 / 1 = 0.5 mm/N, or 5 x 10^-4 m/N.','Transducer Parameter',ARRAY['Compliance','Thiele-Small parameters','BL','Resonance frequency','Stiffness']::text[],ARRAY['Confusing compliance (give) with stiffness, which is its reciprocal.','Treating Cms as constant, though it varies with excursion and age.','Mixing up mechanical compliance Cms with acoustic compliance.']::text[],ARRAY['Reading Thiele-Small data to model a woofer''s resonance.','Explaining why a broken-in suspension lowers resonance frequency.','Comparing driver suspensions on a datasheet.']::text[],'Advanced','Cms = x / F = 1 / k','Mechanical compliance equals diaphragm displacement divided by applied force, which is one over the suspension stiffness.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cms');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '50239f0c-daf3-4b7a-8309-673ad803c7a3','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='50239f0c-daf3-4b7a-8309-673ad803c7a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='50239f0c-daf3-4b7a-8309-673ad803c7a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8395a28-d189-4ca6-86c9-4b39af994ae5','Cohen''s class','Cohen''s class is the general family of bilinear (quadratic) time-frequency distributions expressible as a two-dimensional Fourier-type transform of the signal''s ambiguity function weighted by a kernel. Different kernel choices give members such as the Wigner-Ville, spectrogram, and Choi-Williams distributions, trading resolution against cross-term suppression.','Cohen''s class is a whole family of time-frequency plots. Each one shows how a signal''s frequencies change over time. They all share one general formula with a chosen weighting kernel. The kernel sets the trade-off between sharpness and unwanted artifacts.','It unifies quadratic time-frequency distributions under one framework, letting the kernel be chosen to balance resolution against interference terms.','A technician picks a Choi-Williams kernel from Cohen''s class to view a chirp''s changing frequency while suppressing cross-terms between components.','Time-Frequency Analysis',ARRAY['Wigner-Ville distribution','Spectrogram','Choi-Williams distribution','Continuous wavelet transform','Cross-terms']::text[],ARRAY['Ignoring cross-terms in bilinear distributions like the Wigner-Ville member.','Assuming sharper resolution comes free, without added interference.','Treating the spectrogram as unrelated, though it is a Cohen''s-class member.']::text[],ARRAY['Analyzing a frequency sweep whose content changes with time.','Choosing a kernel to reduce artifacts in a transient analysis.','Comparing time-frequency methods for a non-stationary signal.']::text[],'Advanced','C(t,f) = INT INT phi(theta,tau) * A(theta,tau) * exp(-j*2*pi*(theta*t + tau*f)) d(theta) d(tau)','A Cohen''s-class distribution is the double Fourier-type transform of the kernel times the signal''s ambiguity function over the two delay and Doppler variables.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cohen''s class');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8395a28-d189-4ca6-86c9-4b39af994ae5','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8395a28-d189-4ca6-86c9-4b39af994ae5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8395a28-d189-4ca6-86c9-4b39af994ae5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd4e8c706-2092-4afe-8ca6-1cb7ed4bc144','Complex cepstrum','The complex cepstrum is the inverse Fourier transform of the complex logarithm of a signal''s Fourier transform, retaining both log-magnitude and phase. Because the log turns convolution into addition, it separates a source signal from a filter or echo, and it is invertible back to the original signal.','The complex cepstrum transforms a signal in an unusual way. It takes the log of its spectrum, keeping phase, then transforms back. This turns echoes and filtering into simple sums. Unlike the plain cepstrum, it can be reversed.','It separates convolved parts of a signal, such as a source and an echo or filter, into an additive form that can be edited and inverted.','A technician computes the complex cepstrum of an echoed sound; the echo appears as a peak at the echo delay, which can be removed and the signal rebuilt.','Signal Analysis',ARRAY['Cepstrum','Quefrency','Deconvolution','Homomorphic filtering','DFT']::text[],ARRAY['Confusing the complex cepstrum with the real (power) cepstrum, which drops phase.','Mishandling phase unwrapping, which corrupts the complex logarithm.','Expecting invertibility from the real cepstrum, which is not invertible.']::text[],ARRAY['Removing an echo from a recorded signal by cepstral editing.','Separating vocal-tract filtering from a glottal source in speech.','Estimating and lifting a reflection in an impulse response.']::text[],'Advanced','x_hat[n] = IDFT{ log( DFT{ x[n] } ) }','The complex cepstrum is the inverse discrete Fourier transform of the complex logarithm of the discrete Fourier transform of the signal.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex cepstrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd4e8c706-2092-4afe-8ca6-1cb7ed4bc144','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d4e8c706-2092-4afe-8ca6-1cb7ed4bc144') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d4e8c706-2092-4afe-8ca6-1cb7ed4bc144');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '358777d9-72fd-4a1b-b218-1502e3e4aa9d','Complex envelope','The complex envelope is the baseband, complex-valued representation of a bandpass signal, obtained by forming the analytic signal and shifting it down by the carrier frequency. Its magnitude gives the instantaneous amplitude envelope and its angle gives the instantaneous phase relative to the carrier.','The complex envelope is a simpler view of a modulated signal. It strips away the carrier and keeps the message. Its size is the amplitude envelope. Its angle is the phase. Engineers use it to study modulation.','It reduces a bandpass signal to its baseband amplitude and phase, simplifying analysis of modulation and demodulation.','A technician forms the analytic signal with a Hilbert transform, then multiplies by e^(-j2*pi*fc*t); the magnitude is the amplitude envelope of the modulated tone.','Signal Analysis',ARRAY['Analytic signal','Hilbert transform','Instantaneous amplitude','Instantaneous phase','Complex cepstrum']::text[],ARRAY['Confusing the complex envelope with the real amplitude envelope alone, dropping phase.','Choosing a wrong carrier frequency, which leaves residual rotation in the envelope.','Forgetting the Hilbert transform needed to build the analytic signal.']::text[],ARRAY['Demodulating an amplitude-modulated test tone.','Extracting the envelope of a machine vibration for fault detection.','Simplifying a bandpass signal to baseband for analysis.']::text[],'Advanced','z(t) = [ x(t) + j*Hilbert{x(t)} ] * exp(-j*2*pi*fc*t)','The complex envelope is the analytic signal, formed from the signal and its Hilbert transform, shifted down by the carrier frequency.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex envelope');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '358777d9-72fd-4a1b-b218-1502e3e4aa9d','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='358777d9-72fd-4a1b-b218-1502e3e4aa9d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='358777d9-72fd-4a1b-b218-1502e3e4aa9d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '00f83caa-57c9-4001-97c4-31b00fb222dd','Complex impedance','Complex impedance is the frequency-dependent, complex-valued opposition a circuit or transducer presents to sinusoidal current, written as a resistance plus a reactance. Its real part dissipates power and its imaginary part stores energy, with magnitude and phase describing the voltage-to-current relationship at a given frequency.','Complex impedance is how a circuit resists AC current. It has two parts. One part, resistance, uses up power. The other part, reactance, stores and returns energy. Together they change with frequency.','It describes how voltage and current relate at each frequency, capturing both energy loss and energy storage in circuits and transducers.','For a load with 8 ohms resistance and 6 ohms reactance, the impedance magnitude is sqrt(8^2 + 6^2) = 10 ohms at that frequency.','Electrical Measurement',ARRAY['Reactance','Resistance','Impedance magnitude','Phase angle','Complex envelope']::text[],ARRAY['Treating a loudspeaker''s rated impedance as a single fixed value at all frequencies.','Adding resistance and reactance directly instead of as a vector magnitude.','Ignoring the phase, which shows whether the load is inductive or capacitive.']::text[],ARRAY['Reading a loudspeaker impedance curve versus frequency.','Matching an amplifier to a reactive load.','Interpreting a network-analyzer impedance measurement.']::text[],'Intermediate','Z = R + j*X','Complex impedance equals resistance plus the imaginary unit times reactance.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '00f83caa-57c9-4001-97c4-31b00fb222dd','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='00f83caa-57c9-4001-97c4-31b00fb222dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='00f83caa-57c9-4001-97c4-31b00fb222dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cac7ee2a-37b3-46dc-b850-70f95721cbdf','Compliance','Compliance is the measure of how readily a mechanical system yields to an applied force, equal to displacement per unit force and the reciprocal of stiffness. In transducers it characterizes springy elements such as a loudspeaker suspension, in units of metres per newton.','Compliance is how easily something gives under force. A soft spring has high compliance. A stiff one has low compliance. It is the opposite of stiffness.','It quantifies the springiness of a mechanical element, which sets how it stores energy and where it resonates.','For an element that deflects 2 mm under 4 N, its compliance is 0.002 / 4 = 5 x 10^-4 m/N.','Mechanical Parameter',ARRAY['Cms','Stiffness','Thiele-Small parameters','Resonance frequency','Complex impedance']::text[],ARRAY['Confusing compliance with stiffness, which is its inverse.','Assuming compliance stays constant over large displacements.','Mixing mechanical compliance with electrical or acoustic compliance analogues.']::text[],ARRAY['Describing the give of a loudspeaker''s spider and surround.','Modeling a spring-mass isolator''s resonance.','Comparing suspension softness between two drivers.']::text[],'Intermediate','C = x / F = 1 / k','Compliance equals displacement divided by applied force, which is the reciprocal of stiffness.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compliance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cac7ee2a-37b3-46dc-b850-70f95721cbdf','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cac7ee2a-37b3-46dc-b850-70f95721cbdf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cac7ee2a-37b3-46dc-b850-70f95721cbdf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '586c6f30-c14f-4ca4-8f96-d3cb5e4d9f68','Constant-Q transform','The constant-Q transform is a time-frequency analysis whose frequency bins are geometrically spaced so that the ratio of centre frequency to bandwidth stays constant. This gives finer frequency resolution at low frequencies and finer time resolution at high frequencies, matching musical pitch spacing.','The constant-Q transform analyzes sound with musically spaced bands. Each band keeps the same ratio of centre frequency to width. Low notes get fine frequency detail. High notes get fine timing detail. This suits music well.','It provides a logarithmic, pitch-aligned frequency analysis, unlike the fixed linear spacing of the ordinary Fourier transform.','A technician uses a constant-Q transform to display a musical passage so each semitone falls on an evenly spaced bin.','Time-Frequency Analysis',ARRAY['Constant-Q filter','Auditory filterbank','DFT','Wavelet transform','Octave-band filter']::text[],ARRAY['Expecting linear, evenly spaced frequency bins as in the DFT.','Ignoring the higher computation cost compared with a plain FFT.','Assuming constant time resolution across all frequency bands.']::text[],ARRAY['Displaying a music spectrogram aligned to musical pitches.','Analyzing an instrument''s harmonics on a log-frequency axis.','Feature extraction for music information retrieval.']::text[],'Advanced','Q = f / (delta_f) = constant;  f_k = f_0 * 2^(k/b)','The quality factor, centre frequency divided by bandwidth, is held constant, and centre frequencies rise geometrically by a fixed number of bins per octave.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant-Q transform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '586c6f30-c14f-4ca4-8f96-d3cb5e4d9f68','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='586c6f30-c14f-4ca4-8f96-d3cb5e4d9f68') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='586c6f30-c14f-4ca4-8f96-d3cb5e4d9f68');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab8c66f5-8d14-4a13-a960-4b38124616aa','Continuous wavelet transform','The continuous wavelet transform correlates a signal with scaled and shifted copies of a mother wavelet, producing coefficients over continuous scale and time. Scale acts like an inverse frequency, giving multi-resolution analysis that localizes transient events in both time and frequency.','The continuous wavelet transform compares a signal to a small wave pattern. It stretches and slides that pattern across the signal. Narrow versions catch fast events; wide versions catch slow ones. This locates events in time and frequency.','It analyzes signals at many resolutions at once, localizing short transients better than a fixed-window Fourier analysis.','A technician runs a continuous wavelet transform on a click-plus-tone signal; the click shows at fine scales and the tone at coarse scales, each placed in time.','Time-Frequency Analysis',ARRAY['Discrete wavelet transform','Mother wavelet','Scale','Cohen''s class','Constant-Q transform']::text[],ARRAY['Reading scale directly as frequency without the mapping between them.','Ignoring the admissibility condition a valid wavelet must satisfy.','Assuming the redundant continuous transform is efficient for storage.']::text[],ARRAY['Localizing a transient click within a longer recording.','Analyzing a signal whose frequency content changes quickly.','Detecting edges or onsets at multiple time scales.']::text[],'Advanced','W(a,b) = (1/sqrt(a)) * INT x(t) * conj( psi((t-b)/a) ) dt','The transform coefficient equals the integral of the signal times the conjugate of the mother wavelet, scaled by a and shifted by b, normalized by one over the square root of the scale.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Continuous wavelet transform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab8c66f5-8d14-4a13-a960-4b38124616aa','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab8c66f5-8d14-4a13-a960-4b38124616aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab8c66f5-8d14-4a13-a960-4b38124616aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b4d9d16d-5f3d-44c3-a61c-3c9da9e69805','Cumulative spectral decay','Cumulative spectral decay is a three-dimensional waterfall display showing how the frequency spectrum of a system''s impulse response decays over time. Computed from successively later windows of the impulse response, it reveals stored energy and resonances that ring on after the input stops.','Cumulative spectral decay is a 3D waterfall plot of a speaker''s response. It shows how each frequency fades after a sound stops. Resonances appear as ridges that ring on too long. Engineers use it to find those resonances.','It exposes time-delayed resonances and stored energy in loudspeakers and rooms that a single magnitude response cannot show.','A technician measures a driver''s impulse response, then computes its cumulative spectral decay; a ridge that lingers at one frequency flags a resonance to damp.','Signal Analysis',ARRAY['Impulse response','Waterfall plot','Resonance','Short-time Fourier transform','Accelerometer']::text[],ARRAY['Confusing decay ridges caused by resonance with normal frequency-response dips.','Ignoring that the analysis window choice shapes the displayed decay.','Reading absolute decay times without accounting for window effects.']::text[],ARRAY['Finding a lingering cabinet or cone resonance in a loudspeaker.','Checking a room for late-decaying modal ringing.','Comparing two drivers for stored-energy behavior.']::text[],'Advanced','CSD(f, t_k) = | DFT{ h[n] * w[n - n_k] } |','The decay surface is the magnitude spectrum of the impulse response viewed through a window that starts at progressively later times.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cumulative spectral decay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b4d9d16d-5f3d-44c3-a61c-3c9da9e69805','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b4d9d16d-5f3d-44c3-a61c-3c9da9e69805') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b4d9d16d-5f3d-44c3-a61c-3c9da9e69805');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '54b6f89d-d809-441e-8184-fef9ff229191','Cyclostationary analysis','Cyclostationary analysis studies signals whose statistical properties, such as mean or autocorrelation, vary periodically with time. It uses tools like the cyclic autocorrelation and spectral correlation to reveal hidden periodicities, making it well suited to rotating-machinery and modulated signals.','Cyclostationary analysis is a signal method. It studies signals whose statistics repeat on a set cycle. Many machine and modulated signals do this. It finds hidden patterns that come back again and again. Plain spectra often miss this structure.','It detects and exploits periodic statistical structure that stationary spectral analysis overlooks, aiding machinery diagnostics and communications.','A technician computes the cyclic autocorrelation of a bearing vibration signal; a peak at the fault repetition rate reveals the developing defect.','Signal Analysis',ARRAY['Cyclic autocorrelation','Spectral correlation','Bispectrum','Autocorrelation','Modulation']::text[],ARRAY['Assuming a signal is stationary when its statistics actually vary periodically.','Looking only at the ordinary spectrum, which hides cyclic structure.','Confusing the cyclic frequency with the ordinary spectral frequency.']::text[],ARRAY['Diagnosing a bearing or gear fault by its repetition rate.','Detecting a modulated communication signal in noise.','Separating sources that share a frequency band but differ in cycle.']::text[],'Advanced','R_x^alpha(tau) = < x(t + tau/2) * conj(x(t - tau/2)) * exp(-j*2*pi*alpha*t) >','The cyclic autocorrelation is the time average of the lagged product of the signal with its conjugate, modulated by a complex exponential at the cyclic frequency.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cyclostationary analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '54b6f89d-d809-441e-8184-fef9ff229191','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='54b6f89d-d809-441e-8184-fef9ff229191') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='54b6f89d-d809-441e-8184-fef9ff229191');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23ebbb6e-bc62-4283-8a74-e9c5d973b77a','DFT','The discrete Fourier transform (DFT) converts a finite sequence of N time-domain samples into N complex frequency-domain values, each giving the amplitude and phase of a harmonically related sinusoid. It is the basis of digital spectrum analysis and is usually computed by the fast Fourier transform algorithm.','The discrete Fourier transform turns samples into frequencies. It takes a block of N samples and returns N frequency values. Each value gives one tone''s size and phase. The fast Fourier transform computes it quickly.','It provides the frequency content of a sampled signal, forming the core of digital spectrum and FFT analysis.','A technician takes a 1024-sample block at 48 kHz and runs its DFT; each bin then spans 48000 / 1024, about 46.9 Hz.','Signal Analysis',ARRAY['FFT','Spectral leakage','Windowing','Frequency resolution','Blackman window']::text[],ARRAY['Confusing the DFT (the transform) with the FFT (a fast algorithm for it).','Ignoring spectral leakage when the signal is not periodic in the block.','Forgetting that bin spacing equals sample rate divided by block length.']::text[],ARRAY['Reading an FFT analyzer''s spectrum of a test tone.','Choosing a block length to set frequency resolution.','Detecting harmonics in a distortion measurement.']::text[],'Intermediate','X[k] = sum_{n=0}^{N-1} x[n] * exp(-j*2*pi*k*n/N)','Each frequency value is the sum over all samples of the input times a complex exponential at frequency index k.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='DFT');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23ebbb6e-bc62-4283-8a74-e9c5d973b77a','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23ebbb6e-bc62-4283-8a74-e9c5d973b77a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23ebbb6e-bc62-4283-8a74-e9c5d973b77a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '18ce4201-cfc7-4381-ad87-496785e8ea31','Directivity correction','Directivity correction accounts for the fact that a source does not radiate sound equally in all directions when its output is derived from measurements over a limited surface. In sound-power work the directivity of the measurement environment or source is captured by the directivity index, which relates on-axis level to the level of an equivalent omnidirectional source.','Directivity correction adjusts for a source that is louder in some directions. Real sources do not radiate evenly. Without correction, a level measured in one direction misleads. The correction ties that reading to an equal all-around source.','It relates a directional measurement to an equivalent omnidirectional radiation, so sound power and coverage estimates stay accurate.','A source with a directivity factor Q of 4 has a directivity index DI = 10 log(4) = about 6 dB more on-axis than an omnidirectional source of equal power.','Acoustic Measurement',ARRAY['Directivity index','Directivity factor','Sound power','Background-noise correction','Coverage angle']::text[],ARRAY['Confusing the directivity factor Q with the directivity index DI in decibels.','Applying an on-axis level as if the source radiated equally everywhere.','Ignoring frequency dependence, since directivity changes with frequency.']::text[],ARRAY['Estimating a horn''s on-axis gain from its directivity factor.','Relating a directional measurement to radiated sound power.','Predicting coverage from a loudspeaker''s directivity data.']::text[],'Intermediate','DI = 10 * log10(Q)','The directivity index in decibels equals ten times the base-ten log of the directivity factor.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '18ce4201-cfc7-4381-ad87-496785e8ea31','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='18ce4201-cfc7-4381-ad87-496785e8ea31') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='18ce4201-cfc7-4381-ad87-496785e8ea31');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56783b14-589f-4d37-91a5-ba5559df5f91','Discrete wavelet transform','The discrete wavelet transform decomposes a signal into approximation and detail coefficients using dyadic (power-of-two) scales and shifts, implemented efficiently by a cascade of filter banks with downsampling. It gives a compact, invertible multi-resolution representation widely used for denoising and compression.','The discrete wavelet transform splits a signal into coarse and fine parts. It uses scales that double at each step. Filter banks and downsampling make it fast. The result is compact and can be rebuilt exactly.','It provides an efficient, non-redundant multi-resolution analysis suited to compression, denoising, and feature extraction.','A technician applies a discrete wavelet transform, sets small detail coefficients to zero to remove noise, then reconstructs a cleaner signal.','Time-Frequency Analysis',ARRAY['Continuous wavelet transform','Filter bank','Multiresolution analysis','Mother wavelet','Downsampling']::text[],ARRAY['Confusing the discrete wavelet transform with the redundant continuous version.','Ignoring boundary effects at the edges of a finite signal.','Choosing a wavelet poorly matched to the signal''s features.']::text[],ARRAY['Denoising a measurement by thresholding detail coefficients.','Compressing a signal into a compact set of coefficients.','Extracting multi-scale features for classification.']::text[],'Advanced','a = 2^j,  b = k * 2^j  (dyadic scale and shift)','The transform samples the wavelet scale in powers of two and shifts it by integer multiples of that scale, computed through a filter-bank cascade.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Discrete wavelet transform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56783b14-589f-4d37-91a5-ba5559df5f91','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56783b14-589f-4d37-91a5-ba5559df5f91') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56783b14-589f-4d37-91a5-ba5559df5f91');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '87e77437-4c5e-4e87-a78f-bbc0fbb32429','Discrete-point measurement','A measurement technique that characterizes a device or system by testing it at a set of individual, selected values of a variable (typically discrete frequency or level points) rather than by a continuous sweep. At each point the analyzer settles, measures, and records one result, building up the response one step at a time.','This method tests a device one point at a time. The tester picks a set of frequencies or levels. It measures each one, waits to settle, then moves on. The result is a list of separate readings, not a smooth curve. Stepping this way often gives cleaner, more repeatable numbers.','It lets a technician measure exactly the frequencies or levels that matter, with time to average and settle at each one, trading speed for accuracy and repeatability.','To check an equalizer, a technician steps a signal generator through 1/3-octave centres (for example 100 Hz, 125 Hz, 160 Hz) and logs the output level at each, producing a stepped response table.','Measurement Method',ARRAY['Stepped-sine measurement','Swept-sine measurement','Frequency response','Signal generator','Averaging']::text[],ARRAY['Choosing too few points and missing a narrow peak or dip between them.','Not allowing the analyzer to settle at each point, so readings are taken before the system stabilizes.','Assuming stepped and continuous-sweep results must be identical for nonlinear devices.']::text[],ARRAY['Measuring an equalizer''s gain at each band centre.','Building a distortion-versus-level table for an amplifier.','Calibrating a sensor at fixed reference frequencies.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Discrete-point measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '87e77437-4c5e-4e87-a78f-bbc0fbb32429','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='87e77437-4c5e-4e87-a78f-bbc0fbb32429') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='87e77437-4c5e-4e87-a78f-bbc0fbb32429');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f08c1160-6990-445e-b26b-2f8a5cbcf17a','Doppler ultrasound','A measurement method that transmits ultrasound at a known frequency and detects the frequency shift of the echoes returned from a moving target, using the Doppler effect to compute the target''s velocity. For a reflector moving along the beam, the round-trip shift is twice that of a one-way source.','This method sends out high-pitched sound waves. When they bounce off a moving object, their pitch changes. The tool measures that pitch change. From it, the tool works out how fast the object moves. Doctors use this to measure blood flow.','It measures the speed and direction of moving matter, such as blood or fluid, without contact, by reading the frequency shift the motion imposes on reflected ultrasound.','With a 5 MHz probe aimed along flow (angle 0 deg) in tissue where sound travels about 1540 m/s, a flow of 0.5 m/s gives a Doppler shift of 2x5,000,000x0.5/1540 which is about 3.2 kHz.','Measurement Method',ARRAY['Doppler effect','Ultrasound transducer','Frequency shift','Instantaneous amplitude','Envelope analysis']::text[],ARRAY['Forgetting the factor of two that comes from the round trip to a reflector.','Ignoring the beam-to-flow angle, which makes speed read too low when the angle is large.','Confusing the audio-band Doppler shift with the megahertz transmit frequency.']::text[],ARRAY['Measuring blood-flow velocity in a vessel.','Detecting motion in a fluid pipeline.','Demonstrating the Doppler effect in a physics or acoustics lab.']::text[],'Advanced','f_d = 2 f_0 v cos(theta) / c','The Doppler shift equals two times the transmit frequency times the target speed times the cosine of the beam-to-motion angle, divided by the speed of sound in the medium.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Doppler ultrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f08c1160-6990-445e-b26b-2f8a5cbcf17a','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f08c1160-6990-445e-b26b-2f8a5cbcf17a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f08c1160-6990-445e-b26b-2f8a5cbcf17a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8b9201b9-87b7-4f7c-a7c5-923a2c95883f','Dynamic capability','An informal figure of merit describing the range of signal amplitudes a measurement instrument can handle at once, bounded at the top by its maximum undistorted input and at the bottom by its noise floor. It is closely tied to, and often quantified by, the instrument''s dynamic range.','This describes how big and how small a signal a tester can measure well. The top limit is the largest signal before it distorts. The bottom limit is its own background noise. A wide dynamic capability means it reads loud and very quiet signals together.','It tells a technician whether an analyzer can measure a small detail, such as low distortion, while a large main signal is present, without the large signal clipping or the small one sinking into noise.','A technician checks that an audio analyzer with, say, a 120 dB dynamic range can resolve a -100 dB distortion product beneath a full-scale tone before trusting a low-distortion reading.','Instrument Specification',ARRAY['Dynamic range','Noise floor','Full-scale level','Signal-to-noise ratio','Distortion analyzer']::text[],ARRAY['Treating dynamic capability as a fixed single number rather than a range set by two limits.','Confusing an instrument''s dynamic capability with the dynamic range of the signal being tested.','Ignoring that added gain can lift small signals but also lowers the usable headroom at the top.']::text[],ARRAY['Selecting an analyzer able to measure very low distortion.','Comparing test-set specifications before a purchase.','Explaining why a quiet artefact hides under a loud tone.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic capability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8b9201b9-87b7-4f7c-a7c5-923a2c95883f','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8b9201b9-87b7-4f7c-a7c5-923a2c95883f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8b9201b9-87b7-4f7c-a7c5-923a2c95883f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '91fca835-7a9b-4983-959d-8a89ddbf8c31','Efficiency bandwidth product','A Thiele-Small loudspeaker-driver figure of merit, abbreviated EBP, equal to the driver''s free-air resonance frequency divided by its electrical quality factor (fs/Qes). It is used as a rough guide to which enclosure alignment suits a driver.','This is a single number that describes a loudspeaker driver. You get it by dividing the driver''s resonance frequency by its electrical Q. A low number suggests a sealed box. A high number suggests a ported box. It helps a builder pick an enclosure fast.','It gives loudspeaker builders a quick screening number that hints whether a driver is better suited to a sealed (acoustic-suspension) or vented (bass-reflex) enclosure before detailed box modelling.','For a woofer with fs = 30 Hz and Qes = 0.4, EBP = 30/0.4 = 75; a value near 50 favours a sealed box, near 100 a vented box, so 75 could work in either.','Loudspeaker Parameter',ARRAY['Thiele-Small parameters','Fs','Qes','Sealed enclosure','Vented enclosure']::text[],ARRAY['Treating the EBP threshold as a hard rule instead of a rough guide.','Using total Q (Qts) instead of the electrical Q (Qes) in the ratio.','Assuming a high EBP guarantees good bass without checking box volume and tuning.']::text[],ARRAY['Screening woofers for a subwoofer build.','Deciding between a sealed and a ported enclosure.','Comparing drivers from a manufacturer''s parameter sheet.']::text[],'Advanced','EBP = fs / Qes','The efficiency bandwidth product equals the driver''s free-air resonance frequency divided by its electrical quality factor.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Efficiency bandwidth product');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '91fca835-7a9b-4983-959d-8a89ddbf8c31','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='91fca835-7a9b-4983-959d-8a89ddbf8c31') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='91fca835-7a9b-4983-959d-8a89ddbf8c31');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc9a9625-2959-4863-8379-257f393d568a','Engineering-grade measurement','A measurement performed to the intermediate accuracy class defined in acoustic standards (grade 2, ''engineering''), which sits between the highest-accuracy ''precision'' grade and the lowest ''survey'' grade. It has defined bounds on measurement uncertainty and on the test environment.','This is a mid-level accuracy class for measurements. It is more exact than a quick survey check. It is less exact than a full precision test. Standards set clear limits on its error and its test room. It balances good accuracy with practical effort.','It defines a repeatable accuracy level that is trustworthy enough for engineering decisions yet achievable outside a specialized laboratory, so results can be compared across sites.','A technician determines a machine''s sound power using ISO 3744, the engineering-grade method for a free field over a reflecting plane, meeting its stated uncertainty limits instead of using an anechoic-room precision method.','Measurement Class',ARRAY['Precision measurement','Survey measurement','Measurement uncertainty','ISO 3740 series','Sound power level']::text[],ARRAY['Assuming ''engineering grade'' means the most accurate class rather than the middle one.','Ignoring the environmental limits (such as background noise and room corrections) the grade requires.','Reporting a result to the engineering grade without meeting its uncertainty conditions.']::text[],ARRAY['Determining a product''s sound power for a datasheet.','Choosing a test method that fits the available room.','Documenting the accuracy class of a noise report.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Engineering-grade measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc9a9625-2959-4863-8379-257f393d568a','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc9a9625-2959-4863-8379-257f393d568a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc9a9625-2959-4863-8379-257f393d568a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df379051-6cc9-41e1-9a98-2fa5138184d7','Envelope analysis','A signal-analysis technique that extracts the slowly varying amplitude envelope of a signal (often via the magnitude of its analytic signal from the Hilbert transform) and then studies that envelope, commonly by taking its spectrum. It is widely used to reveal periodic amplitude modulation such as bearing or gear fault signatures.','This method looks at how a signal''s loudness rises and falls over time. That outline is called the envelope. Analysts then study the envelope, often its spectrum. Hidden repeating patterns, like a worn bearing, show up clearly this way. The fast carrier tone is stripped away.','It uncovers amplitude modulation hidden inside a high-frequency signal, turning a repeating impact or beat into a clear low-frequency line that is easy to identify.','To find a bearing fault, a technician band-pass filters the vibration around a resonance, forms the envelope with the Hilbert transform, and reads the envelope spectrum for the bearing''s characteristic defect frequency.','Analysis Method',ARRAY['Hilbert transform','Analytic signal','Instantaneous amplitude','Amplitude modulation','Demodulation']::text[],ARRAY['Skipping the band-pass filter, so the envelope is dominated by unrelated low-frequency energy.','Confusing the envelope spectrum with the ordinary spectrum of the raw signal.','Assuming the envelope always equals a simple rectified-and-smoothed waveform.']::text[],ARRAY['Diagnosing rolling-element bearing faults from vibration.','Detecting amplitude modulation in a machine signal.','Extracting a beat pattern from a tone burst.']::text[],'Advanced','a(t) = |x(t) + j*H{x(t)}|','The envelope equals the magnitude of the analytic signal, which is the original signal combined with its Hilbert transform as the imaginary part.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Envelope analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df379051-6cc9-41e1-9a98-2fa5138184d7','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df379051-6cc9-41e1-9a98-2fa5138184d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df379051-6cc9-41e1-9a98-2fa5138184d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f1da2745-cfdf-4453-b98c-5b0508c4be88','Environmental correction','A correction applied to acoustic measurements to remove the influence of the test surroundings, most notably the environmental correction K2 in sound-power standards that accounts for sound reflected by nearby room surfaces. Related corrections adjust for atmospheric conditions such as temperature and static pressure.','Real test rooms are not perfect. Walls reflect sound and change the reading. An environmental correction removes that added room effect. Weather can also shift results. Corrections for pressure and temperature fix that too. The goal is a result the room did not distort.','It makes measurements reflect the source or device itself rather than the room or weather, so results are comparable between different test sites and conditions.','Using ISO 3744, a technician finds the equivalent absorption area A and the measurement surface area S, then subtracts K2 = 10*log10(1 + 4S/A) dB from the surface sound-pressure level.','Measurement Correction',ARRAY['Sound power level','ISO 3744','Reverberation','Background noise correction','Free field']::text[],ARRAY['Confusing the environmental correction K2 with the background-noise correction K1.','Applying a room correction in a qualified free field where it should be negligible.','Forgetting temperature and pressure corrections when calibrating measurement microphones.']::text[],ARRAY['Correcting a sound-power test done in an ordinary room.','Adjusting microphone sensitivity for barometric pressure.','Qualifying a test space for engineering-grade measurements.']::text[],'Advanced','K2 = 10*log10(1 + 4*S/A)  [dB]','The environmental correction in decibels equals ten times the base-ten logarithm of one plus four times the measurement surface area divided by the room''s equivalent sound absorption area.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Environmental correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f1da2745-cfdf-4453-b98c-5b0508c4be88','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f1da2745-cfdf-4453-b98c-5b0508c4be88') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f1da2745-cfdf-4453-b98c-5b0508c4be88');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39a8b01d-3674-48f1-adc6-f88b3ea0634f','Error distribution','The probability distribution that describes how the errors of a measurement are spread about the true value. Its shape (for example normal/Gaussian, uniform, or triangular) governs the statistics used to state a measurement''s uncertainty.','No measurement is perfect. Repeat it and the errors scatter around the true value. An error distribution shows how those errors spread. Some errors are common, some rare. Its shape, such as a bell curve, sets how we state uncertainty.','It underpins uncertainty analysis by telling a technician how likely a given error size is, which is needed to convert scatter into confidence intervals and coverage factors.','When a spec gives only limits, a technician often assumes a uniform distribution of half-width a and takes the standard uncertainty as a/sqrt(3); for +/-0.3 dB this is 0.3/1.732 which is about 0.17 dB.','Statistics',ARRAY['Measurement uncertainty','Standard deviation','Gaussian distribution','Random error','Systematic error']::text[],ARRAY['Assuming every error set is Gaussian when limits imply a uniform distribution.','Confusing random scatter (distribution width) with a fixed systematic offset.','Using the full half-width as the standard uncertainty instead of dividing by sqrt(3) for a uniform law.']::text[],ARRAY['Building an uncertainty budget for a calibration.','Deciding a coverage factor for a stated confidence level.','Explaining why repeated readings scatter.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Error distribution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39a8b01d-3674-48f1-adc6-f88b3ea0634f','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39a8b01d-3674-48f1-adc6-f88b3ea0634f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39a8b01d-3674-48f1-adc6-f88b3ea0634f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a3e84f1-7987-473b-b6ea-09f091b926e5','FDTD acoustics','The application of the finite-difference time-domain method to acoustics, in which the governing wave equations for sound pressure and particle velocity are solved on a discrete space-time grid by stepping forward in time. Numerical stability requires the time step to satisfy the Courant condition relative to the grid spacing and sound speed.','This method simulates sound moving through space and time. The space is split into a grid of tiny cells. The computer updates pressure and velocity step by step. Waves then spread across the grid like real sound. It predicts how a room or object behaves acoustically.','It predicts how sound waves propagate, reflect, and resonate in a room or around an object, letting engineers model low-frequency acoustics before building anything physical.','To keep an FDTD room model stable in three dimensions with cubic cells, a technician sets the time step so the Courant number c*dt/dx stays at or below 1/sqrt(3); with dx = 0.05 m and c = 343 m/s, dt is about 84 microseconds.','Numerical Method',ARRAY['Finite-difference time-domain','Finite-element method','Courant condition','Room acoustics','Wave equation']::text[],ARRAY['Violating the Courant stability limit, which makes the simulation blow up.','Using a grid too coarse for the highest frequency, causing numerical dispersion.','Assuming FDTD is efficient at high frequencies where the required grid becomes huge.']::text[],ARRAY['Modelling low-frequency room modes.','Simulating sound diffraction around a barrier.','Predicting a small enclosure''s acoustic response.']::text[],'Advanced','c*dt/dx <= 1/sqrt(D)','For stability, the sound speed times the time step divided by the grid spacing must not exceed one over the square root of the number of spatial dimensions.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='FDTD acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a3e84f1-7987-473b-b6ea-09f091b926e5','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a3e84f1-7987-473b-b6ea-09f091b926e5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a3e84f1-7987-473b-b6ea-09f091b926e5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '93a68818-b8cb-4d17-a97b-cb5a7576863c','FFT','The fast Fourier transform, a family of efficient algorithms (notably Cooley-Tukey) that compute the discrete Fourier transform of an N-point sequence in on the order of N*log2(N) operations instead of the N-squared of a direct evaluation. It converts a sampled time signal into its complex spectrum of frequency components.','The FFT is a fast way to find the frequencies in a signal. A slow, direct method would take far more math. The FFT gets the same answer much faster. It turns a recorded waveform into a list of frequency bins. Nearly every audio analyzer uses it.','It makes real-time and high-resolution spectrum analysis practical by computing a signal''s frequency content quickly, which a direct discrete Fourier transform is too slow to do for large records.','Analyzing a 1024-point block sampled at 48 kHz, the FFT gives bins spaced Fs/N = 48000/1024 = 46.875 Hz apart, doing it in about (N/2)*log2(N) = 5120 butterflies instead of over a million direct multiplies.','Analysis Algorithm',ARRAY['Discrete Fourier transform','Fs','Hamming window','Frequency resolution','Spectrum analyzer']::text[],ARRAY['Forgetting that frequency resolution is fixed by Fs/N, not by the FFT alone.','Not applying a window, so spectral leakage smears the result.','Confusing the number of FFT bins with independent frequency resolution.']::text[],ARRAY['Displaying a live spectrum on an audio analyzer.','Finding a hum frequency in a recording.','Measuring the harmonics of a test tone.']::text[],'Intermediate','X[k] = sum_{n=0}^{N-1} x[n] * e^(-j*2*pi*k*n/N)','Each frequency bin equals the sum over all time samples of the sample value multiplied by a complex exponential whose rate depends on the bin number.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='FFT');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '93a68818-b8cb-4d17-a97b-cb5a7576863c','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='93a68818-b8cb-4d17-a97b-cb5a7576863c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='93a68818-b8cb-4d17-a97b-cb5a7576863c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23dc1d56-d5c7-448a-a173-cd588326f3ad','FIR filter','A finite impulse response digital filter whose output is a weighted sum of the current and a finite number of past input samples, with no feedback of past outputs. Because its impulse response has finite length, it is always stable and can be designed to have exactly linear phase.','This is a digital filter with no feedback. Its output is a weighted mix of recent input samples only. Because it has no loop, it can never go unstable. It can also delay every frequency by the same amount. That keeps the wave shape intact.','It shapes a signal''s frequency content while, when symmetric, preserving phase (waveform shape), which matters for crossovers, room correction, and any task where timing must stay consistent across frequency.','A technician builds a linear-phase loudspeaker crossover as an FIR filter, computing y[n] = sum b_k*x[n-k]; a symmetric 101-tap filter adds a constant delay of (101-1)/2 = 50 samples.','Digital Filter',ARRAY['IIR filter','Linear phase','Impulse response','Convolution','FFT']::text[],ARRAY['Assuming an FIR filter can be unstable; with only feedforward, it is always stable.','Using too few taps to get a sharp low-frequency cutoff, which needs many taps.','Forgetting the constant group delay a linear-phase FIR filter introduces.']::text[],ARRAY['Designing a linear-phase loudspeaker crossover.','Applying room-correction filtering.','Building an anti-alias or interpolation filter.']::text[],'Intermediate','y[n] = sum_{k=0}^{M} b_k * x[n-k]','The output at each sample equals the sum of each filter coefficient multiplied by the input sample that many steps in the past.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='FIR filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23dc1d56-d5c7-448a-a173-cd588326f3ad','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23dc1d56-d5c7-448a-a173-cd588326f3ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23dc1d56-d5c7-448a-a173-cd588326f3ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6dd13453-b2d0-473a-aa6f-0e73da287d99','Finite-difference time-domain','A general numerical method, abbreviated FDTD, that solves time-dependent partial differential equations by replacing derivatives with finite differences on a regular space-time grid and marching the solution forward in time, typically in a leapfrog scheme. Originally developed for electromagnetics, it is also applied to the acoustic wave equation.','This is a general way to solve wave problems on a computer. Space and time are cut into small steps. Rates of change become simple differences between grid points. The solution then moves forward one time step at a time. It works for both electromagnetic and sound waves.','It provides a direct, physically intuitive way to simulate wave propagation in the time domain, capturing reflections, diffraction, and resonance without solving one huge matrix.','An engineer sets grid spacing to at least about ten cells per shortest wavelength, then keeps the time step within the Courant stability limit c*dt/dx <= 1/sqrt(D) so the leapfrog update stays stable.','Numerical Method',ARRAY['FDTD acoustics','Finite-element method','Courant condition','Wave equation','Numerical dispersion']::text[],ARRAY['Ignoring the Courant stability condition, causing the simulation to diverge.','Confusing the general FDTD method with its specific acoustic application.','Using too coarse a grid, which introduces numerical dispersion errors.']::text[],ARRAY['Simulating electromagnetic wave propagation.','Modelling acoustic wave behaviour in a domain.','Teaching time-domain solution of the wave equation.']::text[],'Advanced','df/dx ~ (f(x+dx) - f(x-dx)) / (2*dx)','A spatial derivative is approximated as the difference between the field values one grid step ahead and one grid step behind, divided by twice the grid spacing.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Finite-difference time-domain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6dd13453-b2d0-473a-aa6f-0e73da287d99','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6dd13453-b2d0-473a-aa6f-0e73da287d99') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6dd13453-b2d0-473a-aa6f-0e73da287d99');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e6bcd40-3407-4b0d-a0e0-cf00b0ad9808','Finite-element method','A numerical technique, abbreviated FEM, that divides a continuous region into many small, interconnected elements of simple shape and approximates the governing equations over each element, then assembles them into a large system of equations solved for the field values at the nodes. In acoustics it models pressure fields, structural vibration, and their coupling.','This method breaks a complex shape into many small pieces called elements. Each piece uses simple math. The computer then links all the pieces together. Solving the whole set gives the field everywhere. It handles odd shapes that simple formulas cannot.','It lets engineers predict vibration and sound fields in complex, irregular geometries, such as a loudspeaker cabinet or a car cabin, where closed-form solutions do not exist.','A technician meshes a loudspeaker enclosure into elements, applies material and boundary properties, and solves for the pressure field to locate panel resonances, keeping element size well below the shortest wavelength of interest.','Numerical Method',ARRAY['Finite-difference time-domain','FDTD acoustics','Boundary conditions','Modal analysis','Room acoustics']::text[],ARRAY['Using a mesh too coarse to resolve the highest frequency of interest.','Assuming FEM stays cheap at high frequencies, where element counts explode.','Applying wrong boundary conditions, which invalidates the whole solution.']::text[],ARRAY['Modelling panel resonances in a speaker cabinet.','Predicting low-frequency behaviour of a car interior.','Analyzing structure-borne vibration coupling to air.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Finite-element method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e6bcd40-3407-4b0d-a0e0-cf00b0ad9808','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e6bcd40-3407-4b0d-a0e0-cf00b0ad9808') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e6bcd40-3407-4b0d-a0e0-cf00b0ad9808');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e96ed949-36e8-4864-a5ac-f6e8b45bbc09','Fs','In digital signal processing, Fs denotes the sampling frequency (sample rate): the number of samples taken from a continuous signal per second, measured in hertz. By the sampling theorem, Fs must exceed twice the highest signal frequency to avoid aliasing.','Fs means the sample rate. It is how many samples a system takes each second. A higher rate captures higher frequencies. To record a sound cleanly, the rate must be over twice its top frequency. Common audio rates are 44.1 kHz and 48 kHz.','It sets the highest frequency a digital system can represent and, together with block length, the resolution of a spectrum, so it is a core parameter of any sampled measurement.','At Fs = 48 kHz a system can represent frequencies up to Fs/2 = 24 kHz; an FFT block of N = 4096 samples then gives a bin spacing of Fs/N = 48000/4096 which is about 11.7 Hz.','Sampling Parameter',ARRAY['FFT','Frequency resolution','Aliasing','FIR filter','IIR filter']::text[],ARRAY['Confusing Fs (sampling frequency in DSP) with fs, a loudspeaker''s free-air resonance frequency.','Thinking Fs equals the highest recordable frequency instead of twice it.','Sampling below twice the top frequency and getting aliased false tones.']::text[],ARRAY['Setting the sample rate of an audio interface.','Computing FFT bin spacing.','Explaining why anti-alias filtering is needed.']::text[],'Beginner','Fs = 1/Ts ;  f_max < Fs/2','The sampling frequency equals one divided by the time between samples, and the highest representable frequency must stay below half the sampling frequency.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fs');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e96ed949-36e8-4864-a5ac-f6e8b45bbc09','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e96ed949-36e8-4864-a5ac-f6e8b45bbc09') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e96ed949-36e8-4864-a5ac-f6e8b45bbc09');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8afb2934-340f-4e79-afb9-b728a5c45502','Gammatone transform','A signal decomposition that passes a signal through a bank of gammatone filters, whose impulse response is a gamma-function envelope multiplying a sinusoidal carrier. The filter centre frequencies and bandwidths follow the human ear''s frequency scale, so the transform approximates the frequency analysis performed by the cochlea.','This transform splits sound the way the ear does. It uses a set of special filters called gammatone filters. Their spacing follows how our hearing works. Low bands are narrow and high bands are wide. The result mimics what the inner ear sends to the brain.','It provides a perceptually motivated front end for hearing models and machine listening, matching the cochlea''s filtering so later analysis works on ear-like frequency bands.','A developer builds a gammatone filterbank whose bands are spaced on the ERB scale (for example centres from 50 Hz to 8 kHz), each filter using g(t) = a*t^(n-1)*e^(-2*pi*b*t)*cos(2*pi*fc*t+phi) with order n = 4.','Analysis Method',ARRAY['Auditory filter','Equivalent rectangular bandwidth','Cochlea model','FIR filter','Homomorphic analysis']::text[],ARRAY['Spacing the filters linearly instead of on the ear''s ERB scale.','Assuming the gammatone filter has linear phase like a symmetric FIR filter.','Confusing the gammatone filterbank with the mel filterbank used in speech features.']::text[],ARRAY['Building a cochlea model for hearing research.','Front-end analysis for machine listening.','Studying auditory masking effects.']::text[],'Advanced','g(t) = a * t^(n-1) * e^(-2*pi*b*t) * cos(2*pi*fc*t + phi),  t >= 0','Each gammatone filter''s impulse response is a constant times time raised to the order minus one, times a decaying exponential set by the bandwidth, times a cosine at the centre frequency.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gammatone transform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8afb2934-340f-4e79-afb9-b728a5c45502','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8afb2934-340f-4e79-afb9-b728a5c45502') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8afb2934-340f-4e79-afb9-b728a5c45502');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0c001814-9a2d-4086-bfc2-806e2d1557fd','Geophone','An electromechanical transducer that converts ground motion into a voltage, typically a moving coil suspended by a spring within a permanent-magnet field so that its output above resonance is proportional to velocity. Its sensitivity is expressed in volts per metre per second.','A geophone senses movement of the ground. Inside is a coil hung on a spring near a magnet. When the ground shakes, the coil moves and makes a voltage. That voltage follows the speed of the motion. It is used to record vibrations and small quakes.','It captures ground or structure-borne vibration for seismic surveys and monitoring, giving a velocity-proportional signal without needing external power for the sensing element.','A technician deploys a 10 Hz geophone with a sensitivity of about 28 V/(m/s); a ground velocity of 0.001 m/s then produces roughly 28 mV, which the recorder digitizes.','Transducer',ARRAY['Hydrophone','Accelerometer','Velocity transducer','Resonance frequency','Seismic sensor']::text[],ARRAY['Assuming a geophone measures displacement or acceleration; above resonance it tracks velocity.','Using it far below its natural frequency, where sensitivity falls off sharply.','Ignoring that tilting the geophone off its working axis changes the reading.']::text[],ARRAY['Recording signals in a seismic reflection survey.','Monitoring construction or blast vibration.','Detecting footsteps or machinery ground motion.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Geophone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0c001814-9a2d-4086-bfc2-806e2d1557fd','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0c001814-9a2d-4086-bfc2-806e2d1557fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0c001814-9a2d-4086-bfc2-806e2d1557fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a7937b6-a9b1-4e94-ab5c-4c2d6f74d26b','Hamming window','A tapering function applied to a block of samples before a discrete Fourier transform, defined by a raised cosine of the form 0.54 - 0.46*cos(2*pi*n/(N-1)). Its coefficients are chosen to cancel much of the nearest side lobe, giving a peak side-lobe level of about -43 dB at the cost of a wider main lobe than a rectangular window.','This is a smooth shape put over a block of samples before analysis. It fades the ends of the block gently toward the edges. That reduces leakage between frequency bins. It lowers false skirts around a strong tone. The trade-off is slightly less sharpness.','It reduces spectral leakage in FFT analysis by tapering the record ends, making nearby weak tones easier to see next to a strong one without an abrupt block edge.','Before a 1024-point FFT, a technician multiplies each sample x[n] by w(n) = 0.54 - 0.46*cos(2*pi*n/1023); the resulting spectrum shows side lobes near -43 dB instead of the -13 dB of no window.','Window Function',ARRAY['Hann window','FFT','Spectral leakage','Windowing','Side lobe']::text[],ARRAY['Confusing the Hamming window with the Hann (Hanning) window, which uses 0.5 and 0.5.','Forgetting a window at all, so a strong tone leaks across many bins.','Assuming a window improves true frequency resolution; it actually widens the main lobe.']::text[],ARRAY['Windowing data before an FFT spectrum.','Reducing leakage when measuring a tone''s harmonics.','Comparing window trade-offs in analyzer settings.']::text[],'Intermediate','w(n) = 0.54 - 0.46*cos(2*pi*n/(N-1)),  0 <= n <= N-1','Each window weight equals 0.54 minus 0.46 times the cosine of two pi times the sample index divided by one less than the block length.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hamming window');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a7937b6-a9b1-4e94-ab5c-4c2d6f74d26b','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a7937b6-a9b1-4e94-ab5c-4c2d6f74d26b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a7937b6-a9b1-4e94-ab5c-4c2d6f74d26b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c28d4cb-c958-4693-895e-7e37afc02aff','Head and torso simulator (HATS)','A manikin that reproduces the average acoustic shape of a human head and upper torso, fitted with calibrated ear simulators (and often a mouth simulator), used to make repeatable acoustic measurements that include the effects of head diffraction and ear geometry. Its ear and acoustic properties are specified in IEC 60318-7.','A HATS is a dummy shaped like a human head and shoulders. It has built-in ears with measurement microphones. Some also have a loudspeaker mouth. It captures sound the way a real head would. This gives repeatable tests for headphones, phones, and hearing aids.','It provides a standardized, repeatable stand-in for a human listener or talker, so headphones, telephones, and hearing devices can be measured with realistic head and ear effects.','A technician mounts headphones on a HATS to measure their frequency response at the ear reference point, relying on the standardized ear simulator so results compare across labs.','Measurement Manikin',ARRAY['Ear simulator','Measurement microphone','IEC 61094','Binaural recording','Artificial ear']::text[],ARRAY['Treating a HATS response as a raw microphone response, ignoring its built-in ear and head effects.','Assuming any manikin meets IEC 60318-7 without checking its ear simulator specification.','Positioning the device under test inconsistently, which ruins repeatability.']::text[],ARRAY['Testing headphone frequency response.','Evaluating telephone or headset speech quality.','Measuring hearing-aid performance on a standardized head.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Head and torso simulator (HATS)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c28d4cb-c958-4693-895e-7e37afc02aff','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c28d4cb-c958-4693-895e-7e37afc02aff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c28d4cb-c958-4693-895e-7e37afc02aff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a2f4ce1-c7f6-40f9-991c-3381dd85288e','Higher-order spectrum','A frequency-domain statistic built from higher-order moments or cumulants of a signal, such as the bispectrum (third order) and trispectrum (fourth order), collectively called polyspectra. Unlike the ordinary power spectrum, these retain phase relationships and can reveal nonlinear coupling and non-Gaussian behaviour.','An ordinary spectrum shows only how much energy is at each frequency. A higher-order spectrum shows how frequencies relate to each other. It keeps phase links the power spectrum throws away. This reveals when frequencies are coupled by a nonlinear process. The bispectrum is the simplest example.','It detects phase coupling and nonlinearity that ordinary power spectra miss, helping identify when energy at different frequencies is generated by a common nonlinear mechanism.','To test for quadratic nonlinearity, an analyst computes the bispectrum B(f1,f2) = E[X(f1)*X(f2)*conj(X(f1+f2))] and looks for strong peaks where f1 and f2 sum to a coupled component.','Analysis Method',ARRAY['Bispectrum','Power spectrum','Bicoherence','Envelope analysis','FFT']::text[],ARRAY['Expecting a higher-order spectrum to add value for a linear, Gaussian signal, where it is nearly zero.','Skipping enough averaging, so estimates are dominated by noise.','Confusing the bispectrum with an ordinary two-frequency power spectrum.']::text[],ARRAY['Detecting nonlinear coupling in a machine or amplifier.','Testing whether a signal departs from Gaussian noise.','Studying wave interaction in acoustics.']::text[],'Advanced','B(f1,f2) = E[X(f1) * X(f2) * conj(X(f1+f2))]','The bispectrum at a pair of frequencies is the expected value of the product of the signal''s spectrum at those two frequencies and the conjugate of its spectrum at their sum.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Higher-order spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a2f4ce1-c7f6-40f9-991c-3381dd85288e','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a2f4ce1-c7f6-40f9-991c-3381dd85288e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a2f4ce1-c7f6-40f9-991c-3381dd85288e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '853e52a8-cef8-4ee6-bdae-9497ce7a3ed4','Homomorphic analysis','A class of nonlinear signal processing that maps convolved or multiplied signal components into an additive domain using a logarithm, so they can be separated with linear filtering, then maps back. Applied to spectra it yields the cepstrum, widely used to separate a source excitation from a filter (for example glottal pulses from the vocal tract).','Some signals are two parts mixed by convolution. Homomorphic analysis untangles them. It takes a log so the two parts simply add. Then ordinary filtering can split them apart. This is how the cepstrum separates a voice source from the mouth shaping it.','It separates signal components that are combined by convolution or multiplication, such as an excitation and a filter, which ordinary linear methods cannot pull apart directly.','To find a talker''s pitch, a technician computes the real cepstrum c[n] = IDFT{log|X(f)|} and reads the quefrency of its peak, whose reciprocal is the fundamental frequency.','Analysis Method',ARRAY['Cepstrum','Quefrency','Deconvolution','FFT','Vocal tract']::text[],ARRAY['Confusing quefrency (the cepstrum axis) with ordinary frequency.','Forgetting phase unwrapping when computing the complex cepstrum.','Assuming the log step is optional; it is what makes convolution become addition.']::text[],ARRAY['Estimating vocal pitch from speech.','Separating an echo from a signal.','Removing a room response by deconvolution.']::text[],'Advanced','c[n] = IDFT{ log|DFT{x[n]}| }','The real cepstrum equals the inverse discrete Fourier transform of the logarithm of the magnitude of the signal''s discrete Fourier transform.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Homomorphic analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '853e52a8-cef8-4ee6-bdae-9497ce7a3ed4','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='853e52a8-cef8-4ee6-bdae-9497ce7a3ed4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='853e52a8-cef8-4ee6-bdae-9497ce7a3ed4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bece2f4b-ad91-4ba9-8af6-78e7771cadd5','Hydrophone','A transducer designed to detect sound in water, most commonly a piezoelectric ceramic element that produces a voltage in response to underwater sound pressure. Its sensitivity is stated as a level in decibels relative to one volt per micropascal, and its calibration is covered by IEC 60565.','A hydrophone is a microphone for use underwater. Inside is usually a piezoelectric material. Sound pressure in the water squeezes it and makes a voltage. It works over a very wide frequency range. Scientists use it to listen to the sea and its life.','It converts underwater sound into an electrical signal for measurement and monitoring, letting technicians quantify ocean noise, sonar, and marine sources.','A hydrophone with a sensitivity of -200 dB re 1 V/uPa produces 1e-10 V per micropascal; a 1 Pa (that is 1,000,000 uPa) sound pressure thus yields about 1e-4 V, which the technician amplifies before recording.','Transducer',ARRAY['Geophone','Measurement microphone','Piezoelectric transducer','Sensitivity','Underwater acoustics']::text[],ARRAY['Reading the negative sensitivity value as a fault rather than a normal dB re 1 V/uPa figure.','Forgetting that pressure reference is micropascals, not the 20 uPa air reference.','Ignoring the strong effect of water temperature and depth on the acoustic field.']::text[],ARRAY['Measuring ambient ocean noise.','Calibrating a sonar transmitter.','Recording marine mammal vocalizations.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hydrophone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bece2f4b-ad91-4ba9-8af6-78e7771cadd5','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bece2f4b-ad91-4ba9-8af6-78e7771cadd5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bece2f4b-ad91-4ba9-8af6-78e7771cadd5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e7a36a1-fd19-4fe6-ad5f-07787c82ffd4','IEC 60268','A multi-part international standard from the International Electrotechnical Commission titled ''Sound system equipment'', specifying rated characteristics and measurement methods for professional and consumer audio equipment. Its parts cover items such as amplifiers, loudspeakers, microphones, and program-level metering so specifications can be compared consistently.','IEC 60268 is a family of audio standards. It says how to measure and rate sound equipment. Different parts cover amplifiers, loudspeakers, and microphones. It defines the tests makers should use. This lets buyers compare gear on equal terms.','It gives manufacturers common definitions and test methods for audio equipment so that quoted ratings, such as power or frequency response, mean the same thing across brands.','A technician checks that an amplifier''s rated output power was measured per IEC 60268-3 conditions before comparing it fairly against another maker''s figure.','Standard',ARRAY['IEC 61094','IEC 61672','Sound system equipment','Frequency response','Rated power']::text[],ARRAY['Assuming a single number covers the whole standard; it has many parts for different equipment.','Comparing power ratings measured under different conditions as if they matched.','Confusing IEC 60268 (sound system equipment) with IEC 61672 (sound level meters).']::text[],ARRAY['Comparing amplifier power specifications.','Writing a loudspeaker datasheet.','Defining a microphone''s measured characteristics.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='IEC 60268');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e7a36a1-fd19-4fe6-ad5f-07787c82ffd4','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e7a36a1-fd19-4fe6-ad5f-07787c82ffd4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e7a36a1-fd19-4fe6-ad5f-07787c82ffd4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '958e9cef-1f37-46df-9224-990e5a7439b4','IEC 61094','A multi-part International Electrotechnical Commission standard, ''Electroacoustics - Measurement microphones'', that defines laboratory standard and working standard measurement microphones and the methods to calibrate them, including primary pressure calibration by the reciprocity technique. It underpins traceable acoustic measurement.','IEC 61094 is the standard for measurement mics. It defines the reference mics used in labs. It gives the exact steps to check them. One method gives the most exact results. This keeps sound readings trusted and correct.','It establishes the reference microphones and calibration methods that give acoustic measurements traceability to primary standards, so sound-level data is reliable and comparable.','A calibration lab uses IEC 61094-2 reciprocity calibration to assign a traceable pressure sensitivity to a laboratory standard microphone before it is used to check field instruments.','Standard',ARRAY['IEC 61672','Measurement microphone','Reciprocity calibration','Sensitivity','Head and torso simulator (HATS)']::text[],ARRAY['Confusing a laboratory standard microphone with an ordinary working microphone.','Assuming a single calibration frequency is enough for a full response.','Mixing up IEC 61094 (microphones) with IEC 61672 (sound level meters).']::text[],ARRAY['Calibrating a reference measurement microphone.','Establishing acoustic measurement traceability.','Qualifying a microphone for standards-based tests.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='IEC 61094');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '958e9cef-1f37-46df-9224-990e5a7439b4','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='958e9cef-1f37-46df-9224-990e5a7439b4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='958e9cef-1f37-46df-9224-990e5a7439b4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee0ef1f7-33cd-4ebd-8d3e-4cf9a3397017','IEC 61672','A multi-part International Electrotechnical Commission standard, ''Electroacoustics - Sound level meters'', whose Part 1 specifies the electroacoustic performance of sound level meters in two accuracy grades, class 1 and class 2. Further parts define pattern-evaluation tests (Part 2) and periodic verification (Part 3).','IEC 61672 is the standard for sound level meters. It sets how accurate a meter must be. There are two grades: class 1 and class 2. Class 1 is the tighter, more accurate grade. It also gives the tests used to prove a meter complies.','It defines what a compliant sound level meter must do and how it is tested, so noise measurements made with class 1 or class 2 meters are consistent and legally defensible.','For a regulatory noise survey a technician selects a class 1 sound level meter meeting IEC 61672-1, then has it periodically verified to Part 3 to keep results traceable.','Standard',ARRAY['Sound level meter','IEC 61094','Frequency weighting','Class 1','Class 2']::text[],ARRAY['Calling a meter ''Type 1'' (the old IEC 60651 term) instead of the current ''class 1''.','Assuming class 2 accuracy is acceptable where regulations demand class 1.','Confusing IEC 61672 (meters) with IEC 61094 (measurement microphones).']::text[],ARRAY['Choosing a compliant meter for a noise survey.','Verifying a meter''s periodic calibration.','Specifying the accuracy class in a test report.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='IEC 61672');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee0ef1f7-33cd-4ebd-8d3e-4cf9a3397017','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee0ef1f7-33cd-4ebd-8d3e-4cf9a3397017') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee0ef1f7-33cd-4ebd-8d3e-4cf9a3397017');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8318ab1a-803d-44df-aed5-fc733cab4619','IIR filter','An infinite impulse response digital filter whose output depends on past outputs as well as inputs, giving it feedback and an impulse response that in principle never fully ends. This recursion lets it achieve a sharp frequency response with few coefficients, but it can be unstable and generally does not have linear phase.','This is a digital filter that feeds its output back into itself. That feedback makes it very efficient. It can build a steep filter with little math. The downside is that it can become unstable. It also usually delays different frequencies by different amounts.','It provides sharp, efficient frequency filtering with low computation, which suits real-time equalizers and tone controls where phase linearity is not critical.','A technician implements a parametric EQ band as a biquad IIR filter, y[n] = b0*x[n] + b1*x[n-1] + b2*x[n-2] - a1*y[n-1] - a2*y[n-2], and checks its poles lie inside the unit circle for stability.','Digital Filter',ARRAY['FIR filter','Biquad','Feedback','Pole-zero','Stability']::text[],ARRAY['Assuming an IIR filter is always stable; poles outside the unit circle make it blow up.','Expecting linear phase, which IIR filters generally do not provide.','Ignoring coefficient quantization, which can shift poles and cause instability.']::text[],ARRAY['Building a parametric equalizer band.','Implementing a low-cost real-time filter.','Emulating an analog filter''s response digitally.']::text[],'Intermediate','y[n] = sum_{k=0}^{M} b_k*x[n-k] - sum_{k=1}^{N} a_k*y[n-k]','The output equals the weighted sum of current and past inputs minus the weighted sum of past outputs fed back through the filter.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='IIR filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8318ab1a-803d-44df-aed5-fc733cab4619','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8318ab1a-803d-44df-aed5-fc733cab4619') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8318ab1a-803d-44df-aed5-fc733cab4619');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd1f55573-28d0-4490-b6d6-af057565a468','ISO 3740 series','A family of International Organization for Standardization standards for determining the sound power levels of noise sources from sound-pressure measurements, spanning accuracy grades from precision to survey. ISO 3740 gives guidance for selecting a method; companion parts cover reverberation-room, free-field, and survey methods.','This set of standards measures how much sound power a machine makes. It uses sound-pressure readings around the source. Different parts offer different accuracy levels. Some need special rooms; others allow rougher checks. ISO 3740 itself helps you pick the right method.','It provides agreed methods to rate a source by its total radiated sound power, a room-independent quantity, so products can be compared and declared consistently.','To declare a product''s sound power, a technician picks the method fitting the site: ISO 3744 (engineering grade, free field over a reflecting plane) or ISO 3745 (precision, anechoic room), then follows its grid and corrections.','Standard',ARRAY['Sound power level','ISO 9613','Environmental correction','Engineering-grade measurement','Anechoic chamber']::text[],ARRAY['Confusing sound power (source property) with sound pressure (depends on distance and room).','Using a survey-grade method where an engineering or precision grade is required.','Skipping the required environmental and background-noise corrections.']::text[],ARRAY['Declaring a machine''s sound power on a datasheet.','Choosing a test method for the available facility.','Comparing noise emissions between products.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ISO 3740 series');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd1f55573-28d0-4490-b6d6-af057565a468','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d1f55573-28d0-4490-b6d6-af057565a468') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d1f55573-28d0-4490-b6d6-af057565a468');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e7bb8436-d1f7-4a29-9fa2-c71e2d9e4ef2','ISO 9613','A two-part International Organization for Standardization standard on the attenuation of sound during propagation outdoors. Part 1 gives an analytical method to calculate atmospheric absorption as a function of frequency, temperature, humidity, and pressure; Part 2 gives a general engineering method to predict outdoor sound levels including geometric spreading, ground, barriers, and other effects.','ISO 9613 predicts how outdoor sound fades with distance. Part 1 covers how air itself absorbs sound. That loss depends on frequency, temperature, and humidity. Part 2 adds spreading, ground, and barriers. Together they estimate noise reaching a distant listener.','It lets engineers predict community noise from a distant source by accounting for the physical mechanisms that reduce sound level as it travels outdoors.','Assessing traffic noise at homes, a technician uses ISO 9613-1 to get air absorption at each octave band and ISO 9613-2 to add distance spreading, ground effect, and a barrier''s screening.','Standard',ARRAY['ISO 3740 series','Atmospheric absorption','Geometric spreading','Barrier attenuation','Sound power level']::text[],ARRAY['Ignoring atmospheric absorption, which strongly reduces high frequencies over distance.','Treating the Part 2 method''s downwind assumption as a worst-case result.','Forgetting that Part 2 assumes downwind or moderate temperature-inversion conditions.']::text[],ARRAY['Predicting community noise from an industrial plant.','Modelling road or rail noise at nearby homes.','Designing a noise barrier''s expected benefit.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ISO 9613');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e7bb8436-d1f7-4a29-9fa2-c71e2d9e4ef2','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e7bb8436-d1f7-4a29-9fa2-c71e2d9e4ef2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e7bb8436-d1f7-4a29-9fa2-c71e2d9e4ef2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8cb1325f-9500-4012-8043-e24906af2cd9','Independent-component analysis','A computational method, abbreviated ICA, that separates a set of observed mixed signals into additive components assumed to be statistically independent and mostly non-Gaussian. It solves blind source separation problems, recovering the underlying sources without prior knowledge of how they were mixed.','ICA pulls mixed signals apart into their real sources. It assumes the sources do not depend on each other. It also assumes they are not plain bell-curve noise. Given a few mic tracks, it can find each voice. People call this blind source separation.','It recovers hidden source signals from mixtures, such as separating simultaneous talkers picked up by several microphones, without knowing the mixing process in advance.','With several microphones capturing two overlapping talkers, a technician runs ICA on the recorded channels to estimate the two independent voice signals for cleaner separate analysis.','Analysis Method',ARRAY['Blind source separation','Principal-component analysis','Statistical independence','Higher-order spectrum','Non-Gaussianity']::text[],ARRAY['Confusing ICA with PCA; PCA finds uncorrelated directions, ICA finds independent sources.','Applying ICA when sources are Gaussian, where it cannot separate them.','Expecting ICA to preserve the original amplitude and order of the sources.']::text[],ARRAY['Separating overlapping talkers from multiple microphones.','Removing artefacts from bio-signal recordings.','Isolating machine sources in a noisy environment.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Independent-component analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8cb1325f-9500-4012-8043-e24906af2cd9','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8cb1325f-9500-4012-8043-e24906af2cd9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8cb1325f-9500-4012-8043-e24906af2cd9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3e44a60-7906-418c-be60-6e21c2414d4b','Indication','In metrology, an indication is the raw reading an instrument or system shows on its display or output, taken before any calibration correction. It is simply what the device reports and need not equal the true value of the measurand.','An indication is simply what a meter shows. It is the raw reading on the display. It is not yet the corrected true value. Calibration then adjusts it toward the truth. In short, it is the number the instrument gives you.','It names the raw output of an instrument so that metrologists can clearly distinguish what a device reads from the corrected, traceable measurement result.','If a sound level meter shows 93.2 dB but its calibration certificate lists a +0.3 dB correction, the indication is 93.2 dB and the corrected result is 93.5 dB.','Metrology Concept',ARRAY['Measurand','Calibration','Measurement error','Correction','Measurement result']::text[],ARRAY['Treating the raw indication as the true value without applying the calibration correction.','Confusing the indication with the measurement result, which includes corrections and uncertainty.','Assuming a stable indication means an accurate one.']::text[],ARRAY['Reading an uncorrected value from a meter.','Recording raw readings before applying calibration.','Explaining the difference between reading and result in a report.']::text[],'Beginner',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Indication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3e44a60-7906-418c-be60-6e21c2414d4b','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3e44a60-7906-418c-be60-6e21c2414d4b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3e44a60-7906-418c-be60-6e21c2414d4b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cd6cd2df-a122-45b9-98bb-58abcc25de00','Instantaneous amplitude','The time-varying amplitude of a signal at each instant, defined as the magnitude of its analytic signal, which is the original signal plus j times its Hilbert transform. It traces the signal''s envelope, giving the local strength independent of the underlying oscillation.','This is a signal''s strength at each moment. It follows the outline of the wave over time. It is found using the analytic signal from the Hilbert transform. It ignores the fast up-and-down of the wave. It tells you how strong the signal is right now.','It quantifies how a signal''s strength changes over time, providing the envelope used in amplitude-modulation analysis, transient detection, and loudness-related processing.','To track a tone burst''s rise, a technician forms the analytic signal and computes a(t) = sqrt(x(t)^2 + xh(t)^2), where xh is the Hilbert transform, reading a(t) as the instantaneous envelope.','Signal Property',ARRAY['Envelope analysis','Analytic signal','Hilbert transform','Instantaneous frequency','Amplitude modulation']::text[],ARRAY['Confusing instantaneous amplitude with the peak amplitude of the whole signal.','Computing the envelope without forming the proper analytic (Hilbert) signal.','Assuming it equals a simple full-wave rectified waveform.']::text[],ARRAY['Tracking the envelope of a tone burst.','Detecting transients in a recording.','Measuring amplitude modulation depth.']::text[],'Advanced','a(t) = sqrt( x(t)^2 + xh(t)^2 )','The instantaneous amplitude equals the square root of the sum of the squared signal and its squared Hilbert transform.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Instantaneous amplitude');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cd6cd2df-a122-45b9-98bb-58abcc25de00','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cd6cd2df-a122-45b9-98bb-58abcc25de00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cd6cd2df-a122-45b9-98bb-58abcc25de00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '64231cd2-b7c0-4236-bc17-04b5830747ba','Instantaneous intensity','The instantaneous sound intensity is the product of the instantaneous sound pressure and the instantaneous particle velocity at a point, giving a vector that describes the momentary rate and direction of acoustic energy flow per unit area. Its time average over a period is the (active) sound intensity used for sound-power measurement.','Instantaneous intensity shows how sound energy moves at one instant. You get it by multiplying the pressure by the air''s speed at that moment. It points in the direction the energy flows. Averaging it over time gives the steady sound intensity engineers report.','It underpins sound-intensity measurement, letting technicians find the direction and rate of acoustic energy flow rather than pressure alone.','With a two-microphone probe, in a plane wave of 1 Pa the particle velocity is about 1/415 = 2.4 mm/s, so the instantaneous intensity peaks near 2.4 mW/m^2.','Sound Intensity',ARRAY['Sound intensity','Particle velocity','Sound pressure','Measurement surface','Probe orientation']::text[],ARRAY['Confusing intensity with sound pressure; intensity is a pressure-times-velocity product and has direction.','Assuming instantaneous intensity is always positive; it can be negative when energy flows back.','Forgetting intensity is a vector, so the probe axis sets which component is measured.']::text[],ARRAY['Mapping energy flow around a machine to locate a noise source.','Measuring sound power in situ without an anechoic room.','Checking whether a leak radiates or absorbs energy on a panel.']::text[],'Advanced','I(t) = p(t) * u(t)   (vector);   I_active = <p(t) u(t)>','Instantaneous intensity equals the instantaneous sound pressure multiplied by the instantaneous particle velocity vector; its time average is the active sound intensity.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Instantaneous intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '64231cd2-b7c0-4236-bc17-04b5830747ba','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='64231cd2-b7c0-4236-bc17-04b5830747ba') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='64231cd2-b7c0-4236-bc17-04b5830747ba');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75875bda-5af4-4834-99b9-ad02361d6f0d','Instantaneous phase','The instantaneous phase of a signal is the phase angle of its analytic signal, formed from the real signal and its Hilbert transform. Its time derivative divided by 2*pi gives the instantaneous frequency.','Instantaneous phase is the angle of a signal at each moment. It is found from the signal and its Hilbert transform pair. Watching how fast this angle turns gives the instantaneous frequency. It helps track signals whose pitch changes over time.','It lets analysts describe how a signal''s phase and frequency vary moment to moment, which is central to demodulation and time-frequency analysis.','For a steady 1 kHz tone the instantaneous phase advances 2*pi radians every millisecond, so its derivative yields an instantaneous frequency of 1000 Hz.','Signal Analysis',ARRAY['Analytic signal','Hilbert transform','Instantaneous frequency','Envelope detection','Phase']::text[],ARRAY['Confusing instantaneous phase with the phase of one Fourier bin, which is a fixed number.','Forgetting to unwrap the phase, which creates false 2*pi jumps.','Assuming it is meaningful for wideband signals, where the analytic-signal idea breaks down.']::text[],ARRAY['Demodulating an FM or vibration signal to recover its frequency track.','Detecting the envelope of a bearing signal for fault analysis.','Estimating instantaneous frequency of a swept sine.']::text[],'Advanced','phi(t) = arg{ z(t) },  z(t) = x(t) + j*H{x(t)};  f_inst(t) = (1/2pi) dphi/dt','Instantaneous phase is the argument of the analytic signal built from the signal plus j times its Hilbert transform; instantaneous frequency is one over two pi times the phase''s time derivative.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Instantaneous phase');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75875bda-5af4-4834-99b9-ad02361d6f0d','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75875bda-5af4-4834-99b9-ad02361d6f0d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75875bda-5af4-4834-99b9-ad02361d6f0d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d8c86b1-a0f0-4d39-860f-35206e752331','Kurtogram','A kurtogram is a two-dimensional map of the spectral kurtosis of a signal computed over combinations of centre frequency and frequency-resolution (band width). It reveals which frequency band carries the most impulsive, non-Gaussian content, guiding the choice of a band-pass filter for fault detection.','A kurtogram is a colour map that finds impulsive noise. It measures how ''spiky'' each frequency band is. The band with the sharpest bursts stands out. Engineers use it to pick a filter that reveals hidden bearing or gear faults.','It automates finding the frequency band where impulsive fault signatures are strongest, so a technician can filter there before envelope analysis.','On a vibration record from a rolling bearing, the kurtogram may peak at a 4 kHz band; band-pass filtering there before envelope analysis exposes the bearing''s fault repetition rate.','Vibration Analysis',ARRAY['Spectral kurtosis','Envelope analysis','Bearing fault detection','Band-pass filter','Order tracking']::text[],ARRAY['Treating high kurtosis as proof of a fault; electrical spikes and impacts also raise it.','Ignoring that heavy background impulses can mask the fault band.','Assuming one kurtogram fits all speeds; the best band can shift with load and speed.']::text[],ARRAY['Selecting a demodulation band for rolling-element bearing diagnosis.','Screening gearbox vibration for early impulsive faults.','Setting up condition-monitoring alarms on rotating machinery.']::text[],'Advanced','K_x(f) = <|X(t,f)|^4> / <|X(t,f)|^2>^2 - 2   (spectral kurtosis vs frequency f and resolution)','The kurtogram plots the spectral kurtosis, the fourth-order normalized energy of the signal''s short-time spectral components, as a function of both frequency and analysis bandwidth.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kurtogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d8c86b1-a0f0-4d39-860f-35206e752331','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d8c86b1-a0f0-4d39-860f-35206e752331') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d8c86b1-a0f0-4d39-860f-35206e752331');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'de10e227-7349-4517-854d-5783be2b8d61','Laser Doppler vibrometer','A laser Doppler vibrometer (LDV) is a non-contact instrument that measures surface velocity and displacement from the Doppler frequency shift of laser light scattered by a vibrating surface, using optical (usually heterodyne) interferometry. The Doppler shift is proportional to the surface velocity along the beam.','A laser Doppler vibrometer measures vibration without touching the object. It shines a laser at a moving surface. The surface''s motion shifts the light''s frequency. The instrument reads that shift to find the surface speed. It suits light or hot parts a contact sensor would disturb.','It provides accurate, non-contact vibration measurement where adding a sensor''s mass, heat, or contact would corrupt the result or is impossible.','Aimed at a loudspeaker cone moving at 0.1 m/s with a 633 nm laser, the Doppler shift is 2*0.1/633e-9 = about 316 kHz, which the interferometer converts to velocity.','Test Equipment',ARRAY['Doppler shift','Interferometry','Accelerometer','Particle velocity','Vibration measurement']::text[],ARRAY['Assuming it needs no reflective target; low-reflectivity surfaces may need tape or spray.','Ignoring that it reads velocity along the beam only, so alignment matters.','Forgetting speckle noise and target motion across the beam can add dropouts.']::text[],ARRAY['Measuring loudspeaker cone breakup without loading the diaphragm.','Testing MEMS or small structures too light for an accelerometer.','Scanning a panel to map operating deflection shapes.']::text[],'Advanced','f_D = 2 v / lambda','The Doppler frequency shift equals twice the surface velocity along the beam divided by the laser wavelength.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laser Doppler vibrometer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'de10e227-7349-4517-854d-5783be2b8d61','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='de10e227-7349-4517-854d-5783be2b8d61') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='de10e227-7349-4517-854d-5783be2b8d61');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8bbf56c0-575b-4177-a619-bf9e84a6fac7','Le','Le is the voice-coil inductance of a moving-coil loudspeaker driver, one of its small-signal (Thiele-Small) parameters, usually quoted in millihenries and commonly measured near 1 kHz. It causes the driver''s impedance to rise at high frequencies and is frequency dependent because of eddy currents in the pole piece.','Le is the inductance of a loudspeaker''s voice coil. It is a basic driver specification, given in millihenries. It makes the driver''s impedance climb at high frequencies. Its value changes with frequency due to losses in the metal around the coil.','It quantifies the coil''s inductive impedance so designers can predict a driver''s high-frequency impedance rise and model its behaviour.','A driver with Le = 0.5 mH shows a reactance of 2*pi*1000*0.5e-3 = about 3.1 ohms at 1 kHz, adding to the coil''s DC resistance.','Loudspeaker Parameter',ARRAY['Re','Thiele-Small parameters','Voice coil','Impedance','Mms']::text[],ARRAY['Treating Le as a fixed value; it falls with frequency because of eddy-current losses.','Confusing Le with the DC resistance Re; Le is the inductive part.','Assuming one 1 kHz figure models the whole range; better models use extra loss terms.']::text[],ARRAY['Modelling a woofer''s impedance curve for crossover design.','Comparing datasheet Thiele-Small parameters between drivers.','Explaining why a driver''s impedance rises toward high frequencies.']::text[],'Intermediate','Z_Le(f) = j * 2*pi*f * Le','The inductive impedance contributed by the voice coil equals j times two pi times frequency times the voice-coil inductance.','a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Le');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8bbf56c0-575b-4177-a619-bf9e84a6fac7','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8bbf56c0-575b-4177-a619-bf9e84a6fac7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8bbf56c0-575b-4177-a619-bf9e84a6fac7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b4f705f1-5289-4cac-8ff5-81f94878c42b','Liftering','Liftering is filtering carried out in the cepstral (quefrency) domain, the word being a deliberate anagram of ''filtering''. A low-time (short-pass) lifter keeps the slow spectral envelope, while a high-time lifter keeps the fine periodic structure such as pitch.','Liftering means filtering in the cepstrum. The name is ''filtering'' with letters swapped. A short-time lifter keeps the smooth spectral shape. A long-time lifter keeps the fine pitch detail. Speech tools use it to separate the vocal tract from the voice pitch.','It separates a signal''s slowly varying spectral envelope from its fine periodic content, which is key to speech and echo analysis.','To estimate a talker''s vocal-tract shape, a technician low-time lifters the cepstrum, keeping the first 20-30 coefficients and discarding the high-quefrency pitch peak.','Cepstral Analysis',ARRAY['Cepstrum','Power cepstrum','Quefrency','Mel-frequency spectrum','Homomorphic filtering']::text[],ARRAY['Mixing up quefrency (time-like) with frequency; liftering acts along quefrency.','Assuming a low-time lifter removes noise; it removes fine periodic and pitch detail.','Forgetting the cepstrum is nonlinear, so liftering is not simple linear filtering of the signal.']::text[],ARRAY['Smoothing a spectral envelope for formant estimation in speech.','Removing an echo''s rahmonic peaks from a recording.','Preparing features before computing mel-frequency cepstral coefficients.']::text[],'Advanced',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Liftering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b4f705f1-5289-4cac-8ff5-81f94878c42b','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b4f705f1-5289-4cac-8ff5-81f94878c42b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b4f705f1-5289-4cac-8ff5-81f94878c42b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab98aee7-3068-43e7-9f57-7bfbbfc9c0af','Long-term power','Long-term maximum input power is a loudspeaker rating in IEC 60268-5: the electrical power the driver withstands, without permanent damage, when driven for a set time and repeated a set number of times using the standard''s simulated program (IEC) noise. It represents endurance under sustained program-like drive rather than a brief peak.','Long-term power is an endurance rating for a loudspeaker. The speaker is driven hard with a music-like test noise. This is repeated many times over minutes. If it survives without damage, that power is its long-term rating. It shows how much sustained power the speaker can take.','It gives buyers a repeatable measure of how much sustained, program-like power a loudspeaker can handle without failing.','A technician applies IEC noise at the rated wattage for one-minute bursts, repeated ten times at two-minute intervals, then checks the driver for any permanent damage.','Loudspeaker Rating',ARRAY['Short-term power','IEC noise','Power handling','Rated noise power','Crest factor']::text[],ARRAY['Reading it as continuous sine power; the test uses program-like noise, not a steady tone.','Confusing long-term with short-term rating; they use different burst lengths and counts.','UNSAFE: Driving a bare driver at its rated power without the crossover the standard assumes can overheat and destroy it.']::text[],ARRAY['Comparing endurance ratings between two subwoofers.','Specifying an amplifier so it will not exceed a driver''s long-term rating.','Setting a production stress test for quality control.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Long-term power');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab98aee7-3068-43e7-9f57-7bfbbfc9c0af','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab98aee7-3068-43e7-9f57-7bfbbfc9c0af') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab98aee7-3068-43e7-9f57-7bfbbfc9c0af');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7720f9f7-559f-442a-a44d-5ab01425cb4c','Long-term stability','Long-term stability is the ability of a measuring instrument or reference to keep its metrological properties, such as sensitivity or output frequency, constant over an extended period, typically months or years. It is limited chiefly by ageing of components rather than short-term noise.','Long-term stability is how well an instrument holds its calibration over time. It looks at slow drift across months or years. Ageing parts cause most of this drift. A stable reference or meter keeps reading correctly between calibrations.','It tells users how often an instrument must be recalibrated and how much its readings may drift between calibrations.','A technician tracks a sound calibrator''s output level at each yearly check; a long-term stability of +/-0.1 dB per year sets a realistic recalibration interval.','Metrology',ARRAY['Drift','Calibration','Short-term stability','Ageing','Traceability']::text[],ARRAY['Confusing long-term stability with accuracy; a stable instrument can still read with an offset.','Assuming stability removes the need for periodic calibration.','Mixing up short-term stability (noise, minutes) with long-term drift (ageing, years).']::text[],ARRAY['Setting recalibration intervals for a reference microphone or calibrator.','Choosing a frequency reference for a measurement system.','Judging whether an old instrument can still be trusted.']::text[],'Intermediate',NULL,NULL,'a75e00b4-4648-4780-8913-cc672bc0ffb3' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Long-term stability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7720f9f7-559f-442a-a44d-5ab01425cb4c','a75e00b4-4648-4780-8913-cc672bc0ffb3',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7720f9f7-559f-442a-a44d-5ab01425cb4c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7720f9f7-559f-442a-a44d-5ab01425cb4c');
